class _AdminGrantAchReq(BaseModel):
    admin_steam_id: str
    target_steam_id: str
    achievement_key: str
    hmac_signature: str | None = None


@app.post("/api/v1/admin/grant-achievement", tags=["Admin"])
async def admin_grant_achievement(req: _AdminGrantAchReq, db: AsyncSession = Depends(get_db)):
    await _require_admin(db, req.admin_steam_id, "grant_achievement", req.target_steam_id, req.hmac_signature)
    if req.achievement_key not in ACHIEVEMENT_DEFS:
        raise HTTPException(400, f"Unknown achievement: {req.achievement_key}")
    target = (await db.execute(select(Player).where(Player.steam_id == req.target_steam_id))).scalar_one_or_none()
    if target is None:
        raise HTTPException(404, "Target player not found")
    existing = (await db.execute(
        select(PlayerAchievement).where(
            PlayerAchievement.player_id == target.id,
            PlayerAchievement.achievement_key == req.achievement_key,
        )
    )).scalar_one_or_none()
    if existing is not None:
        return {"status": "already_unlocked"}
    db.add(PlayerAchievement(player_id=target.id, achievement_key=req.achievement_key))
    gold_amt = _achievement_gold(req.achievement_key)
    target.gold_earned = (target.gold_earned or 0) + gold_amt
    db.add(GoldTransaction(
        player_id=target.id, amount=gold_amt,
        reason="achievement", reference_id=req.achievement_key,
    ))
    db.add(AdminAction(
        admin_steam_id=req.admin_steam_id, action="grant_achievement",
        target_steam_id=req.target_steam_id,
        details={"achievement_key": req.achievement_key, "gold_awarded": gold_amt},
    ))
    await db.commit()
    return {"status": "granted", "achievement_key": req.achievement_key, "gold_awarded": gold_amt}


class _AdminReverseSeriesReq(BaseModel):
    admin_steam_id: str
    series_id: str
    reason: str = "admin_reverse"
    hmac_signature: str | None = None


@app.post("/api/v1/admin/reverse-series", tags=["Admin"])
async def admin_reverse_series(req: _AdminReverseSeriesReq, db: AsyncSession = Depends(get_db)):
    await _require_admin(db, req.admin_steam_id, "reverse_series", req.series_id, req.hmac_signature)
    try:
        _sid = UUID(req.series_id)
    except (ValueError, TypeError):
        raise HTTPException(400, "Invalid series_id")
    # Lock protocol (1v1: players → ranked_series → glicko, matching
    # submit_match — see its comment). The pair is discovered UNLOCKED first
    # (player1_id/player2_id are immutable for a 1v1 series, so this read
    # cannot go stale), then the canonical sorted players pass, then the
    # authoritative FOR UPDATE load of the series row. Everything mutable is
    # re-checked after the lock (learning #197 discovery pattern). The locked
    # load also closes this endpoint's own double-reversal race: two
    # concurrent reverses previously both passed the unlocked
    # invalidated_at check and clawed back gold twice.
    _pair = (await db.execute(
        text("SELECT player1_id, player2_id FROM ranked_series WHERE id = :sid"),
        {"sid": _sid},
    )).first()
    if _pair is None:
        raise HTTPException(404, "Series not found")
    for _pid in sorted([_pair[0], _pair[1]], key=str):
        await db.execute(
            text("SELECT 1 FROM players WHERE id = :pid FOR NO KEY UPDATE"),
            {"pid": _pid},
        )
    series = (await db.execute(
        select(RankedSeries).where(RankedSeries.id == _sid).with_for_update()
    )).scalar_one_or_none()
    if series is None:
        raise HTTPException(404, "Series not found")
    if series.invalidated_at is not None:
        return {"status": "already_invalidated"}

    for pid, rc in [(series.player1_id, series.p1_rating_change),
                    (series.player2_id, series.p2_rating_change)]:
        if rc is None:
            continue
        g = (await db.execute(select(GlickoRating).where(GlickoRating.player_id == pid))).scalar_one_or_none()
        if g is not None:
            g.rating = float(g.rating) - float(rc)
            g.updated_at = datetime.now(timezone.utc)

    # July 20 item 6: also claw back the new loser-side series gold — the 2v2
    # counterpart already reverses win AND loss reasons; without series_loss
    # here a colluding pair keeps the loser payout through every reversal.
    txns = (await db.execute(
        select(GoldTransaction).where(
            GoldTransaction.reason.in_(["series_win", "series_loss"]),
            GoldTransaction.reference_id == str(series.id),
        )
    )).scalars().all()
    for tx in txns:
        db.add(GoldTransaction(
            player_id=tx.player_id, amount=-tx.amount,
            reason="reversal", reference_id=str(series.id),
        ))
        player = (await db.execute(select(Player).where(Player.id == tx.player_id))).scalar_one_or_none()
        if player is not None:
            player.gold_earned = max(0, (player.gold_earned or 0) - tx.amount)

    matches_in_series = (await db.execute(select(Match).where(Match.series_id == series.id))).scalars().all()
    for m in matches_in_series:
        if m.invalidated_at is not None:
            continue
        m.invalidated_at = datetime.now(timezone.utc)
        m.invalidation_reason = "admin_reverse"
        await _reverse_match_gold_xp(db, m)

    series.invalidated_at = datetime.now(timezone.utc)
    series.invalidation_reason = req.reason[:64]

    db.add(AdminAction(
        admin_steam_id=req.admin_steam_id, action="reverse_series",
        target_series_id=series.id,
        details={"reason": req.reason, "matches_reversed": len(matches_in_series)},
    ))
    await db.commit()
    return {"status": "reversed", "series_id": req.series_id, "matches_reversed": len(matches_in_series)}


class _AdminReviewFlagReq(BaseModel):
    admin_steam_id: str
    flag_id: str
    review_action: str
    evidence_revision: int = Field(..., ge=1)
    signature_version: int = 1
    hmac_signature: str | None = None


@app.post("/api/v1/admin/review-flag", tags=["Admin"])
async def admin_review_flag(req: _AdminReviewFlagReq, db: AsyncSession = Depends(get_db)):
    if req.review_action not in ("confirmed_cheat", "false_positive"):
        raise HTTPException(400, "review_action must be 'confirmed_cheat' or 'false_positive'")
    if req.signature_version != 3:
        # Released clients signed only the flag id, allowing an intercepted body
        # to swap the verdict or decide evidence that changed after the admin
        # opened it. Do not silently accept either weaker request.
        raise HTTPException(
            status_code=426,
            detail="Flag review requires the updated admin client",
        )
    await _require_admin(
        db, req.admin_steam_id, "review_flag",
        f"{req.flag_id}:{req.review_action}:{req.evidence_revision}",
        req.hmac_signature)
    fm = (await db.execute(
        select(FlaggedMatch).where(FlaggedMatch.id == req.flag_id).with_for_update()
    )).scalar_one_or_none()
    if fm is None:
        raise HTTPException(404, "Flag not found")
    if fm.discord_evidence_revision != req.evidence_revision:
        raise HTTPException(
            409,
            "Flag evidence changed; refresh and review the latest evidence",
        )
    if fm.reviewed_at is not None:
        # The client retries POSTs after transport failures. If this exact
        # admin/verdict already committed, return the durable result; a
        # different admin or opposite verdict remains a conflict.
        if (fm.reviewed_by_steam_id == req.admin_steam_id
                and fm.review_action == req.review_action):
            return {
                "status": "already_reviewed",
                "flag_id": req.flag_id,
                "review_action": fm.review_action,
                "restoration_required": bool(fm.restoration_required),
            }
        raise HTTPException(409, "Flag was already reviewed")
    fm.reviewed_at = datetime.now(timezone.utc)
    fm.reviewed_by_steam_id = req.admin_steam_id
    fm.review_action = req.review_action
    # Auto-invalidated reports have two materially different histories:
    # the triggering match skipped rewards/series processing entirely, while
    # retroactive matches already had XP/gold reversed and their series marked
    # invalid. Merely clearing invalidated_at produces a valid-looking but
    # economically inconsistent row. Record the verdict, preserve the state,
    # and make the required manual repair explicit until a deterministic
    # replay/reward restoration workflow exists.
    restoration_required = bool(
        req.review_action == "false_positive" and fm.auto_invalidated)
    fm.restoration_required = restoration_required
    db.add(AdminAction(
        admin_steam_id=req.admin_steam_id, action="flag_review",
        target_match_id=fm.match_id,
        details={"flag_id": req.flag_id, "review_action": req.review_action,
                 "evidence_revision": req.evidence_revision,
                 "restoration_required": restoration_required},
    ))
    await db.commit()
    return {
        "status": "reviewed",
        "flag_id": req.flag_id,
        "review_action": req.review_action,
        "restoration_required": restoration_required,
    }


class _AdminResolveFlagRestorationReq(BaseModel):
    admin_steam_id: str
    flag_id: str
    hmac_signature: str | None = None


@app.post("/api/v1/admin/resolve-flag-restoration", tags=["Admin"])
async def admin_resolve_flag_restoration(
    req: _AdminResolveFlagRestorationReq,
    db: AsyncSession = Depends(get_db),
):
    """Close the durable repair reminder after an admin has restored the
    invalidated match's rewards/series state through the controlled repair
    workflow. This endpoint records the attestation; it does not alter economy
    or rating rows itself."""
    await _require_admin(
        db, req.admin_steam_id, "resolve_flag_restoration",
        req.flag_id, req.hmac_signature)
    fm = (await db.execute(
        select(FlaggedMatch)
        .where(FlaggedMatch.id == req.flag_id)
        .with_for_update()
    )).scalar_one_or_none()
    if fm is None:
        raise HTTPException(404, "Flag not found")
    if fm.review_action != "false_positive" or fm.reviewed_at is None:
        raise HTTPException(409, "Only a reviewed false positive can close restoration")
    if not fm.restoration_required:
        # A lost HTTP response must not turn the client's automatic retry into
        # a visible failure after the first attempt already committed.
        return {"status": "restoration_already_completed", "flag_id": req.flag_id}
    fm.restoration_required = False
    db.add(AdminAction(
        admin_steam_id=req.admin_steam_id,
        action="flag_restoration_completed",
        target_match_id=fm.match_id,
        details={"flag_id": req.flag_id},
    ))
    await db.commit()
    return {"status": "restoration_completed", "flag_id": req.flag_id}


# ── Maintenance mode endpoints ───────────────────────────────────
# Called by the deploy script to enter maintenance ~30s before docker-compose recreate,
# so clients see clean 503 + Retry-After:30 instead of connection-refused. Authed via
# X-Internal-Key — same secret the bot uses for /chat/post.

@app.post("/api/v1/admin/maintenance/start", tags=["Admin"])
async def maintenance_start(
    x_internal_key: str | None = Header(None, alias="X-Internal-Key"),
    broadcast: bool = Query(True, description="Also post a chat-bridge notice to the in-game/Discord chat"),
):
    """Flip the API into maintenance mode. Non-bypass, non-internal requests now 503."""
    expected = os.getenv("API_SECRET_KEY", "")
    if not expected or x_internal_key != expected:
        raise HTTPException(status_code=403, detail="Invalid internal key")
    global _in_maintenance
    _in_maintenance = True
    print("[MAINT] Entered maintenance mode — non-bypass requests will 503 with Retry-After:30")
    if broadcast:
        # Use the existing chat broadcast pipeline so both in-game players and Discord see the
        # notice. The chat WS subscribers will receive immediately; the bot relays to Discord.
        try:
            now = datetime.now(timezone.utc).isoformat()
            await chat_manager.broadcast({
                # source="ingame" so the bot's existing ingame→Discord forwarder picks this up.
                # source="system" would be filtered out and never reach #scr-discussion.
                "source": "ingame",
                "steam_id": "_server",
                "display_name": "[server]",
                "message": "Server restarting in ~30 seconds — match reports + bets will resume automatically.",
                "rating": None,
                "title": None,
                "title_color": None,
                "timestamp": now,
            })
        except Exception as e:
            print(f"[MAINT] broadcast failed: {e}")
    return {"status": "maintenance_on"}


@app.post("/api/v1/admin/maintenance/stop", tags=["Admin"])
async def maintenance_stop(
    x_internal_key: str | None = Header(None, alias="X-Internal-Key"),
):
    """Manually clear maintenance mode without restarting (rarely needed — fresh containers
    boot with _in_maintenance=False)."""
    expected = os.getenv("API_SECRET_KEY", "")
    if not expected or x_internal_key != expected:
        raise HTTPException(status_code=403, detail="Invalid internal key")
    global _in_maintenance
    _in_maintenance = False
    print("[MAINT] Maintenance mode cleared manually")
    return {"status": "maintenance_off"}


@app.get("/api/v1/admin/maintenance/status", tags=["Admin"])
async def maintenance_status():
    """Public-readable — clients can poll this if they want to confirm the API is back."""
    return {"in_maintenance": _in_maintenance}


# ════════════════════════════════════════════════════════════════════
# 2v2 RANKED (Phase 1 — Backend foundation)
# ════════════════════════════════════════════════════════════════════
# Parallel path to 1v1 ranked. Reuses Glicko-2 helper but separate ratings,
# separate queue, separate matches. See migration 053_2v2_schema.sql.

# Tunables. Wider ranges than 1v1 because the team-balancer absorbs some
# imbalance — 4-player matches don't need as tight a per-player Elo window.
TEAM_QUEUE_EXPIRE_MINUTES = 30
TEAM_READY_TIMEOUT_SECONDS = 120  # +30s vs 1v1 — 4 players coordinating is slower
# Min completed 2v2 series before we trust the 2v2 rating; below that the balancer
# falls back to 1v1 rating for that player (lesson: new accounts shouldn't drag a
# matchmaking decision around with a 1500-default 2v2 rating that means nothing).
TEAM_TRUST_2V2_RATING_AFTER = 10
# 2v2 elo is also trusted earlier than the series count if the player's RD has
# already converged below this threshold — Glicko-2 RD shrinks fast for active
# players, so once it hits ~100 the rating estimate is meaningful even if the
# player only has a few completed series. Without this, two high-elo veterans
# (one with 20 series, one with 4) couldn't get matched as opponents because
# the matchmaker would fall back to the new account's 1v1 elo for balancing.
TEAM_TRUST_2V2_RD_BELOW = 110.0

# 2v2 economy. Per-match XP base + win multiplier targets ~600 XP loss /
# ~900 XP win at base; per-series gold bonus on top.
TEAM_MATCH_XP_BASE       = 600
TEAM_MATCH_WIN_MULT      = 1.5  # 600 → 900 on win
TEAM_SERIES_WIN_GOLD     = 50
TEAM_SERIES_LOSS_GOLD    = 25
# Mid-series auto-balance trigger. Fires after a match in an auto-balanced
# series whose total point margin >= this threshold (e.g., 5-2 = margin 3).
# Lower → swap more often (every close-ish game), higher → swap only on
# blowouts. Tester request: "make sure colors/spawns/etc get properly
# swapped" — server emits rebalance_assignments and the client follows.
AUTO_BALANCE_SWAP_MARGIN = 3


def _verify_team_hmac(report: TeamMatchReport) -> bool:
    """11-field canonical: t1a:t1b:t2a:t2b:t1r:t2r:is_ranked:reporter:room_id:winner_team:series_id"""
    if not MATCH_HMAC_SECRET:
        return True
    if not report.hmac_signature:
        print(f"[TEAM-HMAC] No signature provided")
        return False
    msg = (
        f"{report.t1a.steam_id}:{report.t1b.steam_id}:"
        f"{report.t2a.steam_id}:{report.t2b.steam_id}:"
        f"{report.t1_rounds_won}:{report.t2_rounds_won}:"
        f"{str(report.is_ranked).lower()}:{report.reported_by_steam_id}:"
        f"{report.photon_room_id or ''}:{report.winner_team}:{report.series_id}"
    )
    expected = hmac.new(MATCH_HMAC_SECRET.encode(), msg.encode(), hashlib.sha256).hexdigest()
    ok = hmac.compare_digest(report.hmac_signature, expected)
    if not ok:
        print(f"[TEAM-HMAC] mismatch. canonical='{msg}'")
    return ok


def _balance_teams(players: list[dict]) -> tuple[list[str], list[str]]:
    """Pick the partition (AB-CD / AC-BD / AD-BC) with the smallest |Δ-Elo|.
    `players` is a list of 4 dicts with keys: player_id, balance_rating.
    Returns (team1_ids, team2_ids) in original order — the caller assigns
    team_assigned=1/2 by membership."""
    assert len(players) == 4
    p = players  # alias
    partitions = [
        ([p[0], p[1]], [p[2], p[3]]),
        ([p[0], p[2]], [p[1], p[3]]),
        ([p[0], p[3]], [p[1], p[2]]),
    ]
    def diff(team1, team2):
        s1 = sum(x["balance_rating"] for x in team1)
        s2 = sum(x["balance_rating"] for x in team2)
        return abs(s1 - s2)
    best = min(partitions, key=lambda part: diff(part[0], part[1]))
    return ([x["player_id"] for x in best[0]], [x["player_id"] for x in best[1]])


def _team_balance_rating(rating: float, completed_series: int, fallback_rating: float, rd: float = 350.0) -> float:
    """Use 2v2 rating once a player has either:
       - enough completed series (TEAM_TRUST_2V2_RATING_AFTER), OR
       - converged RD (rd <= TEAM_TRUST_2V2_RD_BELOW)
    Otherwise fall back to their 1v1 rating. RD path catches active players
    whose 2v2 rating is meaningful even before they hit the series threshold."""
    if completed_series >= TEAM_TRUST_2V2_RATING_AFTER:
        return rating
    if rd is not None and rd <= TEAM_TRUST_2V2_RD_BELOW:
        return rating
    return fallback_rating


@app.post("/api/v1/team/queue/join", tags=["Team Queue"])
async def team_queue_join(req: TeamQueueJoinRequest, request: Request, db: AsyncSession = Depends(get_db)):
    """Upsert player into team_queue. Snapshots their 2v2 + 1v1 ratings so the
    balancer at lock-time uses queue-join values (not drifted live ratings)."""
    await _check_steam_session(request, req.steam_id, db)
    _presence_touch(req.steam_id)
    # Identity gate (round-14 find 1): lock + ban/tombstone re-read under it.
    await _enrollment_identity_gate(db, req.steam_id)
    name = req.display_name or req.steam_id
    player = await get_or_create_player(db, req.steam_id, name)
    await _mark_mod_seen(db, player)
    # Joining 2v2 queue = ranked opt-in. Same race fix as /api/v1/queue/join.
    if not player.ranked_enabled:
        player.ranked_enabled = True

    # Cross-queue guard (Codex post-release find 1) — see /queue/join.
    _other = await _locked_in_other_queue(db, player.id, "team_queue")
    if _other:
        raise HTTPException(status_code=409,
                            detail="You're in a live match in another mode - finish it first")

    # Snapshot 2v2 rating (default if no row yet)
    g2_r = await db.execute(select(GlickoRating2v2).where(GlickoRating2v2.player_id == player.id))
    g2 = g2_r.scalar_one_or_none()
    rating_2v2 = g2.rating if g2 else GLICKO2_DEFAULT_RATING
    rd_2v2 = g2.rating_deviation if g2 else GLICKO2_DEFAULT_RD
    completed = g2.completed_series if g2 else 0

    # Snapshot 1v1 rating for the balancer fallback
    g1_r = await db.execute(select(GlickoRating).where(GlickoRating.player_id == player.id))
    g1 = g1_r.scalar_one_or_none()
    fallback_rating = g1.rating if g1 else GLICKO2_DEFAULT_RATING

    qtype = (req.queue_type or "auto").lower()
    if qtype not in ("auto", "manual"):
        qtype = "auto"

    # Switching queue type clears any stale preferred_team — manual queue starts
    # fresh with no team claimed; auto queue ignores preferred_team entirely.
    stmt = pg_insert(TeamQueue).values(
        player_id=player.id,
        steam_id=req.steam_id,
        display_name=player.display_name,
        rating=rating_2v2,
        rating_deviation=rd_2v2,
        completed_series=completed,
        fallback_rating=fallback_rating,
        region=req.region,
        status="searching",
        series_id=None,
        team_assigned=None,
        room_name=None,
        room_region=None,
        ready=False,
        joined_at=datetime.now(timezone.utc),
        matched_at=None,
        last_polled=datetime.now(timezone.utc),
        queue_type=qtype,
    ).on_conflict_do_update(
        index_elements=[TeamQueue.player_id],
        set_={
            "status": "searching",
            "rating": rating_2v2,
            "rating_deviation": rd_2v2,
            "completed_series": completed,
            "fallback_rating": fallback_rating,
            "region": req.region,
            "series_id": None,
            "team_assigned": None,
            "room_name": None,
            "room_region": None,
            "ready": False,
            "joined_at": datetime.now(timezone.utc),
            "matched_at": None,
            "last_polled": datetime.now(timezone.utc),
            "queue_type": qtype,
            "preferred_team": None,
            "manual_pick_enabled": (qtype == "manual"),
        },
    )
    await db.execute(stmt)
    await db.commit()
    return {"status": "searching", "queue_type": qtype, "message": f"Joined 2v2 {qtype} queue"}


@app.post("/api/v1/team/queue/leave", tags=["Team Queue"])
async def team_queue_leave(request: Request, steam_id: str = Query(...), db: AsyncSession = Depends(get_db)):
    # A8: session enforcement — HMAC alone is forgeable by anyone with the DLL secret.
    await _check_steam_session(request, steam_id, db)
    await _lease_release_by_steam(db, steam_id)
    result = await db.execute(select(Player).where(Player.steam_id == steam_id))
    player = result.scalar_one_or_none()
    if player:
        r = await _lock_queue_group_for_player(db, "team_queue", steam_id)
        if r is None:
            return {"status": "left"}
        # If player is in a locked match (status='matched'), tearing down their row
        # alone would strand the other 3. Cascade: cancel the whole series and
        # release the other 3 back to searching, rather than leave them locked
        # against a ghost teammate.
        #
        # July 30 lifecycle audit item 2: that cascade used to be UNCONDITIONAL,
        # and the client fires this endpoint when a player quits mid-game — so
        # one leaver cancelled a LIVE series (recorded games and all), destroyed
        # its bets, and the survivors' next report 400'd. Cancel is legitimate
        # only for a series that never produced a game AND has no live-game
        # evidence (ready-up abandonment, failed assembly). A mid-game leave
        # deletes the leaver's own row below and nothing else — the DC-report /
        # grace machinery owns a played series' outcome, exactly as it does when
        # a player disconnects without calling leave.
        if r and r["series_id"] and r["status"] in ("matched", "ready"):
            games = (await db.execute(
                text("SELECT COUNT(*) FROM team_matches WHERE series_id = :sid"),
                {"sid": r["series_id"]},
            )).scalar() or 0
            if games == 0 and not _group_game_positively_live(str(r["series_id"])):
                await db.execute(
                    text("""
                        UPDATE team_queue
                        SET status='searching', series_id=NULL, team_assigned=NULL,
                            room_name=NULL, room_region=NULL, ready=false,
                            matched_at=NULL, joined_at=NOW()
                        WHERE series_id = :sid AND player_id != :pid
                    """),
                    {"sid": r["series_id"], "pid": player.id},
                )
                # Mark the series invalidated so the post-lock /matches submit can't
                # accidentally write to it after a no-show.
                await db.execute(
                    text("""
                        UPDATE team_series
                        SET status='cancelled', invalidated_at=NOW(),
                            invalidation_reason='pre_match_leaver'
                        WHERE id = :sid AND status='active'
                    """),
                    {"sid": r["series_id"]},
                )
                await _reconcile_team_series_bets(db, r["series_id"], "pre_match_leaver")
            else:
                print(f"[TEAM-QUEUE] mid-game leave by {steam_id} — series "
                      f"{r['series_id']} left to the match pipeline "
                      f"(games={games})")
        await db.execute(
            text("DELETE FROM team_queue WHERE player_id = :pid"),
            {"pid": player.id},
        )
        await db.commit()
    return {"status": "left"}


@app.get("/api/v1/team/queue/count", tags=["Team Queue"])
async def team_queue_count(db: AsyncSession = Depends(get_db)):
    """Lightweight: live queue size for the F5 tab "X searching" banner.
    90s freshness filter (July 28): a ghost row the janitor hasn't swept yet
    must not inflate the banner — that's how a 285-minute-old husk read as a
    live queuer on the 2v2 tab while the cleanup loop was down."""
    result = await db.execute(text(
        "SELECT COUNT(*) FROM team_queue WHERE status = 'searching'"
        " AND last_polled > NOW() - INTERVAL '90 seconds'"))
    searching = result.scalar() or 0
    return {"searching": searching}


@app.get("/api/v1/team/queue/list", tags=["Team Queue"])
async def team_queue_list(db: AsyncSession = Depends(get_db)):
    """Snapshot of every player currently in the 2v2 queue. Powers the
    "who else is queueing" panels on the F5 2v2 tab. Returns the unified
    `queuers` list (legacy) PLUS split `auto` / `manual` buckets so the
    client can render two side-by-side panels without re-filtering."""
    # 90s freshness filter (July 28): only players whose client is actually
    # polling belong on the panel. Ghost rows (crashed clients the janitor
    # hasn't swept yet) showed as phantom queuers — NotNic's dead row sat on
    # the tab reading "285 minutes" and made custom lobbies look fuller than
    # they were.
    result = await db.execute(
        text("""
            SELECT tq.steam_id, tq.display_name, tq.rating, tq.rating_deviation, tq.completed_series,
                   tq.fallback_rating, tq.region, tq.joined_at, tq.status,
                   tq.team_assigned, tq.series_id,
                   tq.manual_pick_enabled, tq.preferred_team, tq.queue_type
            FROM team_queue tq
            WHERE tq.status IN ('searching', 'matched', 'ready')
              AND tq.last_polled > NOW() - INTERVAL '90 seconds'
            ORDER BY tq.joined_at ASC
        """),
    )
    rows = result.mappings().all()
    out: list[dict] = []
    auto_bucket: list[dict] = []
    manual_bucket: list[dict] = []
    for r in rows:
        cs = int(r["completed_series"] or 0)
        rd = float(r["rating_deviation"] or 350.0)
        # Same trust rule the matchmaker uses — series count OR converged RD.
        using_fb = (cs < TEAM_TRUST_2V2_RATING_AFTER) and (rd > TEAM_TRUST_2V2_RD_BELOW)
        fb = float(r["fallback_rating"] or 0)
        balance = int(round(fb)) if using_fb else int(round(r["rating"]))
        qt = (r["queue_type"] or "auto").lower()
        entry = {
            "steam_id": r["steam_id"],
            "display_name": r["display_name"],
            "rating": int(round(r["rating"] or 0)),
            "balance_rating": balance,
            "using_fallback_rating": using_fb,
            "completed_series": cs,
            "region": r["region"],
            "status": r["status"],
            "team_assigned": r["team_assigned"],
            "series_id": str(r["series_id"]) if r["series_id"] else None,
            "joined_at": r["joined_at"].isoformat() if r["joined_at"] else None,
            "wait_seconds": int((datetime.now(timezone.utc) - r["joined_at"]).total_seconds()) if r["joined_at"] else 0,
            "manual_pick_enabled": bool(r["manual_pick_enabled"]),
            "preferred_team": r["preferred_team"],
            "queue_type": qt,
        }
        out.append(entry)
        (manual_bucket if qt == "manual" else auto_bucket).append(entry)
    return {
        "queuers": out,
        "count": len(out),
        "auto": auto_bucket,
        "manual": manual_bucket,
        "auto_count": len(auto_bucket),
        "manual_count": len(manual_bucket),
    }


@app.get("/api/v1/team/queue/recent-joins", tags=["Team Queue"])
async def team_queue_recent_joins(seconds: int = Query(20), db: AsyncSession = Depends(get_db)):
    """Players who joined the 2v2 queue in the last N seconds. Drives the Discord
    beacon `🎯 NAME searching for 2v2!` post — auto queue only. Custom-lobby
    (manual) queuers are intentionally excluded so #ranked-looking-for-people
    only beacons random-matchmaking joins."""
    result = await db.execute(
        text("""
            SELECT tq.display_name, tq.steam_id, tq.rating, tq.joined_at,
                   CASE WHEN p.show_discord THEN p.discord_display_name END AS discord_display_name
            FROM team_queue tq
            LEFT JOIN players p ON p.steam_id = tq.steam_id
            WHERE tq.status = 'searching'
              AND tq.queue_type = 'auto'
              AND tq.joined_at > NOW() - INTERVAL '1 second' * :secs
            ORDER BY tq.joined_at DESC
        """), {"secs": seconds},
    )
    rows = result.mappings().all()
    cnt_q = await db.execute(text(
        "SELECT COUNT(*) FROM team_queue WHERE status='searching' AND queue_type='auto'"
        " AND last_polled > NOW() - INTERVAL '90 seconds'"))
    cnt = cnt_q.scalar() or 0
    return {
        "joins": [
            {"display_name": r["display_name"], "steam_id": r["steam_id"],
             "rating": round(r["rating"]), "joined_at": r["joined_at"].isoformat(),
             "discord_display_name": r["discord_display_name"]}
            for r in rows
        ],
        "queue_size": cnt,
    }


@app.get("/api/v1/team/queue/poll/{steam_id}", response_model=TeamQueuePollResponse, tags=["Team Queue"])
async def team_queue_poll(steam_id: str, db: AsyncSession = Depends(get_db)):
    """Polled by all 4 participants. Drives the searching → matched → ready_join state machine.
    At lock time, runs the balancer to assign teams. Identical safety pattern to 1v1:
    SELECT FOR UPDATE SKIP LOCKED on the candidate set, atomic update of all 4 rows."""
    import uuid as uuid_mod

    _presence_touch(steam_id)

    # Discover and lock either just the searching caller or the entire existing
    # series group. The old self-FOR-UPDATE followed by bulk four-row writes was
    # the same ABBA shape as 1v1; SKIP LOCKED candidate selection below was safe,
    # but the matched/ready branch was not.
    locked = await _lock_queue_group_for_player(db, "team_queue", steam_id)
    if locked is None:
        return TeamQueuePollResponse(status="not_in_queue")

    # Authoritative full row under the locks.
    me_q = await db.execute(
        text("""
            SELECT tq.player_id, tq.steam_id, tq.display_name, tq.rating, tq.rating_deviation,
                   tq.completed_series, tq.fallback_rating, tq.region, tq.status, tq.series_id,
                   tq.team_assigned, tq.room_name, tq.room_region, tq.ready,
                   tq.joined_at, tq.matched_at, tq.queue_type
            FROM team_queue tq
            JOIN players p ON tq.player_id = p.id
            WHERE p.steam_id = :sid
        """),
        {"sid": steam_id},
    )
    me = me_q.mappings().first()
    if not me:
        await db.commit()
        return TeamQueuePollResponse(status="not_in_queue")

    now = datetime.now(timezone.utc)
    wait_seconds = int((now - me["joined_at"]).total_seconds())
    my_pid = me["player_id"]

    # Heartbeat
    await db.execute(
        text("UPDATE team_queue SET last_polled = NOW() WHERE player_id = :pid"),
        {"pid": my_pid},
    )

    # Searching expiry
    if me["status"] == "searching" and wait_seconds > TEAM_QUEUE_EXPIRE_MINUTES * 60:
        await db.execute(text("DELETE FROM team_queue WHERE player_id = :pid"), {"pid": my_pid})
        await db.commit()
        return TeamQueuePollResponse(status="expired")

    # ── MATCHED / READY state ────────────────────────────────
    if me["status"] in ("matched", "ready") and me["series_id"]:
        # Authoritative series-status check (Codex round-3 find 1, ovt
        # dead-lock-reset pattern): rows must never keep serving a series
        # that is no longer active (janitor cancel, admin action). The group
        # lock we hold covers the series row, so this read can't race a
        # concurrent cancel.
        srow_chk = (await db.execute(
            text("SELECT status FROM team_series WHERE id = :sid"),
            {"sid": me["series_id"]},
        )).scalar_one_or_none()
        if srow_chk != "active":
            await db.execute(
                text("""UPDATE team_queue
                       SET status='searching', series_id=NULL, team_assigned=NULL,
                           room_name=NULL, room_region=NULL, ready=false,
                           matched_at=NULL, joined_at=NOW()
                       WHERE series_id = :sid"""),
                {"sid": me["series_id"]},
            )
            await db.commit()
            print(f"[TEAM-QUEUE] non-active series {me['series_id']} ({srow_chk}) — group reset to searching")
            return TeamQueuePollResponse(status="searching")
        # Pull the other 3 in this series
        peers_q = await db.execute(
            text("""
                SELECT player_id, steam_id, display_name, rating, region, ready, team_assigned
                FROM team_queue
                WHERE series_id = :sid AND player_id != :pid
            """),
            {"sid": me["series_id"], "pid": my_pid},
        )
        peers = list(peers_q.mappings().all())
        if len(peers) < 3:
            # Someone left — cascade was handled in /leave; we degrade back to searching here.
            await db.execute(
                text("""UPDATE team_queue
                       SET status='searching', series_id=NULL, team_assigned=NULL,
                           room_name=NULL, room_region=NULL, ready=false,
                           matched_at=NULL, joined_at=NOW()
                       WHERE player_id = :pid"""),
                {"pid": my_pid},
            )
            await db.commit()
            return TeamQueuePollResponse(status="searching")

        my_team = me["team_assigned"]
        teammates = [p for p in peers if p["team_assigned"] == my_team]
        opponents = [p for p in peers if p["team_assigned"] != my_team]
        all_4 = peers + [me]
        all_ready = all(p["ready"] for p in all_4)

        # Ready timeout
        if me["matched_at"]:
            match_age = int((now - me["matched_at"]).total_seconds())
            if match_age > TEAM_READY_TIMEOUT_SECONDS and not all_ready:
                # Cancel the series — boot all 4 back to searching.
                ids = [p["player_id"] for p in all_4]
                await db.execute(
                    text("""UPDATE team_queue
                           SET status='searching', series_id=NULL, team_assigned=NULL,
                               room_name=NULL, room_region=NULL, ready=false,
                               matched_at=NULL, joined_at=NOW()
                           WHERE player_id = ANY(:ids)"""),
                    {"ids": ids},
                )
                await db.execute(
                    text("UPDATE team_series SET status='cancelled', invalidated_at=NOW(), invalidation_reason='ready_timeout' WHERE id = :sid"),
                    {"sid": me["series_id"]},
                )
                await _reconcile_team_series_bets(db, me["series_id"], "ready_timeout")
                await db.commit()
                return TeamQueuePollResponse(status="searching")

        # Build response payload
        def to_member(row):
            cs = int(row.get("completed_series") or 0)
            rd = float(row.get("rating_deviation") or 350.0)
            using_fb = (cs < TEAM_TRUST_2V2_RATING_AFTER) and (rd > TEAM_TRUST_2V2_RD_BELOW)
            fb = float(row.get("fallback_rating") or 0)
            balance = int(round(fb)) if using_fb else int(round(row["rating"]))
            return TeamQueueMember(
                steam_id=row["steam_id"],
                display_name=row["display_name"],
                rating=int(round(row["rating"])),
                region=row["region"],
                team_assigned=row["team_assigned"],
                using_fallback_rating=using_fb,
                balance_rating=balance,
                completed_series=cs,
                ready=bool(row.get("ready") or False),
            )
        teammates_pl = [to_member(r) for r in teammates]
        opponents_pl = [to_member(r) for r in opponents]

        if all_ready:
            # Generate room if not yet set (any one of the 4 can establish it).
            room_generated_2v2 = not me["room_name"]
            if not me["room_name"]:
                # ALL-member ban recheck at room issuance (round-17 find 2):
                # a ban landing after a member readied must not be frozen
                # into the roster. Same dissolution as the ready-timeout
                # branch above, under the group locks already held — plus
                # the banned rows are DELETED (unmatchable thereafter).
                _banned_ids = []
                for _p in all_4:
                    if (await _is_banned(db, _p["steam_id"])) is not None:
                        _banned_ids.append(_p["player_id"])
                if _banned_ids:
                    _innocent = [p["player_id"] for p in all_4
                                 if p["player_id"] not in _banned_ids]
                    if _innocent:
                        await db.execute(
                            text("""UPDATE team_queue
                                   SET status='searching', series_id=NULL, team_assigned=NULL,
                                       room_name=NULL, room_region=NULL, ready=false,
                                       matched_at=NULL, joined_at=NOW()
                                   WHERE player_id = ANY(:ids)"""),
                            {"ids": _innocent},
                        )
                    await db.execute(
                        text("DELETE FROM team_queue WHERE player_id = ANY(:ids)"),
                        {"ids": _banned_ids},
                    )
                    await db.execute(
                        text("UPDATE team_series SET status='cancelled', invalidated_at=NOW(),"
                             " invalidation_reason='member_banned' WHERE id = :sid"),
                        {"sid": me["series_id"]},
                    )
                    await _reconcile_team_series_bets(db, me["series_id"], "member_banned")
                    await db.commit()
                    return TeamQueuePollResponse(status="searching")
                room_name = f"team_{uuid_mod.uuid4().hex[:12]}"
                # Pick region by mode of the 4 region values; fallback to 'us'.
                regions = [p["region"] for p in all_4 if p["region"]]
                if regions:
                    chosen_region = max(set(regions), key=regions.count)
                else:
                    chosen_region = "us"
                await db.execute(
                    text("""UPDATE team_queue
                           SET room_name = :rn, room_region = :rr
                           WHERE series_id = :sid"""),
                    {"rn": room_name, "rr": chosen_region, "sid": me["series_id"]},
                )
                # room_issued_at anchors the assembly deadline (migration 170):
                # created_at is MATCH time and also had to cover the whole
                # ready-up window, which made the deadline wrong by design.
                await db.execute(
                    text("UPDATE team_series SET photon_room_id = :rn, region = :rr,"
                         " room_issued_at = NOW() WHERE id = :sid"),
                    {"rn": room_name, "rr": chosen_region, "sid": me["series_id"]},
                )
                # Re-read so the response reflects the new room name.
                me_re = await db.execute(
                    text("SELECT room_name, room_region FROM team_queue WHERE player_id = :pid"),
                    {"pid": my_pid},
                )
                rr = me_re.mappings().first()
                room_out = rr["room_name"]
                region_out = rr["room_region"]
            else:
                room_out = me["room_name"]
                region_out = me["room_region"]

            await db.commit()
            # Room just issued — all four are committed to a 2v2 game; drop
            # their searching rows in the other queues. Post-commit, own
            # transaction; gated to the one poll that generated the room.
            if room_generated_2v2:
                await _evict_other_queue_searching(
                    db, [p["player_id"] for p in all_4], "team_queue", "a 2v2 match")
            return TeamQueuePollResponse(
                status="ready_join",
                series_id=str(me["series_id"]),
                team_assigned=my_team,
                teammates=teammates_pl,
                opponents=opponents_pl,
                room_name=room_out,
                room_region=region_out,
                match_age_seconds=int((now - me["matched_at"]).total_seconds()) if me["matched_at"] else 0,
                my_ready=bool(me["ready"]),
            )

        # Matched but not all-ready
        await db.commit()
        return TeamQueuePollResponse(
            status="matched",
            series_id=str(me["series_id"]),
            team_assigned=my_team,
            teammates=teammates_pl,
            opponents=opponents_pl,
            match_age_seconds=int((now - me["matched_at"]).total_seconds()) if me["matched_at"] else 0,
            my_ready=bool(me["ready"]),
        )

    # ── SEARCHING ── try to lock 4 mutually-acceptable players
    elo_range = compute_elo_range(wait_seconds)
    my_balance = _team_balance_rating(me["rating"], me["completed_series"], me["fallback_rating"], me["rating_deviation"])

    # Custom lobbies (manual queue) are consent-based — 4 friends who joined the
    # same lobby type on purpose. The auto-queue Elo band (±100 widening to ±800
    # only after 120s) made mixed-rating friend groups wait minutes before the
    # lock could even see each other (bug #57: ">1 minute for the game to be
    # created"). Manual queues skip the rating gate entirely; the balancer /
    # preferred_team logic downstream still decides the teams.
    if (me.get("queue_type") or "auto").lower() == "manual":
        elo_range = 1_000_000

    # CALLER-side ban gate (round-17 find 1): the candidate predicate covers
    # only the OTHER three — a banned caller (row reset to searching, client
    # still polling) must not form a series either. Delete + not_in_queue;
    # the enrollment gate refuses a rejoin. Covers the dc-resume path below
    # too, since both live behind this point.
    if (await _is_banned(db, steam_id)) is not None:
        await db.execute(text("DELETE FROM team_queue WHERE player_id = :pid"),
                         {"pid": my_pid})
        await db.commit()
        return TeamQueuePollResponse(status="not_in_queue")
    # Find 3 other compatible players. Bilateral Elo overlap, no mutual blocks.
    # Use the SAME elo_range as the caller's tier — wider tier callers find each
    # other faster but a 60s-old caller can't lock with a brand-new 100-Elo-band caller.
    my_qtype = (me.get("queue_type") or "auto").lower()
    cands = await db.execute(
        text("""
            SELECT tq.player_id, tq.steam_id, tq.display_name, tq.rating, tq.rating_deviation,
                   tq.completed_series, tq.fallback_rating, tq.region, tq.joined_at,
                   tq.manual_pick_enabled, tq.preferred_team, tq.queue_type
            FROM team_queue tq
            WHERE tq.status = 'searching'
              AND tq.player_id != :pid
              AND tq.queue_type = :qt
              -- Freshness (review find): a crashed client's row must never lock
              -- into a series (its player would never spawn-confirm). Mirrors
              -- the 1v2 matcher's 10s rule; matters more now that the janitor
              -- sweep runs at 90s instead of 30s.
              AND tq.last_polled > NOW() - INTERVAL '10 seconds'
              AND ABS(tq.rating - :my_r) <= :range
              AND tq.player_id NOT IN (
                  SELECT blocked_id FROM player_blocks WHERE blocker_id = :pid
                  UNION SELECT blocker_id FROM player_blocks WHERE blocked_id = :pid
                  UNION SELECT blocked_id FROM queue_blocks WHERE blocker_id = :pid AND expires_at > now()
                  UNION SELECT blocker_id FROM queue_blocks WHERE blocked_id = :pid AND expires_at > now()
              )
              AND NOT EXISTS (SELECT 1 FROM player_bans pb
                               WHERE pb.steam_id = tq.steam_id
                                 AND pb.unbanned_at IS NULL)
            ORDER BY ABS(tq.rating - :my_r), tq.joined_at
            LIMIT 3
            FOR UPDATE SKIP LOCKED
        """),
        {"pid": my_pid, "my_r": me["rating"], "range": elo_range, "qt": my_qtype},
    )
    others = list(cands.mappings().all())

    # ── Sticky-team requeue resume ──────────────────────────────────
    # If this caller belongs to a `dc_paused` series whose grace deadline
    # hasn't expired, and the other 3 original players are ALSO in queue,
    # resume the existing series with the SAME teams instead of creating
    # a fresh one. Falls through to the normal balancer path otherwise.
    dc_resume_series = await db.execute(
        text("""
            SELECT id, t1a_id, t1b_id, t2a_id, t2b_id, dc_grace_until
              FROM team_series
             WHERE status = 'dc_paused'
               AND dc_grace_until > NOW()
               AND :pid IN (t1a_id, t1b_id, t2a_id, t2b_id)
             ORDER BY dc_grace_until DESC
             LIMIT 1
             FOR UPDATE SKIP LOCKED
        """),
        {"pid": my_pid},
    )
    dc_row = dc_resume_series.mappings().first()
    if dc_row is not None:
        original_pids = [dc_row["t1a_id"], dc_row["t1b_id"], dc_row["t2a_id"], dc_row["t2b_id"]]
        # Are the OTHER 3 original players currently in queue (any status)?
        rs = await db.execute(
            text("""
                SELECT player_id, steam_id, display_name, rating, region
                  FROM team_queue
                 WHERE player_id = ANY(:pids)
                   AND status IN ('searching', 'matched', 'ready')
                   AND player_id != :me
                   -- Freshness (review find): don't resume a series onto a
                   -- crashed teammate's ghost row.
                   AND last_polled > NOW() - INTERVAL '10 seconds'
                   AND NOT EXISTS (SELECT 1 FROM player_bans pb
                                    WHERE pb.steam_id = team_queue.steam_id
                                      AND pb.unbanned_at IS NULL)
                FOR UPDATE SKIP LOCKED
            """),
            {"pids": original_pids, "me": my_pid},
        )
        present = list(rs.mappings().all())
        if len(present) == 3:
            # All 4 originals are here. Re-lock them with the EXISTING series.
            print(f"[TEAM-QUEUE-LOCK] sticky-team resume: series={dc_row['id']} caller={steam_id}")
            # Map original team to t1/t2 — keep the original assignments so the
            # balancer-time slot order remains canonical for HMAC matching.
            t1a, t1b = dc_row["t1a_id"], dc_row["t1b_id"]
            t2a, t2b = dc_row["t2a_id"], dc_row["t2b_id"]
            for pid in [my_pid] + [p["player_id"] for p in present]:
                t = 1 if pid in (t1a, t1b) else 2
                await db.execute(
                    text("""
                        UPDATE team_queue
                           SET status = 'matched',
                               series_id = :sid,
                               team_assigned = :t,
                               matched_at = NOW()
                         WHERE player_id = :pid
                    """),
                    {"sid": dc_row["id"], "t": t, "pid": pid},
                )
            await _lease_acquire_many(
                db, [my_pid] + [p["player_id"] for p in present],
                "team", dc_row["id"], LEASE_TTL_ASSEMBLY)
            # Flip the series back to active and clear DC fields so the next
            # match plays through normally.
            await db.execute(
                text("""
                    UPDATE team_series
                       SET status = 'active',
                           dc_grace_until = NULL,
                           dc_team_remaining = NULL,
                           dc_player_id = NULL
                     WHERE id = :sid
                """),
                {"sid": dc_row["id"]},
            )
            await db.commit()
            # The poll responder reads the queue rows again on its next pass —
            # return matched here so the caller sees the resume and surfaces
            # the ready-up button.
            my_team = 1 if my_pid in (t1a, t1b) else 2
            return TeamQueuePollResponse(
                status="matched",
                series_id=str(dc_row["id"]),
                team_assigned=my_team,
                teammates=[],   # filled by next poll tick from the queue rows
                opponents=[],
                match_age_seconds=0,
            )

    if len(others) < 3:
        # Not enough — count searching, return. Freshness-filtered so the
        # "X searching" banner and the lock diagnostic below never count
        # ghost rows the janitor hasn't swept yet.
        cnt_q = await db.execute(text(
            "SELECT COUNT(*) FROM team_queue WHERE status='searching'"
            " AND last_polled > NOW() - INTERVAL '90 seconds'"))
        cnt = cnt_q.scalar() or 0
        # Diagnostic: when the searching queue has >= 4 players but our lock
        # only finds < 3 candidates from THIS poller's perspective, something
        # filter-side is rejecting them (Elo band too tight, mutual block, or
        # SKIP LOCKED on a concurrent poll). This log is the primary signal
        # for "queue is full but match isn't locking".
        if cnt >= 4:
            print(f"[TEAM-QUEUE-LOCK] caller={steam_id} q_size={cnt} found_others={len(others)} elo_range={elo_range} my_rating={me['rating']:.0f}")
        await db.commit()
        return TeamQueuePollResponse(status="searching", queue_count=cnt, elo_range=elo_range)

    # 4 candidates total (caller + others). Run balancer (or honor manual picks).
    print(f"[TEAM-QUEUE-LOCK] caller={steam_id} locking 4-player series with {[o['steam_id'] for o in others]}")
    pool = [
        {"player_id": me["player_id"], "balance_rating": my_balance,
         "rating": me["rating"], "rd": me["rating_deviation"],
         "steam_id": me["steam_id"],
         "manual_pick_enabled": bool(me.get("manual_pick_enabled")),
         "preferred_team": me.get("preferred_team")},
    ]
    for o in others:
        pool.append({
            "player_id": o["player_id"],
            "balance_rating": _team_balance_rating(o["rating"], o["completed_series"], o["fallback_rating"], o["rating_deviation"]),
            "rating": o["rating"],
            "rd": o["rating_deviation"],
            "steam_id": o["steam_id"],
            "manual_pick_enabled": bool(o.get("manual_pick_enabled")),
            "preferred_team": o.get("preferred_team"),
        })

    # Manual queue: honor each player's preferred_team (queue membership IS the
    # opt-in). Players without a preference fill remaining slots. Auto queue:
    # always run the elo balancer regardless of any stale preferred_team.
    was_auto_balanced = True
    if my_qtype == "manual":
        team1_ids, team2_ids, unassigned = [], [], []
        for p in pool:
            pt = p["preferred_team"]
            if pt == 1 and len(team1_ids) < 2:
                team1_ids.append(p["player_id"])
            elif pt == 2 and len(team2_ids) < 2:
                team2_ids.append(p["player_id"])
            else:
                unassigned.append(p["player_id"])
        for pid in unassigned:
            if len(team1_ids) < 2:
                team1_ids.append(pid)
            elif len(team2_ids) < 2:
                team2_ids.append(pid)
        was_auto_balanced = False
        print(f"[TEAM-QUEUE-LOCK] manual-pick honored: t1={team1_ids} t2={team2_ids}")
    else:
        team1_ids, team2_ids = _balance_teams(pool)

    # Within each team, canonicalize the t-a / t-b slot order by sorting on
    # steam_id. The client reconstructs the same canonical order without any
    # extra metadata, so its 11-field HMAC byte-matches what the server
    # rebuilds at /team/matches submit time. Without this canonicalization
    # the balancer's arbitrary partition order would break HMAC verification.
    pid_to_steam = {p["player_id"]: p["steam_id"] for p in pool}
    team1_ids_sorted = sorted(team1_ids, key=lambda pid: pid_to_steam[pid])
    team2_ids_sorted = sorted(team2_ids, key=lambda pid: pid_to_steam[pid])

    # Create the team_series row.
    series_id = uuid_mod.uuid4()
    await db.execute(
        text("""
            INSERT INTO team_series (id, t1a_id, t1b_id, t2a_id, t2b_id,
                                     status, was_auto_balanced, created_at)
            VALUES (:sid, :t1a, :t1b, :t2a, :t2b, 'active', :wab, NOW())
        """),
        {
            "sid": series_id,
            "t1a": team1_ids_sorted[0], "t1b": team1_ids_sorted[1],
            "t2a": team2_ids_sorted[0], "t2b": team2_ids_sorted[1],
            "wab": was_auto_balanced,
        },
    )
    team1_ids = team1_ids_sorted
    team2_ids = team2_ids_sorted

    # Auto-clear permanent player_blocks within each team. If A blocked B from
    # 1v1 ranked but they ended up paired as teammates by the balancer, the
    # block would otherwise persist into 1v1 (annoying after a friendly 2v2).
    # Mirror of the tournament-lock behavior — clearing only WITHIN-team pairs.
    all_pairs = []
    for team in (team1_ids, team2_ids):
        all_pairs.extend([(team[0], team[1]), (team[1], team[0])])
    if all_pairs:
        # Use CAST(...) instead of `:bind::type` — asyncpg's parameter parser
        # can't distinguish PG's `::` cast operator from a bind-parameter prefix
        # when they're adjacent (`:b1::uuid[]` was throwing PostgresSyntaxError
        # on every lock attempt, silently rolling back the whole 4-player lock
        # transaction so no series ever materialized).
        await db.execute(
            text("""
                DELETE FROM player_blocks
                WHERE (blocker_id, blocked_id) IN (
                    SELECT UNNEST(CAST(:b1 AS uuid[])), UNNEST(CAST(:b2 AS uuid[]))
                )
            """),
            {"b1": [p[0] for p in all_pairs], "b2": [p[1] for p in all_pairs]},
        )
    # Update all 4 queue rows in one statement using arrays.
    matched_at = datetime.now(timezone.utc)
    await db.execute(
        text("""
            UPDATE team_queue
            SET status='matched',
                series_id=:sid,
                team_assigned = CASE WHEN player_id = ANY(:t1) THEN 1 ELSE 2 END,
                matched_at = :mat,
                ready = false,
                room_name = NULL, room_region = NULL
            WHERE player_id = ANY(:all4)
        """),
        {
            "sid": series_id,
            "t1": team1_ids,
            "mat": matched_at,
            "all4": team1_ids + team2_ids,
        },
    )
    # Lease all four in the same transaction as the lock (migration 174).
    # Renewed by the authenticated in_match ping while the sitting is live;
    # once battleOngoing stops for good it lapses on its own, which is what
    # replaces team_queue's old predicate — the one that had NO recency bound
    # at all and could therefore block a player indefinitely.
    await _lease_acquire_many(db, team1_ids + team2_ids, "team", series_id,
                              LEASE_TTL_ASSEMBLY)
    await db.commit()

    # Reload our row to figure out our team.
    me_re = await db.execute(
        text("""SELECT team_assigned, matched_at FROM team_queue WHERE player_id = :pid"""),
        {"pid": my_pid},
    )
    me_row = me_re.mappings().first()
    my_team = me_row["team_assigned"]

    # Build initial matched response.
    peers_q = await db.execute(
        text("""SELECT player_id, steam_id, display_name, rating, region, team_assigned
               FROM team_queue WHERE series_id = :sid AND player_id != :pid"""),
        {"sid": series_id, "pid": my_pid},
    )
    peers = list(peers_q.mappings().all())
    teammates_pl = [
        TeamQueueMember(steam_id=p["steam_id"], display_name=p["display_name"],
                        rating=int(round(p["rating"])), region=p["region"], team_assigned=p["team_assigned"])
        for p in peers if p["team_assigned"] == my_team
    ]
    opponents_pl = [
        TeamQueueMember(steam_id=p["steam_id"], display_name=p["display_name"],
                        rating=int(round(p["rating"])), region=p["region"], team_assigned=p["team_assigned"])
        for p in peers if p["team_assigned"] != my_team
    ]

    return TeamQueuePollResponse(
        status="matched",
        series_id=str(series_id),
        team_assigned=my_team,
        teammates=teammates_pl,
        opponents=opponents_pl,
        match_age_seconds=0,
    )


@app.post("/api/v1/team/queue/manual-pick-toggle", tags=["Team Queue"])
async def team_queue_manual_pick_toggle(
    request: Request,
    steam_id: str = Query(...),
    enabled: bool = Query(...),
    db: AsyncSession = Depends(get_db),
):
    """Flip the per-queuer manual_pick_enabled flag. The matchmaker respects
    `preferred_team` only when at least 3 queuers have the flag enabled
    (otherwise it auto-balances by elo). When disabling, the queuer's
    preferred_team is cleared."""
    # A8: session enforcement — HMAC alone is forgeable by anyone with the DLL secret.
    await _check_steam_session(request, steam_id, db)
    pid = (await db.execute(select(Player.id).where(Player.steam_id == steam_id))).scalar_one_or_none()
    if pid is None:
        raise HTTPException(404, "Player not found")
    if enabled:
        await db.execute(
            text("UPDATE team_queue SET manual_pick_enabled = TRUE WHERE player_id = :pid"),
            {"pid": pid},
        )
    else:
        await db.execute(
            text("UPDATE team_queue SET manual_pick_enabled = FALSE, preferred_team = NULL WHERE player_id = :pid"),
            {"pid": pid},
        )
    await db.commit()
    return {"status": "ok", "enabled": enabled}


@app.post("/api/v1/team/queue/preferred-team", tags=["Team Queue"])
async def team_queue_preferred_team(
    request: Request,
    steam_id: str = Query(...),
    team: int = Query(..., ge=1, le=2),
    db: AsyncSession = Depends(get_db),
):
    """Claim Team 1 or Team 2. Only honored when the queuer is in the manual
    (pick-teams) queue. Auto-queue calls are no-ops because the matchmaker
    ignores preferred_team for that queue."""
    # A8: session enforcement — HMAC alone is forgeable by anyone with the DLL secret.
    await _check_steam_session(request, steam_id, db)
    pid = (await db.execute(select(Player.id).where(Player.steam_id == steam_id))).scalar_one_or_none()
    if pid is None:
        raise HTTPException(404, "Player not found")
    await db.execute(
        text("""
            UPDATE team_queue
               SET preferred_team = :team
             WHERE player_id = :pid AND queue_type = 'manual'
        """),
        {"pid": pid, "team": team},
    )
    await db.commit()
    return {"status": "ok", "preferred_team": team}


@app.post("/api/v1/team/queue/ready", tags=["Team Queue"])
async def team_queue_ready(request: Request, steam_id: str = Query(...), db: AsyncSession = Depends(get_db)):
    """Mark caller ready. Resets matched_at on all 4 rows so the timeout window
    refreshes for whoever is the slowest of the four. (Lesson 51 from 1v1.)"""
    # A8: session enforcement — HMAC alone is forgeable by anyone with the DLL secret.
    await _check_steam_session(request, steam_id, db)
    result = await db.execute(select(Player).where(Player.steam_id == steam_id))
    player = result.scalar_one_or_none()
    if not player:
        return {"status": "error", "message": "Unknown player"}
    me = await _lock_queue_group_for_player(db, "team_queue", steam_id)
    if not me or not me["series_id"] or me["status"] not in ("matched", "ready"):
        await db.commit()
        return {"status": "error", "message": "Not in a matched 2v2 series"}
    await db.execute(
        text("""UPDATE team_queue
               SET ready = (player_id = :pid OR ready),
                   matched_at = NOW(),
                   status = 'ready'
               WHERE series_id = :sid"""),
        {"pid": player.id, "sid": me["series_id"]},
    )
    await db.commit()
    # Log how many of the 4 are now ready so the lobby state is observable
    # without firing a separate poll log per player.
    cnt_q = await db.execute(
        text("SELECT COUNT(*) FROM team_queue WHERE series_id = :sid AND ready = true"),
        {"sid": me["series_id"]},
    )
    ready_cnt = cnt_q.scalar() or 0
    print(f"[TEAM-READY] {steam_id} ready ({ready_cnt}/4) in series {me['series_id']}")
    return {"status": "ok", "ready_count": ready_cnt}


# ─────────────────────────────────────────────────────────────────────────
# Match-assembly tracking (added v1.25.11). Each client posts spawn-confirm
# when its auto-spawn override successfully creates the local Player. Server
# bumps spawn_confirmations + records the player_id (idempotent). When state
# is polled with <4 confirmations past the deadline — measured from
# room_issued_at since the July 30 audit (item 4) — the server cancels the
# series with reason='assembly_timeout' so all 4 clients can bail to menu.
# 180s from ROOM ISSUE: Photon region connect + room join + map load +
# spawn + the confirm POST for the slowest of four clients, with the
# in_match veto covering a live game whose confirm POST was lost. Until the
# heartbeat-carrying client ships, this constant is the only protection.
# ─────────────────────────────────────────────────────────────────────────

_ASSEMBLY_DEADLINE_SECONDS = 180


def _verify_spawn_confirm_hmac(steam_id: str, series_id: str, signature: str) -> bool:
    """HMAC for spawn-confirm = sha256(secret, "{steam_id}:{series_id}:spawn")."""
    if not MATCH_HMAC_SECRET:
        return True  # dev mode without secret
    expected = hmac.new(
        MATCH_HMAC_SECRET.encode(),
        f"{steam_id}:{series_id}:spawn".encode(),
        hashlib.sha256,
    ).hexdigest()
    return hmac.compare_digest(expected, signature or "")


@app.post("/api/v1/team/series/{series_id}/spawn-confirm", tags=["Team Matches"])
async def team_series_spawn_confirm(
    series_id: str,
    steam_id: str = Query(...),
    hmac_sig: str = Query(...),
    db: AsyncSession = Depends(get_db),
):
    """Client posts this when its 2v2 auto-spawn override successfully creates
    the local Player. Idempotent per (series, player) — safe to retry."""
    if not _verify_spawn_confirm_hmac(steam_id, series_id, hmac_sig):
        raise HTTPException(403, "Invalid spawn-confirm signature")
    try:
        sid_uuid = UUID(series_id)
    except (ValueError, TypeError):
        raise HTTPException(400, "Invalid series_id")
    # Resolve player to UUID for the idempotency record.
    p_row = await db.execute(select(Player.id).where(Player.steam_id == steam_id))
    pid = p_row.scalar_one_or_none()
    if pid is None:
        raise HTTPException(404, "Unknown player")

    # Idempotent atomic update: only increment if this player hasn't already
    # been recorded. asyncpg + jsonb @> for membership.
    # asyncpg's parameter parser collides with PostgreSQL's `::` cast operator
    # (learning #46 — same bug we hit with `:b1::uuid[]`). Use CAST(...) form.
    res = await db.execute(
        text("""
            UPDATE team_series
               SET spawn_confirmations = spawn_confirmations + 1,
                   spawn_confirmed_by = spawn_confirmed_by || to_jsonb(CAST(:pid AS text))
             WHERE id = :sid
               AND status = 'active'
               AND NOT (spawn_confirmed_by @> to_jsonb(CAST(:pid AS text)))
            RETURNING spawn_confirmations
        """),
        {"sid": sid_uuid, "pid": str(pid)},
    )
    new_count = res.scalar_one_or_none()
    await db.commit()
    if new_count is None:
        # Either series not active, or player already confirmed. Read current
        # value to return — useful for clients to see "already done".
        row = await db.execute(
            text("SELECT spawn_confirmations, status FROM team_series WHERE id = :sid"),
            {"sid": sid_uuid},
        )
        cur = row.first()
        if cur is None:
            raise HTTPException(404, "Series not found")
        return {"confirmations": int(cur[0] or 0), "status": cur[1], "already_recorded": True}
    return {"confirmations": int(new_count), "status": "active", "already_recorded": False}


@app.get("/api/v1/team/series/{series_id}/state", tags=["Team Matches"])
async def team_series_state(series_id: str, db: AsyncSession = Depends(get_db)):
    """Per-series assembly + lifecycle state. Polled by clients after
    ready_join. If the room has been issued for longer than the assembly
    deadline (_ASSEMBLY_DEADLINE_SECONDS from room_issued_at) with fewer
    than 4 spawn-confirms and no live-game evidence, transitions to
    status='canceled' with reason 'assembly_timeout' so all 4 clients can
    bail back to menu."""
    try:
        sid_uuid = UUID(series_id)
    except (ValueError, TypeError):
        raise HTTPException(400, "Invalid series_id")

    row = await db.execute(
        text("""
            SELECT id, status, created_at, spawn_confirmations,
                   invalidation_reason, completed_at,
                   dc_grace_until, dc_team_remaining, dc_player_id,
                   t1_series_wins, t2_series_wins, room_issued_at
              FROM team_series
             WHERE id = :sid
        """),
        {"sid": sid_uuid},
    )
    r = row.first()
    if r is None:
        raise HTTPException(404, "Series not found")

    s_status = r[1]
    s_created = r[2]
    s_confirms = int(r[3] or 0)
    s_reason = r[4]
    s_dc_grace_until = r[6]
    s_dc_team = r[7]
    s_dc_player = r[8]

    # July 30 lifecycle audit item 4: the deadline used to measure from
    # created_at — MATCH time — so it also had to absorb ready-up (up to
    # 120s), Photon connect, map load and spawn-confirm delivery, and a state
    # poll right after room issue could cancel a healthy assembly off the
    # exhausted earlier clock. Measure from room_issued_at (migration 170;
    # COALESCE covers pre-migration rows with the old conservative anchor).
    s_room_issued = r[11] or s_created
    age_seconds = (datetime.now(timezone.utc) - s_room_issued).total_seconds()

    # Auto-cancel if the assembly deadline has passed and we still don't have 4.
    # The in_match veto covers the "game is live but a spawn-confirm POST was
    # lost" hole: a live game stuck at 3/4 confirmations must not be cancelled
    # by this poll-driven timer.
    if (
        s_status == "active"
        and s_confirms < 4
        and age_seconds > _ASSEMBLY_DEADLINE_SECONDS
        and not _group_game_positively_live(str(sid_uuid))
    ):
        await db.execute(
            text("""
                UPDATE team_series
                   SET status = 'canceled',
                       invalidated_at = NOW(),
                       invalidation_reason = 'assembly_timeout'
                 WHERE id = :sid AND status = 'active'
            """),
            {"sid": sid_uuid},
        )
        await _reconcile_team_series_bets(db, sid_uuid, "assembly_timeout")
        await db.commit()
        return {
            "status": "canceled",
            "reason": "assembly_timeout",
            "confirmations": s_confirms,
            "expected": 4,
            "age_seconds": int(age_seconds),
            "deadline_seconds": _ASSEMBLY_DEADLINE_SECONDS,
        }

    # 5-min sticky-team requeue grace window: if the deadline has passed and
    # the series is still flagged dc_paused, resolve it. The non-DC team takes
    # the series win by forfeit (their 2 members were ready to keep going).
    dc_grace_seconds_remaining = 0
    if s_dc_grace_until is not None:
        dc_grace_seconds_remaining = max(0, int((s_dc_grace_until - datetime.now(timezone.utc)).total_seconds()))
        if dc_grace_seconds_remaining == 0 and s_status == "dc_paused":
            # Manual-control policy: a lapsed grace window no longer auto-forfeits to
            # the remaining team (a long 2v2 restart must not hand someone the series).
            # Flip to dc_incomplete so it surfaces in the admin panel for a manual call.
            # (New DCs no longer enter dc_paused at all; this only catches legacy rows.)
            await db.execute(
                text("""UPDATE team_series SET status='dc_incomplete',
                           invalidation_reason='dc_manual_pending'
                         WHERE id=:sid AND status='dc_paused'"""),
                {"sid": sid_uuid},
            )
            await db.commit()
            return {
                "status": "dc_incomplete",
                "reason": "awaiting_admin_resolution",
                "winner_team": None,
                "confirmations": s_confirms,
                "expected": 4,
                "age_seconds": int(age_seconds),
                "deadline_seconds": _ASSEMBLY_DEADLINE_SECONDS,
                "dc_grace_seconds_remaining": 0,
            }

    return {
        "status": s_status,
        "reason": s_reason,
        "confirmations": s_confirms,
        "expected": 4,
        "age_seconds": int(age_seconds),
        "deadline_seconds": _ASSEMBLY_DEADLINE_SECONDS,
        "dc_grace_seconds_remaining": dc_grace_seconds_remaining,
        "dc_team_remaining": s_dc_team,
        "dc_player_id": str(s_dc_player) if s_dc_player else None,
        "t1_series_wins": int(r[9] or 0),
        "t2_series_wins": int(r[10] or 0),
    }


_DC_GRACE_SECONDS = 300  # 5-minute sticky-team requeue window


async def _complete_team_series_with_ratings(
    db: AsyncSession,
    series_uuid: UUID,
    winner_team: int,
    reason: str,
    dc_pid=None,
):
    """Fully complete a 2v2 series — Glicko-2 + series gold + per-slot accumulators +
    completed_series counter — for the DC / forfeit / admin-resolution paths.

    Deliberately awards NO XP: match XP is a per-GAME payout granted inline by
    submit_team_match for each game actually played (and those games already
    paid out before the DC). A forfeit ends the series without another game, so
    there is no game to pay XP for. (The docstring used to claim xp — audit
    found the body never awarded it; the claim was wrong, not the body.)

    Before v1.28 the DC paths (report-dc, grace-expiry) marked a series 'completed'
    but applied NO ratings/gold, so a DC-decided win never moved Elo or paid out —
    making leaving strictly better than losing on the board. This factors the SAME
    completion math used by submit_team_match's inline block (rating period = this
    series, each player's two opponents = the other team) so every completion path
    produces identical economy + rating effects.

    Idempotent guard: callers must only invoke this for a series transitioning OUT of
    a non-completed status in the SAME transaction; the UPDATE ... WHERE status<>'completed'
    in the caller is the lock. This helper assumes the row is already (or about to be)
    marked completed and just applies the side effects. Safe to call once per series.

    winner_team: 1 or 2. reason: stored in invalidation_reason. dc_pid: optional.
    Returns dict of {str(pid): new_rating} for logging.
    """
    # FOR UPDATE row-locks the series so concurrent completion attempts serialize.
    # The SECOND caller (e.g. a duo rage-quitting fires OnPlayerLeftRoom twice → two
    # report-dc POSTs, or a DC report racing a normal match-end submit) sees the row
    # already 'completed' and no-ops — without this guard both would apply a full
    # rating period + gold payout + bet settle, double-crediting everyone. This is
    # the single guard that closes the double-credit / double-settle / admin-re-pay
    # races (2v2 audit finding #1).
    srow = (await db.execute(
        text("""SELECT status, t1a_id, t1b_id, t2a_id, t2b_id
                  FROM team_series WHERE id = :sid FOR UPDATE"""),
        {"sid": series_uuid},
    )).mappings().first()
    if srow is None:
        return {}
    if srow["status"] == "completed":
        # Already finished by a concurrent caller — do nothing.
        return {}
    t1a_id, t1b_id, t2a_id, t2b_id = srow["t1a_id"], srow["t1b_id"], srow["t2a_id"], srow["t2b_id"]
    gids = [t1a_id, t1b_id, t2a_id, t2b_id]
    if any(g is None for g in gids):
        # Defensive: a series with an unfilled slot can't have ratings applied.
        # Still free the queue rows — the normal path's DELETE at the bottom is
        # skipped by this early return, and completed-series rows that linger in
        # team_queue block their players from re-queueing until the janitor.
        await db.execute(
            text("""UPDATE team_series SET status='completed', winner_team=:wt,
                       completed_at=NOW(), invalidation_reason=:rsn WHERE id=:sid"""),
            {"wt": winner_team, "rsn": reason, "sid": series_uuid},
        )
        await _lock_queue_rows_ordered(db, "team_queue", [g for g in gids if g is not None])
        await db.execute(text("DELETE FROM team_queue WHERE series_id = :sid"), {"sid": series_uuid})
        return {}

    # Mark completed (winner + reason) up front.
    await db.execute(
        text("""UPDATE team_series SET status='completed', winner_team=:wt,
                   completed_at=NOW(), invalidation_reason=:rsn, dc_player_id=COALESCE(:dpid, dc_player_id)
                 WHERE id=:sid"""),
        {"wt": winner_team, "rsn": reason, "sid": series_uuid, "dpid": dc_pid},
    )

    # Canonical players-row lock pass BEFORE any glicko access (adversarial
    # review of the submit_team_match lock-order fix): the players row is the
    # only reliable cross-series gate — every member has one from queue join,
    # while glicko_ratings_2v2 rows don't exist until a player's first
    # completion, so for first-series players the glicko pass below matches
    # zero rows and locks nothing. Without this pass, this helper's first
    # players tuple locks came from _grant_rating_achievements' gold UPDATEs
    # in SLOT order — an ABBA edge against submit_team_match's sorted pass
    # when the shared players have no glicko rows — and two first-completion
    # transactions could race duplicate-PK glicko INSERTs. FOR NO KEY UPDATE:
    # the mode every later non-key players UPDATE takes anyway, and unlike
    # FOR UPDATE it does not conflict with the FOR KEY SHARE RI locks a
    # caller may already hold from INSERTing a team_matches row naming these
    # players (report-dc's synthetic forfeit row).
    for _pid in sorted(gids, key=str):
        await db.execute(
            text("SELECT 1 FROM players WHERE id = :pid FOR NO KEY UPDATE"),
            {"pid": _pid},
        )

    # ── Glicko-2 (mirrors submit_team_match:7232-7306) ──
    # Canonical-order lock pass first (learning #197 / review find): two
    # completions can share players across DIFFERENT series (dc_incomplete
    # husk resolved while the same four play a new series), and each series'
    # slot order differs — an ANY(...) FOR UPDATE locks in planner order, an
    # ABBA edge. One indexed lock per row, ascending str(pid), same rule as
    # _lock_queue_rows_ordered. (Cross-series serialization itself is
    # guaranteed by the players pass above; this keeps glicko row access
    # ordered among completers whose rows already exist.)
    for _pid in sorted(gids, key=str):
        await db.execute(
            text("SELECT 1 FROM glicko_ratings_2v2 WHERE player_id = :pid FOR UPDATE"),
            {"pid": _pid},
        )
    gres = await db.execute(
        text("SELECT player_id, rating, rating_deviation, volatility, peak_rating, completed_series "
             "FROM glicko_ratings_2v2 WHERE player_id = ANY(:ids)"),
        {"ids": gids},
    )
    existing = {r["player_id"]: dict(r) for r in gres.mappings().all()}
    for pid in gids:
        if pid not in existing:
            existing[pid] = {
                "player_id": pid, "rating": GLICKO2_DEFAULT_RATING,
                "rating_deviation": GLICKO2_DEFAULT_RD, "volatility": GLICKO2_DEFAULT_VOLATILITY,
                "peak_rating": GLICKO2_DEFAULT_RATING, "completed_series": 0, "_new": True,
            }
    team1_won = (winner_team == 1)
    inputs = {pid: existing[pid] for pid in gids}

    def update_player(p, opps_pre, won: bool):
        opps = [(o["rating"], o["rating_deviation"], 1.0 if won else 0.0) for o in opps_pre]
        return calculate_new_rating(p["rating"], p["rating_deviation"], p["volatility"], opps, GLICKO2_TAU)

    results = {}
    for pid in (t1a_id, t1b_id):
        results[pid] = update_player(inputs[pid], [inputs[t2a_id], inputs[t2b_id]], team1_won)
    for pid in (t2a_id, t2b_id):
        results[pid] = update_player(inputs[pid], [inputs[t1a_id], inputs[t1b_id]], not team1_won)

    new_ratings = {}
    for pid, (new_r, new_rd, new_vol) in results.items():
        if inputs[pid].get("_new"):
            db.add(GlickoRating2v2(
                player_id=pid, rating=new_r, rating_deviation=new_rd, volatility=new_vol,
                peak_rating=max(GLICKO2_DEFAULT_RATING, new_r), games_in_period=0,
                completed_series=1, last_calculated=datetime.now(timezone.utc),
            ))
        else:
            await db.execute(
                text("""UPDATE glicko_ratings_2v2
                       SET rating=:r, rating_deviation=:rd, volatility=:v,
                           peak_rating=GREATEST(COALESCE(peak_rating,:r), :r),
                           completed_series = completed_series + 1,
                           last_calculated=NOW(), updated_at=NOW()
                       WHERE player_id=:pid"""),
                {"r": new_r, "rd": new_rd, "v": new_vol, "pid": pid},
            )
        new_ratings[str(pid)] = round(new_r, 1)
        await _grant_rating_achievements(db, pid, new_r)

    # Per-slot rating deltas (joined by player_id, same as the inline path).
    delta_by_pid = {pid: round(results[pid][0] - inputs[pid]["rating"], 1) for pid in gids}
    await db.execute(
        text("""UPDATE team_series SET
                   t1a_rating_change=:t1a_d, t1b_rating_change=:t1b_d,
                   t2a_rating_change=:t2a_d, t2b_rating_change=:t2b_d
                 WHERE id=:sid"""),
        {"sid": series_uuid, "t1a_d": delta_by_pid[t1a_id], "t1b_d": delta_by_pid[t1b_id],
         "t2a_d": delta_by_pid[t2a_id], "t2b_d": delta_by_pid[t2b_id]},
    )

    # ── Series-completion gold (+50 win / +25 loss) + per-slot accumulator ──
    # July 20 item 6: scaled by the opposing team's tier, same formula as the
    # inline submit path (learning #77 family: DC-decided series must pay
    # identically). `inputs` holds the pre-update rating snapshot.
    _t1_avg_rating = (inputs[t1a_id]["rating"] + inputs[t1b_id]["rating"]) / 2.0
    _t2_avg_rating = (inputs[t2a_id]["rating"] + inputs[t2b_id]["rating"]) / 2.0
    bonus_by_pid = {}
    # sorted(key=str): players-row tuple locks in canonical order — slot order
    # differs per series and two completions can share players (review find).
    for pid in sorted(gids, key=str):
        player_team = 1 if pid in (t1a_id, t1b_id) else 2
        won_series = (player_team == winner_team)
        _s_mult, _ = _tier_mult_for(_t2_avg_rating if player_team == 1 else _t1_avg_rating)
        bonus = int((TEAM_SERIES_WIN_GOLD if won_series else TEAM_SERIES_LOSS_GOLD) * _s_mult)
        await db.execute(
            text("UPDATE players SET gold_earned=COALESCE(gold_earned,0)+:g, "
                 "team_gold_earned=COALESCE(team_gold_earned,0)+:g WHERE id=:pid"),
            {"g": bonus, "pid": pid},
        )
        db.add(GoldTransaction(
            player_id=pid, amount=bonus,
            reason=("team_series_win" if won_series else "team_series_loss"),
            reference_id=str(series_uuid),
        ))
        bonus_by_pid[pid] = bonus
    await db.execute(
        text("UPDATE team_series SET "
             "t1a_gold_earned=COALESCE(t1a_gold_earned,0)+:t1a_g, "
             "t1b_gold_earned=COALESCE(t1b_gold_earned,0)+:t1b_g, "
             "t2a_gold_earned=COALESCE(t2a_gold_earned,0)+:t2a_g, "
             "t2b_gold_earned=COALESCE(t2b_gold_earned,0)+:t2b_g WHERE id=:sid"),
        {"sid": series_uuid, "t1a_g": bonus_by_pid[t1a_id], "t1b_g": bonus_by_pid[t1b_id],
         "t2a_g": bonus_by_pid[t2a_id], "t2b_g": bonus_by_pid[t2b_id]},
    )

    # Settle any open 2v2 bets on this series (mirror submit_team_match).
    # SAVEPOINT (learning #187 family): a bare try/except around writes inside
    # an open Postgres transaction does NOT contain the failure — a failed
    # statement aborts the WHOLE transaction and the later commit dies anyway.
    # begin_nested() rolls back only this block on error, so the series
    # completion above still commits. The flush() runs the pending ORM adds
    # inside the savepoint (an unflushed add would survive the rollback).
    try:
        async with db.begin_nested():
            unsettled = (await db.execute(text("""
                SELECT id, player_id, amount, odds_multiplier, bet_on_team
                  FROM team_bets WHERE team_series_id = :sid AND settled_at IS NULL
                 ORDER BY player_id::text, id
            """), {"sid": series_uuid})).mappings().all()
            for b in unsettled:
                won = (b["bet_on_team"] == winner_team)
                payout = int(round(b["amount"] * b["odds_multiplier"])) if won else 0
                # Claim-gated (Codex Jul-29 find 1): the SELECT above is a
                # snapshot — a janitor reconcile can settle/refund this bet
                # between it and here, and an unconditional UPDATE would
                # overwrite that terminal state and pay a second time.
                claimed = (await db.execute(text(
                    "UPDATE team_bets SET settled_at=NOW(), payout=:p, settlement_kind=:k"
                    " WHERE id=:id AND settled_at IS NULL RETURNING id"),
                    {"p": payout, "k": "won" if won else "lost", "id": b["id"]})).scalar()
                if claimed is None:
                    continue
                if payout > 0:
                    await db.execute(text("UPDATE players SET gold_earned=COALESCE(gold_earned,0)+:p WHERE id=:pid"),
                                     {"p": payout, "pid": b["player_id"]})
                    db.add(GoldTransaction(player_id=b["player_id"], amount=payout,
                                           reason="team_bet_payout", reference_id=str(series_uuid)))
            await db.flush()
    except Exception as bex:
        print(f"[TEAM-DC-COMPLETE] bet settle error for {series_uuid}: {bex}")

    # Free the queue rows.
    await _lock_queue_rows_ordered(db, "team_queue", gids)
    await db.execute(text("DELETE FROM team_queue WHERE series_id = :sid"), {"sid": series_uuid})
    return new_ratings


# Statuses on which _reconcile_team_series_bets may REFUND. Deliberately NOT
# "anything but completed": dc_incomplete / dc_paused are awaiting an admin
# decision — refunding there would strand a valid winning bet forever, because
# the eventual completion only selects unsettled rows (Codex Jul-29 find 2).
_TEAM_BET_REFUND_STATUSES = ("cancelled", "canceled")


async def _reconcile_team_series_bets(db: AsyncSession, series_uuid, reason: str,
                                      allow_refund_statuses: tuple = _TEAM_BET_REFUND_STATUSES):
    """Terminal bet resolution for a 2v2 series that is being cancelled/voided
    (or is discovered already closed with unsettled bets — the janitor sweep).
    A completed, non-invalidated series with a recorded winner SETTLES its
    unsettled bets against that result (#241 — the settle savepoint can roll
    back while the completion commits, leaving chargeable-but-unpaid winners);
    a series in an allowed terminal-cancel status refunds the stake; ANY other
    status (active, dc_incomplete, dc_paused, ...) is skipped — its lifecycle
    isn't decided yet. The stalled-active janitor arm opts 'active' into the
    refund set explicitly (the husk policy, mirroring the 1v1 stalled prune).

    The series row is locked FOR NO KEY UPDATE first (#202: the weakest mode
    that conflicts with everything we must serialize against): it conflicts
    with the FOR UPDATE every completion path holds AND with the plain status
    UPDATEs (report-dc's flip to dc_incomplete takes NO KEY UPDATE, which
    KEY SHARE would have sailed past — Codex round-2 find 2), while staying
    compatible with the FK KEY SHARE that team_bets/team_matches INSERTs take.
    So an in-flight completion or DC transition commits before we classify,
    and we then settle/skip against the real state instead of refunding it.
    Accepted residual (round-2 find 1 / round-3 find 1): a series writer that
    has not yet taken its series lock when the stalled sweep claims a refund
    can still finish afterwards — report-dc between its synthetic-match
    INSERT (FK KEY SHARE only) and the completion helper's FOR UPDATE, or the
    non-forfeit DC path whose dc_incomplete flip was read-then-write. Both
    need a game-less HOUR plus a ~ms interleaving, and the outcome is always
    the documented refund-sticky policy (#107): stakes returned, never a
    double-pay (every write is claimed), with the skip/settle decision made
    against whatever state committed first.
    Claim-first per bet (settled_at gate inside the UPDATE) so a concurrent
    settle can never double-pay; gold direction mirrors the live paths (win:
    gold_earned += payout; refund: gold_spent -= stake). Bounded per pass
    (leftovers picked up by the janitor's next tick). Savepoint-contained,
    never raises."""
    try:
        async with db.begin_nested():
            srow = (await db.execute(text(
                "SELECT status, winner_team, invalidated_at FROM team_series"
                " WHERE id = :sid FOR NO KEY UPDATE"
            ), {"sid": series_uuid})).mappings().first()
            if srow is None:
                return
            settle_against = (srow["winner_team"]
                              if (srow["status"] == "completed"
                                  and srow["winner_team"] in (1, 2)
                                  and srow["invalidated_at"] is None)
                              else None)
            if settle_against is None and srow["status"] not in allow_refund_statuses:
                print(f"[TEAM-BETS] reconcile skipped for {series_uuid} ({reason}): "
                      f"status '{srow['status']}' is not terminal here")
                return
            unsettled = (await db.execute(text(
                "SELECT id, player_id, amount, odds_multiplier, bet_on_team"
                "  FROM team_bets WHERE team_series_id = :sid AND settled_at IS NULL"
                " ORDER BY player_id::text, id LIMIT 200"
            ), {"sid": series_uuid})).mappings().all()
            settled = refunded = 0
            for b in unsettled:
                if settle_against is not None:
                    won = b["bet_on_team"] == settle_against
                    pay = int(round(b["amount"] * float(b["odds_multiplier"]))) if won else 0
                    kind = "won" if won else "lost"
                else:
                    pay = b["amount"]   # payout == stake marks a refund (#107/#244)
                    kind = "refunded"
                claimed = (await db.execute(text(
                    "UPDATE team_bets SET payout = :p, settled_at = NOW(), settlement_kind = :k"
                    " WHERE id = :bid AND settled_at IS NULL RETURNING id"
                ), {"p": pay, "k": kind, "bid": b["id"]})).scalar()
                if claimed is None:
                    continue
                if settle_against is not None:
                    settled += 1
                    if pay > 0:
                        await db.execute(text(
                            "UPDATE players SET gold_earned = COALESCE(gold_earned,0) + :p WHERE id = :pid"
                        ), {"p": pay, "pid": b["player_id"]})
                        db.add(GoldTransaction(player_id=b["player_id"], amount=pay,
                                               reason="team_bet_payout", reference_id=str(series_uuid)))
                else:
                    refunded += 1
                    await db.execute(text(
                        "UPDATE players SET gold_spent = GREATEST(0, COALESCE(gold_spent,0) - :amt) WHERE id = :pid"
                    ), {"amt": b["amount"], "pid": b["player_id"]})
                    db.add(GoldTransaction(player_id=b["player_id"], amount=b["amount"],
                                           reason="team_bet_refund", reference_id=str(series_uuid)))
            # Flush INSIDE the savepoint — an unflushed ORM add would survive
            # the rollback and write a ledger row without its gold move (#187).
            await db.flush()
            if settled or refunded:
                print(f"[TEAM-BETS] reconciled series {series_uuid} ({reason}): "
                      f"{settled} settled, {refunded} refunded")
    except Exception as ex:
        print(f"[TEAM-BETS] reconcile failed for {series_uuid} ({reason}) — janitor retries: {ex}")


@app.post("/api/v1/admin/team/series/{series_id}/resolve", tags=["Admin"])
async def admin_resolve_team_series(
    series_id: str,
    action: str = Query(..., description="'complete' (award winner_team) or 'void' (cancel, no result)"),
    winner_team: int | None = Query(None, description="1 or 2; required when action=complete"),
    x_internal_key: str = Header(None, alias="X-Internal-Key"),
    admin_steam_id: str = Query(None),
    hmac_signature: str = Query(None),
    db: AsyncSession = Depends(get_db),
):
    """Admin: force-resolve a stuck / incomplete 2v2 series.

    Callable two ways: (1) API_SECRET_KEY via the X-Internal-Key header (server-side
    scripts), or (2) admin-HMAC (admin_steam_id + hmac_signature) so the mod's in-game
    admin panel can resolve a series. Canonical for (2):
    admin:{steam}:resolve_team_series:{series_id}:{action}:{winner_team or 0}.

    action='complete' applies the SAME Glicko/gold/xp as a normal completion via
    _complete_team_series_with_ratings (awards a DC/forfeit after the fact).
    action='void' cancels the series with no winner and no rating/economy effect.
    Operates on any series not already completed/cancelled."""
    expected = os.getenv("API_SECRET_KEY", "")
    internal_ok = bool(expected) and x_internal_key == expected
    admin_ok = False
    if not internal_ok and admin_steam_id:
        _tgt = f"{series_id}:{action}:{winner_team if winner_team is not None else 0}"
        admin_ok = (await _is_admin(db, admin_steam_id)) and _verify_admin_hmac(
            admin_steam_id, "resolve_team_series", _tgt, hmac_signature)
    if not (internal_ok or admin_ok):
        raise HTTPException(403, "Not authorized")
    try:
        sid_uuid = UUID(series_id)
    except (ValueError, TypeError):
        raise HTTPException(400, "Invalid series_id")
    if admin_steam_id and admin_ok:
        db.add(AdminAction(admin_steam_id=admin_steam_id, action="resolve_team_series",
                           target_series_id=sid_uuid,
                           details={"action": action, "winner_team": winner_team}))
    srow = (await db.execute(
        text("SELECT status FROM team_series WHERE id=:sid FOR UPDATE"), {"sid": sid_uuid},
    )).scalar_one_or_none()
    if srow is None:
        raise HTTPException(404, "Series not found")
    # Guard against re-resolution: a completed OR already-voided series must not be
    # re-paid (void→complete would otherwise double-credit). The helper has its own
    # status guard too, but bail early for a clean response.
    if srow in ("completed", "cancelled", "canceled"):
        return {"status": "noop", "reason": f"already {srow}"}

    if action == "void":
        await db.execute(
            text("""UPDATE team_series SET status='cancelled', completed_at=NOW(),
                       invalidation_reason='admin_void' WHERE id=:sid"""),
            {"sid": sid_uuid},
        )
        # Soft-invalidate any match rows so they don't pollute match-W/L stats.
        await db.execute(
            text("""UPDATE team_matches SET invalidated_at=NOW(),
                       invalidation_reason='admin_void' WHERE series_id=:sid AND invalidated_at IS NULL"""),
            {"sid": sid_uuid},
        )
        void_queue_ids = list((await db.execute(text(
            "SELECT player_id FROM team_queue WHERE series_id = :sid"
        ), {"sid": sid_uuid})).scalars().all())
        await _lock_queue_rows_ordered(db, "team_queue", void_queue_ids)
        await db.execute(text("DELETE FROM team_queue WHERE series_id=:sid"), {"sid": sid_uuid})
        await _reconcile_team_series_bets(db, sid_uuid, "admin_void")
        await db.commit()
        return {"status": "voided", "series_id": series_id}

    if action == "complete":
        if winner_team not in (1, 2):
            raise HTTPException(400, "winner_team must be 1 or 2 for action=complete")
        new_ratings = await _complete_team_series_with_ratings(
            db, sid_uuid, winner_team, "admin_resolved",
        )
        await db.commit()
        return {"status": "completed", "winner_team": winner_team, "new_ratings": new_ratings}

    raise HTTPException(400, "action must be 'complete' or 'void'")


@app.get("/api/v1/admin/recent-series", tags=["Admin"])
async def admin_recent_series(
    admin_steam_id: str = Query(...),
    hmac_signature: str = Query(None),
    limit: int = Query(30, ge=1, le=100),
    db: AsyncSession = Depends(get_db),
):
    """Unified recent 1v1 + 2v2 series for the mod admin panel. Each entry carries a
    per-ladder series #, players + card picks, series score, status, and who DC'd (2v2).
    incomplete=true → resolvable (Award/Void); completed → reversible. Admin-HMAC gated
    (canonical admin:{steam}:list_recent_series:)."""
    if not await _is_admin(db, admin_steam_id):
        raise HTTPException(403, "Not an admin")
    if not _verify_admin_hmac(admin_steam_id, "list_recent_series", "", hmac_signature):
        raise HTTPException(403, "Bad admin signature")

    # ── 2v2 ──
    team_rows = (await db.execute(text("""
        WITH numbered AS (SELECT id, ROW_NUMBER() OVER (ORDER BY created_at) AS num FROM team_series)
        SELECT s.id, n.num, s.status, s.created_at, s.completed_at,
               s.t1_series_wins, s.t2_series_wins, s.winner_team,
               s.t1a_id, s.t1b_id, s.t2a_id, s.t2b_id, s.dc_player_id,
               p1a.display_name AS t1a_name, p1a.steam_id AS t1a_sid,
               p1b.display_name AS t1b_name, p1b.steam_id AS t1b_sid,
               p2a.display_name AS t2a_name, p2a.steam_id AS t2a_sid,
               p2b.display_name AS t2b_name, p2b.steam_id AS t2b_sid,
               dcp.display_name AS dc_name, dcp.steam_id AS dc_sid
          FROM team_series s
          JOIN numbered n ON n.id = s.id
          JOIN players p1a ON p1a.id = s.t1a_id
          JOIN players p1b ON p1b.id = s.t1b_id
          JOIN players p2a ON p2a.id = s.t2a_id
          JOIN players p2b ON p2b.id = s.t2b_id
          LEFT JOIN players dcp ON dcp.id = s.dc_player_id
         ORDER BY s.created_at DESC LIMIT :lim
    """), {"lim": limit})).mappings().all()

    team_ids = [r["id"] for r in team_rows]
    team_cards = {}
    if team_ids:
        for cr in (await db.execute(text("""
            SELECT tm.series_id, tmc.player_id, tm.id AS match_id, tmc.card_name
              FROM team_matches tm JOIN team_match_cards tmc ON tmc.match_id = tm.id
             WHERE tm.series_id = ANY(:sids)
             ORDER BY tm.ended_at, tmc.pick_order
        """), {"sids": team_ids})).mappings().all():
            team_cards.setdefault((cr["series_id"], cr["player_id"]), []).append((cr["match_id"], cr["card_name"]))

    def _games_join(entries):
        # Two-level flat encoding (bug #68): '||' separates GAMES, '|' separates
        # cards within a game. Stays a flat scalar so JsonUtility parses it
        # (learning #25 — no nested arrays); the admin tab splits on '||' to
        # render one line per game instead of the whole series mashed together.
        games, last_mid = [], object()
        for mid, name in entries:
            if mid != last_mid:
                games.append([])
                last_mid = mid
            games[-1].append(name)
        return "||".join("|".join(g) for g in games)

    def _tc(r, pre):  # per-game card names for a 2v2 slot
        return _games_join(team_cards.get((r["id"], r[f"{pre}_id"]), []))

    # Flat scalar fields only (cards pipe-joined) so the client parses the whole
    # payload with JsonUtility — nested arrays silently fail there (learning #25).
    two = []
    for r in team_rows:
        two.append({
            "ladder": "2v2", "series_number": int(r["num"]), "series_id": str(r["id"]),
            "status": r["status"], "num_players": 4,
            "created_at": r["created_at"].isoformat() if r["created_at"] else "",
            "completed_at": r["completed_at"].isoformat() if r["completed_at"] else "",
            "score": f"{r['t1_series_wins'] or 0}-{r['t2_series_wins'] or 0}",
            "winner_team": r["winner_team"] or 0,
            "incomplete": r["status"] in ("active", "dc_paused", "dc_incomplete"),
            "dc_name": r["dc_name"] or "", "dc_steam": r["dc_sid"] or "",
            "p1_name": r["t1a_name"], "p1_steam": r["t1a_sid"], "p1_team": 1, "p1_cards": _tc(r, "t1a"),
            "p2_name": r["t1b_name"], "p2_steam": r["t1b_sid"], "p2_team": 1, "p2_cards": _tc(r, "t1b"),
            "p3_name": r["t2a_name"], "p3_steam": r["t2a_sid"], "p3_team": 2, "p3_cards": _tc(r, "t2a"),
            "p4_name": r["t2b_name"], "p4_steam": r["t2b_sid"], "p4_team": 2, "p4_cards": _tc(r, "t2b"),
        })

    # ── 1v1 ──
    solo_rows = (await db.execute(text("""
        WITH numbered AS (SELECT id, ROW_NUMBER() OVER (ORDER BY created_at) AS num FROM ranked_series)
        SELECT s.id, n.num, s.status, s.created_at, s.completed_at,
               s.p1_series_wins, s.p2_series_wins, s.winner_id,
               s.player1_id, s.player2_id, s.invalidated_at,
               p1.display_name AS p1_name, p1.steam_id AS p1_sid,
               p2.display_name AS p2_name, p2.steam_id AS p2_sid
          FROM ranked_series s
          JOIN numbered n ON n.id = s.id
          JOIN players p1 ON p1.id = s.player1_id
          JOIN players p2 ON p2.id = s.player2_id
         ORDER BY s.created_at DESC LIMIT :lim
    """), {"lim": limit})).mappings().all()

    solo_ids = [r["id"] for r in solo_rows]
    solo_cards = {}
    if solo_ids:
        for cr in (await db.execute(text("""
            SELECT m.series_id, mc.player_id, m.id AS match_id, mc.card_name
              FROM matches m JOIN match_cards mc ON mc.match_id = m.id
             WHERE m.series_id = ANY(:sids)
             ORDER BY m.created_at, mc.pick_order
        """), {"sids": solo_ids})).mappings().all():
            solo_cards.setdefault((cr["series_id"], cr["player_id"]), []).append((cr["match_id"], cr["card_name"]))

    one = []
    for r in solo_rows:
        winner = 1 if r["winner_id"] == r["player1_id"] else (2 if r["winner_id"] == r["player2_id"] else 0)
        status = "cancelled" if r["invalidated_at"] is not None else r["status"]
        one.append({
            "ladder": "1v1", "series_number": int(r["num"]), "series_id": str(r["id"]),
            "status": status, "num_players": 2,
            "created_at": r["created_at"].isoformat() if r["created_at"] else "",
            "completed_at": r["completed_at"].isoformat() if r["completed_at"] else "",
            "score": f"{r['p1_series_wins'] or 0}-{r['p2_series_wins'] or 0}",
            "winner_team": winner,
            "incomplete": status not in ("completed", "cancelled"),
            "dc_name": "", "dc_steam": "",
            "p1_name": r["p1_name"], "p1_steam": r["p1_sid"], "p1_team": 1,
            "p1_cards": _games_join(solo_cards.get((r["id"], r["player1_id"]), [])),
            "p2_name": r["p2_name"], "p2_steam": r["p2_sid"], "p2_team": 2,
            "p2_cards": _games_join(solo_cards.get((r["id"], r["player2_id"]), [])),
            "p3_name": "", "p3_steam": "", "p3_team": 0, "p3_cards": "",
            "p4_name": "", "p4_steam": "", "p4_team": 0, "p4_cards": "",
        })

    combined = two + one
    combined.sort(key=lambda x: x["created_at"] or "", reverse=True)
    return {"series": combined[:limit]}


class _AdminReverseTeamSeriesReq(BaseModel):
    admin_steam_id: str
    series_id: str
    reason: str = "admin_reverse"
    hmac_signature: str | None = None


@app.post("/api/v1/admin/team/reverse-series", tags=["Admin"])
async def admin_reverse_team_series(req: _AdminReverseTeamSeriesReq, db: AsyncSession = Depends(get_db)):
    """Reverse a COMPLETED 2v2 series: undo each slot's Glicko rating change, decrement
    completed_series, reverse the series-completion gold (+ bet payouts), invalidate its
    matches, and cancel the series. Rating-only reversal (RD/volatility not restored),
    matching the 1v1 admin/reverse-series. Admin-HMAC gated."""
    await _require_admin(db, req.admin_steam_id, "reverse_team_series", req.series_id, req.hmac_signature)
    try:
        sid = UUID(req.series_id)
    except (ValueError, TypeError):
        raise HTTPException(400, "Invalid series_id")
    s = (await db.execute(text("""
        SELECT status, t1a_id, t1b_id, t2a_id, t2b_id,
               t1a_rating_change, t1b_rating_change, t2a_rating_change, t2b_rating_change
          FROM team_series WHERE id = :sid FOR UPDATE
    """), {"sid": sid})).mappings().first()
    if s is None:
        raise HTTPException(404, "Series not found")
    if s["status"] != "completed":
        return {"status": "noop", "reason": f"series is '{s['status']}', not completed"}

    slots = [(s["t1a_id"], s["t1a_rating_change"]), (s["t1b_id"], s["t1b_rating_change"]),
             (s["t2a_id"], s["t2a_rating_change"]), (s["t2b_id"], s["t2b_rating_change"])]
    # Lock protocol (same as _complete_team_series_with_ratings: series row
    # first — held above — then players sorted str(pid) FOR NO KEY UPDATE,
    # then glicko in the same sorted order). This endpoint previously took
    # glicko tuple locks in SLOT order with no players pass at all — a
    # glicko-before-players inversion that could ABBA against a concurrent
    # completion sharing players (dc_incomplete husk scenario).
    for _pid in sorted((pid for pid, _ in slots if pid is not None), key=str):
        await db.execute(
            text("SELECT 1 FROM players WHERE id = :pid FOR NO KEY UPDATE"),
            {"pid": _pid},
        )
    for pid, rc in sorted((sl for sl in slots if sl[0] is not None), key=lambda sl: str(sl[0])):
        await db.execute(text("""
            UPDATE glicko_ratings_2v2
               SET rating = rating - :rc,
                   completed_series = GREATEST(0, completed_series - 1),
                   updated_at = NOW(), last_calculated = NOW()
             WHERE player_id = :pid
        """), {"rc": float(rc or 0), "pid": pid})

    # Reverse series-completion gold (win/loss bonus + bet payouts). Win/loss bonus also
    # bumped team_gold_earned; bet payouts only gold_earned. Bettor rows sit
    # outside the four held member locks (same accepted class as live bet
    # settlement); ORDER BY player_id::text matches the settle path's order so
    # the two can't invert against each other.
    for tx in (await db.execute(text("""
        SELECT player_id, amount, reason FROM gold_transactions
         WHERE reference_id = :ref
           AND reason IN ('team_series_win', 'team_series_loss', 'team_bet_payout')
         ORDER BY player_id::text, id
    """), {"ref": str(sid)})).mappings().all():
        await db.execute(text(
            "UPDATE players SET gold_earned = GREATEST(0, COALESCE(gold_earned,0) - :amt) WHERE id = :pid"
        ), {"amt": tx["amount"], "pid": tx["player_id"]})
        if tx["reason"] in ("team_series_win", "team_series_loss"):
            await db.execute(text(
                "UPDATE players SET team_gold_earned = GREATEST(0, COALESCE(team_gold_earned,0) - :amt) WHERE id = :pid"
            ), {"amt": tx["amount"], "pid": tx["player_id"]})
        db.add(GoldTransaction(player_id=tx["player_id"], amount=-tx["amount"],
                               reason="team_series_reversal", reference_id=str(sid)))

    await db.execute(text("""
        UPDATE team_matches SET invalidated_at = NOW(), invalidation_reason = 'admin_reverse'
         WHERE series_id = :sid AND invalidated_at IS NULL
    """), {"sid": sid})
    await db.execute(text("""
        UPDATE team_series SET status = 'cancelled', winner_team = NULL,
               invalidated_at = NOW(), invalidation_reason = :rsn
         WHERE id = :sid
    """), {"sid": sid, "rsn": (req.reason or "admin_reverse")[:64]})
    # Unsettled bets on the now-voided result are refunded (settled bets are
    # deliberately untouched — winnings clawback is a separate policy call).
    await _reconcile_team_series_bets(db, sid, "admin_reverse")
    db.add(AdminAction(admin_steam_id=req.admin_steam_id, action="reverse_team_series",
                       target_series_id=sid, details={"reason": req.reason}))
    await db.commit()
    return {"status": "reversed", "series_id": req.series_id}


@app.post("/api/v1/admin/team/rebuild-glicko", tags=["Admin"])
async def admin_rebuild_team_glicko(
    x_internal_key: str = Header(None, alias="X-Internal-Key"),
    db: AsyncSession = Depends(get_db),
):
    """Admin: rebuild ALL 2v2 Glicko ratings + completed_series counters from the
    completed-series history. API_SECRET_KEY gated. Idempotent / re-runnable.

    Fixes the historical invisibility bug: prior recovery migrations (077-080)
    inserted completed team_series + credited gold/xp but never created the
    glicko_ratings_2v2 rows or bumped completed_series, so recovered players had
    NULL/zero 2v2 ratings and were filtered off the 2v2 leaderboard
    (WHERE completed_series >= 1). This replays every completed, non-invalidated
    series in chronological order through the same Glicko-2 math, writing fresh
    ratings + an accurate completed_series count for every participant.

    Does NOT touch gold/xp (those were already credited by the live path /
    recovery migrations — replaying them would double-pay). Ratings-only rebuild."""
    expected = os.getenv("API_SECRET_KEY", "")
    if not expected or x_internal_key != expected:
        raise HTTPException(403, "Internal endpoint")

    async def _read_completed_series():
        return (await db.execute(text("""
            SELECT id, t1a_id, t1b_id, t2a_id, t2b_id, winner_team, completed_at
              FROM team_series
             WHERE status='completed' AND winner_team IN (1,2)
               AND t1a_id IS NOT NULL AND t1b_id IS NOT NULL
               AND t2a_id IS NOT NULL AND t2b_id IS NOT NULL
             ORDER BY completed_at ASC NULLS LAST
        """))).mappings().all()

    series_rows = await _read_completed_series()

    # In-memory rating state per player; seed defaults on first appearance.
    # sids_by_pid: the exact SET of series ids replayed for each player —
    # the recheck below compares sets, not counts, because a count can alias
    # (a reversal cancelling one series while a new one completes leaves the
    # count equal with the membership changed). len(set) is also the correct
    # completed_series value even for a degenerate row carrying the same
    # player in two slots (which a raw count would tally twice, making the
    # recheck permanently mismatch and the player unfixable).
    state: dict = {}
    sids_by_pid: dict = {}

    def seed(pid):
        if pid not in state:
            state[pid] = {"rating": GLICKO2_DEFAULT_RATING, "rating_deviation": GLICKO2_DEFAULT_RD,
                          "volatility": GLICKO2_DEFAULT_VOLATILITY, "peak": GLICKO2_DEFAULT_RATING}
            sids_by_pid[pid] = set()

    for s in series_rows:
        t1 = [s["t1a_id"], s["t1b_id"]]
        t2 = [s["t2a_id"], s["t2b_id"]]
        for pid in t1 + t2:
            seed(pid)
            sids_by_pid[pid].add(s["id"])
        team1_won = (s["winner_team"] == 1)
        snap = {pid: dict(state[pid]) for pid in t1 + t2}

        def calc(pid, opp_pids, won):
            opps = [(snap[o]["rating"], snap[o]["rating_deviation"], 1.0 if won else 0.0) for o in opp_pids]
            return calculate_new_rating(snap[pid]["rating"], snap[pid]["rating_deviation"],
                                        snap[pid]["volatility"], opps, GLICKO2_TAU)
        for pid in t1:
            nr, nrd, nv = calc(pid, t2, team1_won)
            state[pid] = {"rating": nr, "rating_deviation": nrd, "volatility": nv,
                          "peak": max(state[pid]["peak"], nr)}
        for pid in t2:
            nr, nrd, nv = calc(pid, t1, not team1_won)
            state[pid] = {"rating": nr, "rating_deviation": nrd, "volatility": nv,
                          "peak": max(state[pid]["peak"], nr)}

    # Universe = replayed participants UNION everyone who ALREADY has a 2v2
    # rating row (Codex cold review). If a player's only completed series was
    # reversed they vanish from `state` entirely, and their existing row would
    # keep a stale rating/RD/peak and a nonzero completed_series forever —
    # visible on the 2v2 leaderboard, which filters `completed_series >= 1`.
    # Seeding them gives defaults and zero series, so this really is a replay
    # of history rather than a replay of whoever currently appears in one.
    for _pid in (await db.execute(text("SELECT player_id FROM glicko_ratings_2v2"))).scalars().all():
        seed(_pid)

    # Persist via one SHORT transaction per player: lock that player's row
    # (canonical FOR NO KEY UPDATE), re-verify the history generation, upsert,
    # commit. Why not one big sorted lock pass over every participant
    # (adversarial review find): bettor gold UPDATEs in the live paths are
    # outside every writer's sorted lock set, and a pass this wide is
    # near-guaranteed to hold some bettor's row while waiting on a row a live
    # report holds, whose bet settle then wants the bettor — an ABBA no
    # ordering discipline covers. A mini-transaction holds at most one players
    # row (+ that player's glicko row, which any live writer only takes AFTER
    # holding the same players row), so no hold-and-wait chain can form.
    #
    # The guard is GLOBAL, not per-player (Codex cold review): Glicko is a
    # chain, so a reversal in an OPPONENT's history changes the correct result
    # for this player even though this player's own series set is untouched —
    # a per-player check passes and writes a silently stale rating. Any change
    # to the completed-series set therefore invalidates the whole replay: stop,
    # report every not-yet-written player as contended, and let the admin
    # re-run (idempotent). One extra indexed read per player on a small table
    # is a fine price for not writing wrong ratings.
    #
    # KNOWN TRADE, accepted: committing per player means readers can observe a
    # MIXED generation mid-run (`place_team_bet` stores durable odds from the
    # 2v2 ratings it reads). The alternative — one transaction — is the wide
    # lock pass that deadlocks live match reports. Run this when nobody is
    # playing; it is an admin repair tool, not a live-safe operation.
    _snapshot_sids = {r["id"] for r in series_rows}
    _ordered = sorted(state.items(), key=lambda kv: str(kv[0]))
    written = 0
    contended: list = []
    for _idx, (pid, st) in enumerate(_ordered):
        await db.execute(
            text("SELECT 1 FROM players WHERE id = :pid FOR NO KEY UPDATE"),
            {"pid": pid},
        )
        live_sids = set((await db.execute(text("""
            SELECT id FROM team_series
             WHERE status='completed' AND winner_team IN (1,2)
               AND t1a_id IS NOT NULL AND t1b_id IS NOT NULL
               AND t2a_id IS NOT NULL AND t2b_id IS NOT NULL
        """))).scalars().all())
        if live_sids != _snapshot_sids:
            contended = [str(p) for p, _ in _ordered[_idx:]]
            await db.commit()
            print(f"[REBUILD-2V2] completed-series history changed under the rebuild after "
                  f"{written} player(s); STOPPING with {len(contended)} unwritten. The replay is "
                  f"stale for everyone downstream of the change — re-run when play has settled.")
            break
        await db.execute(text("""
            INSERT INTO glicko_ratings_2v2
                (player_id, rating, rating_deviation, volatility, peak_rating,
                 games_in_period, completed_series, last_calculated, updated_at)
            VALUES (:pid, :r, :rd, :v, :peak, 0, :cs, NOW(), NOW())
            ON CONFLICT (player_id) DO UPDATE SET
                rating=:r, rating_deviation=:rd, volatility=:v,
                peak_rating=:peak, completed_series=:cs,
                last_calculated=NOW(), updated_at=NOW()
        """), {"pid": pid, "r": st["rating"], "rd": st["rating_deviation"],
               "v": st["volatility"], "peak": st["peak"], "cs": len(sids_by_pid[pid])})
        await db.commit()
        written += 1
    return {"status": ("rebuilt" if not contended else "incomplete_rerun_needed"),
            "series_replayed": len(series_rows),
            "players_written": written, "players_contended": contended}


def _verify_team_dc_hmac(steam_id: str, series_id: str, dc_player_steam_id: str, signature: str) -> bool:
    """HMAC for team-DC reports: sha256(secret, "{reporter}:{series}:{dc_player}:dc")."""
    if not MATCH_HMAC_SECRET:
        return True
    expected = hmac.new(
        MATCH_HMAC_SECRET.encode(),
        f"{steam_id}:{series_id}:{dc_player_steam_id}:dc".encode(),
        hashlib.sha256,
    ).hexdigest()
    return hmac.compare_digest(expected, signature or "")


@app.post("/api/v1/team/series/{series_id}/report-dc", tags=["Team Matches"])
async def team_series_report_dc(
    series_id: str,
    reporter_steam_id: str = Query(...),
    dc_player_steam_id: str = Query(...),
    t1_points_total: int = Query(0, ge=0),
    t2_points_total: int = Query(0, ge=0),
    hmac_sig: str = Query(...),
    db: AsyncSession = Depends(get_db),
):
    """Mid-series disconnect report. The 2v2 DC rule: if the abandoned match
    had >=2 total points scored across both teams, award the match win to the
    non-DC team (different from 1v1 which usually cancels). Series stays
    active but flips to status='dc_paused' for 5 minutes — if the same 4
    re-queue within that window the matchmaker resumes the existing series;
    otherwise the team that was still around takes the series by forfeit
    (handled by the state-poll endpoint when the deadline expires)."""
    if not _verify_team_dc_hmac(reporter_steam_id, series_id, dc_player_steam_id, hmac_sig):
        raise HTTPException(403, "Invalid DC report signature")
    try:
        sid_uuid = UUID(series_id)
    except (ValueError, TypeError):
        raise HTTPException(400, "Invalid series_id")

    # Resolve players.
    pid_row = await db.execute(select(Player.id).where(Player.steam_id == dc_player_steam_id))
    dc_pid = pid_row.scalar_one_or_none()
    if dc_pid is None:
        raise HTTPException(404, "DC'd player unknown")

    s_row = await db.execute(
        text("""
            SELECT id, status, t1a_id, t1b_id, t2a_id, t2b_id,
                   t1_series_wins, t2_series_wins
              FROM team_series WHERE id = :sid
        """),
        {"sid": sid_uuid},
    )
    s = s_row.mappings().first()
    if s is None:
        raise HTTPException(404, "Series not found")
    if s["status"] not in ("active", "dc_paused"):
        return {"status": s["status"], "ignored": True}

    # Determine which team the DC'd player was on.
    dc_team = 1 if dc_pid in (s["t1a_id"], s["t1b_id"]) else 2 if dc_pid in (s["t2a_id"], s["t2b_id"]) else None
    if dc_team is None:
        raise HTTPException(400, "DC'd player isn't part of this series")
    other_team = 2 if dc_team == 1 else 1

    # F6 hardening: the reporter must be a member of THIS series and on the team
    # that did NOT disconnect. The DC HMAC proves "a mod produced this", not that
    # the reporter was in the match (shared-secret limitation), so bind to series
    # membership server-side — stops attributing a DC to an arbitrary player.
    rep_pid = (await db.execute(
        select(Player.id).where(Player.steam_id == reporter_steam_id)
    )).scalar_one_or_none()
    rep_team = 1 if rep_pid in (s["t1a_id"], s["t1b_id"]) else 2 if rep_pid in (s["t2a_id"], s["t2b_id"]) else None
    if rep_team is None or rep_team == dc_team:
        raise HTTPException(400, "reporter must be a member of the non-DC team")

    # F6 FOLLOW-UP (tracked in docs/SECURITY_ACTION_ITEMS.md): t1/t2_points_total
    # are still client-supplied + outside the DC HMAC, so a member could misreport
    # the abandoned game's score to flip the >=2-points game-award branch. Lower
    # impact (one 2v2 game; the lead-forfeit rule below ignores points entirely)
    # and needs a coordinated client-canonical change — folding points into the
    # DC signature is the next pass.
    total_points = (t1_points_total or 0) + (t2_points_total or 0)

    # ── Anti-abuse lead-forfeit (v1.28) ───────────────────────────────────
    # If the NON-DC (remaining) team has ALREADY won at least one game of this
    # series, a DC by the other team forfeits the WHOLE series to them
    # immediately — regardless of the abandoned game's point total. This is the
    # rule Sid asked for: you can't leave a 2v2 to dodge a loss once the other
    # team is up a game. Applies full Glicko/gold/xp via the shared helper so
    # the forfeit win actually moves the board (the old dc_decided/dc_forfeit
    # paths completed the series with NO ratings — leaving was strictly safer
    # than losing).
    other_team_existing_wins = (s["t1_series_wins"] or 0) if other_team == 1 else (s["t2_series_wins"] or 0)
    # "Clear case" (Sid's rule): auto-forfeit ONLY when the non-DC team was already
    # up a game AND real play happened in the abandoned game (>=2 points). A break/
    # restart DC (little or no play) or an even series is NOT auto-decided — it drops
    # to dc_incomplete below for manual resolution in the mod admin panel, so a 2v2
    # that breaks and needs a restart never auto-penalizes anyone.
    if (other_team_existing_wins or 0) >= 1 and total_points >= 2:
        # Record a synthetic forfeit game for history parity.
        await db.execute(
            text("""INSERT INTO team_matches
                       (series_id, t1a_id, t1b_id, t2a_id, t2b_id,
                        t1_rounds_won, t2_rounds_won, t1_points_total, t2_points_total,
                        winner_team, dc_player_id, dc_at, ended_at, photon_room_id)
                   VALUES (:sid, :t1a, :t1b, :t2a, :t2b, 0, 0, :t1p, :t2p,
                           :wt, :dpid, NOW(), NOW(), 'dc_leadforfeit')"""),
            {"sid": sid_uuid, "t1a": s["t1a_id"], "t1b": s["t1b_id"],
             "t2a": s["t2a_id"], "t2b": s["t2b_id"], "t1p": t1_points_total or 0,
             "t2p": t2_points_total or 0, "wt": other_team, "dpid": dc_pid},
        )
        new_ratings = await _complete_team_series_with_ratings(
            db, sid_uuid, other_team, "dc_leadforfeit", dc_pid=dc_pid,
        )
        await db.commit()
        return {"status": "completed", "winner_team": other_team,
                "reason": "dc_leadforfeit", "new_ratings": new_ratings}

    # Not a clear-cut forfeit (non-DC team wasn't already up a game, or too little
    # was played to count). Per the 2v2 manual-control policy — a game can break and
    # need a restart, and we never auto-penalize for that — record who left and mark
    # the series INCOMPLETE for an admin to award/void from the mod's admin panel.
    # No auto-forfeit, no rating/economy effect. Games reported before the DC stand;
    # the admin decides the series outcome from the recent-series log.
    await db.execute(
        text("""
            UPDATE team_series
               SET status = 'dc_incomplete',
                   dc_player_id = :dpid,
                   dc_team_remaining = :ot,
                   invalidation_reason = 'dc_manual_pending'
             WHERE id = :sid AND status IN ('active', 'dc_paused')
        """),
        {"sid": sid_uuid, "dpid": dc_pid, "ot": other_team},
    )
    await db.commit()
    return {
        "status": "dc_incomplete",
        "dc_team_remaining": other_team,
        "reason": "awaiting_admin_resolution",
    }


# ── 2v2 series continuation (recording-gap fix) ─────────────────────────────
# When four players keep playing in the same cr_ff room past the first BO3 (which
# locks at first-to-2), the client had no active series to report to and later games
# were dropped entirely. The reporter (lowest Steam ID) calls this at game start to
# open a fresh 'active' series for the SAME four + room, so games 4+ of a sitting
# record as ranked. Anti-abuse: the four must have a real recent series together
# (the sitting's series 1) and the caller must be the lowest Steam ID. HMAC over the
# shared mod secret (canonical below).
class _TeamContinuationReq(BaseModel):
    reporter_steam_id: str
    room_id: str
    region: str | None = None
    t1a_steam: str
    t1b_steam: str
    t2a_steam: str
    t2b_steam: str
    hmac_signature: str | None = None


_CONTINUATION_WINDOW_MINUTES = 60  # prior series must have completed this recently


@app.post("/api/v1/team/series/continuation", tags=["Team Matches"])
async def team_series_continuation(req: _TeamContinuationReq, db: AsyncSession = Depends(get_db)):
    canonical = (
        f"team-continuation:{req.t1a_steam}:{req.t1b_steam}:"
        f"{req.t2a_steam}:{req.t2b_steam}:{req.room_id}:{req.reporter_steam_id}"
    )
    if not _verify_action_sig(canonical, req.hmac_signature):
        raise HTTPException(403, "Bad continuation signature")

    steams = [req.t1a_steam, req.t1b_steam, req.t2a_steam, req.t2b_steam]
    if len(set(steams)) != 4:
        raise HTTPException(400, "Need four distinct players")
    # Round-19 find 2: identity locks (sorted) so the ban gate below is
    # ordered against ban issuance, not a point read.
    for _cc_sid in sorted(steams):
        await db.execute(text("SELECT pg_advisory_xact_lock(hashtext(:sid))"),
                         {"sid": _cc_sid})
    # Round-18 find 3: no continuation with a banned member — the sitting
    # ends for everyone rather than minting a new post-ban active pairing.
    for _cc_sid in steams:
        if (await _is_banned(db, _cc_sid)) is not None:
            raise HTTPException(409, "Continuation refused: a participant is banned")
    if req.reporter_steam_id not in steams:
        raise HTTPException(403, "Reporter not part of the match")
    numeric = [s for s in steams if s.isdigit()]
    if numeric and req.reporter_steam_id != min(numeric, key=int):
        raise HTTPException(403, "Reporter must be the lowest Steam ID")

    rows = (await db.execute(
        select(Player.id, Player.steam_id).where(Player.steam_id.in_(steams))
    )).all()
    id_by_steam = {r.steam_id: r.id for r in rows}
    if len(id_by_steam) != 4:
        raise HTTPException(404, "One or more players not registered")
    ids = list(id_by_steam.values())

    # A live series for this exact four already exists → return it (idempotent: covers
    # series 1 still in progress, and a double-fire from client retries).
    live = (await db.execute(text("""
        SELECT id, photon_room_id FROM team_series
         WHERE status IN ('active', 'dc_paused', 'dc_incomplete')
           AND t1a_id = ANY(:ids) AND t1b_id = ANY(:ids)
           AND t2a_id = ANY(:ids) AND t2b_id = ANY(:ids)
         ORDER BY created_at DESC LIMIT 1
    """), {"ids": ids})).mappings().first()
    if live is not None:
        # Round-20 find 4: the idempotent return must honor the same room-
        # continuity bar as the prior-series branch below — a caller naming
        # an unrelated room must not be handed a live sitting's series id.
        # Every legit continuation runs in the sitting's issued room (DC
        # resume re-issues AND rewrites the stored room, so they still
        # match); NULL stored room = pre-issuance/legacy, falls through.
        _live_room = (live["photon_room_id"] or "").strip()
        if _live_room and (req.room_id or "").strip() != _live_room:
            raise HTTPException(409, "Continuation refused: room does not match the sitting")
        return {"series_id": str(live["id"]), "status": "existing"}

    # Otherwise require a recent COMPLETED series for the same four (proves this is a
    # real rematch of an ongoing sitting, not a fabricated pairing).
    prior = (await db.execute(text("""
        SELECT completed_at, t1a_id, t1b_id, t2a_id, t2b_id, photon_room_id
          FROM team_series
         WHERE status = 'completed'
           AND t1a_id = ANY(:ids) AND t1b_id = ANY(:ids)
           AND t2a_id = ANY(:ids) AND t2b_id = ANY(:ids)
         ORDER BY completed_at DESC LIMIT 1
    """), {"ids": ids})).mappings().first()
    if prior is None:
        raise HTTPException(409, "No prior series for these players")
    if prior["completed_at"] is not None:
        age_min = (datetime.now(timezone.utc) - prior["completed_at"]).total_seconds() / 60.0
        if age_min > _CONTINUATION_WINDOW_MINUTES:
            raise HTTPException(409, "Prior series too old to continue")
    # PARTITION preservation (round-18 find 3): `= ANY(:ids)` alone is
    # set-blind — the same four players in a DIFFERENT team split (A+C vs
    # B+D after A+B vs C+D) is a genuinely NEW pairing, not a continuation.
    # The requested split must equal the prior's, sides swapped or not.
    _prior_t1 = {prior["t1a_id"], prior["t1b_id"]}
    _new_t1 = {id_by_steam[s] for s in sorted([req.t1a_steam, req.t1b_steam])}
    _new_t2 = {id_by_steam[s] for s in sorted([req.t2a_steam, req.t2b_steam])}
    if _prior_t1 != _new_t1 and _prior_t1 != _new_t2:
        raise HTTPException(409, "Continuation refused: team split differs from the prior series")
    # ROOM CONTINUITY (round-19 find 5): a 2v2 sitting lives in ONE Photon
    # room — the server issued it at lock time, rematches replay inside it —
    # so a genuine continuation must name the room the prior series carries.
    # This is the structural "existing sitting" proof: the caller can only
    # know a server-issued room by being in the sitting. Legacy priors with
    # no stored room (pre-binding rows) fall through unproven — a shrinking,
    # documented residue.
    _prior_room = (prior["photon_room_id"] or "").strip()
    if _prior_room and (req.room_id or "").strip() != _prior_room:
        raise HTTPException(409, "Continuation refused: room does not match the sitting")

    # Preserve the sitting's team assignment; canonicalize within team by Steam ID so
    # t1a/t1b/t2a/t2b match what the match-report path computes.
    t1 = sorted([req.t1a_steam, req.t1b_steam])
    t2 = sorted([req.t2a_steam, req.t2b_steam])
    # NOTE: module-level `uuid`, NOT `uuid_mod` — that alias only exists as a
    # function-local import in the queue endpoints. Referencing it here raised
    # NameError -> 500 on every continuation-create, which silently dropped all
    # games after the first series of a 2v2 sitting (bug #70). The idempotent
    # "existing" branch above returns earlier, which is why smoke tests passed.
    new_id = uuid.uuid4()
    await db.execute(text("""
        INSERT INTO team_series (id, t1a_id, t1b_id, t2a_id, t2b_id,
                                 status, was_auto_balanced, photon_room_id, region, created_at)
        VALUES (:sid, :t1a, :t1b, :t2a, :t2b, 'active', false, :room, :region, NOW())
    """), {
        "sid": new_id,
        "t1a": id_by_steam[t1[0]], "t1b": id_by_steam[t1[1]],
        "t2a": id_by_steam[t2[0]], "t2b": id_by_steam[t2[1]],
        "room": (req.room_id or "")[:64], "region": (req.region or "")[:8] or None,
    })
    await db.commit()
    print(f"[TEAM-CONTINUATION] created {new_id} for {steams} room={req.room_id}")
    return {"series_id": str(new_id), "status": "created"}


# ══════════════════════════════════════════════════════════════════════════
# 1v2 (solo vs duo) — parallel pipeline, launched UNSCORED (Sid July 13 #2).
# Mirrors the 2v2 machinery + its hard-won learnings: consent queue skips the
# Elo band (#127), continuation closes the recording gap from day one (#70/#135
# — uses module-level `uuid`, never a function-local alias), the completion
# helper takes FOR UPDATE + re-checks status to survive concurrent DC/report
# callers (#78), room ids are per-game suffixed so replays dedup. No ratings
# are applied yet; every match records the full replay surface for a later
# retroactive Glicko turn-on.
# ══════════════════════════════════════════════════════════════════════════

OVT_MATCH_XP_BASE   = 500          # a touch under 2v2's 600 (games are shorter)
OVT_MATCH_WIN_MULT  = 1.5
OVT_SERIES_WIN_GOLD = 40
OVT_SERIES_LOSS_GOLD = 20
OVT_READY_TIMEOUT_SECONDS = 90     # matches team ready window (#51)

# ── 1v2 difficulty scaling (bug #129) ────────────────────────────────────
# 1v2 shipped as the ONLY mode with no opponent-tier multiplier and an
# un-scaled series bonus, which put it ~40-50% below 2v2/FFA per minute of
# play: measured at prod average game lengths (1v2 487s, 2v2 544s, FFA 643s)
# the old numbers paid the solo 3.33 g/min and a duo member 1.85, against
# 2v2's 5.57 winner / 3.03 loser and FFA's 6.91 first / 1.49 last.
#
# The lift comes from multipliers, NOT from raising the bases — deliberately,
# because 1v2 has no AFK detector (the 1v1 signal is cards_picked == 0 and has
# no 1v2 analogue), and a flat per-game floor is the farmable surface (#58).
# Everything below is multiplicative on XP, so an idle game still pays ~nothing.
#
# Factors are the four Sid asked for: harder seat, handicap off, stronger
# opponents, and opponents who are actually top of the 1v2 board.
OVT_SOLO_MULT           = 1.5   # the solo seat fights two players
OVT_NO_EXTRA_PICK_MULT  = 1.20  # solo with the extra-pick handicap OFF = hardest config
OVT_EXTRA_PICK_DUO_MULT = 1.10  # mirror: the duo facing a BUFFED solo has it harder
OVT_PODIUM_OPP_MULT     = 1.35  # any OPPOSING player sits in the 1v2 leaderboard top 3
OVT_DIFFICULTY_CAP      = 4.0   # ceiling on the product (GM+solo+no-pick+podium = 7.29 raw)


def _ovt_difficulty_mult(is_solo: bool, extra_pick: bool,
                         opp_rating: float | None, opp_podium: bool):
    """(multiplier, [human labels]) for one 1v2 seat.

    `opp_rating` is the opponents' average **1v1** Glicko. 1v2 has no rating of
    its own (`glicko_ratings_1v2.rating` is 1500/350 for every row and nothing
    writes it), and the 1v2 leaderboard already shows 1v1 elo as the mode's
    context rating — so it is both the only implementable signal and the one
    players already see. Sid's ask says "inline with 1v1" explicitly.
    Note this diverges on purpose from FFA, which forces x1.0 while unranked.
    """
    m = 1.0
    labels: list[str] = []
    if is_solo:
        m *= OVT_SOLO_MULT
        labels.append(f"Solo seat x{OVT_SOLO_MULT:g}")
        if not extra_pick:
            m *= OVT_NO_EXTRA_PICK_MULT
            labels.append(f"No extra pick x{OVT_NO_EXTRA_PICK_MULT:g}")
    elif extra_pick:
        m *= OVT_EXTRA_PICK_DUO_MULT
        labels.append(f"Buffed solo x{OVT_EXTRA_PICK_DUO_MULT:g}")
    t, tlabel = _tier_mult_for(opp_rating)
    m *= t
    if t > 1.0:
        labels.append(f"{tlabel} opp x{t:g}")
    if opp_podium:
        m *= OVT_PODIUM_OPP_MULT
        # Must NOT contain the substring "Top 3" — shipped v1.33.0 clients
        # Contains-match that and render a defunct label (see the 1v1 series
        # gold block's identical warning).
        labels.append(f"Podium opp x{OVT_PODIUM_OPP_MULT:g}")
    if m > OVT_DIFFICULTY_CAP:
        m = OVT_DIFFICULTY_CAP
        labels.append(f"capped x{OVT_DIFFICULTY_CAP:g}")
    return m, labels


# 1v2 podium (factor iv). Runs the SAME query shape as GET
# /ovt/leaderboard?role=combined — same UNION ALL over ovt_matches, same
# invalidated_at/deleted_at filters, same `games DESC, win-rate DESC` ordering,
# same >= 1 game floor — so the player DISPLAYED at #3 is the player whose defeat
# pays the bonus (#153). Review-noted caveat: the 60s TTL means a result that
# just reshuffled the standings can leave up to 60s where the rewarded top-3 and
# the displayed top-3 differ. That is accepted, and identical to how the 1v1
# podium (which gates real series gold doubling) has always behaved. Deliberately
# NOT _podium_map (1v1-only) and deliberately does NOT grant title_podium: that
# shop item is defined as the 1v1 podium, and cross-granting would silently
# widen an existing cosmetic's meaning.
_ovt_podium_cache: dict = {"at": 0.0, "ids": []}

_OVT_PODIUM_QUERY = """
    WITH per_player AS (
        SELECT pid, SUM(played) AS games, SUM(won) AS wins
        FROM (
            SELECT solo_id AS pid, 1 AS played,
                   CASE WHEN winner_side = 1 THEN 1 ELSE 0 END AS won
              FROM ovt_matches WHERE invalidated_at IS NULL
            UNION ALL
            SELECT duo_a_id, 1, CASE WHEN winner_side = 2 THEN 1 ELSE 0 END
              FROM ovt_matches WHERE invalidated_at IS NULL
            UNION ALL
            SELECT duo_b_id, 1, CASE WHEN winner_side = 2 THEN 1 ELSE 0 END
              FROM ovt_matches WHERE invalidated_at IS NULL
        ) u GROUP BY pid
    )
    SELECT pp.pid
      FROM per_player pp
      JOIN players p ON p.id = pp.pid
     WHERE p.deleted_at IS NULL AND pp.games >= 1
     ORDER BY pp.games DESC, pp.wins::float / NULLIF(pp.games, 0) DESC NULLS LAST
     LIMIT 3
"""


async def _ovt_podium_ids(db: AsyncSession) -> list:
    """[1st, 2nd, 3rd] player ids as strings. 60s TTL; a failure serves the
    stale copy and never raises — a podium lookup must not fail a match report."""
    now = time.monotonic()
    if now - _ovt_podium_cache["at"] > 60:
        try:
            # SAVEPOINT-wrapped: this runs inside the caller's match-report
            # transaction, and under asyncpg a caught statement error would
            # otherwise abort that transaction and 500 the report (#235). The
            # savepoint is what makes "serve the stale copy" actually work.
            async with db.begin_nested():
                rows = (await db.execute(text(_OVT_PODIUM_QUERY))).scalars().all()
            _ovt_podium_cache["ids"] = [str(r) for r in rows]
        except Exception as ex:
            print(f"[OVT-PODIUM] cache refresh failed: {ex}")
        _ovt_podium_cache["at"] = now
    return _ovt_podium_cache["ids"]


def _verify_ovt_hmac(report: OvtMatchReport) -> bool:
    """10-field canonical: solo:duo_a:duo_b:sr:dr:is_ranked:reporter:room:winner_side:series."""
    if not MATCH_HMAC_SECRET:
        return True
    if not report.hmac_signature:
        print("[OVT-HMAC] no signature provided")
        return False
    msg = (
        f"{report.solo.steam_id}:{report.duo_a.steam_id}:{report.duo_b.steam_id}:"
        f"{report.solo_rounds_won}:{report.duo_rounds_won}:"
        f"{str(report.is_ranked).lower()}:{report.reported_by_steam_id}:"
        f"{report.photon_room_id or ''}:{report.winner_side}:{report.series_id}"
    )
    expected = hmac.new(MATCH_HMAC_SECRET.encode(), msg.encode(), hashlib.sha256).hexdigest()
    ok = hmac.compare_digest(report.hmac_signature, expected)
    if not ok:
        print(f"[OVT-HMAC] mismatch. canonical='{msg}'")
    return ok


class _OvtQueueJoinReq(BaseModel):
    steam_id: str
    display_name: str = "Player"
    region: str | None = None
    preferred_side: int = 0            # 0 none, 1 solo, 2 duo
    solo_extra_pick: bool = False
    hmac_signature: str | None = None


@app.post("/api/v1/ovt/queue/join", tags=["1v2 Queue"])
async def ovt_queue_join(req: _OvtQueueJoinReq, request: Request, db: AsyncSession = Depends(get_db)):
    """Join the 1v2 manual lobby (consent queue — no Elo band). Idempotent per
    player; re-joining refreshes preferences and the poll timestamp."""
    await _check_steam_session(request, req.steam_id, db)
    # Identity gate (round-14 find 1, subsumes the round-13 usage-site ban
    # check): lock + ban/tombstone re-read under it.
    await _enrollment_identity_gate(db, req.steam_id)
    _presence_touch(req.steam_id)
    player = (await db.execute(select(Player).where(Player.steam_id == req.steam_id))).scalar_one_or_none()
    if player is None:
        raise HTTPException(404, "Player not registered")
    # Cross-queue guard (Codex post-release find 1): the auto-rejoin path must
    # not recreate a row the lock-time eviction removed — see /queue/join.
    _other = await _locked_in_other_queue(db, player.id, "ovt_queue")
    if _other:
        raise HTTPException(status_code=409,
                            detail="You're in a live match in another mode - finish it first")
    # Same-mode husk clear as FFA (migration 174): the lease bounds the
    # CROSS-mode block, but 1v2's own upsert preserves a locked row's
    # lifecycle, so without this a player whose lease has lapsed stays
    # unqueueable in 1v2 specifically — the permanent half of the strand, just
    # in a different mode.
    if await _lease_live_mode(db, player.id) is None:
        _cleared = (await db.execute(text(
            "UPDATE ovt_queue SET status='searching', series_id=NULL, side_assigned=NULL,"
            "       room_name=NULL, room_region=NULL, matched_at=NULL"
            " WHERE player_id = :pid AND status <> 'searching'"
            " RETURNING status"), {"pid": player.id})).scalar()
        if _cleared:
            print(f"[LEASE] 1v2 join cleared an unleased '{_cleared}' husk for {req.steam_id}")
    # Snapshot ratings (1v2 rating if it exists, else 1v1 as fallback ordering hint).
    g = (await db.execute(text(
        "SELECT rating, rating_deviation, completed_series FROM glicko_ratings_1v2 WHERE player_id = :pid"
    ), {"pid": player.id})).mappings().first()
    rating = g["rating"] if g else 1500.0
    rd = g["rating_deviation"] if g else 350.0
    cs = g["completed_series"] if g else 0
    # fallback_rating is the player's 1v1 elo — the 1v2 pool is all-1500 until
    # ranked launches, so the 1v1 number is the only meaningful ordering hint.
    g1 = (await db.execute(text(
        "SELECT rating FROM glicko_ratings WHERE player_id = :pid"
    ), {"pid": player.id})).mappings().first()
    fallback = float(g1["rating"]) if g1 and g1["rating"] is not None else 1500.0
    side = req.preferred_side if req.preferred_side in (0, 1, 2) else 0
    await db.execute(text("""
        INSERT INTO ovt_queue (player_id, steam_id, display_name, rating, rating_deviation,
                               completed_series, fallback_rating, region, queue_type,
                               preferred_side, solo_extra_pick, status, joined_at, last_polled)
        VALUES (:pid, :sid, :dn, :r, :rd, :cs, :fr, :reg, 'manual', :side, :sep, 'searching', NOW(), NOW())
        ON CONFLICT (player_id) DO UPDATE SET
            display_name = EXCLUDED.display_name, region = EXCLUDED.region,
            preferred_side = EXCLUDED.preferred_side, solo_extra_pick = EXCLUDED.solo_extra_pick,
            -- Bug #109 (same contract as the FFA join): rejoin of a SEARCHING
            -- row resets the search clock and rating snapshot; LOCKED rows
            -- keep both (Codex find 7 — the lock owns its snapshot).
            rating = CASE WHEN ovt_queue.status = 'searching'
                          THEN EXCLUDED.rating ELSE ovt_queue.rating END,
            rating_deviation = CASE WHEN ovt_queue.status = 'searching'
                          THEN EXCLUDED.rating_deviation ELSE ovt_queue.rating_deviation END,
            completed_series = CASE WHEN ovt_queue.status = 'searching'
                          THEN EXCLUDED.completed_series ELSE ovt_queue.completed_series END,
            fallback_rating = CASE WHEN ovt_queue.status = 'searching'
                          THEN EXCLUDED.fallback_rating ELSE ovt_queue.fallback_rating END,
            last_polled = NOW(),
            joined_at = CASE WHEN ovt_queue.status = 'searching'
                             THEN NOW() ELSE ovt_queue.joined_at END
    """), {"pid": player.id, "sid": req.steam_id, "dn": req.display_name[:64], "r": rating,
           "rd": rd, "cs": cs, "fr": fallback, "reg": (req.region or "")[:8] or None,
           "side": side, "sep": req.solo_extra_pick})
    await db.commit()
    n = (await db.execute(text("SELECT COUNT(*) FROM ovt_queue WHERE status = 'searching'"))).scalar() or 0
    return {"status": "ok", "queue_count": int(n), "preferred_side": side}


@app.post("/api/v1/ovt/queue/leave", tags=["1v2 Queue"])
async def ovt_queue_leave(request: Request, steam_id: str = Query(...),
                          cause: str = Query("", max_length=16),
                          db: AsyncSession = Depends(get_db)):
    """Leave the 1v2 queue. If the leaver was LOCKED into a series that never
    produced a game, the lock is dissolved: the series is canceled and the
    other two lobby rows reset to searching. Without this, a no-show/failed
    join left permanent 'ready_join' husk rows and a forever-'active' series
    (the leave endpoint used to delete only the leaver's own row). A series
    with >=1 reported game is left alone — that's a mid-series leave and the
    match pipeline owns its lifecycle."""
    # A8: session enforcement — HMAC alone is forgeable by anyone with the DLL secret.
    await _check_steam_session(request, steam_id, db)
    await _lease_release_by_steam(db, steam_id)
    me = await _lock_queue_group_for_player(db, "ovt_queue", steam_id)
    if me is None:
        await db.commit()
        return {"status": "ok"}
    dissolved = False
    if me["status"] in ("ready_join", "matched") and me["series_id"] is not None:
        srow = (await db.execute(text(
            "SELECT s.status,"
            "       (SELECT COUNT(*) FROM ovt_matches m WHERE m.series_id = s.id) AS games"
            "  FROM ovt_series s WHERE s.id = :sid FOR UPDATE"
        ), {"sid": me["series_id"]})).mappings().first()
        # July 30 lifecycle audit item 2: "zero recorded games" is true for the
        # ENTIRE duration of live game 1 (reports land at game END), so one
        # player quitting 30 minutes into game 1 used to dissolve the series
        # under the other two and the reporter's result then 409'd. The
        # in_match heartbeat veto separates "failed assembly" (dissolve, as
        # before) from "game 1 is live" (leave the series to the match
        # pipeline; only the leaver's own row is deleted below).
        # Round-8 gate, same rule as the FFA leave: a PRE-BOOT zero-game lock
        # during the post-restart evidence window is INDETERMINATE — take the
        # departure path (series stays; the guarded janitor cleans a real
        # dead assembly once evidence matures). Post-boot locks keep the
        # one-shot dissolution (#270a).
        # Round-9 gate: same cause-fencing as the FFA leave — an exit from
        # inside the ovt_ ROOM is never assembly failure.
        _ovt_in_room_exit = cause == "in_room_exit"
        _ovt_startup_indeterminate = False
        if (not _ovt_in_room_exit
                and srow is not None and srow["status"] == "active"
                and int(srow["games"] or 0) == 0
                and not _in_match_evidence_trustworthy()
                and not _group_game_positively_live(str(me["series_id"]))):
            _ovt_locked_at = (await db.execute(text(
                "SELECT MAX(matched_at) FROM ovt_queue WHERE series_id = :sid"
            ), {"sid": me["series_id"]})).scalar()
            _ovt_startup_indeterminate = (_ovt_locked_at is None
                                          or _ovt_locked_at <= _PROCESS_STARTED_WALL)
        if (srow is not None and srow["status"] == "active"
                and int(srow["games"] or 0) == 0
                and not _ovt_in_room_exit
                and not _ovt_startup_indeterminate
                and not _group_game_positively_live(str(me["series_id"]))):
            await db.execute(text(
                "UPDATE ovt_series SET status='canceled', invalidation_reason='assembly_timeout',"
                "       invalidated_at=NOW() WHERE id=:sid AND status='active'"
            ), {"sid": me["series_id"]})
            await db.execute(text("""
                UPDATE ovt_queue SET status='searching', series_id=NULL, side_assigned=NULL,
                       room_name=NULL, room_region=NULL, matched_at=NULL, joined_at=NOW()
                 WHERE series_id = :sid AND player_id != :pid
            """), {"sid": me["series_id"], "pid": me["player_id"]})
            dissolved = True
            print(f"[OVT-LOCK] lock dissolved by leave (series {me['series_id']}, leaver {steam_id})")
        elif srow is not None and srow["status"] == "active" and int(srow["games"] or 0) == 0:
            print(f"[OVT-LOCK] mid-game-1 leave by {steam_id} — series "
                  f"{me['series_id']} left to the match pipeline")
    await db.execute(text(
        "DELETE FROM ovt_queue WHERE player_id = :pid"
    ), {"pid": me["player_id"]})
    await db.commit()
    return {"status": "ok", "lock_dissolved": dissolved}


@app.get("/api/v1/ovt/queue/recent-joins", tags=["1v2 Queue"])
async def ovt_queue_recent_joins(seconds: int = Query(20), db: AsyncSession = Depends(get_db)):
    """Players who joined the 1v2 lobby in the last N seconds. Drives the
    Discord #ranked-looking-for-people beacon, same as the 1v1 and 2v2
    queues. `rating` is the 1v1 elo snapshot (fallback_rating) — the 1v2
    pool is all-1500 until ranked lands, so it's the only meaningful number
    to show. queue_size counts only FRESH searching rows (same liveness the
    lock uses) so the beacon never advertises ghost lobbies."""
    result = await db.execute(text("""
        SELECT q.display_name, q.steam_id, q.fallback_rating, q.joined_at,
               CASE WHEN p.show_discord THEN p.discord_display_name END AS discord_display_name
          FROM ovt_queue q
          LEFT JOIN players p ON p.steam_id = q.steam_id
         WHERE q.status = 'searching'
           AND q.joined_at > NOW() - INTERVAL '1 second' * :secs
         ORDER BY q.joined_at DESC
    """), {"secs": seconds})
    rows = result.mappings().all()
    cnt = (await db.execute(text(
        "SELECT COUNT(*) FROM ovt_queue WHERE status = 'searching'"
        "   AND last_polled > NOW() - INTERVAL '75 seconds'"
    ))).scalar() or 0
    return {
        "joins": [
            {"display_name": r["display_name"], "steam_id": r["steam_id"],
             "rating": int(round(r["fallback_rating"] or 1500)),
             "joined_at": r["joined_at"].isoformat() if r["joined_at"] else None,
             "discord_display_name": r["discord_display_name"]}
            for r in rows
        ],
        "queue_size": int(cnt),
    }


@app.get("/api/v1/ovt/queue/list", tags=["1v2 Queue"])
async def ovt_queue_list(db: AsyncSession = Depends(get_db)):
    """Snapshot of everyone in the 1v2 lobby — powers the "who's in the lobby"
    panel on the F5 1v2 tab (same surface the 2v2 tab gets from
    /team/queue/list). 1v2 is unscored at launch, so the context ratings worth
    showing are the player's 1v1 and 2v2 elos — the 1v2 pool is all-1500 until
    ranked lands. Stale searching rows (client crashed/killed, stopped polling)
    are filtered out so the panel never shows ghosts."""
    rows = (await db.execute(text("""
        SELECT q.steam_id, q.display_name, q.preferred_side, q.solo_extra_pick,
               q.status, q.side_assigned, q.region, q.joined_at,
               gr.rating AS rating_1v1,
               g2.rating AS rating_2v2, COALESCE(g2.completed_series, 0) AS cs_2v2
          FROM ovt_queue q
          LEFT JOIN glicko_ratings gr ON gr.player_id = q.player_id
          LEFT JOIN glicko_ratings_2v2 g2 ON g2.player_id = q.player_id
         WHERE (q.status = 'searching' AND q.last_polled > NOW() - INTERVAL '75 seconds')
            OR (q.status != 'searching'
                AND COALESCE(q.matched_at, q.joined_at) > NOW() - INTERVAL '3 hours')
         ORDER BY q.joined_at ASC
    """))).mappings().all()
    now = datetime.now(timezone.utc)
    out = []
    for r in rows:
        # 2v2 elo only counts once the player has a completed 2v2 series —
        # a bare default-1500 glicko row is noise, not information.
        has_2v2 = (r["cs_2v2"] or 0) > 0 and r["rating_2v2"] is not None
        out.append({
            "steam_id": r["steam_id"],
            "display_name": r["display_name"],
            "rating_1v1": int(round(r["rating_1v1"])) if r["rating_1v1"] is not None else 1500,
            "rating_2v2": int(round(r["rating_2v2"])) if has_2v2 else 0,
            "preferred_side": int(r["preferred_side"] or 0),
            "solo_extra_pick": bool(r["solo_extra_pick"]),
            "status": r["status"],
            "side_assigned": int(r["side_assigned"]) if r["side_assigned"] is not None else 0,
            "wait_seconds": int((now - r["joined_at"]).total_seconds()) if r["joined_at"] else 0,
            "region": r["region"],
        })
    return {"queuers": out, "count": len(out)}


@app.get("/api/v1/ovt/queue/poll/{steam_id}", tags=["1v2 Queue"])
async def ovt_queue_poll(steam_id: str, request: Request, db: AsyncSession = Depends(get_db)):
    """Poll the 1v2 queue. When 3 searching players are present, the lowest
    Steam ID locks the match: assigns 1 solo + 2 duo (honoring preferences,
    else join order), creates the series + room, and flips all three to
    'ready_join'. SELECT FOR UPDATE SKIP LOCKED (#34) prevents duplicate rooms.

    Session-bound (Codex sitting-over review find 1, FFA-poll parity): this
    poll refreshes last_polled for the CLAIMED steam_id, and the new
    all-members-polling inference makes that a destructive input — an
    unauthenticated caller could forge freshness for a whole locked trio and
    cancel their live series. Enforcement inherits the steam-auth arming
    rollout; unarmed accounts remain soft (documented residual until
    STEAM_AUTH_ENFORCE fully arms)."""
    await _check_steam_session(request, steam_id, db)
    _presence_touch(steam_id)
    locked = await _lock_queue_group_for_player(db, "ovt_queue", steam_id)
    if locked is None:
        return {"status": "not_in_queue", "queue_count": 0}
    me = (await db.execute(text(
        "SELECT q.*, p.id AS pid FROM ovt_queue q JOIN players p ON p.id = q.player_id "
        "WHERE q.steam_id = :sid"
    ), {"sid": steam_id})).mappings().first()
    if me is None:
        await db.commit()
        return {"status": "not_in_queue", "queue_count": 0}
    await db.execute(
        text("UPDATE ovt_queue SET last_polled = NOW() WHERE player_id = :pid"),
        {"pid": me["player_id"]},
    )

    # Prune ghosts: a crashed/killed client stops polling but its 'searching'
    # row stays. Clients poll every ~2s; the 75s window survives a backend
    # rebuild (~30s of connection-refused during /deploy-backend) without the
    # first poller back mass-evicting every other live queuer. The SKIP LOCKED
    # sub-select avoids the two-way deadlock two concurrently-recovering
    # pollers would otherwise hit (each holds its own-row lock from the
    # last_polled UPDATE while DELETEing the other's row). Ghost rows can't
    # lock into a series meanwhile — the lock query filters on fresh
    # last_polled. The second DELETE sweeps ancient locked husks (a 3h-old
    # lock is dead by any definition; live-series rows are hours younger).
    await db.execute(text("""
        DELETE FROM ovt_queue WHERE player_id IN (
            SELECT player_id FROM ovt_queue
             WHERE status = 'searching' AND last_polled < NOW() - INTERVAL '75 seconds'
             FOR UPDATE SKIP LOCKED)
    """))
    # Own-group exclusion — same rationale as the FFA poll's 3h sweep
    # (Codex sitting-over review find 4).
    await db.execute(text("""
        DELETE FROM ovt_queue WHERE player_id IN (
            SELECT player_id FROM ovt_queue
             WHERE status != 'searching' AND matched_at IS NOT NULL
               AND matched_at < NOW() - INTERVAL '3 hours'
               AND series_id IS DISTINCT FROM :my_series
             FOR UPDATE SKIP LOCKED)
    """), {"my_series": me["series_id"]})

    # Absolute 30-min searching cap (July 28, Sid item 1 — parity with the
    # 1v1/2v2 polls). Explicit 'expired' status so the client shows WHY the
    # queue ended instead of auto-rejoining on a bare not_in_queue.
    if me["status"] == "searching" and me["joined_at"] is not None:
        _waited = (datetime.now(timezone.utc) - me["joined_at"]).total_seconds()
        if _waited > 30 * 60:
            await db.execute(text("DELETE FROM ovt_queue WHERE player_id = :pid"),
                             {"pid": me["player_id"]})
            await db.commit()
            return {"status": "expired", "queue_count": 0}

    # Already locked → report my slot + lobby.
    if me["status"] in ("ready_join", "matched") and me["series_id"] is not None:
        # Self-heal a dead lock (learning #33 family — the state machine must
        # never re-feed clients a husk): if the series was completed/canceled
        # elsewhere, reset immediately. The zero-games age check is a LAST
        # resort at 10 minutes: game 1 of a live series has zero ovt_matches
        # rows for its whole duration, and a locked player re-clicking Join
        # mid-game polls this branch — a 2-minute threshold canceled LIVE
        # series (review-confirmed critical). Abandoned locks are normally
        # dissolved much earlier by the leave endpoint (watchdog bails and
        # queue-join failures now call /ovt/queue/leave client-side).
        srow = (await db.execute(text(
            "SELECT s.status, s.created_at,"
            "       (SELECT COUNT(*) FROM ovt_matches m WHERE m.series_id = s.id) AS games"
            "  FROM ovt_series s WHERE s.id = :sid"
        ), {"sid": me["series_id"]})).mappings().first()
        lock_age = ((datetime.now(timezone.utc) - me["matched_at"]).total_seconds()
                    if me["matched_at"] is not None else 0)
        # Presence gate — same rule as the FFA dead-check (bug #114 item 3):
        # a zero-game old lock is only dead when NO member's always-on
        # presence ping has landed within its 3-minute TTL. A live 1v2 game 1
        # longer than 10 minutes must never be cancelled out from under the
        # players again.
        zero_game_stale = (srow is not None and srow["status"] == "active"
                           and int(srow["games"] or 0) == 0 and lock_age > 600)
        members_online = False
        if zero_game_stale and not _in_match_evidence_trustworthy():
            # Round-6 gate find, same hole as the FFA branch: a fresh
            # process has an EMPTY presence map — absence proves nothing for
            # ~210s after boot, and this recurring poll can safely defer
            # (#270 recurring-actor veto rule).
            members_online = True
        elif zero_game_stale:
            mem_sids = (await db.execute(text(
                "SELECT steam_id FROM ovt_queue WHERE series_id = :sid"
            ), {"sid": me["series_id"]})).scalars().all()
            members_online = any(_presence_is_online(s) for s in mem_sids)
        dead = (srow is None or srow["status"] != "active"
                or (zero_game_stale and not members_online))
        # ── Sitting-over self-heal — same two rules as the FFA locked branch
        # (July 28 trapped-lobby incident; also the bug #85 class, "1v2 keeps
        # putting me back in the same match"). The queue-poll is the inverse
        # in-game heartbeat: all members polling = nobody is in a game.
        sitting_over = False
        assembly_failed = False
        if not dead and srow is not None and srow["status"] == "active":
            mem_polls = (await db.execute(text(
                "SELECT COUNT(*) AS total,"
                "       COUNT(*) FILTER (WHERE last_polled > NOW() - INTERVAL '90 seconds') AS fresh"
                "  FROM ovt_queue WHERE series_id = :sid"
            ), {"sid": me["series_id"]})).mappings().first()
            all_polling = (mem_polls is not None and int(mem_polls["total"] or 0) > 0
                           and int(mem_polls["total"]) == int(mem_polls["fresh"]))
            if all_polling and int(srow["games"] or 0) > 0:
                last_game = (await db.execute(text(
                    "SELECT MAX(ended_at) FROM ovt_matches WHERE series_id = :sid"
                ), {"sid": me["series_id"]})).scalar()
                # 900s, not 300s - the FFA copy of this rule (see the locked
                # branch in the FFA poll) killed a live sitting between games on
                # July 30, and 1v2 runs the identical rule against a BO3 whose
                # between-games gap is just as ordinary. Prod already carries a
                # likely victim: series 2442a2dc, abandoned at 0-1 after one
                # recorded game with reason 'sitting_abandoned', which paid no
                # series bonus to either side.
                # Elapsed time alone must never close a sitting (this exact rule
                # killed a live FFA game 5m04s after its game 1 recorded). A
                # recent in-match ping from any member vetoes it outright.
                if (last_game is not None
                        and (datetime.now(timezone.utc) - last_game).total_seconds() > 900
                        and not _group_game_in_progress(me["series_id"])):
                    sitting_over = True
            elif (all_polling and int(srow["games"] or 0) == 0 and lock_age > 300
                  # Round-7 gate: "all polling" must mean the COMPLETE frozen
                  # roster (3 for 1v2), not every SURVIVING row — a husk-swept
                  # roster leaves one fresh survivor reading as "everyone".
                  and int(mem_polls["total"] or 0) >= 3
                  # And a live battle (positive evidence, any process age) or
                  # a startup-unknown window vetoes the cancel outright.
                  and _in_match_evidence_trustworthy()
                  and not _group_game_positively_live(me["series_id"])):
                assembly_failed = True
        if sitting_over:
            await db.execute(text(
                "UPDATE ovt_series SET status='canceled', invalidation_reason='sitting_abandoned',"
                "       invalidated_at=NOW() WHERE id=:sid AND status='active'"
            ), {"sid": me["series_id"]})
            await db.execute(text("DELETE FROM ovt_queue WHERE series_id = :sid"),
                             {"sid": me["series_id"]})
            await db.commit()
            print(f"[OVT-LOCK] sitting over — series {me['series_id']} closed, members freed")
            return {"status": "not_in_queue", "queue_count": 0}
        if dead or assembly_failed:
            if srow is not None and srow["status"] == "active":
                reason = "assembly_failed" if assembly_failed else "assembly_timeout"
                await db.execute(text(
                    "UPDATE ovt_series SET status='canceled', invalidation_reason=:rsn,"
                    "       invalidated_at=NOW() WHERE id=:sid AND status='active'"
                ), {"sid": me["series_id"], "rsn": reason})
            await db.execute(text("""
                UPDATE ovt_queue SET status='searching', series_id=NULL, side_assigned=NULL,
                       room_name=NULL, room_region=NULL, matched_at=NULL, joined_at=NOW()
                 WHERE series_id = :sid
            """), {"sid": me["series_id"]})
            await db.commit()
            print(f"[OVT-LOCK] dead lock reset (series {me['series_id']}, age {int(lock_age)}s, assembly_failed={assembly_failed})")
            n = (await db.execute(text("SELECT COUNT(*) FROM ovt_queue WHERE status = 'searching'"))).scalar() or 0
            return {"status": "searching", "queue_count": int(n)}
        await db.commit()
        return await _ovt_poll_locked_payload(db, me["series_id"], steam_id)

    # Try to lock. Only the lowest current Steam ID attempts, so the three
    # clients don't race to create three series. Fresh-poll filter: a row
    # whose client stopped polling must never lock into a series (its player
    # would never join the room) — live clients poll every ~2s, so 10s of
    # silence disqualifies without waiting for the 75s prune.
    # LIMIT 3: lock exactly one lobby's worth of rows, not the whole searching
    # pool. The old no-LIMIT form locked every fresh searching row (only
    # rows[:3] were used), so a second independent trio could never assemble
    # concurrently — its poller found everything locked and bounced. With
    # LIMIT 3 + SKIP LOCKED, concurrent pollers carve the pool into disjoint
    # 3-row lobbies. queue_count is reported from a separate plain COUNT —
    # len(rows) is capped by the LIMIT and misses rows other pollers hold.
    rows = (await db.execute(text("""
        SELECT player_id, steam_id, display_name, preferred_side, solo_extra_pick,
               region, rating, rating_deviation, completed_series
          FROM ovt_queue
         WHERE status = 'searching'
           AND last_polled > NOW() - INTERVAL '10 seconds'
           AND NOT EXISTS (SELECT 1 FROM player_bans pb
                            WHERE pb.steam_id = ovt_queue.steam_id
                              AND pb.unbanned_at IS NULL)
         ORDER BY joined_at
         LIMIT 3
         FOR UPDATE SKIP LOCKED
    """))).mappings().all()
    if len(rows) < 3:
        await db.commit()
        n = (await db.execute(text(
            "SELECT COUNT(*) FROM ovt_queue WHERE status = 'searching'"
            "   AND last_polled > NOW() - INTERVAL '75 seconds'"
        ))).scalar() or 0
        return {"status": "searching", "queue_count": int(n)}

    # Review HIGH: the decider MUST be a member of the lobby it locks. Pick the
    # lobby (3 earliest joiners) FIRST, then elect the decider from exactly those
    # three. The old code chose the decider as min Steam ID over ALL searching
    # rows while locking rows[:3] — when a 4th player with the lowest Steam ID
    # was waiting, they'd elect themselves, lock a room for the OTHER three, and
    # strand themselves in a 3-player room as a 4th client (permanent stall).
    lobby = rows[:3]  # exactly three lock together (earliest by joined_at)
    lobby_numeric = [r["steam_id"] for r in lobby if r["steam_id"].isdigit()]
    lowest = min(lobby_numeric, key=int) if lobby_numeric else lobby[0]["steam_id"]
    if steam_id != lowest:
        await db.commit()
        n = (await db.execute(text(
            "SELECT COUNT(*) FROM ovt_queue WHERE status = 'searching'"
            "   AND last_polled > NOW() - INTERVAL '75 seconds'"
        ))).scalar() or 0
        return {"status": "searching", "queue_count": int(n)}
    # Assign sides: first player who wants solo (pref 1) takes solo, else the
    # first by join order; the other two are the duo.
    solo = next((r for r in lobby if r["preferred_side"] == 1), None) or lobby[0]
    duo = [r for r in lobby if r["player_id"] != solo["player_id"]]
    if len(duo) != 2:
        await db.commit()
        return {"status": "searching", "queue_count": len(rows)}
    extra_pick = any(bool(r["solo_extra_pick"]) for r in lobby)
    region = next((r["region"] for r in lobby if r["region"]), "us")
    room = f"ovt_{uuid.uuid4().hex[:12]}"
    series_id = uuid.uuid4()
    await db.execute(text("""
        INSERT INTO ovt_series (id, solo_id, duo_a_id, duo_b_id, status, is_ranked,
                                solo_extra_pick, photon_room_id, region, created_at)
        VALUES (:sid, :solo, :da, :db, 'active', false, :sep, :room, :reg, NOW())
    """), {"sid": series_id, "solo": solo["player_id"], "da": duo[0]["player_id"],
           "db": duo[1]["player_id"], "sep": extra_pick, "room": room, "reg": (region or "us")[:8]})
    for r in lobby:
        this_side = 1 if r["player_id"] == solo["player_id"] else 2
        await db.execute(text("""
            UPDATE ovt_queue SET status='ready_join', series_id=:sid, side_assigned=:side,
                   room_name=:room, room_region=:reg, matched_at=NOW()
             WHERE player_id=:pid
        """), {"sid": series_id, "side": this_side, "room": room, "reg": (region or "us")[:8],
               "pid": r["player_id"]})
    await _lease_acquire_many(db, [r["player_id"] for r in lobby], "ovt",
                              series_id, LEASE_TTL_ASSEMBLY)
    await db.commit()
    print(f"[OVT-LOCK] series {series_id} room {room} solo={solo['steam_id']} extra_pick={extra_pick}")
    # Post-commit, own transaction: a locked trio is out of every other queue.
    await _evict_other_queue_searching(
        db, [r["player_id"] for r in lobby], "ovt_queue", "a 1v2 lobby")
    return await _ovt_poll_locked_payload(db, series_id, steam_id)


async def _ovt_poll_locked_payload(db: AsyncSession, series_id, steam_id: str) -> dict:
    s = (await db.execute(text("""
        SELECT s.*, ps.steam_id AS solo_sid, ps.display_name AS solo_name,
               pa.steam_id AS da_sid, pa.display_name AS da_name,
               pb.steam_id AS db_sid, pb.display_name AS db_name
          FROM ovt_series s
          JOIN players ps ON ps.id = s.solo_id
          JOIN players pa ON pa.id = s.duo_a_id
          JOIN players pb ON pb.id = s.duo_b_id
         WHERE s.id = :sid
    """), {"sid": series_id})).mappings().first()
    if s is None:
        return {"status": "searching", "queue_count": 0}
    my_side = 1 if s["solo_sid"] == steam_id else 2
    return {
        "status": "ready_join",
        "series_id": str(series_id),
        "side_assigned": my_side,
        "room_name": s["photon_room_id"],
        "room_region": s["region"],
        "solo_extra_pick": bool(s["solo_extra_pick"]),
        "solo": {"steam_id": s["solo_sid"], "display_name": s["solo_name"]},
        "duo": [
            {"steam_id": s["da_sid"], "display_name": s["da_name"]},
            {"steam_id": s["db_sid"], "display_name": s["db_name"]},
        ],
    }


@app.post("/api/v1/ovt/series/continuation", tags=["1v2 Matches"])
async def ovt_series_continuation(req: _TeamContinuationReq, db: AsyncSession = Depends(get_db)):
    """Open a fresh 1v2 series when the three keep playing past a completed
    BO3 (recording-gap fix, learning #70). Reuses _TeamContinuationReq's shape
    but only the first three steam fields matter (t1a=solo, t1b=duo_a,
    t2a=duo_b; t2b ignored). Idempotent."""
    canonical = (
        f"ovt-continuation:{req.t1a_steam}:{req.t1b_steam}:"
        f"{req.t2a_steam}:{req.room_id}:{req.reporter_steam_id}"
    )
    if not _verify_action_sig(canonical, req.hmac_signature):
        raise HTTPException(403, "Bad continuation signature")
    steams = [req.t1a_steam, req.t1b_steam, req.t2a_steam]
    if len(set(steams)) != 3:
        raise HTTPException(400, "Need three distinct players")
    if req.reporter_steam_id not in steams:
        raise HTTPException(403, "Reporter not part of the match")
    numeric = [s for s in steams if s.isdigit()]
    if numeric and req.reporter_steam_id != min(numeric, key=int):
        raise HTTPException(403, "Reporter must be the lowest Steam ID")
    # Round-19 find 2: identity locks (sorted) before the gate, as in the
    # team continuation.
    for _cc_sid in sorted(steams):
        await db.execute(text("SELECT pg_advisory_xact_lock(hashtext(:sid))"),
                         {"sid": _cc_sid})
    # Round-18 find 3: no continuation with a banned member (same rule as
    # the team continuation — the sitting ends rather than minting a new
    # post-ban active pairing).
    for _cc_sid in steams:
        if (await _is_banned(db, _cc_sid)) is not None:
            raise HTTPException(409, "Continuation refused: a participant is banned")
    rows = (await db.execute(
        select(Player.id, Player.steam_id).where(Player.steam_id.in_(steams))
    )).all()
    id_by_steam = {r.steam_id: r.id for r in rows}
    if len(id_by_steam) != 3:
        raise HTTPException(404, "One or more players not registered")
    ids = list(id_by_steam.values())
    # Activity window (July 22 forensics): without it, a days-old abandoned
    # 'active' husk (e.g. a 0-1 series the trio walked away from) would be
    # returned as "existing" and the next sitting's games would complete an
    # ancient series with stale tallies. Recent creation OR a recent match
    # counts as live (learning #101 pattern).
    live = (await db.execute(text("""
        SELECT id, photon_room_id FROM ovt_series s
         WHERE s.status IN ('active', 'dc_paused', 'dc_incomplete')
           AND s.solo_id = ANY(:ids) AND s.duo_a_id = ANY(:ids) AND s.duo_b_id = ANY(:ids)
           AND (s.created_at > NOW() - INTERVAL '6 hours'
                OR EXISTS (SELECT 1 FROM ovt_matches m
                           WHERE m.series_id = s.id
                             AND m.ended_at > NOW() - INTERVAL '6 hours'))
         ORDER BY s.created_at DESC LIMIT 1
    """), {"ids": ids})).mappings().first()
    if live is not None:
        # Round-20 find 4: same room-continuity bar as the team live branch
        # (ovt series rooms are immutable after insert, so a mismatch can
        # never be a re-issued room — it is a wrong-room caller).
        _live_room = (live["photon_room_id"] or "").strip()
        if _live_room and (req.room_id or "").strip() != _live_room:
            raise HTTPException(409, "Continuation refused: room does not match the sitting")
        return {"series_id": str(live["id"]), "status": "existing"}
    # A canceled series counts as a prior too: the trio DID lock together
    # (that's the consent proof this lookup exists for), and a lock canceled
    # as assembly_timeout must not 409 the sitting's remaining games — the
    # match pipeline would silently stop recording (review finding).
    prior = (await db.execute(text("""
        SELECT completed_at, created_at, solo_id, duo_a_id, duo_b_id, solo_extra_pick,
               photon_room_id
          FROM ovt_series
         WHERE status IN ('completed', 'canceled', 'cancelled')
           AND solo_id = ANY(:ids) AND duo_a_id = ANY(:ids) AND duo_b_id = ANY(:ids)
         ORDER BY COALESCE(completed_at, created_at) DESC LIMIT 1
    """), {"ids": ids})).mappings().first()
    if prior is None:
        raise HTTPException(409, "No prior series for these players")
    # ROOM CONTINUITY (round-19 find 5, same bar as the team continuation):
    # the sitting's Photon room was server-issued at lock; a genuine
    # continuation names it. This is what makes the deliberate canceled-
    # prior acceptance (assembly_timeout must not strand a sitting's games)
    # safe against fabrication: the caller must know the issued room.
    _prior_room = (prior["photon_room_id"] or "").strip()
    if _prior_room and (req.room_id or "").strip() != _prior_room:
        raise HTTPException(409, "Continuation refused: room does not match the sitting")
    anchor = prior["completed_at"] or prior["created_at"]
    if anchor is not None:
        age_min = (datetime.now(timezone.utc) - anchor).total_seconds() / 60.0
        if age_min > _CONTINUATION_WINDOW_MINUTES:
            raise HTTPException(409, "Prior series too old to continue")
    # Preserve the SAME solo/duo assignment as the prior series (the client keeps
    # its sides across a sitting; the report path canonicalizes to match).
    new_id = uuid.uuid4()
    await db.execute(text("""
        INSERT INTO ovt_series (id, solo_id, duo_a_id, duo_b_id, status, is_ranked,
                                solo_extra_pick, photon_room_id, region, created_at)
        VALUES (:sid, :solo, :da, :db, 'active', false, :sep, :room, :region, NOW())
    """), {"sid": new_id, "solo": prior["solo_id"], "da": prior["duo_a_id"], "db": prior["duo_b_id"],
           "sep": bool(prior["solo_extra_pick"]), "room": (req.room_id or "")[:64],
           "region": (req.region or "")[:8] or None})
    await db.commit()
    print(f"[OVT-CONTINUATION] created {new_id} for {steams} room={req.room_id}")
    return {"series_id": str(new_id), "status": "created"}


@app.post("/api/v1/ovt/matches", response_model=OvtMatchResponse, tags=["1v2 Matches"])
async def submit_ovt_match(report: OvtMatchReport, request: Request, db: AsyncSession = Depends(get_db)):
    """Record one 1v2 game. Advances the series (first to 2), applies gold+XP
    (NO rating at launch), stores the full replay surface. Concurrency-safe:
    the series completion path locks the row and re-checks status (#78)."""
    await _check_steam_session(request, report.reported_by_steam_id, db)
    if not _verify_ovt_hmac(report):
        raise HTTPException(403, "Invalid 1v2 match signature")
    try:
        series_uuid = UUID(report.series_id)
    except (ValueError, TypeError):
        raise HTTPException(400, "Invalid series_id format")
    steams = {report.solo.steam_id, report.duo_a.steam_id, report.duo_b.steam_id}
    if len(steams) != 3:
        raise HTTPException(400, "Need three distinct players")

    prows = (await db.execute(
        select(Player.id, Player.steam_id).where(Player.steam_id.in_(list(steams)))
    )).all()
    id_by_steam = {r.steam_id: r.id for r in prows}
    if len(id_by_steam) != 3:
        raise HTTPException(404, "One or more players not registered")
    solo_id = id_by_steam[report.solo.steam_id]
    duo_a_id = id_by_steam[report.duo_a.steam_id]
    duo_b_id = id_by_steam[report.duo_b.steam_id]

    # Review MEDIUM: an empty/NULL room bypasses the dedup UNIQUE (Postgres treats
    # NULLs as distinct), so two reports of a room-less game would both insert and
    # double-credit. The client always sends a per-game-suffixed room; enforce it.
    if not (report.photon_room_id or "").strip():
        raise HTTPException(400, "photon_room_id is required")
    # Review CONFIRMED: don't trust the client's solo/duo ORDERING — verify the
    # three reported players are exactly the series' three, and derive solo/duo
    # from the SERIES row (the authoritative lock-time assignment), not the report.
    if report.winner_side not in (1, 2):
        raise HTTPException(400, "winner_side must be 1 or 2")
    if report.winner_side != (1 if report.solo_rounds_won > report.duo_rounds_won else 2):
        raise HTTPException(400, "winner_side disagrees with the round score")

    # Lock the series row FIRST (serializes concurrent reports / DC callers, #78).
    # FOR NO KEY UPDATE, not FOR UPDATE (#202): the INSERT INTO ovt_matches below
    # has an FK to this row, so every inserter also takes FOR KEY SHARE on it —
    # and KEY SHARE conflicts with exactly one mode, FOR UPDATE. NO KEY UPDATE is
    # the weakest mode that still self-conflicts (so two reports still serialize)
    # while staying KEY-SHARE-compatible, which keeps any future ovt_matches
    # writer out of this lock graph.
    series = (await db.execute(text(
        "SELECT * FROM ovt_series WHERE id = :sid FOR NO KEY UPDATE"
    ), {"sid": series_uuid})).mappings().first()
    if series is None:
        raise HTTPException(404, "Series not found")
    # Round-20 find 4: bind the report to the sitting's issued room. Report
    # rooms are per-game suffixed ("<room>_<token>_r<total>", the shared
    # BuildReportRoomId helper) while the series stores the raw room, so the
    # relation is PREFIX. Ovt series rooms are immutable after insert; NULL
    # (legacy) falls through.
    _series_room = (series["photon_room_id"] or "").strip()
    # Full suffix grammar, not a bare prefix (round-21 find 2) — see the
    # matching comment in the team sink.
    if _series_room and not _re.fullmatch(
            _re.escape(_series_room) + r"_\d{6}_r\d+",
            (report.photon_room_id or "")):
        raise HTTPException(400, "Report room does not match the series room")

    # ── Difficulty inputs (bug #129) ──────────────────────────────────────
    # Opponents' 1v1 Glicko drives the tier multiplier; guarded exactly like
    # 2v2's fetch so a ratings hiccup degrades to x1.0-at-1500 instead of
    # failing the report.
    # begin_nested, not a bare try/except (#235, and review-confirmed): under
    # asyncpg a caught statement error still leaves the TRANSACTION aborted, so
    # the "degrade to 1500" promise below would be a lie — the very next
    # statement (the ovt_matches INSERT) would raise InFailedSQLTransaction and
    # 500 the whole report. The SAVEPOINT is what makes the fallback real.
    _r_by_pid: dict = {}
    try:
        async with db.begin_nested():
            for _row in (await db.execute(text(
                "SELECT player_id, rating FROM glicko_ratings "
                " WHERE player_id IN (:a, :b, :c)"
            ), {"a": solo_id, "b": duo_a_id, "c": duo_b_id})).mappings().all():
                _r_by_pid[str(_row["player_id"])] = float(_row["rating"])
    except Exception as ex:
        print(f"[OVT-ECON] 1v1 tier-mult rating fetch failed (defaulting 1500): {ex}")
    _solo_r = _r_by_pid.get(str(solo_id), 1500.0)
    _duo_avg_r = (_r_by_pid.get(str(duo_a_id), 1500.0)
                  + _r_by_pid.get(str(duo_b_id), 1500.0)) / 2.0
    _ovt_pod = set(await _ovt_podium_ids(db))
    # Verify the three reported players are exactly the series' three (a client
    # can't swap in a different opponent). Keep the client's solo/duo LABELING
    # though — it's derived from the actual in-game team sizes (team-of-1 = solo),
    # which is what the reported rounds correspond to. The series row's own
    # solo/duo is a queue-time preference that vanilla team assignment may not
    # preserve, so it's NOT authoritative for round attribution.
    if {solo_id, duo_a_id, duo_b_id} != {series["solo_id"], series["duo_a_id"], series["duo_b_id"]}:
        raise HTTPException(403, "Reported players do not match the series")

    # Slot-identity realign (July 22 forensics): the series row's solo/duo_a/duo_b
    # is a queue-time preference; the report's is the in-game truth (team sizes).
    # When they disagree, the per-slot accumulators (solo_xp_earned, ...) and a
    # future ranked replay would credit the wrong player. On the FIRST match of
    # a series, rewrite the series row's slot ids to the report's ordering —
    # under the row lock, before any accumulator applies. Mid-series drift
    # (should be impossible: sides are fixed per sitting) is logged only.
    if (solo_id, duo_a_id, duo_b_id) != (series["solo_id"], series["duo_a_id"], series["duo_b_id"]):
        prior_games = (await db.execute(text(
            "SELECT COUNT(*) FROM ovt_matches WHERE series_id = :sid"
        ), {"sid": series_uuid})).scalar() or 0
        if prior_games == 0:
            await db.execute(text("""
                UPDATE ovt_series SET solo_id = :solo, duo_a_id = :da, duo_b_id = :db
                 WHERE id = :sid
            """), {"solo": solo_id, "da": duo_a_id, "db": duo_b_id, "sid": series_uuid})
            print(f"[OVT] series {series_uuid} slots realigned to report ordering "
                  f"(solo={report.solo.steam_id})")
        else:
            print(f"[OVT] WARNING: series {series_uuid} slot ordering differs from "
                  f"report mid-series (game {prior_games + 1}) — leaving as-is")

    # Insert the match (dedup on the room+players unique constraint → replay no-op).
    match_id = uuid.uuid4()
    try:
        await db.execute(text("""
            INSERT INTO ovt_matches (id, series_id, solo_id, duo_a_id, duo_b_id,
                solo_rounds_won, duo_rounds_won, solo_points_total, duo_points_total,
                winner_side, solo_fps_avg, duo_a_fps_avg, duo_b_fps_avg, duration_seconds,
                photon_room_id, game_version, region, hmac_signature, reported_by,
                is_ranked, started_at, ended_at,
                solo_rating_at, duo_a_rating_at, duo_b_rating_at)
            VALUES (:id, :sid, :solo, :da, :db, :sr, :dr, :sp, :dp, :ws,
                    :sf, :daf, :dbf, :dur, :room, :gv, :reg, :hmac, :rep, false, :started, NOW(),
                    :sra, :dar, :dbr)
        """), {"id": match_id, "sid": series_uuid, "solo": solo_id, "da": duo_a_id, "db": duo_b_id,
               # Snapshot the ratings the multiplier was computed from — these
               # three columns were dead (NULL on all 11 legacy rows) and without
               # them no audit or back-pay can reproduce what was actually paid
               # (#229/#236).
               "sra": _solo_r,
               "dar": _r_by_pid.get(str(duo_a_id), 1500.0),
               "dbr": _r_by_pid.get(str(duo_b_id), 1500.0),
               "sr": report.solo_rounds_won, "dr": report.duo_rounds_won,
               "sp": report.solo_points_total, "dp": report.duo_points_total, "ws": report.winner_side,
               "sf": report.solo_fps, "daf": report.duo_a_fps, "dbf": report.duo_b_fps,
               "dur": report.match_duration, "room": (report.photon_room_id or "")[:64] or None,
               "gv": (report.game_version or "")[:32] or None, "reg": (report.region or "")[:8] or None,
               "hmac": (report.hmac_signature or "")[:128] or None, "rep": id_by_steam.get(report.reported_by_steam_id),
               "started": report.started_at})
    except IntegrityError:
        await db.rollback()
        # Already recorded (replay). Return the current series state idempotently.
        s2 = (await db.execute(text("SELECT * FROM ovt_series WHERE id = :sid"), {"sid": series_uuid})).mappings().first()
        if s2 is None:
            raise HTTPException(404, "Series not found")
        # Reporter-first score (learning #121) — a duo-member reporter must not
        # see the solo-first order and read a won series as a loss.
        rep_side_r = 1 if report.reported_by_steam_id == report.solo.steam_id else 2
        score_r = (f"{s2['solo_series_wins']}-{s2['duo_series_wins']}" if rep_side_r == 1
                   else f"{s2['duo_series_wins']}-{s2['solo_series_wins']}")
        return OvtMatchResponse(
            match_id=match_id, series_id=series_uuid, series_status=s2["status"],
            series_score=score_r, winner_side=report.winner_side, message="Already recorded")

    # Per-game card picks (both duo members + solo).
    for pmd, pid in ((report.solo, solo_id), (report.duo_a, duo_a_id), (report.duo_b, duo_b_id)):
        for i, c in enumerate(pmd.cards or []):
            nm = getattr(c, "card_name", None) or getattr(c, "name", None)
            if not nm:
                continue
            await db.execute(text(
                "INSERT INTO ovt_match_cards (match_id, player_id, card_name, pick_order) "
                "VALUES (:m, :p, :c, :o)"
            ), {"m": match_id, "p": pid, "c": str(nm)[:64], "o": i})

    # Advance the series win tally only if still active (re-check under the lock).
    if series["status"] != "active":
        await db.commit()  # keeps the match/card rows we already inserted
        rep_side2 = 1 if report.reported_by_steam_id == report.solo.steam_id else 2
        score2 = (f"{series['solo_series_wins']}-{series['duo_series_wins']}" if rep_side2 == 1
                  else f"{series['duo_series_wins']}-{series['solo_series_wins']}")
        return OvtMatchResponse(
            match_id=match_id, series_id=series_uuid, series_status=series["status"],
            series_score=score2, winner_side=report.winner_side, message="Series already resolved")

    solo_wins = series["solo_series_wins"] + (1 if report.winner_side == 1 else 0)
    duo_wins = series["duo_series_wins"] + (1 if report.winner_side == 2 else 0)
    series_done = solo_wins >= 2 or duo_wins >= 2
    winner_side = 1 if solo_wins > duo_wins else 2

    # ── Per-match XP + gold. Review CONFIRMED: use an ATOMIC increment
    # (total_xp = total_xp + delta) with RETURNING, not a Python-computed
    # absolute write over a separate SELECT — the latter loses updates if the
    # same player is credited by two concurrent series completions. NO rating
    # at launch. Gold conversion (100xp=1g) computed from the returned totals. ──
    async def _award(pid, won_game: bool, mult: float):
        xp = int(OVT_MATCH_XP_BASE * (OVT_MATCH_WIN_MULT if won_game else 1.0) * mult)
        row = (await db.execute(text(
            "UPDATE players SET total_xp = COALESCE(total_xp,0) + :xp WHERE id = :pid "
            "RETURNING total_xp AS new_xp, (COALESCE(total_xp,0) - :xp) AS old_xp"
        ), {"xp": xp, "pid": pid})).mappings().first()
        new_xp = row["new_xp"] if row else xp
        old_xp = row["old_xp"] if row else 0
        gold_delta = max(0, (new_xp // 100) - (old_xp // 100))
        # Level-ding gold (bug #129): 1v2 was the ONLY mode that never granted it
        # — verified zero `level_reward` rows referencing an ovt match, while
        # 1v1/2v2/FFA all do. It is the game's 3rd-largest gold source, so a
        # 1v2-only player banked nothing for levelling.
        old_lvl, _, _ = level_from_xp(old_xp)
        new_lvl, _, _ = level_from_xp(new_xp)
        level_gold = (sum(level_reward_for(lv) for lv in range(old_lvl + 1, new_lvl + 1))
                      if new_lvl > old_lvl else 0)
        # ONE gold UPDATE per player per game (FFA's rule) — a second UPDATE of
        # the same row buys nothing and widens the write set.
        if gold_delta + level_gold > 0:
            await db.execute(text(
                "UPDATE players SET gold_earned = COALESCE(gold_earned,0) + :g WHERE id = :pid"
            ), {"g": gold_delta + level_gold, "pid": pid})
        # ...but two audit rows, so `reason` stays a truthful breakdown.
        if gold_delta > 0:
            db.add(GoldTransaction(player_id=pid, amount=gold_delta, reason="ovt_xp", reference_id=str(match_id)))
        if level_gold > 0:
            db.add(GoldTransaction(player_id=pid, amount=level_gold,
                                   reason="level_reward", reference_id=str(match_id)))
        return xp, gold_delta + level_gold

    solo_won_game = report.winner_side == 1
    # Award in canonical str(pid) order, not solo/duo slot order — players-row
    # tuple locks must follow one global order across concurrent completions
    # (learning #197 / review find).
    _award_results = {}
    _bonus_labels: dict = {}
    _duo_pod = (str(duo_a_id) in _ovt_pod) or (str(duo_b_id) in _ovt_pod)
    _solo_pod = str(solo_id) in _ovt_pod
    # solo_extra_pick is already in scope — the series SELECT is `SELECT *`.
    _extra_pick = bool(series["solo_extra_pick"])
    for _pid in sorted([solo_id, duo_a_id, duo_b_id], key=str):
        _is_solo = (_pid == solo_id)
        _won = solo_won_game if _is_solo else (not solo_won_game)
        _m, _lbl = _ovt_difficulty_mult(
            _is_solo, _extra_pick,
            _duo_avg_r if _is_solo else _solo_r,
            _duo_pod if _is_solo else _solo_pod)
        _bonus_labels[_pid] = _lbl
        _award_results[_pid] = await _award(_pid, _won, _m)
    sx, sg = _award_results[solo_id]
    ax, ag = _award_results[duo_a_id]
    bx, bg = _award_results[duo_b_id]
    await db.execute(text("""
        UPDATE ovt_series SET
            solo_series_wins=:sw, duo_series_wins=:dw,
            solo_xp_earned = solo_xp_earned + :sx, duo_a_xp_earned = duo_a_xp_earned + :ax,
            duo_b_xp_earned = duo_b_xp_earned + :bx,
            solo_gold_earned = solo_gold_earned + :sg, duo_a_gold_earned = duo_a_gold_earned + :ag,
            duo_b_gold_earned = duo_b_gold_earned + :bg
         WHERE id = :sid
    """), {"sw": solo_wins, "dw": duo_wins, "sx": sx, "ax": ax, "bx": bx,
           "sg": sg, "ag": ag, "bg": bg, "sid": series_uuid})

    status = "active"
    _series_bonus_by_pid: dict = {}
    if series_done:
        status = "completed"
        # Series-completion gold: 40 winners / 20 losers, now TIER-scaled by the
        # opponents' 1v1 elo exactly as 2v2 scales its 50/25 (bug #129 — 1v2 was
        # the only mode paying a flat series bonus). Tier ONLY here; the
        # side/extra-pick/podium factors stay on the XP half, which keeps the
        # per-minute totals inside the 2v2/FFA band.
        #
        # This loop iterates in solo/duo_a/duo_b order, NOT sorted by str(pid) —
        # safe only because the _award loop above already tuple-locked all three
        # players in canonical order inside this same transaction. Do not move any
        # players write above that loop (#197).
        for pid, side in ((solo_id, 1), (duo_a_id, 2), (duo_b_id, 2)):
            _s_mult, _ = _tier_mult_for(_duo_avg_r if pid == solo_id else _solo_r)
            bonus = int((OVT_SERIES_WIN_GOLD if side == winner_side
                         else OVT_SERIES_LOSS_GOLD) * _s_mult)
            _series_bonus_by_pid[pid] = bonus
            await db.execute(text(
                "UPDATE players SET gold_earned = COALESCE(gold_earned,0) + :g WHERE id = :pid"
            ), {"g": bonus, "pid": pid})
            db.add(GoldTransaction(player_id=pid, amount=bonus,
                                   reason=("ovt_series_win" if side == winner_side else "ovt_series_loss"),
                                   reference_id=str(series_uuid)))
            # Accumulate the bonus on this player's own slot column.
            slot = "solo" if pid == solo_id else ("duo_a" if pid == duo_a_id else "duo_b")
            await db.execute(text(
                f"UPDATE ovt_series SET {slot}_gold_earned = {slot}_gold_earned + :g WHERE id = :sid"
            ), {"g": bonus, "sid": series_uuid})
        # Bump per-player completed-series / side game counts (rating table rows
        # created lazily so the future ranked replay has counts to read).
        for pid, is_solo in ((solo_id, True), (duo_a_id, False), (duo_b_id, False)):
            await db.execute(text("""
                INSERT INTO glicko_ratings_1v2 (player_id, completed_series, solo_games, duo_games)
                VALUES (:pid, 1, :sg, :dg)
                ON CONFLICT (player_id) DO UPDATE SET
                    completed_series = glicko_ratings_1v2.completed_series + 1,
                    solo_games = glicko_ratings_1v2.solo_games + :sg,
                    duo_games = glicko_ratings_1v2.duo_games + :dg,
                    updated_at = NOW()
            """), {"pid": pid, "sg": 1 if is_solo else 0, "dg": 0 if is_solo else 1})
        await db.execute(text(
            "UPDATE ovt_series SET status='completed', winner_side=:ws, completed_at=NOW() WHERE id=:sid"
        ), {"ws": winner_side, "sid": series_uuid})
        await _lock_queue_rows_ordered(
            db, "ovt_queue", [solo_id, duo_a_id, duo_b_id])
        await db.execute(text("DELETE FROM ovt_queue WHERE series_id = :sid"), {"sid": series_uuid})

    await db.commit()
    # Score from the REPORTER's own side (reporter-first, learning #121).
    reporter_side = 1 if report.reported_by_steam_id == report.solo.steam_id else 2
    score = f"{solo_wins}-{duo_wins}" if reporter_side == 1 else f"{duo_wins}-{solo_wins}"
    print(f"[OVT-REPORT] match {match_id} series {series_uuid} {solo_wins}-{duo_wins} status={status}")
    # The reporter's own game reward (#129). id_by_steam is the report's own
    # steam->player-id map, so this is the reporter's row whichever seat they hold.
    _rep_pid = id_by_steam.get(report.reported_by_steam_id)
    _rep_xp, _rep_gold = _award_results.get(_rep_pid, (0, 0))
    _rep_labels = list(_bonus_labels.get(_rep_pid, []))
    # On the closing game, fold the series bonus into the reported gold so the
    # toast matches what actually landed in the player's balance.
    _rep_series_bonus = _series_bonus_by_pid.get(_rep_pid, 0)
    if _rep_series_bonus > 0:
        _rep_gold += _rep_series_bonus
        _rep_labels.append(f"Series bonus +{_rep_series_bonus}g")
    return OvtMatchResponse(
        match_id=match_id, series_id=series_uuid, series_status=status,
        series_score=score, winner_side=report.winner_side,
        xp_gained=_rep_xp, gold_gained=_rep_gold,
        xp_bonuses=_rep_labels)


@app.get("/api/v1/ovt/series/active", tags=["1v2 Matches"])
async def ovt_series_active(steam_id: str = Query(...), db: AsyncSession = Depends(get_db)):
    """The caller's live 1v2 series (for the in-game HUD), if any."""
    p = (await db.execute(select(Player.id).where(Player.steam_id == steam_id))).scalar_one_or_none()
    if p is None:
        return {"active": False}
    s = (await db.execute(text("""
        SELECT * FROM ovt_series
         WHERE status = 'active'
           AND (solo_id = :pid OR duo_a_id = :pid OR duo_b_id = :pid)
           AND created_at > NOW() - INTERVAL '3 hours'
         ORDER BY created_at DESC LIMIT 1
    """), {"pid": p})).mappings().first()
    if s is None:
        return {"active": False}
    return {"active": True, "series_id": str(s["id"]),
            "solo_wins": s["solo_series_wins"], "duo_wins": s["duo_series_wins"],
            "solo_extra_pick": bool(s["solo_extra_pick"])}


@app.get("/api/v1/ovt/leaderboard", response_model=Ovt1v2LeaderboardResponse, tags=["1v2 Matches"])
async def ovt_leaderboard(
    limit: int = 200,
    role: str = "combined",
    db: AsyncSession = Depends(get_db),
):
    """1v2 stats leaderboard, optionally scoped to solo or duo games."""
    if role not in {"combined", "solo", "duo"}:
        role = "combined"

    rows = (await db.execute(text("""
        WITH per_player AS (
            SELECT pid, SUM(played) AS games, SUM(won) AS wins,
                   SUM(solo_g) AS solo_games, SUM(duo_g) AS duo_games,
                   SUM(solo_w) AS solo_wins, SUM(duo_w) AS duo_wins,
                   MAX(ended_at) AS last_played
            FROM (
                SELECT solo_id AS pid, 1 AS played,
                       CASE WHEN winner_side=1 THEN 1 ELSE 0 END AS won, 1 AS solo_g, 0 AS duo_g,
                       CASE WHEN winner_side=1 THEN 1 ELSE 0 END AS solo_w, 0 AS duo_w,
                       ended_at
                  FROM ovt_matches WHERE invalidated_at IS NULL
                UNION ALL
                SELECT duo_a_id, 1, CASE WHEN winner_side=2 THEN 1 ELSE 0 END, 0, 1,
                       0, CASE WHEN winner_side=2 THEN 1 ELSE 0 END, ended_at
                  FROM ovt_matches WHERE invalidated_at IS NULL
                UNION ALL
                SELECT duo_b_id, 1, CASE WHEN winner_side=2 THEN 1 ELSE 0 END, 0, 1,
                       0, CASE WHEN winner_side=2 THEN 1 ELSE 0 END, ended_at
                  FROM ovt_matches WHERE invalidated_at IS NULL
            ) u
            GROUP BY pid
        ),
        scoped AS (
            SELECT pp.*,
                   CASE WHEN :role = 'solo' THEN pp.solo_games
                        WHEN :role = 'duo' THEN pp.duo_games
                        ELSE pp.games END AS scoped_games,
                   CASE WHEN :role = 'solo' THEN pp.solo_wins
                        WHEN :role = 'duo' THEN pp.duo_wins
                        ELSE pp.wins END AS scoped_wins
              FROM per_player pp
        )
        SELECT sc.pid AS player_id, p.steam_id, p.display_name, p.total_xp,
               sc.games, sc.wins, sc.solo_games, sc.duo_games,
               sc.solo_wins, sc.duo_wins, sc.scoped_games, sc.scoped_wins,
               sc.last_played,
               si.name AS title_name, si.preview_color AS title_color, si.sku AS title_sku,
               gr.rating AS rating_1v1
          FROM scoped sc
          JOIN players p ON p.id = sc.pid
          LEFT JOIN shop_items si ON si.id = p.active_title_id
          LEFT JOIN glicko_ratings gr ON gr.player_id = p.id
         WHERE p.deleted_at IS NULL
           AND sc.scoped_games >= 1
         ORDER BY
               CASE WHEN :role = 'combined' THEN sc.games END DESC,
               CASE WHEN :role = 'combined'
                    THEN sc.wins::float / NULLIF(sc.games, 0) END DESC NULLS LAST,
               CASE WHEN :role IN ('solo', 'duo') THEN sc.scoped_wins END DESC,
               CASE WHEN :role IN ('solo', 'duo')
                    THEN sc.scoped_wins::float / NULLIF(sc.scoped_games, 0)
                    END DESC NULLS LAST,
               CASE WHEN :role IN ('solo', 'duo') THEN sc.scoped_games END DESC
         LIMIT :lim
    """), {"lim": max(1, min(limit, 500)), "role": role})).mappings().all()

    _colors = await _rank_colors(db)
    _pmap = await _podium_map(db) if any(
        r["title_sku"] == TITLE_PODIUM_SKU for r in rows) else {}
    entries = []
    for i, r in enumerate(rows):
        games = int(r["scoped_games"] or 0)
        wins = int(r["scoped_wins"] or 0)
        losses = games - wins
        lvl, _, _ = level_from_xp(r["total_xp"] or 0)
        solo_g = int(r["solo_games"] or 0)
        duo_g = int(r["duo_games"] or 0)
        solo_w = int(r["solo_wins"] or 0)
        duo_w = int(r["duo_wins"] or 0)
        t_name, t_color = _display_title_sync(
            _colors, r["title_sku"], r["title_name"], r["title_color"],
            r["rating_1v1"], podium_pos=_pmap.get(str(r["player_id"])))
        entries.append(Ovt1v2LeaderboardEntry(
            rank=i + 1, steam_id=r["steam_id"], display_name=r["display_name"] or "Player",
            games_played=games, wins=wins, losses=losses,
            win_rate=round(100.0 * wins / games, 1) if games else 0.0,
            solo_games=solo_g, duo_games=duo_g,
            solo_wins=solo_w, solo_losses=solo_g - solo_w,
            duo_wins=duo_w, duo_losses=duo_g - duo_w,
            level=lvl, title=t_name, title_color=t_color,
            last_played=r["last_played"].isoformat() if r["last_played"] else None,
        ))
    return Ovt1v2LeaderboardResponse(
        entries=entries, total_players=len(entries),
        last_updated=datetime.now(timezone.utc), is_ranked=False)


@app.get("/api/v1/ovt/recent", tags=["1v2 Matches"])
async def ovt_recent(
    page: int = Query(0, ge=0),
    page_size: int = Query(5, ge=1, le=10),
    db: AsyncSession = Depends(get_db),
):
    """Paginated feed of 1v2 series that contain at least one valid match."""
    total = (await db.execute(text("""
        SELECT COUNT(*)
          FROM ovt_series s
         WHERE EXISTS (
                   SELECT 1
                     FROM ovt_matches vm
                    WHERE vm.series_id = s.id
                      AND vm.invalidated_at IS NULL
               )
    """))).scalar() or 0

    series_rows = (await db.execute(text("""
        SELECT s.id AS series_id, s.status, s.winner_side,
               s.created_at, s.completed_at,
               s.solo_series_wins, s.duo_series_wins, s.solo_extra_pick,
               s.solo_id, s.duo_a_id, s.duo_b_id,
               s.solo_gold_earned, s.duo_a_gold_earned, s.duo_b_gold_earned,
               s.solo_xp_earned, s.duo_a_xp_earned, s.duo_b_xp_earned,
               solo.steam_id AS solo_sid, solo.display_name AS solo_name,
               duo_a.steam_id AS duo_a_sid, duo_a.display_name AS duo_a_name,
               duo_b.steam_id AS duo_b_sid, duo_b.display_name AS duo_b_name
          FROM ovt_series s
          JOIN players solo ON solo.id = s.solo_id
          JOIN players duo_a ON duo_a.id = s.duo_a_id
          JOIN players duo_b ON duo_b.id = s.duo_b_id
         WHERE EXISTS (
                   SELECT 1
                     FROM ovt_matches vm
                    WHERE vm.series_id = s.id
                      AND vm.invalidated_at IS NULL
               )
         ORDER BY COALESCE(s.completed_at, s.created_at) DESC
         LIMIT :lim OFFSET :off
    """), {"lim": page_size, "off": page * page_size})).mappings().all()

    series_ids = [r["series_id"] for r in series_rows]
    matches_by_series: dict[str, list] = {}
    cards_by_match: dict[str, dict[str, list[str]]] = {}
    if series_ids:
        match_rows = (await db.execute(text("""
            SELECT m.id AS match_id, m.series_id, m.ended_at, m.winner_side,
                   m.solo_rounds_won, m.duo_rounds_won,
                   m.solo_points_total, m.duo_points_total,
                   m.duration_seconds,
                   m.solo_fps_avg, m.duo_a_fps_avg, m.duo_b_fps_avg,
                   solo.steam_id AS solo_sid,
                   duo_a.steam_id AS duo_a_sid,
                   duo_b.steam_id AS duo_b_sid
              FROM ovt_matches m
              JOIN players solo ON solo.id = m.solo_id
              JOIN players duo_a ON duo_a.id = m.duo_a_id
              JOIN players duo_b ON duo_b.id = m.duo_b_id
             WHERE m.series_id = ANY(:sids)
               AND m.invalidated_at IS NULL
             ORDER BY m.series_id, m.ended_at ASC
        """), {"sids": series_ids})).mappings().all()

        match_ids = [m["match_id"] for m in match_rows]
        if match_ids:
            card_rows = (await db.execute(text("""
                SELECT c.match_id, p.steam_id, c.card_name
                  FROM ovt_match_cards c
                  JOIN players p ON p.id = c.player_id
                 WHERE c.match_id = ANY(:mids)
                 ORDER BY c.match_id, c.player_id, c.pick_order, c.id
            """), {"mids": match_ids})).mappings().all()
            for c in card_rows:
                cards_by_match.setdefault(str(c["match_id"]), {}).setdefault(
                    c["steam_id"], []).append(c["card_name"])

        for m in match_rows:
            fps_by_steam = {}
            for sid_key, fps_key in (
                ("solo_sid", "solo_fps_avg"),
                ("duo_a_sid", "duo_a_fps_avg"),
                ("duo_b_sid", "duo_b_fps_avg"),
            ):
                if m[fps_key]:
                    fps_by_steam[m[sid_key]] = int(m[fps_key])
            matches_by_series.setdefault(str(m["series_id"]), []).append({
                "match_id": str(m["match_id"]),
                "ended_at": m["ended_at"].isoformat() if m["ended_at"] else None,
                "winner_side": m["winner_side"],
                "solo_rounds": int(m["solo_rounds_won"] or 0),
                "duo_rounds": int(m["duo_rounds_won"] or 0),
                "solo_points": int(m["solo_points_total"] or 0),
                "duo_points": int(m["duo_points_total"] or 0),
                "duration_seconds": int(m["duration_seconds"] or 0),
                "fps_by_steam": fps_by_steam,
                "cards_by_steam": cards_by_match.get(str(m["match_id"]), {}),
            })

    out_series = []
    for r in series_rows:
        gold_by_steam = {
            r["solo_sid"]: int(r["solo_gold_earned"] or 0),
            r["duo_a_sid"]: int(r["duo_a_gold_earned"] or 0),
            r["duo_b_sid"]: int(r["duo_b_gold_earned"] or 0),
        }
        xp_by_steam = {
            r["solo_sid"]: int(r["solo_xp_earned"] or 0),
            r["duo_a_sid"]: int(r["duo_a_xp_earned"] or 0),
            r["duo_b_sid"]: int(r["duo_b_xp_earned"] or 0),
        }
        out_series.append({
            "series_id": str(r["series_id"]),
            "status": r["status"],
            "winner_side": r["winner_side"],
            "created_at": r["created_at"].isoformat() if r["created_at"] else None,
            "completed_at": r["completed_at"].isoformat() if r["completed_at"] else None,
            "solo_wins": int(r["solo_series_wins"] or 0),
            "duo_wins": int(r["duo_series_wins"] or 0),
            "solo_extra_pick": bool(r["solo_extra_pick"]),
            "solo": {
                "steam_id": r["solo_sid"],
                "display_name": r["solo_name"] or "Player",
            },
            "duo": [
                {
                    "steam_id": r["duo_a_sid"],
                    "display_name": r["duo_a_name"] or "Player",
                },
                {
                    "steam_id": r["duo_b_sid"],
                    "display_name": r["duo_b_name"] or "Player",
                },
            ],
            "gold_by_steam": gold_by_steam,
            "xp_by_steam": xp_by_steam,
            "matches": matches_by_series.get(str(r["series_id"]), []),
        })

    return {
        "series": out_series,
        "page": page,
        "page_size": page_size,
        "total": total,
        "total_pages": (total + page_size - 1) // page_size if total else 0,
    }


# ══════════════════════════════════════════════════════════════════════════
# FFA (free-for-all, 3-10 players) — RANKED from day one (Sid July 27).
# One FFA match is a complete rated unit (no series layer); the "lobby" row
# groups rematches in one room for the queue lifecycle. Pairwise Glicko-2:
# each player is scored against every opponent by placement (better=1,
# worse=0, tie=0.5) from PRE-match snapshots. Queue is consent-at-join
# (#127): no Elo band, no ready step. Lock protocol follows #197/#202-#207:
# lobby row first (client names it), players FOR NO KEY UPDATE sorted,
# glicko FOR UPDATE sorted after (the players pass is the real gate — #203).
# ══════════════════════════════════════════════════════════════════════════

FFA_MIN_PLAYERS = 3
FFA_MAX_PLAYERS = 10
# Once >= MIN fresh searching rows exist, the lock fires when the MIN-th
# earliest of them has been waiting this long (a gather window so later
# joiners can still make the lobby), or immediately at MAX. Anchoring on the
# MIN-th earliest join means the countdown starts when the pool became
# viable — anchoring on the EARLIEST would fire instantly for any pool whose
# first member had been waiting alone.
FFA_GATHER_SECONDS = 25
# Bug #111: each NEW joiner guarantees this much additional pile-in time
# (window extends while people keep arriving), bounded by the hard cap below
# so the first 3 are never held hostage by a slow trickle.
FFA_GATHER_EXTEND_SECONDS = 20
FFA_GATHER_CAP_SECONDS = 120
# Gather timing state (Codex post-release finds 4+5): timing must come from
# authoritative monotonic state — NOT from the SKIP LOCKED candidate slice (a
# joiner's own in-flight poll briefly hides its fresh row from the scan) and
# NOT from resettable joined_at values (a rejoin at second 110 must not
# restart the 120s cap — joined_at legally resets on rejoin per bug #109).
# In-memory is safe: single uvicorn worker is enforced (#125); an API restart
# merely restarts the window.
_ffa_gather_started_mono: float | None = None
_ffa_gather_last_join_mono: float = 0.0
# Last time any poll OBSERVED a >=3 fresh pool via the PLAIN count (re-review
# find 4: the SKIP LOCKED slice hides in-flight rows, so slice-driven resets
# false-fire; and a fully-abandoned pool leaves nobody to reset the window, so
# a later trio would inherit a stale start and cap instantly). Live searchers
# poll every ~2s, so an observation gap >15s means the pool collapsed or the
# process restarted — either way the next gather starts a fresh window.
_ffa_gather_pool_seen_mono: float = 0.0
# ── FFA economy (bug #121) ─────────────────────────────────────────────────
# Parity target is 2v2's per-player-MINUTE rate, not its per-game rate. One
# FFA game is a first-to-5 (each point = 2 half-points) and runs ~13 min in
# prod at 5 players — i.e. about a 2-0 2v2 BO3 — so one FFA game must pay like
# one 2v2 SERIES, not like one 2v2 game. Pre-fix FFA paid 0.45 g/player-min
# against 2v2's 2.71, a 6x deficit, because of three compounding gaps:
#   (1) the XP base was half of TEAM_MATCH_XP_BASE,
#   (2) there was no flat completion bonus at all (every other mode has one:
#       SERIES_GOLD_BASE / TEAM_SERIES_WIN_GOLD / OVT_SERIES_WIN_GOLD),
#   (3) the lobby-size multiplier was gated behind `place == 1`, so lobby size
#       paid nothing to 9 of 10 players — 4th-of-10 earned exactly 4th-of-4.
# v1.35 LEGACY constants — SUPERSEDED by the battles × players meter below.
# Kept because migration 164's pg_temp mirror reproduces the legacy flat
# formula from these for the pre-meter back-pay; they are dead in the live
# award path. (The old model paid per-GAME constants, so a 23-minute
# 10-player game earned LESS per hour than a 8-minute 3-player one — the
# meter inverts that by paying per signed half-point.)
FFA_MATCH_XP_BASE = 600     # was 300 — parity with TEAM_MATCH_XP_BASE
FFA_XP_PER_BEATEN = 90      # + per opponent placed STRICTLY below you (was 60)
FFA_PLACE_GOLD_TOP = 50     # 1st  — parity with TEAM_SERIES_WIN_GOLD
FFA_PLACE_GOLD_LAST = 10    # last — deliberately BELOW TEAM_SERIES_LOSS_GOLD
                            # (25): an FFA game has n-1 losers, not 2, and a
                            # flat floor is the AFK-farm surface (no FFA AFK
                            # detector exists yet — learning #58 has no analogue).


def _ffa_win_mult(n_players: int) -> float:
    """Winner's XP/gold multiplier scales with lobby size (Sid round-2 item
    2): x1.5 at the 3-player minimum up to x5.0 for a full 10 — winning a
    bigger FFA is a bigger feat. Gold rides the 100xp=1g conversion."""
    return min(5.0, 1.5 + 0.5 * max(0, n_players - 3))


def _ffa_place_frac(place: int, beaten: int, n_live: int) -> float:
    """0.0 at last place, 1.0 at 1st — the share of the field you outplaced.
    Driven off `beaten` (already ghost-filtered and tie-correct) rather than
    `place`, because ghosts keep their original placement so a live player's
    `place` can exceed `n_live`. `place <= 1` short-circuits so a TIE FOR 1ST
    still gets the full share (the beaten-fraction alone would under-pay it)."""
    if place <= 1 or n_live <= 1:
        return 1.0
    return min(1.0, max(0.0, beaten / float(n_live - 1)))


def _ffa_place_mult(place: int, beaten: int, n_live: int) -> float:
    """Placement multiplier: _ffa_win_mult(n) at 1st, decaying linearly to x1.0
    at last. This is gap (3) above — the lobby-size multiplier becomes a curve
    over the whole field instead of a winner-only switch. 1st place is
    byte-identical to the old winner-only path, so no payout can ever DROP."""
    top = _ffa_win_mult(n_live)
    return 1.0 + (top - 1.0) * _ffa_place_frac(place, beaten, n_live)


def _ffa_place_gold(place: int, beaten: int, n_live: int) -> int:
    """SUPERSEDED by the battles-x-players meter (v1.36.0) — kept because it
    is the exact formula migration 164's pg_temp mirror reproduces for the
    LEGACY back-pay, and legacy games must forever be re-derivable from it.
    Not called by the live award path any more."""
    size = _ffa_win_mult(n_live) / _ffa_win_mult(5)
    frac = _ffa_place_frac(place, beaten, n_live)
    base = FFA_PLACE_GOLD_LAST + (FFA_PLACE_GOLD_TOP - FFA_PLACE_GOLD_LAST) * frac
    return int(round(base * size))


# ── FFA economy v2: the battles × players meter (v1.36.0) ──────────────────
# Sid's rule: meter on WORK, not wall-clock — camping produces no battles and
# therefore no gold. A "battle" is one decisive round = one half-point;
# battles = Σ points_total across the roster, and points_total is INSIDE the
# frozen ffa: HMAC canonical, so the meter's input is signed. Because
# duration ≡ battles × s(P) for honest play, gold per player-minute collapses
# to 60·rate(P)·shape/s(P) — independent of score target and battle count, so
# the score-target knob prices itself with no config table.
#
# KNOWN RESIDUAL (accepted, do NOT document as "structurally closed"): in the
# clamped regime, banked half-points cash in against idle wall-clock —
# fabricate-then-idle is bounded at ≈FFA_PACE_HEADROOM × the honest rate
# (vs 39.6× pre-meter), not zero.
# Drawn rounds (simultaneous death) consume real seconds and award zero
# points_total — baked into the fitted s(P), but a second source of pace
# variance; a reason not to tighten the headroom below 2.0 on current data.
FFA_G_PER_PLAYER_MIN = 3.5    # g per player-minute at the tier-x1.5 calibration
                              # field (2v2 mean 4.32, 1v1 mean 2.50).
FFA_SIZE_SLOPE = 0.05         # DECIDED (Sid, 2026-08-01): 10-player FFA should
                              # be the best gold rate in the game — 0.05/player
                              # above 4 puts the P=10 mean at 4.55 g/plr-min
                              # (~8.3 for 1st once level_reward is counted,
                              # ≈1.44x the best rate in any other mode). The
                              # slope encodes the intent; the base is scale.
FFA_SEC_A, FFA_SEC_B = 3.08, 6.54   # s(P) = A + B·P, weighted LS over 38 prod games
FFA_SEC_CLAMP_P = 6           # s(P) above 6 players is pure extrapolation (two
                              # observed P=6 games, zero above) — clamp the
                              # meter at the P=6 fit until ~200 games exist,
                              # then re-fit from the new audit columns.
FFA_PACE_HEADROOM = 2.0       # rate ceiling = H × the average pace; residual
                              # abuse equals H exactly. The fast tail of s(P)
                              # has never been measured — do not tighten below
                              # 2.0 without measuring it.
FFA_XP_SHARE = 0.45           # 45% of the pool rides as XP (×100 → the
                              # 100xp=1g drip returns it as 'ffa_xp' gold);
                              # 55% pays flat under reason='ffa_placement'.
FFA_MIN_XP = 50               # LOAD-BEARING: migration 164's live/ghost
                              # discriminator is xp_gained > 0 — a metered XP
                              # that rounded to zero would make a live player
                              # read as a ghost to every future back-pay.
FFA_SHAPE_TOP = 1.666         # 1st place pays this × the lobby mean (7.58 vs
                              # 4.55 g/plr-min at P=10 in the r2 model); last
                              # pays 2−this. Linear in the beaten-fraction, so
                              # the shape's mean is 1.0 ABSENT TIES — bottom
                              # ties lower the mean frac below 0.5 and underpay
                              # the lobby (≤~9% at a 4-way bottom tie in a
                              # 10-player game). Documented, not corrected:
                              # flat-in-expectation is the guarantee.


def _ffa_sec_per_battle(n_live: int) -> float:
    return FFA_SEC_A + FFA_SEC_B * min(max(int(n_live or 3), 3), FFA_SEC_CLAMP_P)


def _ffa_battle_rate(n_live: int) -> float:
    """Gold-equivalent per battle per player, at the tier-x1.5 calibration
    field. rate(P) ∝ s(P): battles take longer in bigger lobbies, so a flat
    per-battle rate would pay small lobbies ~2.3x more per MINUTE."""
    gpm = FFA_G_PER_PLAYER_MIN * (1.0 + FFA_SIZE_SLOPE * max(0, int(n_live or 0) - 4))
    return gpm * _ffa_sec_per_battle(n_live) / 60.0


def _ffa_pool_shape(place: int, beaten: int, n_live: int) -> float:
    """Placement shape on the per-player pool: FFA_SHAPE_TOP at 1st, its
    mirror at last, linear in the beaten-fraction, mean 1.0 absent ties."""
    frac = _ffa_place_frac(place, beaten, n_live)
    return (2.0 - FFA_SHAPE_TOP) + (2.0 * FFA_SHAPE_TOP - 2.0) * frac
# Rating movement per game is bounded: each player is compared against at
# most this many placement-adjacent opponents (see submit_ffa_match).
FFA_MAX_RATED_OPPONENTS = 4
# ── FFA betting: odds band + how long a lobby stays bettable ───────────────
FFA_ODDS_MAX = 5.0          # ceiling, reachable only at 10 players with a low RD
FFA_ODDS_MIN_LARGE = 2.0    # floor at 5+ players (Sid's ask)
FFA_ODDS_MIN_SMALL = 1.4    # floor at 3-4 players — 1/3 of a 3-man field is a
                            # 33% shot, so a 2.0 floor there would be near-fair
                            # odds with no margin at all.
# A lobby is bettable only while a NEXT game is plausibly coming. Without this
# a finished sitting stayed listed forever (the "Live FFA betting still shows
# the last session" report) because the only predicate was status='active'.
FFA_BET_LIVE_AFTER_GAME_MINUTES = 30   # ...since the last recorded game ended
FFA_BET_LIVE_ASSEMBLY_MINUTES = 15     # ...since lock, for a lobby with 0 games
# INTERIM exploit gate (see the docstring on _ffa_bet_window_open). FFA has no
# live score server-side, so bets currently stay open until the game's REPORT
# lands — i.e. until the final kill, which is free money for anyone watching.
# Sid's rule is "bet until someone has 2 points"; that needs a client push and
# ships with the next build. Until then, betting on game N closes this many
# seconds after game N-1 ended (or after the lock, for game 1). Delete this
# once the live-score lock is live and adoption is confirmed.
FFA_BET_OPEN_SECONDS = 90
# Engine DEFAULTS — MUST match plugin/FfaMode.cs (RoundsToWin/PointsToWinRound).
# 3 -> 5 after the first playtest (Sid: games ended too fast for the rolling
# card bar to ever engage).
# Since the configurable-lobby columns landed (migration 176), report
# validation reads the LOBBY ROW's frozen config, falling back to these when
# a column is somehow absent. A report is validated against the row, never
# against the report's own claims.
FFA_ROUNDS_TO_WIN = 5
FFA_POINTS_TO_WIN_ROUND = 2
# Feature floor for non-default lobby config: every roster member's
# players.mod_version must be at least this or the lobby's config collapses
# to the defaults AS A SET at Start (never partially — a mixed lobby plays
# exactly today's rules). is_ranked is exempt: it is mixed-version safe
# because the server ANDs it against the row and an old client only
# mis-renders its own HUD badge.
FFA_CONFIG_MIN_VERSION = "1.36.0"
# Kills tie-break floor (Sid approved 2026-08-03): a lobby gets kills-split
# placements only when EVERY member's session-authenticated join advertised
# at least this version (frozen as ffa_lobbies.kills_tiebreak at lock —
# migration 187). ⚠ SHIP COUPLING: must equal the version that ships the v2
# ffa: canonical, or the tie-break never engages / engages one release early.
FFA_KILLS_TIEBREAK_MIN_VERSION = "1.36.0"
FFA_CONFIG_DEFAULTS = {
    "score_target": 5, "card_candidates": 5, "initial_picks": 1,
    "card_cap": 5, "same_card_rule": False,
}


def _ffa_lobby_config(lobby) -> dict:
    """Effective config off a lobby row, default-safe (a row predating
    migration 176 or a None column yields today's shipped values)."""
    cfg = {}
    for k, dflt in FFA_CONFIG_DEFAULTS.items():
        try:
            v = lobby[k] if lobby is not None and k in lobby else None
        except (KeyError, TypeError):
            v = None
        if isinstance(dflt, bool):
            cfg[k] = bool(dflt if v is None else v)
        else:
            cfg[k] = int(v) if v is not None else dflt
    return cfg
# Max points_total one player can honestly bank in one game. points_total is
# CUMULATIVE while the engine's points.Clear() wipes everyone's live half
# whenever ANY player converts a round — so besides their own
# rounds*PointsToWinRound + (PointsToWinRound-1) unconverted, a player can
# lose up to PointsToWinRound-1 banked halves to EACH conversion by each of
# the other n-1 players (Codex review 2026-07-28 find 1: the old flat cap of
# 11 rejected honest long games outright — e.g. 18 halves in a 3-player
# first-to-5). Bound each opponent's conversions by ROUNDS_TO_WIN.
def _ffa_max_points(n_players: int, score_target: int | None = None) -> int:
    tgt = int(score_target or FFA_ROUNDS_TO_WIN)
    own = tgt * FFA_POINTS_TO_WIN_ROUND + (FFA_POINTS_TO_WIN_ROUND - 1)
    cleared = (FFA_POINTS_TO_WIN_ROUND - 1) * tgt * max(0, n_players - 1)
    return own + cleared
# A lobby is one sitting; this bounds a compromised client's fabrication rate.
FFA_MAX_GAMES_PER_LOBBY = 40


async def _quarantine_report(db: AsyncSession, *, mode: str, reason: str, status_code: int,
                             payload, group_id=None, photon_room_id: str | None = None,
                             reporter_id=None, player_ids=None) -> None:
    """Preserve a match report that was rejected for a LIFECYCLE reason.

    Sid, July 30, after two completed FFA games were destroyed: "if it fails
    again, send it to the admin tab instead of having it straight deleted."

    Call this ONLY where the rejection's predicate read a DB row (lobby not
    active, series already resolved, roster missing, game limit) — never for an
    integrity failure (bad HMAC, unknown player, impossible score), or this table
    becomes an unauthenticated write primitive. HMAC has always been verified by
    the time any caller reaches here.

    Runs in its OWN transaction, and the caller is expected to raise immediately
    afterwards: every lifecycle gate fires BEFORE the endpoint's first write, so
    rolling back here discards nothing. Never raises — a failure to quarantine
    must not change the response the client already had coming (#187).
    """
    try:
        await db.rollback()
        # Flood bound, take 2 (Codex round-3 finds 2+3): the round-2 one-row
        # semantic dedupe DESTROYED distinct legitimate games — an outbox
        # retrying two real games of a since-closed lobby shares the
        # (mode, group, reporter, reason) tuple, so game 2's payload was
        # dropped forever. Distinct games have distinct per-game room ids and
        # MUST each be kept: the (mode, photon_room_id) ON CONFLICT below is
        # the retry-idempotency. Hostile flooding (fresh fabricated room ids)
        # is bounded instead by a PER-GROUP pending QUOTA — generous above
        # FFA_MAX_GAMES_PER_LOBBY so every honest multi-game sitting fits —
        # counted under a transaction-scoped ADVISORY lock, because a plain
        # count-then-insert races two concurrent captures past the bound
        # (#207: serialize on a value that exists before the rows do).
        if group_id is not None:
            await db.execute(text(
                "SELECT pg_advisory_xact_lock(hashtext('mrq:' || CAST(:g AS text)))"
            ), {"g": str(group_id)})
            _pending = (await db.execute(text("""
                SELECT COUNT(*) FROM match_report_quarantine
                 WHERE mode = :m AND group_id = :g AND status = 'pending'
            """), {"m": mode, "g": group_id})).scalar() or 0
            if int(_pending) >= 50:
                await db.rollback()
                print(f"[QUARANTINE] pending quota reached for {mode} group={group_id} — not capturing more")
                return
        await db.execute(text("""
            INSERT INTO match_report_quarantine
                (mode, reason, http_status, group_id, photon_room_id,
                 reporter_id, player_ids, payload)
            VALUES (:m, :r, :s, :g, :room, :rep, :pids, CAST(:pl AS JSONB))
            ON CONFLICT (mode, photon_room_id) WHERE photon_room_id IS NOT NULL
                DO NOTHING
        """), {"m": mode, "r": reason[:64], "s": status_code, "g": group_id,
               "room": (photon_room_id or "")[:64] or None, "rep": reporter_id,
               "pids": list(player_ids or []),
               "pl": payload if isinstance(payload, str) else _json.dumps(payload, default=str)})
        await db.commit()
        print(f"[QUARANTINE] {mode} report kept for admin review: {reason} room={photon_room_id}")
    except Exception as ex:
        print(f"[QUARANTINE] capture failed ({mode}/{reason}): {ex}")
        try:
            await db.rollback()
        except Exception:
            pass


def _ffa_sort_key(steam_id: str) -> tuple:
    """Deterministic cross-language ordering for steam ids: (length, ordinal)
    equals numeric order for canonical non-padded numeric ids, and the C#
    reporter implements the identical comparison — the HMAC canonical and
    slot assignment must byte-match without either side parsing int64."""
    return (len(steam_id or ""), steam_id or "")


def _ffa_hmac_canonical(report: FfaMatchReport, include_kills: bool) -> str:
    """FFA is the domain-tagged VARIABLE-length canonical (#213) — it may
    evolve, but only in client/server lockstep. Two live forms:
      v2 (kills-signed, v1.36.0+ clients): per-player steam:rounds:points:kills
      v1 (legacy, <= v1.35.x clients):      per-player steam:rounds:points
    No cross-form collision is possible: both carry str(len(players)) at the
    same position, and 7+4n == 7+3m forces n != m, contradicting the shared
    count field — so one signature can never validate under the other form
    for a different roster shape."""
    parts = [
        "ffa", report.lobby_id, report.photon_room_id or "",
        report.reported_by_steam_id, str(report.is_ranked).lower(),
        report.winner_steam_id, str(len(report.players)),
    ]
    for p in sorted(report.players, key=lambda e: _ffa_sort_key(e.steam_id)):
        parts.extend([p.steam_id, str(p.rounds_won), str(p.points_total)])
        if include_kills:
            parts.append(str(p.kills))
    return ":".join(parts)


def _verify_ffa_hmac(report: FfaMatchReport) -> str | None:
    """Returns the canonical form that verified ("v2" = kills signed,
    "v1" = legacy 3-field players), or None on failure. The DUAL acceptance
    is the deliberate version gate (TODO item 1, Sid-approved 2026-08-03):
    old clients keep reporting under v1 with no MIN_MOD_VERSION bump. Drop v1
    after adoption. TRUST MODEL, stated precisely (Codex Aug-3 finds 2/3):
    the HMAC authenticates the REPORTING BUILD, not gameplay truth — kills,
    like rounds/points/winner, are reporter-attested values a modified client
    can fabricate wholesale; "signed" only means unsigned fields can't
    reorder what the signature covers. A v1 signature is honored only for
    lobbies that are NOT kills-capable (some member below the floor at lock);
    from a kills-capable lobby submit_ffa_match quarantines any v1 report of
    an UNRECORDED room as a downgrade attempt (an already-recorded room gets
    the idempotent replay echo regardless of form) — so deliberately signing
    v1 buys at most the same semantics as joining with an old version
    advertised, which turns the lobby flag off for everyone. Retired when
    the staged MIN_MOD_VERSION raise reaches 1.36.0."""
    if not MATCH_HMAC_SECRET:
        return "v2"
    if not report.hmac_signature:
        print("[FFA-HMAC] no signature provided")
        return None
    for form, include_kills in (("v2", True), ("v1", False)):
        msg = _ffa_hmac_canonical(report, include_kills)
        expected = hmac.new(MATCH_HMAC_SECRET.encode(), msg.encode(), hashlib.sha256).hexdigest()
        if hmac.compare_digest(report.hmac_signature, expected):
            return form
    print(f"[FFA-HMAC] mismatch. canonical_v2='{_ffa_hmac_canonical(report, True)}'")
    return None


class _FfaQueueJoinReq(BaseModel):
    steam_id: str
    display_name: str = "Player"
    region: str | None = None


@app.post("/api/v1/ffa/queue/join", tags=["FFA Queue"])
async def ffa_queue_join(req: _FfaQueueJoinReq, request: Request, db: AsyncSession = Depends(get_db)):
    """Join the FFA queue (consent queue — no Elo band). Idempotent per
    player; re-joining refreshes the display fields and poll timestamp but
    never resets a locked row (same contract as the 1v2 join)."""
    await _check_steam_session(request, req.steam_id, db)
    # Identity gate (round-14 find 1, subsumes the round-13 usage-site ban
    # check): lock + ban/tombstone re-read under it.
    await _enrollment_identity_gate(db, req.steam_id)
    _presence_touch(req.steam_id)
    player = (await db.execute(select(Player).where(Player.steam_id == req.steam_id))).scalar_one_or_none()
    if player is None:
        raise HTTPException(404, "Player not registered")
    # Cross-queue guard (Codex post-release find 1): the auto-rejoin path must
    # not recreate a row the lock-time eviction removed — see /queue/join.
    _other = await _locked_in_other_queue(db, player.id, "ffa_queue")
    if _other:
        raise HTTPException(status_code=409,
                            detail="You're in a live match in another mode - finish it first")
    # Clear an unleased husk BEFORE the upsert (migration 174). The upsert
    # below deliberately preserves a LOCKED row's lifecycle, which is correct
    # for a live lobby and catastrophic for a dead one: the row survives, the
    # endpoint still answers {"status":"ok"}, and the client then shows
    # "searching" while the server has it locked forever. That divergence is
    # the FFA half of "stuck in the queue" — the player presses Join, is told
    # it worked, and nothing happens, repeatedly.
    if await _lease_live_mode(db, player.id) is None:
        _cleared = (await db.execute(text(
            "UPDATE ffa_queue SET status='searching', series_id=NULL, slot=NULL,"
            "       room_name=NULL, room_region=NULL, matched_at=NULL"
            " WHERE player_id = :pid AND status <> 'searching'"
            " RETURNING status"), {"pid": player.id})).scalar()
        if _cleared:
            print(f"[LEASE] FFA join cleared an unleased '{_cleared}' husk for {req.steam_id}")
    g = (await db.execute(text(
        "SELECT rating, rating_deviation, games_played FROM glicko_ratings_ffa WHERE player_id = :pid"
    ), {"pid": player.id})).mappings().first()
    rating = g["rating"] if g else 1500.0
    rd = g["rating_deviation"] if g else 350.0
    games = g["games_played"] if g else 0
    g1 = (await db.execute(text(
        "SELECT rating FROM glicko_ratings WHERE player_id = :pid"
    ), {"pid": player.id})).mappings().first()
    fallback = float(g1["rating"]) if g1 and g1["rating"] is not None else 1500.0
    _res = await db.execute(text("""
        INSERT INTO ffa_queue (player_id, steam_id, display_name, rating, rating_deviation,
                               games_played, fallback_rating, region, status, joined_at, last_polled,
                               mod_version)
        VALUES (:pid, :sid, :dn, :r, :rd, :gp, :fr, :reg, 'searching', NOW(), NOW(), :mv)
        ON CONFLICT (player_id) DO UPDATE SET
            display_name = EXCLUDED.display_name, region = EXCLUDED.region,
            -- Capability provenance (Codex Aug-3 r2 find 1): this is the
            -- caller's OWN session-authenticated header — the only version
            -- signal the kills-tiebreak lock computation may trust.
            mod_version = EXCLUDED.mod_version,
            -- Bug #109: a rejoin after quitting the game found the old ghost
            -- row and kept its joined_at ("in queue 18 minutes already").
            -- A SEARCHING row is a fresh search — reset the clock and the
            -- rating snapshot. A LOCKED row keeps BOTH (Codex find 7): its
            -- lifecycle — and its lock-time snapshot the whole lobby shares —
            -- belong to the lock.
            rating = CASE WHEN ffa_queue.status = 'searching'
                          THEN EXCLUDED.rating ELSE ffa_queue.rating END,
            rating_deviation = CASE WHEN ffa_queue.status = 'searching'
                          THEN EXCLUDED.rating_deviation ELSE ffa_queue.rating_deviation END,
            games_played = CASE WHEN ffa_queue.status = 'searching'
                          THEN EXCLUDED.games_played ELSE ffa_queue.games_played END,
            fallback_rating = CASE WHEN ffa_queue.status = 'searching'
                          THEN EXCLUDED.fallback_rating ELSE ffa_queue.fallback_rating END,
            last_polled = NOW(),
            joined_at = CASE WHEN ffa_queue.status = 'searching'
                             THEN NOW() ELSE ffa_queue.joined_at END
        RETURNING status
    """), {"pid": player.id, "sid": req.steam_id, "dn": req.display_name[:64], "r": rating,
           "rd": rd, "gp": games, "fr": fallback, "reg": (req.region or "")[:8] or None,
           "mv": (_current_mod_version.get() or "")[:16] or None})
    _row_status = _res.scalar_one_or_none()
    if _row_status == "searching":
        # Authoritative arrival stamp for the gather window (Codex find 5):
        # the poll's SKIP LOCKED slice can momentarily miss this row, so the
        # join itself records the arrival. Locked rows never extend a gather.
        globals()["_ffa_gather_last_join_mono"] = time.monotonic()
    await db.commit()
    n = (await db.execute(text("SELECT COUNT(*) FROM ffa_queue WHERE status = 'searching'"))).scalar() or 0
    return {"status": "ok", "queue_count": int(n)}


# ── FFA host lobbies (July 29 redesign — Sid's spec) ───────────────────────
# A host opens a lobby, players browse and join, the host presses Start at
# 3+ members. Start produces EXACTLY the state the legacy gather-decider lock
# produces (active ffa_lobbies row + ready_join queue rows), so everything
# downstream — auto-join, reports, roster validation, self-heals, betting —
# is the existing shipped machinery, untouched. While a lobby is OPEN, its
# queue rows (status='lobby', series_id=lobby id) are the ONLY membership
# truth; member_ids stays empty until Start freezes the roster. The legacy
# auto-gather flow above stays intact for 1.35.1 clients until the minimum
# version crosses the redesign build (the pools are disjoint by status).
#
# Locking protocol (design review find 4): every membership mutation locks
# the LOBBY row first, then queue rows in canonical player-id order, then
# re-reads authoritative state. Poll/leave/start get this from
# _lock_queue_group_for_player ('lobby' is a grouped status); create/join
# implement it directly; the janitor arm and account deletion use
# FOR UPDATE SKIP LOCKED on the lobby. Freshness is the established 75s
# contract everywhere (find 5).

FFA_LOBBY_MEMBER_FRESH_SQL = "last_polled > NOW() - INTERVAL '75 seconds'"


async def _ffa_live_lobby_members(db: AsyncSession, lobby_id):
    """Fresh 'lobby' members of an open lobby, promotion order (joined_at,
    then player_id::text — deterministic per design review Q3)."""
    return (await db.execute(text(f"""
        SELECT player_id, steam_id, display_name, rating, games_played,
               fallback_rating, region, joined_at
          FROM ffa_queue
         WHERE series_id = :lid AND status = 'lobby'
           AND {FFA_LOBBY_MEMBER_FRESH_SQL}
         ORDER BY joined_at, player_id::text
    """), {"lid": lobby_id})).mappings().all()


def _ffa_effective_host(lobby_host_id, live_members):
    """The player allowed to press Start: the stored host if still a live
    member, else the earliest-joined live member (display + validation use
    this; it is PERSISTED only by leave/prune/start — never by reads)."""
    if not live_members:
        return None
    live_ids = {m["player_id"] for m in live_members}
    if lobby_host_id in live_ids:
        return lobby_host_id
    return live_members[0]["player_id"]


async def _ffa_lobby_snapshot_fields(db: AsyncSession, player_id):
    """Rating-snapshot fields for a queue row (same shape the legacy join
    stores — the browser shows them, and Start's lock reuses them)."""
    g = (await db.execute(text(
        "SELECT rating, rating_deviation, games_played FROM glicko_ratings_ffa WHERE player_id = :pid"
    ), {"pid": player_id})).mappings().first()
    g1 = (await db.execute(text(
        "SELECT rating FROM glicko_ratings WHERE player_id = :pid"
    ), {"pid": player_id})).mappings().first()
    return {
        "r": g["rating"] if g else 1500.0,
        "rd": g["rating_deviation"] if g else 350.0,
        "gp": g["games_played"] if g else 0,
        "fr": float(g1["rating"]) if g1 and g1["rating"] is not None else 1500.0,
    }


class _FfaLobbyCreateReq(BaseModel):
    steam_id: str
    display_name: str = "Player"
    region: str | None = None


class _FfaLobbyJoinReq(BaseModel):
    steam_id: str
    display_name: str = "Player"
    region: str | None = None
    lobby_id: str


async def _ffa_lobby_enroll_caller(db: AsyncSession, player, req, lobby_id) -> None:
    """Move the caller's queue row into `lobby_id` under the already-held
    lobby lock. CAS ladder (design review find 8): only a missing row or a
    'searching' row may become a lobby membership — a row the legacy gather
    just locked (ready_join) or a different lobby's membership 409s; no
    implicit lobby switching in round one (Q4/Q7). Raises HTTPException on
    conflict; caller's transaction (including a just-created lobby row)
    rolls back with it."""
    mine = (await db.execute(text(
        "SELECT status, series_id FROM ffa_queue WHERE player_id = :pid FOR UPDATE"
    ), {"pid": player.id})).mappings().first()
    # A locked row whose LEASE has lapsed is a husk, not a commitment
    # (migration 174). Without this the cross-mode half of the strand would be
    # fixed while the FFA half stayed permanent: the row still 409s every
    # Create/Join, so the player watches everyone else queue FFA while their
    # own button rejects them with no way to clear it. This is the specific
    # "stuck in the ffa queue" half of bug reports #124 and #139.
    if mine is not None and mine["status"] != "searching":
        if await _lease_live_mode(db, player.id) is None:
            await db.execute(text(
                "UPDATE ffa_queue SET status='searching', series_id=NULL, slot=NULL,"
                "       room_name=NULL, room_region=NULL, matched_at=NULL,"
                "       joined_at=NOW(), last_polled=NOW()"
                " WHERE player_id = :pid"), {"pid": player.id})
            print(f"[LEASE] FFA enroll cleared an unleased {mine['status']} husk "
                  f"for {req.steam_id} (lobby {mine['series_id']})")
            mine = {"status": "searching", "series_id": None}
    if mine is not None and mine["status"] == "lobby":
        if mine["series_id"] == lobby_id:
            # Idempotent same-lobby rejoin — the client recovery path (find 6).
            # mod_version refreshes too: this is the member's own session-
            # authenticated call, and the lobby is still OPEN (pre-lock).
            await db.execute(text(
                "UPDATE ffa_queue SET last_polled = NOW(), display_name = :dn,"
                "       mod_version = :mv WHERE player_id = :pid"
            ), {"pid": player.id, "dn": req.display_name[:64],
                "mv": (_current_mod_version.get() or "")[:16] or None})
            return
        raise HTTPException(409, "Leave your current lobby first")
    if mine is not None and mine["status"] not in ("searching",):
        raise HTTPException(409, "You're locked into another FFA game — finish or leave it first")
    snap = await _ffa_lobby_snapshot_fields(db, player.id)
    _enrolled = False
    if mine is None:
        # ON CONFLICT DO NOTHING + re-check (impl review adjacent find): two
        # concurrent enrolls for the same account (double-click across PCs)
        # must produce a 409, not a unique-violation 500 that aborts the
        # caller's transaction.
        inserted = (await db.execute(text("""
            INSERT INTO ffa_queue (player_id, steam_id, display_name, rating, rating_deviation,
                                   games_played, fallback_rating, region, status, series_id,
                                   joined_at, last_polled, mod_version)
            VALUES (:pid, :sid, :dn, :r, :rd, :gp, :fr, :reg, 'lobby', :lid, NOW(), NOW(), :mv)
            ON CONFLICT (player_id) DO NOTHING
            RETURNING player_id
        """), {"pid": player.id, "sid": req.steam_id, "dn": req.display_name[:64],
               "reg": (req.region or "")[:8] or None, "lid": lobby_id,
               "mv": (_current_mod_version.get() or "")[:16] or None, **snap})).scalar()
        if inserted is None:
            raise HTTPException(409, "Your queue state just changed — try again")
        _enrolled = True
    else:
        # CAS: the WHERE re-checks 'searching' on the locked row — a legacy
        # gather cannot have flipped it under our lock, but the guard makes
        # the invariant explicit and free.
        flipped = (await db.execute(text("""
            UPDATE ffa_queue SET status='lobby', series_id=:lid, slot=NULL,
                   room_name=NULL, room_region=NULL, matched_at=NULL,
                   display_name=:dn, region=:reg, rating=:r, rating_deviation=:rd,
                   games_played=:gp, fallback_rating=:fr,
                   joined_at=NOW(), last_polled=NOW(), mod_version=:mv
             WHERE player_id=:pid AND status='searching'
            RETURNING player_id
        """), {"pid": player.id, "dn": req.display_name[:64],
               "reg": (req.region or "")[:8] or None, "lid": lobby_id,
               "mv": (_current_mod_version.get() or "")[:16] or None, **snap})).scalar()
        if flipped is None:
            raise HTTPException(409, "Your queue state just changed — try again")
        _enrolled = True
    # Open-lobby seat: short lease, renewed by this member's own ~2s poll. If
    # they close the game while sitting in a lobby the seat frees itself in
    # minutes instead of waiting on the 75s prune plus a lobby closure.
    #
    # Placed AFTER the if/else on purpose: it used to sit inside the `else`,
    # so a player with NO existing ffa_queue row — i.e. anyone joining an open
    # lobby fresh, the common case — got a membership with no lease at all.
    # Cross-mode admission would then have considered them free for the whole
    # open-lobby wait and another mode could have locked them out from under
    # the host's Start.
    if _enrolled:
        await _lease_acquire(db, player.id, "ffa", lobby_id, LEASE_TTL_POLLING)


@app.post("/api/v1/ffa/lobby/create", tags=["FFA Queue"])
async def ffa_lobby_create(req: _FfaLobbyCreateReq, request: Request, db: AsyncSession = Depends(get_db)):
    """Open a host lobby. The caller becomes host and its only member."""
    await _check_steam_session(request, req.steam_id, db)
    _presence_touch(req.steam_id)
    # Identity gate (round-14 find 1): lock + ban/tombstone re-read under it.
    await _enrollment_identity_gate(db, req.steam_id)
    player = (await db.execute(select(Player).where(Player.steam_id == req.steam_id))).scalar_one_or_none()
    if player is None:
        raise HTTPException(404, "Player not registered")
    _other = await _locked_in_other_queue(db, player.id, "ffa_queue")
    if _other:
        raise HTTPException(409, "You're in a live match in another mode - finish it first")
    lobby_id = uuid.uuid4()
    # Brand-new row: invisible to every other transaction until commit, so
    # inserting it first IS the lobby-first order for the enroll below.
    await db.execute(text("""
        INSERT INTO ffa_lobbies (id, status, player_count, member_ids, host_player_id, created_at)
        VALUES (:lid, 'open', 0, '{}', :host, NOW())
    """), {"lid": lobby_id, "host": player.id})
    await _ffa_lobby_enroll_caller(db, player, req, lobby_id)
    await db.commit()
    print(f"[FFA-LOBBY] {req.steam_id} opened lobby {lobby_id}")
    # A lobby member is committed to FFA — clear their searches elsewhere
    # (design review find 3; post-commit, own transactions, SKIP LOCKED).
    await _evict_other_queue_searching(db, [player.id], "ffa_queue", "an open FFA lobby")
    return {"status": "ok", "lobby_id": str(lobby_id)}


@app.post("/api/v1/ffa/lobby/join", tags=["FFA Queue"])
async def ffa_lobby_join(req: _FfaLobbyJoinReq, request: Request, db: AsyncSession = Depends(get_db)):
    """Join an open host lobby from the browser."""
    await _check_steam_session(request, req.steam_id, db)
    _presence_touch(req.steam_id)
    # Identity gate (round-14 find 1): lock + ban/tombstone re-read under it.
    await _enrollment_identity_gate(db, req.steam_id)
    player = (await db.execute(select(Player).where(Player.steam_id == req.steam_id))).scalar_one_or_none()
    if player is None:
        raise HTTPException(404, "Player not registered")
    try:
        lobby_id = UUID(req.lobby_id)
    except (ValueError, TypeError):
        raise HTTPException(400, "Invalid lobby_id")
    _other = await _locked_in_other_queue(db, player.id, "ffa_queue")
    if _other:
        raise HTTPException(409, "You're in a live match in another mode - finish it first")
    # Lobby-first lock, then prune/count/enroll under it (find 4: join must
    # revalidate open + capacity under the lobby lock, or two joins at 9/10
    # both pass and produce 11).
    lrow = (await db.execute(text(
        "SELECT id, status FROM ffa_lobbies WHERE id = :lid FOR UPDATE"
    ), {"lid": lobby_id})).mappings().first()
    if lrow is None or lrow["status"] != "open":
        raise HTTPException(404, "That lobby is no longer open")
    await db.execute(text(f"""
        DELETE FROM ffa_queue
         WHERE series_id = :lid AND status = 'lobby'
           AND NOT ({FFA_LOBBY_MEMBER_FRESH_SQL})
    """), {"lid": lobby_id})
    live = await _ffa_live_lobby_members(db, lobby_id)
    if any(m["player_id"] == player.id for m in live):
        # Idempotent same-lobby rejoin handled in the enroll helper too, but
        # short-circuit so the capacity check below can't 409 our own row.
        await _ffa_lobby_enroll_caller(db, player, req, lobby_id)
        await db.commit()
        # Eviction runs on the idempotent path too (impl review find 10): if
        # the FIRST enrollment's best-effort eviction failed, the recovery
        # rejoin is the only later actor that can repair the cross-queue ghost.
        await _evict_other_queue_searching(db, [player.id], "ffa_queue", "an open FFA lobby")
        return {"status": "ok", "lobby_id": str(lobby_id),
                **(await _ffa_lobby_config_echo(db, lobby_id))}
    if len(live) >= FFA_MAX_PLAYERS:
        raise HTTPException(409, "That lobby is full")
    await _ffa_lobby_enroll_caller(db, player, req, lobby_id)
    await db.commit()
    print(f"[FFA-LOBBY] {req.steam_id} joined lobby {lobby_id} ({len(live)+1} members)")
    await _evict_other_queue_searching(db, [player.id], "ffa_queue", "an open FFA lobby")
    # Config echo (Codex client round-2 find 13): without it the client's
    # mirrors show defaults (or the PREVIOUS lobby's values) until the first
    # membership poll lands.
    return {"status": "ok", "lobby_id": str(lobby_id),
            **(await _ffa_lobby_config_echo(db, lobby_id))}


async def _ffa_lobby_config_echo(db: AsyncSession, lobby_id) -> dict:
    """The five config fields the client mirrors, straight off the row.
    Best-effort: an error returns {} (client falls back to defaults + poll)."""
    try:
        row = (await db.execute(text(
            "SELECT score_target, card_candidates, initial_picks, card_cap,"
            "       same_card_rule, is_ranked FROM ffa_lobbies WHERE id = :lid"
        ), {"lid": lobby_id})).mappings().first()
        cfg = _ffa_lobby_config(row)
        return {
            "score_target": cfg["score_target"],
            "initial_picks": cfg["initial_picks"],
            "card_cap": cfg["card_cap"],
            "same_card_rule": bool(cfg["same_card_rule"]),
            # is_ranked is not in FFA_CONFIG_DEFAULTS (it predates the config
            # system) — read it off the row directly, default TRUE.
            "lobby_ranked": bool(row["is_ranked"]) if row is not None and row["is_ranked"] is not None else True,
        }
    except Exception as ex:
        print(f"[FFA-LOBBY] config echo failed for {lobby_id}: {ex}")
        return {}


def _ffa_initial_picks_floor(card_cap: int, score_target: int) -> int:
    """§7d: every NON-WINNER banks at least `score_target` picks, so total
    opening draws T >= clamp(C+1-N, 1, C) guarantees they fill a complete
    hand even in the worst case. (The sweeper is out of scope by decision —
    a clean sweep finishes with exactly T cards, accepted.)"""
    return max(1, min(int(card_cap), int(card_cap) + 1 - int(score_target)))


def _ffa_apply_ranked_bounds(cfg: dict) -> list:
    """Sid, Aug 3: RANKED FFA runs on a tighter config than casual.

      * card_cap 3-5 (casual may go to 6). A 6-card hand changes the mode
        enough that rated results stop being comparable across lobbies.
      * initial_picks <= card_cap ALWAYS. Dealing more opening cards than a
        player can hold just burns picks and real time at the card screen —
        the surplus is discarded the moment the hand fills.

    CLAMPS rather than rejects, and returns the names of what it changed, so
    a host who flips ranked ON with a casual-legal config lands on a valid
    ranked config with the change reported instead of an error they have to
    decode. Called from EVERY config writer (create/settings/start) — the
    bound must not depend on which endpoint happened to write last."""
    touched = []
    if cfg.get("is_ranked", True):
        if int(cfg.get("card_cap", 5)) > 5:
            cfg["card_cap"] = 5
            touched.append("card_cap")
    if int(cfg.get("initial_picks", 1)) > int(cfg.get("card_cap", 5)):
        cfg["initial_picks"] = int(cfg["card_cap"])
        touched.append("initial_picks")
    return touched


class _FfaLobbySettingsReq(BaseModel):
    steam_id: str
    score_target: int | None = None
    card_candidates: int | None = None
    initial_picks: int | None = None
    card_cap: int | None = None
    same_card_rule: bool | None = None
    is_ranked: bool | None = None


@app.post("/api/v1/ffa/lobby/settings", tags=["FFA Queue"])
async def ffa_lobby_settings(req: _FfaLobbySettingsReq, request: Request,
                             db: AsyncSession = Depends(get_db)):
    """Host edits the lobby config while it is still OPEN. Values are
    validated + clamped server-side and the CLAMPED values are returned so
    the host's UI reflects reality immediately (§7d). Omitted fields keep
    their current value. settings_changed_at re-arms the 60s start gate only
    when a value ACTUALLY changes (a host mashing the same value must not be
    locked out; A→B→A does re-arm, correctly — someone who joined during B
    saw B)."""
    await _check_steam_session(request, req.steam_id, db)
    _presence_touch(req.steam_id)
    me = await _lock_queue_group_for_player(db, "ffa_queue", req.steam_id)
    if me is None or me["status"] != "lobby" or me["series_id"] is None:
        raise HTTPException(409, "You're not in an open lobby")
    lobby_id = me["series_id"]
    lrow = (await db.execute(text(
        "SELECT * FROM ffa_lobbies WHERE id = :lid"
    ), {"lid": lobby_id})).mappings().first()
    if lrow is None or lrow["status"] != "open":
        raise HTTPException(409, "That lobby is no longer open")
    live = await _ffa_live_lobby_members(db, lobby_id)
    host_id = _ffa_effective_host(lrow["host_player_id"], live)
    if host_id != me["player_id"]:
        raise HTTPException(403, "Only the lobby host can change settings")

    cur = _ffa_lobby_config(lrow)
    cur["is_ranked"] = bool(lrow["is_ranked"]) if ("is_ranked" in lrow and lrow["is_ranked"] is not None) else True
    new = dict(cur)
    if req.score_target is not None:
        if not (3 <= req.score_target <= 10):
            raise HTTPException(400, "score_target must be 3-10")
        new["score_target"] = int(req.score_target)
    if req.card_candidates is not None:
        # Range check kept 1-5 but the KNOB IS LOCKED for v1.36.0 (Sid,
        # 2026-08-01: same-card rule ships this release; the candidates knob
        # ships a later one — §9c forbids both in one release). Reject any
        # non-default so no lobby row can carry a value no client honors yet.
        if req.card_candidates != 5:
            raise HTTPException(400, "Card draw size is locked at 5 for now")
        new["card_candidates"] = 5
    if req.card_cap is not None:
        if not (3 <= req.card_cap <= 6):
            raise HTTPException(400, "card_cap must be 3-6")
        new["card_cap"] = int(req.card_cap)
    if req.initial_picks is not None:
        if not (1 <= req.initial_picks <= 4):
            raise HTTPException(400, "initial_picks must be 1-4 (base draw + up to 3 extra)")
        new["initial_picks"] = int(req.initial_picks)
    if req.same_card_rule is not None:
        new["same_card_rule"] = bool(req.same_card_rule)
    if req.is_ranked is not None:
        new["is_ranked"] = bool(req.is_ranked)
    # §7d floor: clamp UP (never reject) so leaving both new controls alone
    # can never silently violate the fill-a-hand guarantee, and clamp to the
    # cap (T > C would drag rolling removal into game start — decided T <= C).
    floor_t = _ffa_initial_picks_floor(new["card_cap"], new["score_target"])
    new["initial_picks"] = max(floor_t, min(new["initial_picks"], new["card_cap"], 4))
    _bounded = _ffa_apply_ranked_bounds(new)
    if _bounded:
        print(f"[FFA] lobby {lobby_id}: ranked bounds clamped {_bounded} -> "
              f"cap={new['card_cap']} picks={new['initial_picks']}")

    changed = [k for k in new if new[k] != cur[k]]
    if changed:
        # clock_timestamp(), not NOW(): NOW() freezes before a lock wait, so a
        # settings write that waited would stamp the past and the 60s gate
        # would expire early (#277).
        await db.execute(text("""
            UPDATE ffa_lobbies
               SET score_target=:st, card_candidates=:cc, initial_picks=:ip,
                   card_cap=:cap, same_card_rule=:scr, is_ranked=:rk,
                   settings_changed_at=clock_timestamp()
             WHERE id=:lid AND status='open'
        """), {"st": new["score_target"], "cc": new["card_candidates"],
               "ip": new["initial_picks"], "cap": new["card_cap"],
               "scr": new["same_card_rule"], "rk": new["is_ranked"],
               "lid": lobby_id})
        print(f"[FFA-LOBBY] {req.steam_id} changed lobby {lobby_id} settings: "
              + ", ".join(f"{k}={new[k]}" for k in changed))
    await db.commit()
    return {"status": "ok", "changed": changed,
            "score_target": new["score_target"],
            "card_candidates": new["card_candidates"],
            "initial_picks": new["initial_picks"],
            "card_cap": new["card_cap"],
            "same_card_rule": new["same_card_rule"],
            "lobby_ranked": new["is_ranked"]}


class _FfaLobbyStartReq(BaseModel):
    steam_id: str


@app.post("/api/v1/ffa/lobby/start", tags=["FFA Queue"])
async def ffa_lobby_start(req: _FfaLobbyStartReq, request: Request, db: AsyncSession = Depends(get_db)):
    """Host presses Start: freeze the roster and produce the legacy lock
    state. From here on the lobby is indistinguishable from a gather lock."""
    await _check_steam_session(request, req.steam_id, db)
    _presence_touch(req.steam_id)
    # Refresh our own liveness FIRST (find 5): the authenticated Start is
    # proof the host's client is alive even if its polls lagged a rebuild.
    await db.execute(text(
        "UPDATE ffa_queue SET last_polled = NOW() WHERE steam_id = :sid AND status = 'lobby'"
    ), {"sid": req.steam_id})
    await db.commit()
    me = await _lock_queue_group_for_player(db, "ffa_queue", req.steam_id)
    if me is None or me["status"] != "lobby" or me["series_id"] is None:
        raise HTTPException(409, "You're not in an open lobby")
    lobby_id = me["series_id"]
    # The group helper already holds the lobby row FOR UPDATE + member rows.
    lrow = (await db.execute(text(
        "SELECT * FROM ffa_lobbies WHERE id = :lid"
    ), {"lid": lobby_id})).mappings().first()
    if lrow is None or lrow["status"] != "open":
        raise HTTPException(409, "That lobby is no longer open")
    await db.execute(text(f"""
        DELETE FROM ffa_queue
         WHERE series_id = :lid AND status = 'lobby'
           AND NOT ({FFA_LOBBY_MEMBER_FRESH_SQL})
    """), {"lid": lobby_id})
    live = await _ffa_live_lobby_members(db, lobby_id)
    # Hosted Start is a FORMATION surface (round-17 find 3): a banned seat —
    # e.g. one left by the pre-deploy old API, which purged sessions but not
    # queue rows — must not be frozen into member_ids. Remove banned seats
    # here, before the roster freeze; the survivor count then decides.
    _start_banned = []
    for _m in live:
        _msid = (await db.execute(text(
            "SELECT steam_id FROM players WHERE id = :pid"
        ), {"pid": _m["player_id"]})).scalar()
        if _msid is not None and (await _is_banned(db, _msid)) is not None:
            _start_banned.append(_m["player_id"])
    if _start_banned:
        await db.execute(text(
            "DELETE FROM ffa_queue WHERE player_id = ANY(:ids)"), {"ids": _start_banned})
        live = [m for m in live if m["player_id"] not in _start_banned]
        print(f"[FFA-LOBBY] start: removed {len(_start_banned)} banned seat(s) from lobby {lobby_id}")
    host_id = _ffa_effective_host(lrow["host_player_id"], live)
    if host_id != me["player_id"]:
        raise HTTPException(403, "Only the lobby host can start the game")
    if host_id is not None and host_id != lrow["host_player_id"]:
        await db.execute(text("UPDATE ffa_lobbies SET host_player_id=:h WHERE id=:lid"),
                         {"h": host_id, "lid": lobby_id})
    # §7b settings lock, BOTH anchors (decided): a configured lobby cannot
    # start within 60s of a real settings change, NOR within 15s of the
    # newest member joining (a host who configured alone and pressed Start
    # one second after someone walked in baited nobody — but nobody read
    # anything either). Applies ONLY when the lobby was actually configured
    # (settings_changed_at non-NULL); a default lobby keeps today's
    # zero-friction start. clock_timestamp() on the read side too, so a lock
    # wait can't hand out a stale remaining-seconds figure. The server check
    # is the gate; the client countdown is decoration.
    _sc_at = lrow["settings_changed_at"] if "settings_changed_at" in lrow else None
    if _sc_at is not None:
        _gate = (await db.execute(text("""
            SELECT GREATEST(
                     60.0 - EXTRACT(EPOCH FROM (clock_timestamp() - l.settings_changed_at)),
                     15.0 - EXTRACT(EPOCH FROM (clock_timestamp() - COALESCE((
                           SELECT MAX(q.joined_at) FROM ffa_queue q
                            WHERE q.series_id = l.id AND q.status = 'lobby'),
                           l.settings_changed_at)))
                   ) AS wait_s
              FROM ffa_lobbies l WHERE l.id = :lid
        """), {"lid": lobby_id})).scalar()
        if _gate is not None and float(_gate) > 0:
            raise HTTPException(409,
                f"Settings changed recently - wait {int(float(_gate)) + 1}s so everyone can read them")
    if len(live) < FFA_MIN_PLAYERS:
        raise HTTPException(409, f"Need at least {FFA_MIN_PLAYERS} players to start")
    # §7d re-validation at Start: the floor depends on BOTH card_cap and
    # score_target, so a later change to either can invalidate an earlier
    # initial_picks (#208's re-read rule applied to config). Clamp up
    # silently — the guarantee, not the host's number, is the contract.
    _start_cfg = _ffa_lobby_config(lrow)
    _start_cfg["is_ranked"] = bool(lrow["is_ranked"]) if ("is_ranked" in lrow and lrow["is_ranked"] is not None) else True
    _floor_t = _ffa_initial_picks_floor(_start_cfg["card_cap"], _start_cfg["score_target"])
    _start_cfg["initial_picks"] = max(_floor_t, min(_start_cfg["initial_picks"], _start_cfg["card_cap"], 4))
    # Ranked bounds re-checked HERE too (Sid, Aug 3): a lobby row can predate
    # the rule, or have been flipped to ranked after its cap was set, so Start
    # is the last gate before a rated game inherits an out-of-bounds config.
    _ffa_apply_ranked_bounds(_start_cfg)
    _fixed_t = _start_cfg["initial_picks"]
    if _fixed_t != int(lrow["initial_picks"] or 1) or _start_cfg["card_cap"] != int(lrow["card_cap"] or 5):
        await db.execute(text(
            "UPDATE ffa_lobbies SET initial_picks = :t, card_cap = :c WHERE id = :lid"
        ), {"t": _fixed_t, "c": _start_cfg["card_cap"], "lid": lobby_id})
        print(f"[FFA] lobby {lobby_id}: start-time config clamp -> "
              f"cap={_start_cfg['card_cap']} picks={_fixed_t}")
    # EXACTLY the legacy gather-decider lock body from here. created_at is
    # reset to NOW() because every active-lobby consumer (25-min dispersed
    # close, bettable assembly window, zero-game dead sweep) reads it as the
    # ACTIVATION time (design review find 2 — a lobby that sat open 26
    # minutes would otherwise be janitor-closed on the next sweep).
    ordered = sorted(live, key=lambda r: _ffa_sort_key(r["steam_id"]))
    # Config feature floor (§3a): the server is the real authority, and it
    # decides HERE — before any Photon room exists, so there is no propagation
    # race to lose. If ANY roster member's build is below the floor, the
    # lobby's config collapses to the defaults AS A SET (never partially): a
    # mixed lobby plays exactly today's rules. is_ranked is deliberately not
    # part of the collapse (mixed-version safe — the server ANDs it at
    # submit; an old client only mis-renders its own HUD badge).
    _pids = [r["player_id"] for r in ordered]
    _vrows = (await db.execute(
        select(Player.id, Player.mod_version).where(Player.id.in_(_pids))
    )).all()
    _floor = _parse_version(FFA_CONFIG_MIN_VERSION)
    _all_capable = len(_vrows) == len(_pids) and all(
        _parse_version(v.mod_version or "0") >= _floor for v in _vrows)
    if not _all_capable:
        await db.execute(text("""
            UPDATE ffa_lobbies
               SET score_target=5, card_candidates=5, initial_picks=1,
                   card_cap=5, same_card_rule=FALSE
             WHERE id=:lid
        """), {"lid": lobby_id})
        print(f"[FFA-LOBBY] lobby {lobby_id}: roster below config floor "
              f"{FFA_CONFIG_MIN_VERSION} — config collapsed to defaults")
    # Kills tie-break capability, frozen HERE (migration 187): TRUE only when
    # EVERY member's ffa_queue.mod_version — stamped by that member's OWN
    # session-authenticated join/create call — clears the floor.
    # players.mod_version is deliberately NOT consulted for this flag: any
    # preflight caller can stamp that column onto another player's row (Codex
    # Aug-3 r2 find 1), while a queue row's version is only ever written by
    # its own player's request. NULL/missing ⇒ not capable ⇒ legacy shared-tie
    # semantics (the safe direction, #288).
    _kt_vals = (await db.execute(text(
        "SELECT mod_version FROM ffa_queue WHERE player_id = ANY(:ids)"
    ), {"ids": [r["player_id"] for r in ordered]})).scalars().all()
    _kt_floor = _parse_version(FFA_KILLS_TIEBREAK_MIN_VERSION)
    _kills_tiebreak = len(_kt_vals) == len(ordered) and all(
        _parse_version((v or "0").lstrip("vV")) >= _kt_floor for v in _kt_vals)
    regions = [r["region"] for r in ordered if r["region"]]
    region = max(set(regions), key=regions.count) if regions else "us"
    room = f"ffa_{uuid.uuid4().hex[:12]}"
    await db.execute(text("""
        UPDATE ffa_lobbies
           SET status='active', photon_room_id=:room, region=:reg,
               player_count=:n, member_ids=:members, created_at=NOW(),
               kills_tiebreak=:kt
         WHERE id=:lid AND status='open'
    """), {"room": room, "reg": (region or "us")[:8], "n": len(ordered),
           "members": [r["player_id"] for r in ordered], "lid": lobby_id,
           "kt": _kills_tiebreak})
    for slot, r in enumerate(ordered):
        await db.execute(text("""
            UPDATE ffa_queue SET status='ready_join', series_id=:lid, slot=:slot,
                   room_name=:room, room_region=:reg, matched_at=NOW()
             WHERE player_id=:pid
        """), {"lid": lobby_id, "slot": slot, "room": room, "reg": (region or "us")[:8],
               "pid": r["player_id"]})
    # Locked seats: assembly-length lease, then renewed by the authenticated
    # in_match ping for as long as battles are actually running. Once the
    # sitting genuinely ends nothing renews it and it lapses on its own -- no
    # cleanup path has to fire, which is the whole point (migration 174).
    await _lease_acquire_many(db, [r["player_id"] for r in ordered], "ffa",
                              lobby_id, LEASE_TTL_ASSEMBLY)
    await db.commit()
    print(f"[FFA-LOBBY] host {req.steam_id} started lobby {lobby_id} room {room} n={len(ordered)}")
    await _evict_other_queue_searching(
        db, [r["player_id"] for r in ordered], "ffa_queue", "an FFA lobby")
    return await _ffa_poll_locked_payload(db, lobby_id, req.steam_id)


@app.get("/api/v1/ffa/lobbies", tags=["FFA Queue"])
async def ffa_lobby_browser(db: AsyncSession = Depends(get_db)):
    """Open host lobbies for the browser panel. Host name + live member count
    only (round-one scope per the design review — member names arrive in the
    joined poll). Read-only: effective host is derived, never persisted here."""
    # HAVING inside the query, not a post-LIMIT filter (impl review find 6):
    # zero-member husks awaiting the janitor must not consume the LIMIT and
    # crowd real lobbies out of the browser.
    lobbies = (await db.execute(text(f"""
        SELECT l.id, l.host_player_id, l.created_at,
               COUNT(q.player_id) FILTER (WHERE {FFA_LOBBY_MEMBER_FRESH_SQL}) AS live_n
          FROM ffa_lobbies l
          LEFT JOIN ffa_queue q ON q.series_id = l.id AND q.status = 'lobby'
         WHERE l.status = 'open'
         GROUP BY l.id, l.host_player_id, l.created_at
        HAVING COUNT(q.player_id) FILTER (WHERE {FFA_LOBBY_MEMBER_FRESH_SQL}) > 0
         ORDER BY l.created_at DESC
         LIMIT 20
    """))).mappings().all()
    now = datetime.now(timezone.utc)
    out = []
    for l in lobbies:
        live = await _ffa_live_lobby_members(db, l["id"])
        if not live:
            continue   # started/emptied between the two reads — skip, not "?"
        host_id = _ffa_effective_host(l["host_player_id"], live)
        host = next((m for m in live if m["player_id"] == host_id), None)
        out.append({
            "lobby_id": str(l["id"]),
            "host_name": (host["display_name"] if host else "?") or "?",
            "player_count": len(live),
            "max_players": FFA_MAX_PLAYERS,
            "age_seconds": int((now - l["created_at"]).total_seconds()) if l["created_at"] else 0,
        })
    return {"lobbies": out, "count": len(out)}


@app.post("/api/v1/ffa/queue/leave", tags=["FFA Queue"])
async def ffa_queue_leave(request: Request, steam_id: str = Query(...),
                          expected_lobby_id: str | None = Query(None),
                          cause: str = Query("", max_length=16),
                          db: AsyncSession = Depends(get_db)):
    """Leave the FFA queue. Zero-game locked lobby → DISSOLVED (canceled,
    everyone else reset to searching — the #150 lifecycle rule). Lobby WITH
    recorded games → the whole lobby CLOSES: the roster is fixed at lock, so
    one member leaving means the remaining group can never reach N again in
    that room (Codex design find 4 — leaving them 'ready_join' would re-feed
    a dead room forever). Everyone's rows are deleted; they requeue fresh."""
    await _check_steam_session(request, steam_id, db)
    # Fenced on the lobby the client actually means, so a delayed retry for a
    # finished lobby cannot revoke the lease of one joined since.
    await _lease_release_by_steam(db, steam_id, expected_lobby_id)
    # (Removed, July 30 audit item 3: this endpoint used to run a 2h "stale
    # sweep" over UNRELATED active lobbies on every leave request. It was a
    # blind closer — old activity, no live-game evidence, no veto — and the
    # janitor's dispersed close is the single lifecycle authority now:
    # size-scaled window, in_match veto, bounded 3h ceiling.)
    me = await _lock_queue_group_for_player(db, "ffa_queue", steam_id)
    if me is None:
        # Codex round-3 residual 10: a member whose queue row is already gone
        # (sweeps prune rows independently of the lobby) still needs their
        # departure RECORDED, or the all-but-one closure arithmetic never
        # completes and the roster looks fuller than it is. Membership comes
        # from the lobby's frozen roster, not the row. Mark-only — closure
        # stays with the row-carrying paths and the janitor.
        #
        # Round-4 find 4: scoped to the EXACT lobby the client's leave intent
        # names — new clients always send expected_lobby_id, and without the
        # scope a retried leave could mark a departure on a NEWER lobby the
        # player joined meanwhile. A leave without a target marks nothing
        # (old-client behaviour, unchanged).
        if expected_lobby_id:
            try:
                marked = (await db.execute(text("""
                    UPDATE ffa_lobbies l
                       SET departed_ids = (SELECT ARRAY(SELECT DISTINCT e
                                             FROM unnest(l.departed_ids || p.id) e))
                      FROM players p
                     WHERE p.steam_id = :sid
                       AND l.id = CAST(:lid AS uuid)
                       AND l.status = 'active'
                       AND p.id = ANY(l.member_ids)
                       AND NOT (l.departed_ids @> ARRAY[p.id])
                     RETURNING l.id
                """), {"sid": steam_id, "lid": expected_lobby_id})).scalars().all()
                if marked:
                    print(f"[FFA-LOCK] rowless leaver {steam_id} marked departed on lobby {expected_lobby_id}")
            except Exception as ex:
                print(f"[FFA-LOCK] rowless departure mark failed for {steam_id}: {ex}")
                try:
                    await db.rollback()
                except Exception:
                    pass
        await db.commit()
        return {"status": "ok"}
    dissolved = False
    lobby_id = me["series_id"]
    # Delayed-retry fence for BOTH lobby shapes (impl review find 2): a leave
    # retry that was aimed at lobby A must never tear down a LATER membership
    # or lock in lobby B. New clients always send the id they mean.
    if (expected_lobby_id and lobby_id is not None
            and me["status"] in ("lobby", "ready_join")
            and str(lobby_id) != expected_lobby_id):
        await db.commit()
        return {"status": "ok", "note": "membership moved on"}
    # Open host-lobby member (July 29 redesign): remove, promote, disband —
    # all under the lobby-first locks the group helper already holds.
    if me["status"] == "lobby" and lobby_id is not None:
        await db.execute(text("DELETE FROM ffa_queue WHERE player_id = :pid"),
                         {"pid": me["player_id"]})
        lrow = (await db.execute(text(
            "SELECT status, host_player_id FROM ffa_lobbies WHERE id = :lid"
        ), {"lid": lobby_id})).mappings().first()
        if lrow is not None and lrow["status"] == "open":
            live = await _ffa_live_lobby_members(db, lobby_id)
            if not live:
                await db.execute(text(
                    """UPDATE ffa_lobbies SET status='canceled', invalidated_at=NOW(),
                              invalidation_reason='lobby_disbanded'
                        WHERE id=:lid AND status='open'"""), {"lid": lobby_id})
                print(f"[FFA-LOBBY] lobby {lobby_id} disbanded (last member left: {steam_id})")
            elif lrow["host_player_id"] == me["player_id"]:
                await db.execute(text(
                    "UPDATE ffa_lobbies SET host_player_id=:h WHERE id=:lid"
                ), {"h": live[0]["player_id"], "lid": lobby_id})
                print(f"[FFA-LOBBY] host left lobby {lobby_id} — promoted earliest member")
        await db.commit()
        return {"status": "ok"}
    if me["status"] == "ready_join" and lobby_id is not None:
        lrow = (await db.execute(text(
            "SELECT l.status, l.games_played FROM ffa_lobbies l WHERE l.id = :lid FOR UPDATE"
        ), {"lid": lobby_id})).mappings().first()
        # July 30 lifecycle audit item 2: games_played stays 0 for the WHOLE of
        # live game 1 (reports land at game END), so "zero games" alone is not
        # assembly-failure evidence — one player quitting 30 minutes into a
        # 40-minute game 1 used to dissolve the lobby for everyone and the
        # reporter's result then 409'd (the July 30 incident's second half).
        # A zero-game lobby WITH live-game evidence takes the played-lobby
        # departure path below instead.
        # Round-8 gate: during the post-boot evidence window, a PRE-BOOT lock
        # with no observed heartbeat is INDETERMINATE, not a failed assembly —
        # the API restarting mid-game-1 empties _in_match_seen, and a member
        # quitting in the ~60s before the next ping used to dissolve the live
        # lobby (the survivors' report then 409'd). A pre-boot zero-game lock
        # in that window takes the DEPARTURE path below (lobby stays; if it
        # really was a dead assembly, the guarded janitor cleans it once
        # evidence matures). A lock created AFTER boot keeps the one-shot
        # dissolution — this process would have heard its heartbeats (#270a:
        # veto-on-ignorance must not turn post-boot failed assemblies into
        # husks).
        # Round-9 gate, the STRUCTURAL fix Codex named: the CLIENT knows this
        # leave's cause — an exit from inside the ffa_ ROOM can never be
        # "failed assembly" (the leaver was demonstrably at/past assembly),
        # and no server-side evidence scheme can reconstruct that knowledge
        # through the async heartbeat edge (a battle's first in_match ping
        # trails its start by up to ~5s + HTTP). in_room_exit therefore takes
        # the departure path UNCONDITIONALLY; only pre-room leaves (menu
        # clicks, declines, watchdog bails — cause absent or other) may
        # dissolve. Old clients send no cause and keep the evidence-based
        # behaviour below.
        _in_room_exit = cause == "in_room_exit"
        # Round-13 REVERSAL of the round-12 fresh_cancel override: Codex
        # proved it was a hostile-void primitive — ONE member's unverified
        # claim cancelled a LIVE game (warm heartbeat and all), refunded its
        # wagers, and 409'd the real report; a rematch could even mislabel
        # game 2's cancel onto unreported game 1 (#280's criterion fails:
        # a false in_room_exit preserves, a false fresh_cancel destroys,
        # irreversibly). The cause is now LOG-ONLY: a genuine below-quorum
        # fresh cancel rides the evidence-guarded path like any other leave,
        # and its worst case is a few minutes of janitor-cleaned husk with
        # delayed bet reconciliation — bounded and reversible.
        if cause == "fresh_cancel":
            print(f"[FFA-LOCK] leave cause=fresh_cancel from {steam_id} (log-only)")
        _startup_indeterminate = False
        if (not _in_room_exit
                and lrow is not None and lrow["status"] == "active"
                and int(lrow["games_played"] or 0) == 0
                and not _in_match_evidence_trustworthy()
                and not _group_game_positively_live(str(lobby_id))):
            _locked_at = (await db.execute(text(
                "SELECT MAX(matched_at) FROM ffa_queue WHERE series_id = :lid"
            ), {"lid": lobby_id})).scalar()
            _startup_indeterminate = (_locked_at is None
                                      or _locked_at <= _PROCESS_STARTED_WALL)
        if (lrow is not None and lrow["status"] == "active"
                and int(lrow["games_played"] or 0) == 0
                and not _in_room_exit
                and not _startup_indeterminate
                and not _group_game_positively_live(str(lobby_id))):
            await db.execute(text(
                "UPDATE ffa_lobbies SET status='canceled', invalidation_reason='assembly_timeout',"
                "       invalidated_at=NOW() WHERE id=:lid AND status='active'"
            ), {"lid": lobby_id})
            await db.execute(text("""
                UPDATE ffa_queue SET status='searching', series_id=NULL, slot=NULL,
                       room_name=NULL, room_region=NULL, matched_at=NULL, joined_at=NOW()
                 WHERE series_id = :lid AND player_id != :pid
            """), {"lid": lobby_id, "pid": me["player_id"]})
            await _reconcile_ffa_lobby_bets(db, lobby_id, "lobby dissolved")
            dissolved = True
            print(f"[FFA-LOCK] lobby dissolved by leave (lobby {lobby_id}, leaver {steam_id})")
        elif lrow is not None and lrow["status"] == "active":
            # Played (or live-game-1) lobby: the lobby STAYS ACTIVE while >=2
            # members remain (closing it here made the survivors' final report
            # 409 — the leaver's client fires this the moment they quit
            # mid-game). Round-2 review find 6: the lobby TRACKS departures —
            # the bettable field excludes departed players, and the lobby
            # closes deterministically when all-but-one member has left.
            #
            # Codex batch find 10: the survivors' queue rows are no longer
            # deleted HERE. Deleting them at leave time stripped the
            # cross-mode lock off players still mid-game, and a LATER leaver
            # then had no row, so their leave hit the me-is-None path (which
            # since round 3 marks departure from the frozen roster instead of
            # dropping it). Rows still die with the lobby's own lifecycle
            # (closure below, dispersed close, sitting-over) and the janitor's
            # 60-min windows bound them regardless — "kept" means kept while
            # the sitting is genuinely live, not immortal.
            # Codex round-3 regression 7: all-but-one departures can land while
            # the FINAL game's report is still in flight (leavers quit during
            # the last game) — closing then quarantines the genuine report and
            # refunds bets that should settle against it. With live-game
            # evidence the leave only MARKS; the report's own completion path,
            # or the dispersed sweep, closes the lobby afterwards.
            # Round-9 gate find 1: uncertainty must SURVIVE into this
            # decision. Positive evidence, a client-attested in-room exit,
            # or the startup-unknown window all take the mark-only branch —
            # completing on collapsed-to-false uncertainty quarantined the
            # last survivor's in-flight report. A lobby wrongly left active
            # here is closed later by the dispersed/sitting-over sweeps.
            game_live_now = (_group_game_positively_live(str(lobby_id))
                             or _in_room_exit
                             or not _in_match_evidence_trustworthy())
            all_but_one = False
            # CAST(:pid AS uuid) is LOAD-BEARING, not decoration. departed_ids
            # is uuid[], and with a bare bind parameter on the right Postgres
            # resolves `||` as array||array and types the parameter as uuid[] —
            # so asyncpg demands a list, gets a scalar UUID, and raises
            # DataError. That aborts the transaction, the endpoint's trailing
            # "DELETE FROM ffa_queue WHERE player_id = :pid" never runs, and the
            # caller keeps a ready_join row that locks them out of EVERY queue
            # in every mode. Shipped broken from v1.35.0 to v1.35.4: 34/34 leave
            # requests in one prod log window were 500s and departed_ids was
            # empty on 35 of 36 lobbies. Verified against prod:
            #   ARRAY[]::uuid[] || $1              -> parameter_types {uuid[]}
            #   ARRAY[]::uuid[] || CAST($1 AS uuid) -> parameter_types {uuid}
            # The rowless-leaver UPDATE above is safe only because it concats a
            # real column (p.id), whose type the parser already knows.
            if game_live_now:
                # RETURNING the all-but-one test, not just performing the mark.
                # Previously this branch hardcoded closed="active", so the
                # threshold was never evaluated on the live-game path and the
                # survivor-freeing DELETE below was unreachable from it. The
                # comment above justified that by deferring to "the report's
                # own completion path" — which does not exist: the only
                # ffa_lobbies write in submit_ffa_match is
                # `games_played = games_played + 1`. A crossed threshold was
                # therefore recorded and then acted on by nobody, leaving the
                # last survivor holding a ready_join row on a permanently
                # 'active' lobby.
                all_but_one = bool((await db.execute(text("""
                    UPDATE ffa_lobbies
                       SET departed_ids = (SELECT ARRAY(SELECT DISTINCT e FROM unnest(departed_ids || CAST(:pid AS uuid)) e))
                     WHERE id = :lid AND status = 'active'
                    RETURNING cardinality(departed_ids)
                              >= COALESCE(player_count, cardinality(member_ids)) - 1
                """), {"lid": lobby_id, "pid": me["player_id"]})).scalar())
                # Still 'active' on purpose: the final game's report may be in
                # flight, and closing here would quarantine it and refund bets
                # that should settle. The survivors are released below without
                # touching the lobby (round-3 regression 7 stands).
                closed = "active"
            else:
                closed = (await db.execute(text("""
                    UPDATE ffa_lobbies
                       SET departed_ids = (SELECT ARRAY(SELECT DISTINCT e FROM unnest(departed_ids || CAST(:pid AS uuid)) e)),
                           status = CASE WHEN cardinality((SELECT ARRAY(SELECT DISTINCT e FROM unnest(departed_ids || CAST(:pid AS uuid)) e)))
                                              >= COALESCE(player_count, cardinality(member_ids)) - 1
                                         THEN 'completed' ELSE status END,
                           completed_at = CASE WHEN cardinality((SELECT ARRAY(SELECT DISTINCT e FROM unnest(departed_ids || CAST(:pid AS uuid)) e)))
                                                    >= COALESCE(player_count, cardinality(member_ids)) - 1
                                               THEN NOW() ELSE completed_at END
                     WHERE id = :lid AND status = 'active'
                     RETURNING status
                """), {"lid": lobby_id, "pid": me["player_id"]})).scalar()
            if closed == "completed" or all_but_one:
                # The sitting is over — now the survivors' rows go too, so
                # nobody stays locked out of other queues by a closed lobby.
                # `all_but_one` covers the live-game branch, where the lobby
                # deliberately stays 'active' for an in-flight report: the
                # remaining player cannot reach N again in that room, so their
                # seat is meaningless and holding it only strands them.
                await db.execute(text(
                    "DELETE FROM ffa_queue WHERE series_id = :lid AND player_id != :pid"
                ), {"lid": lobby_id, "pid": me["player_id"]})
                # And their leases — the row is hygiene, the lease is the
                # actual exclusion (migration 174).
                await db.execute(text("""
                    DELETE FROM queue_leases
                     WHERE mode = 'ffa' AND group_id = :lid AND player_id != :pid
                """), {"lid": lobby_id, "pid": me["player_id"]})
            if closed == "completed":
                await _reconcile_ffa_lobby_bets(db, lobby_id, "sitting over (last members left)")
                print(f"[FFA-LOCK] played lobby {lobby_id} closed — all but one member departed")
            else:
                print(f"[FFA-LOCK] member left played lobby {lobby_id} (leaver {steam_id}) — lobby stays active for the survivors")
    await db.execute(text("DELETE FROM ffa_queue WHERE player_id = :pid"), {"pid": me["player_id"]})
    await db.commit()
    return {"status": "ok", "lock_dissolved": dissolved}


@app.get("/api/v1/ffa/queue/recent-joins", tags=["FFA Queue"])
async def ffa_queue_recent_joins(seconds: int = Query(20), db: AsyncSession = Depends(get_db)):
    """Players who joined the FFA queue in the last N seconds (Discord beacon
    parity with the other queues). Rating shown is the FFA elo once the player
    has FFA games, else their 1v1 elo as the only meaningful hint.

    Covers BOTH FFA flows. The July-29 host-lobby redesign put lobby members in
    this same table under `status='lobby'` (series_id = the lobby), and this
    query still filtered `status='searching'` only — so opening or joining a
    lobby produced no Discord beacon at all, while the legacy gather queue kept
    working. Same shape as the sweep bug in learning #252: a status predicate
    written before a new state existed silently drops the new state's rows.
    Enumerate the VALID states rather than assuming one."""
    rows = (await db.execute(text("""
        SELECT q.display_name, q.steam_id, q.rating, q.games_played, q.fallback_rating, q.joined_at,
               q.status,
               CASE WHEN q.status = 'lobby' THEN q.series_id END AS lobby_id,
               (l.host_player_id IS NOT NULL AND l.host_player_id = q.player_id) AS is_host,
               (SELECT COUNT(*) FROM ffa_queue m
                 WHERE m.series_id = q.series_id AND m.status = 'lobby') AS lobby_members,
               CASE WHEN p.show_discord THEN p.discord_display_name END AS discord_display_name
          FROM ffa_queue q
          LEFT JOIN players p ON p.steam_id = q.steam_id
          LEFT JOIN ffa_lobbies l ON l.id = q.series_id AND q.status = 'lobby'
         WHERE q.joined_at > NOW() - INTERVAL '1 second' * :secs
           AND (q.status = 'searching'
                OR (q.status = 'lobby' AND l.status = 'open'))
         ORDER BY q.joined_at DESC
    """), {"secs": seconds})).mappings().all()
    cnt = (await db.execute(text(
        "SELECT COUNT(*) FROM ffa_queue WHERE status = 'searching'"
        "   AND last_polled > NOW() - INTERVAL '75 seconds'"
    ))).scalar() or 0
    return {
        "joins": [
            {"display_name": r["display_name"], "steam_id": r["steam_id"],
             "rating": int(round(r["rating"] if (r["games_played"] or 0) > 0 else (r["fallback_rating"] or 1500))),
             "joined_at": r["joined_at"].isoformat() if r["joined_at"] else None,
             "discord_display_name": r["discord_display_name"],
             # Lobby fields are null for a legacy gather-queue join, so an old
             # bot build renders exactly what it does today.
             "lobby_id": str(r["lobby_id"]) if r["lobby_id"] else None,
             "is_host": bool(r["is_host"]),
             "lobby_members": int(r["lobby_members"] or 0)}
            for r in rows
        ],
        "queue_size": int(cnt),
    }


@app.get("/api/v1/ffa/queue/list", tags=["FFA Queue"])
async def ffa_queue_list(db: AsyncSession = Depends(get_db)):
    """Snapshot of the LEGACY FFA queue panel: fresh searching rows + recent
    locks. Same ghost-filtering contract as the 1v2 list. Explicitly excludes
    host-lobby members ('lobby' rows) — old 1.35.1 clients render this list as
    ONE gather pool with a "locks at 3+" caption, and hosted-lobby members are
    not part of any gather (design review find 10). New clients browse
    /ffa/lobbies instead."""
    rows = (await db.execute(text("""
        SELECT q.steam_id, q.display_name, q.status, q.slot, q.region, q.joined_at,
               q.rating, q.games_played, q.fallback_rating
          FROM ffa_queue q
         WHERE (q.status = 'searching' AND q.last_polled > NOW() - INTERVAL '75 seconds')
            OR (q.status = 'ready_join'
                AND COALESCE(q.matched_at, q.joined_at) > NOW() - INTERVAL '3 hours')
         ORDER BY q.joined_at ASC
    """))).mappings().all()
    now = datetime.now(timezone.utc)
    out = []
    for r in rows:
        has_ffa = (r["games_played"] or 0) > 0
        out.append({
            "steam_id": r["steam_id"],
            "display_name": r["display_name"],
            "rating": int(round(r["rating"])) if has_ffa else 0,
            "rating_1v1": int(round(r["fallback_rating"] or 1500)),
            "status": r["status"],
            "slot": int(r["slot"]) if r["slot"] is not None else -1,
            "wait_seconds": int((now - r["joined_at"]).total_seconds()) if r["joined_at"] else 0,
            "region": r["region"],
        })
    return {"queuers": out, "count": len(out)}


@app.get("/api/v1/ffa/queue/poll/{steam_id}", tags=["FFA Queue"])
async def ffa_queue_poll(steam_id: str, request: Request, db: AsyncSession = Depends(get_db)):
    """Poll the FFA queue. Lock rule: with >= FFA_MIN_PLAYERS fresh searching
    rows, the lowest Steam ID AMONG THE LOCKED SET (ovt lesson — the decider
    must be a member) locks up to FFA_MAX_PLAYERS earliest joiners once the
    gather window has run (or instantly when full). Session-bound (Codex
    design find 8): an unauthenticated poll would let anyone keep a victim's
    row eternally fresh and repeatedly elect it into doomed lobbies."""
    await _check_steam_session(request, steam_id, db)
    _presence_touch(steam_id)
    locked = await _lock_queue_group_for_player(db, "ffa_queue", steam_id)
    if locked is None:
        return {"status": "not_in_queue", "queue_count": 0}
    me = (await db.execute(text(
        "SELECT * FROM ffa_queue WHERE steam_id = :sid"
    ), {"sid": steam_id})).mappings().first()
    if me is None:
        await db.commit()
        return {"status": "not_in_queue", "queue_count": 0}
    await db.execute(
        text("UPDATE ffa_queue SET last_polled = NOW() WHERE player_id = :pid"),
        {"pid": me["player_id"]},
    )

    # Ghost prune (75s survives a backend redeploy; 3h husks) — same shape and
    # SKIP LOCKED reasoning as the ovt poll.
    await db.execute(text("""
        DELETE FROM ffa_queue WHERE player_id IN (
            SELECT player_id FROM ffa_queue
             WHERE status = 'searching' AND last_polled < NOW() - INTERVAL '75 seconds'
             FOR UPDATE SKIP LOCKED)
    """))
    # Own-group exclusion (Codex sitting-over review find 4): SKIP LOCKED
    # does not skip OUR transaction's locks, so a >3h wedged group's own
    # poll would delete its grouped rows here and the sitting-over self-heal
    # below would see zero members and never close the lobby. The caller's
    # group is the self-heal's to dissolve; this sweep owns everyone else's.
    await db.execute(text("""
        DELETE FROM ffa_queue WHERE player_id IN (
            SELECT player_id FROM ffa_queue
             WHERE status != 'searching' AND matched_at IS NOT NULL
               AND matched_at < NOW() - INTERVAL '3 hours'
               AND series_id IS DISTINCT FROM :my_series
             FOR UPDATE SKIP LOCKED)
    """), {"my_series": me["series_id"]})

    # Absolute 30-min searching cap (July 28, Sid item 1 — parity with the
    # 1v1/2v2 polls). Explicit 'expired' status so the client shows WHY the
    # queue ended instead of auto-rejoining on a bare not_in_queue.
    if me["status"] == "searching" and me["joined_at"] is not None:
        _waited = (datetime.now(timezone.utc) - me["joined_at"]).total_seconds()
        if _waited > 30 * 60:
            await db.execute(text("DELETE FROM ffa_queue WHERE player_id = :pid"),
                             {"pid": me["player_id"]})
            await db.commit()
            return {"status": "expired", "queue_count": 0}

    # Open host-lobby member (July 29 redesign). The group helper holds the
    # lobby row + member rows, so the state we report cannot be mid-mutation.
    if me["status"] == "lobby" and me["series_id"] is not None:
        lrow = (await db.execute(text(
            "SELECT l.*,"
            "       GREATEST(0.0, 60.0 - EXTRACT(EPOCH FROM (clock_timestamp() - l.settings_changed_at)))"
            "           AS settings_lock_remaining"
            "  FROM ffa_lobbies l WHERE l.id = :lid"
        ), {"lid": me["series_id"]})).mappings().first()
        if lrow is None or lrow["status"] != "open":
            # Start flips member rows to ready_join ATOMICALLY under the
            # lobby lock, so a 'lobby' row on a non-open lobby is either a
            # canceled lobby (janitor/disband) or an invariant violation —
            # log the latter, heal both by dropping the row, and tell the
            # client EXPLICITLY (a bare not_in_queue would trip the
            # auto-rejoin path — design review find 9 / #150 family).
            if lrow is not None and lrow["status"] == "active":
                print(f"[FFA-LOBBY] INVARIANT: 'lobby' row survived Start on active lobby "
                      f"{me['series_id']} (player {steam_id}) — healing")
            await db.execute(text("DELETE FROM ffa_queue WHERE player_id = :pid"),
                             {"pid": me["player_id"]})
            await db.commit()
            return {"status": "lobby_closed", "queue_count": 0}
        # Renew the OPEN-lobby seat from the poll. This is the one locked
        # state where poll-renewal is correct: a member of an open lobby is
        # definitionally sitting at the menu, and the seat is cheap to
        # re-acquire if it lapses.
        #
        # DO NOT copy this into the ready_join branch below, however obvious
        # it looks. A LOCKED row's lease must be renewed ONLY by evidence of
        # an actual battle (the authenticated in_match ping). Renewing it from
        # the poll would mean a client wedged in the leave/poll retry loop
        # keeps its own exclusion alive forever — which is precisely the
        # unbounded strand migration 174 exists to remove, reintroduced by a
        # one-line "consistency" edit.
        _seat_ok = True
        try:
            async with db.begin_nested():
                _seat_ok = await _lease_renew(
                    db, me["player_id"], "ffa", me["series_id"],
                    LEASE_TTL_POLLING, max_total_seconds=LEASE_MAX_LOBBY_SEAT)
        except Exception as _lex:
            print(f"[LEASE] ffa lobby renew failed for {steam_id}: {_lex}")
        if not _seat_ok:
            # The seat has outlived the 2h ceiling (or its lease is gone). The
            # first draft ignored this return value, which left the row fresh
            # and the lease dead — so the player became cross-mode free, could
            # start a game in another mode, and the FFA host pressing Start
            # would then have yanked them straight back out. A capped seat has
            # to actually END. 'lobby_closed' (not 'not_in_queue') is the right
            # signal: the client tears the membership down and stops polling,
            # whereas not_in_queue with OpenFfaLobbyId still set re-arms the
            # auto-rejoin loop.
            await db.execute(text("DELETE FROM ffa_queue WHERE player_id = :pid"),
                             {"pid": me["player_id"]})
            # FENCED to this lobby's FFA lease. A bare release would delete
            # whatever lease exists — and _lease_renew returns false for
            # "your lease now belongs to another mode" too, so an expired FFA
            # seat whose player had since been claimed by a team formation
            # would have had that live team lease deleted out from under them.
            await db.execute(text(
                "DELETE FROM queue_leases WHERE player_id = :pid"
                "   AND mode = 'ffa' AND group_id = :lid"),
                {"pid": me["player_id"], "lid": me["series_id"]})
            await db.commit()
            print(f"[LEASE] open-lobby seat expired for {steam_id} (lobby {me['series_id']})")
            return {"status": "lobby_closed", "queue_count": 0}
        live = await _ffa_live_lobby_members(db, me["series_id"])
        host_id = _ffa_effective_host(lrow["host_player_id"], live)
        now_utc = datetime.now(timezone.utc)
        await db.commit()
        _cfg = _ffa_lobby_config(lrow)
        # §7b: REMAINING seconds, never an absolute timestamp (#180 — client
        # clocks are not attribution-safe). The larger of the two anchors so
        # the countdown the host sees matches the gate Start will apply.
        _lock_s = 0
        if lrow["settings_changed_at"] is not None:
            _newest_join = max((m["joined_at"] for m in live if m["joined_at"]), default=None)
            _join_s = 0.0
            if _newest_join is not None:
                _join_s = max(0.0, 15.0 - (now_utc - _newest_join).total_seconds())
            # CEILING, not int-truncation (Codex find 11): at 59.2s the
            # truncated 0 made can_start=true while Start's own float check
            # still 409'd — the display predicate and the gate must agree.
            _lock_s = math.ceil(max(float(lrow["settings_lock_remaining"] or 0.0), _join_s))
        return {
            "status": "lobby",
            "lobby_id": str(me["series_id"]),
            "is_host": host_id == me["player_id"],
            "can_start": (host_id == me["player_id"] and len(live) >= FFA_MIN_PLAYERS
                          and _lock_s <= 0),
            "player_count": len(live),
            "max_players": FFA_MAX_PLAYERS,
            "min_players": FFA_MIN_PLAYERS,
            "queue_count": len(live),
            # Frozen-at-render config scalars for the settings panel (#73).
            "score_target": _cfg["score_target"],
            "card_candidates": _cfg["card_candidates"],
            "initial_picks": _cfg["initial_picks"],
            "card_cap": _cfg["card_cap"],
            "same_card_rule": _cfg["same_card_rule"],
            "lobby_ranked": bool(lrow["is_ranked"]) if lrow["is_ranked"] is not None else True,
            "settings_lock_seconds": _lock_s,
            "members": [
                {"steam_id": m["steam_id"], "display_name": m["display_name"],
                 "rating": int(round(m["rating"])) if (m["games_played"] or 0) > 0 else 0,
                 "rating_1v1": int(round(m["fallback_rating"] or 1500)),
                 "is_host": m["player_id"] == host_id,
                 "wait_seconds": int((now_utc - m["joined_at"]).total_seconds()) if m["joined_at"] else 0}
                for m in live
            ],
        }

    # Already locked → self-heal dead locks, else report the lobby.
    if me["status"] == "ready_join" and me["series_id"] is not None:
        lrow = (await db.execute(text(
            "SELECT l.status, l.games_played, l.player_count"
            "  FROM ffa_lobbies l WHERE l.id = :lid"
        ), {"lid": me["series_id"]})).mappings().first()
        lock_age = ((datetime.now(timezone.utc) - me["matched_at"]).total_seconds()
                    if me["matched_at"] is not None else 0)
        # Presence gate (bug #114 item 3, learning #150's rule the hard way):
        # a first-to-5 FFA game 1 routinely outlasts 10 minutes, and reports
        # only land at game END — "no games yet + old lock" alone cancelled a
        # LIVE 4-player lobby mid-game tonight (assembly_timeout) and every
        # report after it 409'd. Queue polls stop at ready_join, but the
        # always-on presence ping keeps firing from a running game — so a
        # zero-game old lock is only DEAD when no member has pinged presence
        # in the last 3 minutes (all clients gone/crashed).
        zero_game_stale = (lrow is not None and lrow["status"] == "active"
                           and int(lrow["games_played"] or 0) == 0 and lock_age > 600)
        members_online = False
        if zero_game_stale and not _in_match_evidence_trustworthy():
            # Round-6 gate find (the last F1 hole): a FRESH process has an
            # EMPTY presence map, so "no member pinged recently" proves
            # nothing for ~210s after boot — this branch was cancelling a
            # LIVE 10-minute game 1 the moment a relaunched seat polled
            # first. Absence-based destruction defers until the evidence
            # matures; this poll re-fires every 2-3s, so the deferral costs
            # minutes at most (the #270 recurring-actor veto rule), and the
            # tri-state payload below answers startup-unknown meanwhile.
            members_online = True
        elif zero_game_stale and _group_game_positively_live(me["series_id"]):
            # Round-8 gate: a POSITIVE in-match heartbeat (any process age)
            # vetoes the lobby-wide cancel outright — the pings authenticate
            # against the FROZEN roster, so they keep arriving even when the
            # queue rows were partially pruned by the pre-round-8 sweep.
            members_online = True
        elif zero_game_stale:
            # Round-8 gate: derive peers from the FROZEN ROSTER
            # (ffa_lobbies.member_ids), never from surviving ffa_queue rows —
            # a pre-round-8 husk sweep could leave ONE survivor, making the
            # surviving-row peer list empty and "everyone offline" true while
            # pruned members were still mid-game.
            mem_sids = (await db.execute(text(
                "SELECT p.steam_id FROM ffa_lobbies l"
                "  JOIN players p ON p.id = ANY(l.member_ids)"
                " WHERE l.id = :lid AND p.steam_id <> :me"
            ), {"lid": me["series_id"], "me": steam_id})).scalars().all()
            # `steam_id <> :me` is LOAD-BEARING. This poll called
            # _presence_touch(steam_id) at its top, so including the caller
            # made members_online unconditionally True and the whole
            # `zero_game_stale and not members_online` term dead code — a
            # self-heal whose trigger could never fire (learning #247's shape,
            # third occurrence in this subsystem). The question this asks is
            # "is anyone ELSE still running the mod"; the caller demonstrably
            # is, so their own presence answers nothing.
            members_online = any(_presence_is_online(s) for s in mem_sids)
        dead = (lrow is None or lrow["status"] != "active"
                or (zero_game_stale and not members_online))
        # ── Lease expiry frees the CALLER, and only the caller ─────────────
        # Deliberately NOT folded into `dead` above, even though it reads like
        # the same condition. `dead` cancels the LOBBY and reconciles its bets;
        # routing an expired lease through it would mean a run of failed
        # in_match heartbeats during a genuinely live sitting destroys that
        # sitting for everyone — the exact class of bug that has repeatedly
        # killed live games here (the 5m04s sitting-over close, the 25-minute
        # dispersed close, the assembly_timeout cancel).
        #
        # The lease answers "is THIS player still committed", never "is this
        # lobby still alive". So it drops one row and touches nothing else: no
        # lobby status, no departed_ids, no bets, no survivors. A late match
        # report still validates against the lobby's frozen roster, so being
        # freed early can never cost a recorded game — which is what makes the
        # expire-by-default direction safe (migration 174).
        if not dead and await _lease_live_mode(db, me["player_id"]) is None:
            await db.execute(text("DELETE FROM ffa_queue WHERE player_id = :pid"),
                             {"pid": me["player_id"]})
            await db.commit()
            print(f"[LEASE] freed {steam_id} from lobby {me['series_id']} "
                  f"(lease expired; lobby left untouched)")
            return {"status": "not_in_queue", "queue_count": 0}
        # ── Sitting-over self-heal (July 28 "trapped in a dead lobby"
        # incident, Sid's directive). The queue-poll is the INVERSE in-game
        # heartbeat: clients only poll it from the MENU / assembly screens —
        # a client actually playing a game does not poll. So "EVERY member's
        # row is being polled right now" proves nobody is mid-game, and the
        # server can free the group no matter how any client's loop wedged:
        #   A) played lobby, newest game >5 min old, all members polling ->
        #      the sitting is over. Close it (games kept), free everyone.
        #   B) zero-game lobby, all members polling 5+ min after lock ->
        #      the room never came together. Dissolve back to searching so
        #      the group re-gathers fresh. (5 min, not less: the post-
        #      ready_join cancel-detector polls THROUGH a slow assembly, and
        #      a legitimate assembly never needs 5 minutes.)
        sitting_over = False
        assembly_failed = False
        if not dead and lrow is not None and lrow["status"] == "active":
            mem_polls = (await db.execute(text(
                "SELECT COUNT(*) AS total,"
                "       COUNT(*) FILTER (WHERE last_polled > NOW() - INTERVAL '90 seconds') AS fresh"
                "  FROM ffa_queue WHERE series_id = :lid"
            ), {"lid": me["series_id"]})).mappings().first()
            all_polling = (mem_polls is not None and int(mem_polls["total"] or 0) > 0
                           and int(mem_polls["total"]) == int(mem_polls["fresh"]))
            if all_polling and int(lrow["games_played"] or 0) > 0:
                last_game = (await db.execute(text(
                    "SELECT MAX(ended_at) FROM ffa_matches WHERE lobby_id = :lid"
                ), {"lid": me["series_id"]})).scalar()
                # 900s, not 300s (Sid, July 30 - this closed a LIVE sitting 5m04s
                # after its game 1 recorded, and game 2's report then 409'd with
                # "Lobby is not active", losing that game outright).
                #
                # The premise above is sound and still holds: a client mid-GAME
                # does not poll, so "every member is polling" really does prove
                # nobody is in a game right now (verified in prod - lobby fa372459
                # sat at games_played=0 for 40 minutes through a live game 1 and
                # neither this nor the assembly branch fired). What was wrong is
                # the CONCLUSION that 5 minutes of it means the sitting ended.
                # BETWEEN games of a host lobby everyone is legitimately back on
                # the lobby screen - picking, chatting, waiting on a straggler -
                # and 5 minutes of that is ordinary, especially at 6+ players.
                # 15 minutes clears any real between-games gap while still
                # freeing a finished sitting 10 minutes before the 25-minute
                # dispersed-close backstop would.
                # Elapsed time alone must never close a sitting (this exact rule
                # killed a live FFA game 5m04s after its game 1 recorded). A
                # recent in-match ping from any member vetoes it outright.
                if (last_game is not None
                        and (datetime.now(timezone.utc) - last_game).total_seconds() > 900
                        and not _group_game_in_progress(me["series_id"])):
                    sitting_over = True
            elif (all_polling and int(lrow["games_played"] or 0) == 0 and lock_age > 300
                  # Round-7 gate: "all polling" must mean the COMPLETE frozen
                  # roster, not every SURVIVING row — a husk-swept roster
                  # leaves one fresh survivor reading as "everyone". The
                  # lobby's locked player_count is the roster cardinality.
                  and int(mem_polls["total"] or 0) >= int(lrow["player_count"] or 0)
                  and int(lrow["player_count"] or 0) > 0
                  # And a live battle (positive evidence, any process age) or
                  # a startup-unknown window vetoes the cancel outright.
                  and _in_match_evidence_trustworthy()
                  and not _group_game_positively_live(me["series_id"])):
                assembly_failed = True
        if sitting_over:
            await db.execute(text(
                "UPDATE ffa_lobbies SET status='completed', completed_at=NOW()"
                " WHERE id=:lid AND status='active'"), {"lid": me["series_id"]})
            # Reconcile-before-refund (Codex sitting-over review find 3): a
            # report can commit while its bet-settlement savepoint rolled
            # back (the deliberate #187 split) — those bets are unsettled
            # but their game HAS a recorded winner. The shared helper settles
            # them against the recorded result and refunds only wagers on
            # games never played.
            await _reconcile_ffa_lobby_bets(db, me["series_id"], "sitting over (all members back at menu)")
            await db.execute(text("DELETE FROM ffa_queue WHERE series_id = :lid"),
                             {"lid": me["series_id"]})
            await db.commit()
            print(f"[FFA-LOCK] sitting over — lobby {me['series_id']} closed, members freed")
            return {"status": "not_in_queue", "queue_count": 0}
        if dead or assembly_failed:
            if lrow is not None and lrow["status"] == "active":
                reason = "assembly_failed" if assembly_failed else "assembly_timeout"
                await db.execute(text(
                    "UPDATE ffa_lobbies SET status='canceled', invalidation_reason=:rsn,"
                    "       invalidated_at=NOW() WHERE id=:lid AND status='active'"
                ), {"lid": me["series_id"], "rsn": reason})
                await _reconcile_ffa_lobby_bets(db, me["series_id"], "dead lock reset")
            await db.execute(text("""
                UPDATE ffa_queue SET status='searching', series_id=NULL, slot=NULL,
                       room_name=NULL, room_region=NULL, matched_at=NULL, joined_at=NOW()
                 WHERE series_id = :lid
            """), {"lid": me["series_id"]})
            await db.commit()
            print(f"[FFA-LOCK] dead lock reset (lobby {me['series_id']}, age {int(lock_age)}s, assembly_failed={assembly_failed})")
            n = (await db.execute(text(
                "SELECT COUNT(*) FROM ffa_queue WHERE status = 'searching'"
                "   AND last_polled > NOW() - INTERVAL '75 seconds'"
            ))).scalar() or 0
            return {"status": "searching", "queue_count": int(n)}
        await db.commit()
        return await _ffa_poll_locked_payload(db, me["series_id"], steam_id)

    # Candidate scan: earliest fresh searching rows, one lobby's worth. LIMIT
    # bounds the lock set so concurrent pollers carve disjoint lobbies.
    rows = (await db.execute(text("""
        SELECT player_id, steam_id, display_name, region, joined_at
          FROM ffa_queue
         WHERE status = 'searching'
           AND last_polled > NOW() - INTERVAL '10 seconds'
           AND NOT EXISTS (SELECT 1 FROM player_bans pb
                            WHERE pb.steam_id = ffa_queue.steam_id
                              AND pb.unbanned_at IS NULL)
         ORDER BY joined_at
         LIMIT :maxp
         FOR UPDATE SKIP LOCKED
    """), {"maxp": FFA_MAX_PLAYERS})).mappings().all()
    fresh_count = (await db.execute(text(
        "SELECT COUNT(*) FROM ffa_queue WHERE status = 'searching'"
        "   AND last_polled > NOW() - INTERVAL '75 seconds'"
    ))).scalar() or 0

    # Authoritative pool size: PLAIN count (sees rows the SKIP LOCKED slice
    # hides while their own poll briefly holds them — re-review find 4).
    pool10 = (await db.execute(text(
        "SELECT COUNT(*) FROM ffa_queue WHERE status = 'searching'"
        "   AND last_polled > NOW() - INTERVAL '10 seconds'"
    ))).scalar() or 0
    if pool10 < FFA_MIN_PLAYERS:
        # Pool genuinely below the minimum — the gather window restarts when
        # it next reaches 3 (module state, see the FFA_GATHER constants).
        globals()["_ffa_gather_started_mono"] = None
    if len(rows) < FFA_MIN_PLAYERS:
        await db.commit()
        return {"status": "searching", "queue_count": int(fresh_count),
                "players_needed": FFA_MIN_PLAYERS, "gather_seconds_left": -1}

    # Gather window (bug #111 rework): the old fixed 25s from the 3rd joiner
    # meant "FFAs auto begin at 3 unless everyone joins very quickly" — a 4th
    # player arriving at second 24 got 1 second of pile-in time for everyone
    # behind them. Now every NEW joiner extends the window: start when full,
    # OR when both the base window (25s since gathering began) and the quiet
    # period (20s since the newest join) have run, OR at the hard cap (120s)
    # so a trickle of joiners can't gather forever. Timing lives in module
    # monotonic state (see the constants' comment): the join endpoint stamps
    # arrivals, the pool dropping below 3 resets the window, and a lock
    # clears it for the next lobby.
    global _ffa_gather_started_mono, _ffa_gather_pool_seen_mono
    _mono = time.monotonic()
    # Staleness fence: if no poll has OBSERVED a live >=3 pool for >15s, any
    # started-window value predates a pool collapse (or restart) that had no
    # poller left to reset it — start fresh rather than capping instantly.
    if _ffa_gather_started_mono is not None and _mono - _ffa_gather_pool_seen_mono > 15.0:
        _ffa_gather_started_mono = None
    if pool10 >= FFA_MIN_PLAYERS:
        _ffa_gather_pool_seen_mono = _mono
    if _ffa_gather_started_mono is None:
        _ffa_gather_started_mono = _mono
    waited = _mono - _ffa_gather_started_mono
    since_newest = _mono - _ffa_gather_last_join_mono
    full = len(rows) >= FFA_MAX_PLAYERS
    base_done = waited >= FFA_GATHER_SECONDS
    quiet_done = since_newest >= FFA_GATHER_EXTEND_SECONDS
    capped = waited >= FFA_GATHER_CAP_SECONDS
    if not full and not capped and not (base_done and quiet_done):
        left = max(FFA_GATHER_SECONDS - waited, FFA_GATHER_EXTEND_SECONDS - since_newest)
        left = min(left, FFA_GATHER_CAP_SECONDS - waited)
        await db.commit()
        return {"status": "searching", "queue_count": int(fresh_count),
                "players_needed": FFA_MIN_PLAYERS,
                "gather_seconds_left": max(0, int(left))}

    # Decider election: lowest steam id WITHIN the locked set (must be a member).
    lobby_rows = list(rows)
    lowest = min((r["steam_id"] for r in lobby_rows), key=_ffa_sort_key)
    if steam_id != lowest:
        await db.commit()
        return {"status": "searching", "queue_count": int(fresh_count),
                "players_needed": FFA_MIN_PLAYERS, "gather_seconds_left": 0}

    # Lock: slots by the deterministic steam ordering (client mirrors it).
    ordered = sorted(lobby_rows, key=lambda r: _ffa_sort_key(r["steam_id"]))
    # Kills tie-break capability, frozen at lock (migration 187) — same rule
    # and same provenance constraint as the host-lobby Start site: only each
    # member's own session-authenticated queue-row version counts. Legacy
    # gather serves pre-1.36 clients, so this is FALSE in practice until the
    # gather flow itself retires; computed anyway so the two lock sites stay
    # byte-equivalent in the state they produce (the design keystone).
    _kt_vals = (await db.execute(text(
        "SELECT mod_version FROM ffa_queue WHERE player_id = ANY(:ids)"
    ), {"ids": [r["player_id"] for r in ordered]})).scalars().all()
    _kt_floor = _parse_version(FFA_KILLS_TIEBREAK_MIN_VERSION)
    _kills_tiebreak = len(_kt_vals) == len(ordered) and all(
        _parse_version((v or "0").lstrip("vV")) >= _kt_floor for v in _kt_vals)
    regions = [r["region"] for r in lobby_rows if r["region"]]
    region = max(set(regions), key=regions.count) if regions else "us"
    room = f"ffa_{uuid.uuid4().hex[:12]}"
    lobby_id = uuid.uuid4()
    await db.execute(text("""
        INSERT INTO ffa_lobbies (id, status, photon_room_id, region, player_count, member_ids,
                                 created_at, kills_tiebreak)
        VALUES (:lid, 'active', :room, :reg, :n, :members, NOW(), :kt)
    """), {"lid": lobby_id, "room": room, "reg": (region or "us")[:8],
           "n": len(ordered), "members": [r["player_id"] for r in ordered],
           "kt": _kills_tiebreak})
    for slot, r in enumerate(ordered):
        await db.execute(text("""
            UPDATE ffa_queue SET status='ready_join', series_id=:lid, slot=:slot,
                   room_name=:room, room_region=:reg, matched_at=NOW()
             WHERE player_id=:pid
        """), {"lid": lobby_id, "slot": slot, "room": room, "reg": (region or "us")[:8],
               "pid": r["player_id"]})
    # Locked seats: assembly-length lease, then renewed by the authenticated
    # in_match ping for as long as battles are actually running. Once the
    # sitting genuinely ends nothing renews it and it lapses on its own -- no
    # cleanup path has to fire, which is the whole point (migration 174).
    await _lease_acquire_many(db, [r["player_id"] for r in ordered], "ffa",
                              lobby_id, LEASE_TTL_ASSEMBLY)
    await db.commit()
    print(f"[FFA-LOCK] lobby {lobby_id} room {room} n={len(ordered)} decider={steam_id}")
    # This gather is consumed — the next trio starts a fresh window.
    globals()["_ffa_gather_started_mono"] = None
    # Post-commit, own transaction: a locked lobby is out of every other queue
    # (Sid's ghost report — an FFA player left counting as '1 searching' in 1v1).
    await _evict_other_queue_searching(
        db, [r["player_id"] for r in ordered], "ffa_queue", "an FFA lobby")
    return await _ffa_poll_locked_payload(db, lobby_id, steam_id)


async def _ffa_game_in_progress_tristate(db: AsyncSession, lobby_id, lobby) -> bool | None:
    """True / False / None(unknown) — see the payload comment below. The
    destructive consumer (the client's rejoin refusal + leave) acts only on
    True; None makes it wait, which is always safe."""
    try:
        if _group_game_positively_live(lobby_id):
            return True
        if _in_match_evidence_trustworthy():
            return False
        # Startup window. A ZERO-GAME lobby locked AFTER this process booted
        # cannot carry a live game this process never heard about.
        if int((lobby["games_played"] if lobby is not None else 0) or 0) == 0:
            locked_at = (await db.execute(text(
                "SELECT MAX(matched_at) FROM ffa_queue WHERE series_id = :lid"
            ), {"lid": lobby_id})).scalar()
            if locked_at is not None and locked_at > _PROCESS_STARTED_WALL:
                return False
        return None
    except Exception as ex:
        print(f"[FFA] game_in_progress tristate failed for {lobby_id}: {ex}")
        return None   # unknown — the client waits, never destroys


async def _ffa_poll_locked_payload(db: AsyncSession, lobby_id, steam_id: str) -> dict:
    lobby = (await db.execute(text(
        "SELECT * FROM ffa_lobbies WHERE id = :lid"
    ), {"lid": lobby_id})).mappings().first()
    if lobby is None:
        return {"status": "searching", "queue_count": 0}
    members = (await db.execute(text("""
        SELECT q.steam_id, q.display_name, q.slot
          FROM ffa_queue q WHERE q.series_id = :lid AND q.status = 'ready_join'
         ORDER BY q.slot
    """), {"lid": lobby_id})).mappings().all()
    my_slot = next((int(m["slot"]) for m in members
                    if m["steam_id"] == steam_id and m["slot"] is not None), -1)
    _cfg = _ffa_lobby_config(lobby)
    return {
        "status": "ready_join",
        "lobby_id": str(lobby_id),
        "room_name": lobby["photon_room_id"],
        "room_region": lobby["region"],
        "player_count": int(lobby["player_count"] or len(members)),
        "slot": my_slot,
        # Frozen lobby config as FLAT scalars (learning #73 — these parse for
        # free client-side). The row is the authority; the master republishes
        # them as room props so every client pins one identical rule set.
        "score_target": _cfg["score_target"],
        "card_candidates": _cfg["card_candidates"],
        "initial_picks": _cfg["initial_picks"],
        "card_cap": _cfg["card_cap"],
        "same_card_rule": _cfg["same_card_rule"],
        "lobby_ranked": bool(lobby["is_ranked"]) if "is_ranked" in lobby and lobby["is_ranked"] is not None else True,
        # Round-4 find F1 / round-5 gate correction: a relaunched client's
        # recovery must NOT rejoin a room whose game is LIVE. TRI-STATE
        # (round-5: the conservative _group_game_in_progress returns True
        # for EVERY group in the 210s post-boot window — its own docstring
        # says veto-only, and serializing it as positive evidence made a
        # fresh API restart dissolve every new FFA):
        #   true  = POSITIVE heartbeat evidence -> client refuses the rejoin;
        #   false = trustworthy absence (mature process, or a zero-game lobby
        #           locked after this boot — no pre-restart game can exist);
        #   null  = startup-unknown -> client neither joins nor leaves, just
        #           polls again.
        "game_in_progress": await _ffa_game_in_progress_tristate(db, lobby_id, lobby),
        "players": [
            {"steam_id": m["steam_id"], "display_name": m["display_name"],
             "slot": int(m["slot"]) if m["slot"] is not None else -1}
            for m in members
        ],
    }


async def _ffa_replay_echo(db: AsyncSession, report, lobby_uuid, id_by_steam, n):
    """Idempotent echo for an already-recorded room, or None when the room is
    unrecorded. Runs BEFORE every quarantine branch in submit_ffa_match
    (Codex Aug-3 r4 find 1): the durable client outbox legitimately retries a
    committed report whose response was lost — after the lobby completes,
    the inactive-status branch used to QUARANTINE that duplicate (and the
    admin endpoint could show it can_accept=true because the real match
    predates the quarantine row). Also the sole duplicate handler for the
    INSERT's unique-violation path."""
    prior = (await db.execute(text(
        "SELECT id, player_count, lobby_id FROM ffa_matches WHERE photon_room_id = :room"
    ), {"room": (report.photon_room_id or "")[:64]})).mappings().first()
    if prior is None:
        return None
    if str(prior["lobby_id"]) != str(lobby_uuid):
        raise HTTPException(409, "Room already recorded for a different lobby")
    # The detailed echo requires the submitted roster to BE the recorded one
    # (Codex Aug-3 r5 find 1: running before the endpoint's exact-roster
    # validation, a bare existence check would hand match details to any
    # HMAC-holding session that knows the lobby+room ids but wasn't in the
    # game). An honest outbox retry always carries the original roster.
    rec_ids = set((await db.execute(text(
        "SELECT player_id FROM ffa_match_players WHERE match_id = :m"
    ), {"m": prior["id"]})).scalars().all())
    if set(id_by_steam.values()) != rec_ids:
        raise HTTPException(409, "Duplicate room id")
    mine = (await db.execute(text(
        "SELECT placement, rating_change, xp_gained, gold_gained FROM ffa_match_players"
        " WHERE match_id = :m AND player_id = :p"
    ), {"m": prior["id"], "p": id_by_steam[report.reported_by_steam_id]})).mappings().first()
    changes = (await db.execute(text(
        "SELECT p.steam_id, fmp.rating_change FROM ffa_match_players fmp"
        " JOIN players p ON p.id = fmp.player_id WHERE fmp.match_id = :m"
    ), {"m": prior["id"]})).mappings().all()
    return FfaMatchResponse(
        match_id=prior["id"], lobby_id=lobby_uuid,
        placement=int(mine["placement"]) if mine else 0,
        player_count=int(prior["player_count"] or n),
        rating_changes={r["steam_id"]: float(r["rating_change"] or 0.0) for r in changes},
        xp_gained=int(mine["xp_gained"] or 0) if mine else 0,
        gold_gained=int(mine["gold_gained"] or 0) if mine else 0,
        message="Already recorded")


@app.post("/api/v1/ffa/matches", response_model=FfaMatchResponse, tags=["FFA Matches"])
async def submit_ffa_match(report: FfaMatchReport, request: Request, db: AsyncSession = Depends(get_db)):
    """Record one FFA game and apply pairwise Glicko + XP/gold inline (an FFA
    match is a complete rated unit). Placements are computed SERVER-side from
    the per-player round/point tallies — the client's ordering is not trusted.
    Idempotent via the room-id unique (rooms are per-game suffixed)."""
    await _check_steam_session(request, report.reported_by_steam_id, db)
    canonical_form = _verify_ffa_hmac(report)
    if not canonical_form:
        raise HTTPException(403, "Invalid FFA match signature")
    # Two INDEPENDENT facts derived from the verified form:
    #   kills_in_canonical — the kills values are covered by the signature
    #     (v2 form). Feeds the absent-refutation guard only.
    #   kills_break_ties — kills participate in PLACEMENT. Requires v2 AND
    #     the lobby's FROZEN kills_tiebreak capability flag (Codex Aug-3
    #     find 1): semantics must be a property of the GAME, not of which
    #     member reports.
    # A v1 report keeps the legacy shared-tie semantics ONLY in a lobby that
    # is not kills-capable (some member below the floor at lock); from a
    # kills-capable lobby a v1 report of an UNRECORDED room is quarantined +
    # 403'd below as a downgrade attempt (a recorded room returns the replay
    # echo first) — an honest old client can never be a member of one.
    kills_in_canonical = canonical_form == "v2"
    try:
        lobby_uuid = UUID(report.lobby_id)
    except (ValueError, TypeError):
        raise HTTPException(400, "Invalid lobby_id format")
    steams = [p.steam_id for p in report.players]
    if len(set(steams)) != len(steams) or len(steams) < 2:
        raise HTTPException(400, "Need at least two distinct players")
    if report.winner_steam_id not in set(steams):
        raise HTTPException(400, "Winner is not among the players")
    if report.reported_by_steam_id not in set(steams):
        raise HTTPException(400, "Reporter is not a participant")
    if not (report.photon_room_id or "").strip():
        raise HTTPException(400, "photon_room_id is required")
    # §6 casual path: the ranked AUTHORITY is the LOBBY ROW, decided below the
    # FOR UPDATE as `rated = lobby.is_ranked AND report.is_ranked` — this
    # early site fires before the row is loaded, so it can no longer
    # hard-reject. A crafted is_ranked=false still cannot open an economy
    # side channel: the server ANDs it against the row it froze at Start, and
    # a FALSE claim against a ranked lobby only DOWNGRADES the crafter's own
    # game to casual — quarantine-class skew, handled below. An old client
    # always sends true, which the AND makes correct for both lobby kinds.

    # Winner must hold the unique round maximum.
    max_rounds = max(p.rounds_won for p in report.players)
    top = [p for p in report.players if p.rounds_won == max_rounds]
    if len(top) != 1 or top[0].steam_id != report.winner_steam_id:
        raise HTTPException(400, "winner disagrees with the round tallies")

    prows = (await db.execute(
        select(Player.id, Player.steam_id).where(Player.steam_id.in_(steams))
    )).all()
    id_by_steam = {r.steam_id: r.id for r in prows}
    if len(id_by_steam) != len(steams):
        raise HTTPException(404, "One or more players not registered")

    # Lobby row FIRST (the group anchor — serializes concurrent reports).
    lobby = (await db.execute(text(
        "SELECT * FROM ffa_lobbies WHERE id = :lid FOR UPDATE"
    ), {"lid": lobby_uuid})).mappings().first()
    if lobby is None:
        # No row => the report cannot be bound to a real roster, so it is not
        # quarantined (Codex round-3 out-of-scope find: capture-before-binding
        # let anyone with the DLL secret fill the admin queue with invented
        # payloads). The recoverable incident class — a live lobby closed
        # mid-game — always leaves the row behind.
        raise HTTPException(404, "Lobby not found")
    # Duplicate-room replay FIRST — before the status/shape/limit branches
    # below, every one of which quarantines (Codex Aug-3 r4 find 1: an honest
    # outbox retry of a committed report, arriving after the lobby closed,
    # must get its idempotent echo, never a quarantine capture).
    _replay = await _ffa_replay_echo(db, report, lobby_uuid, id_by_steam, len(report.players))
    if _replay is not None:
        return _replay
    # Review find 2: a canceled/completed lobby must not keep minting rated
    # games. Only a live lobby accepts reports.
    members = list(lobby["member_ids"] or [])
    member_set = set(members)
    reported_ids = set(id_by_steam.values())
    # Frozen per-lobby config (migration 176) — the row's values are the
    # authority; the report's claims and the module defaults are not.
    _cfg = _ffa_lobby_config(lobby)
    _score_target = _cfg["score_target"]
    _lobby_ranked = bool(lobby["is_ranked"]) if ("is_ranked" in lobby and lobby["is_ranked"] is not None) else True
    # ── Kills tie-break capability: read the flag FROZEN at lock time
    # (migration 187), computed there from each member's OWN session-
    # authenticated join call (ffa_queue.mod_version) — never from
    # players.mod_version, which any preflight caller can stamp onto another
    # player's row (Codex Aug-3 round-2 find 1: provenance, not parsing).
    # Freezing at lock makes the semantics a property of the GAME: no
    # mid-sitting version change, poll race, or reporter identity can flip
    # them between games of one sitting. Missing column/NULL (pre-187 lobby
    # mid-flight during the deploy) => False => legacy shared-tie semantics,
    # the safe direction (#288: prefer under-application).
    _lobby_kills_capable = bool(lobby["kills_tiebreak"]) if "kills_tiebreak" in lobby else False
    kills_break_ties = kills_in_canonical and _lobby_kills_capable
    # (The v1-downgrade rejection for kills-capable lobbies lives BELOW the
    # roster/shape/limit binding checks — Codex Aug-3 r3 find 1: quarantining
    # up here would run before binding and become a quota-spam primitive.)
    # The LOBBY ROW is the sole ranked authority (Codex v1.36 server review
    # find 2): the first draft ANDed in the report's claim, which let the
    # elected reporter — precisely the client with the most to lose — strip
    # the Glicko block for the ENTIRE roster by flipping one signed flag.
    # A mismatched claim is logged as skew evidence and otherwise ignored;
    # an old client always sends true, which is simply never consulted.
    rated = _lobby_ranked
    if bool(report.is_ranked) != _lobby_ranked:
        print(f"[FFA] report is_ranked={bool(report.is_ranked)} disagrees with "
              f"lobby {lobby_uuid} (is_ranked={_lobby_ranked}) — row wins "
              f"(reporter {report.reported_by_steam_id})")
    if lobby["status"] != "active":
        # Quarantine ONLY a report that binds to this lobby's frozen roster
        # (exact member set, reporter among them) and respects the engine's
        # win invariant — the same trust boundary the team path enforces.
        _bound = (member_set
                  and reported_ids == member_set
                  and report.reported_by_steam_id in id_by_steam
                  and max_rounds == _score_target)
        if _bound:
            await _quarantine_report(
                db, mode="ffa", reason=f"lobby_{lobby['status']}", status_code=409, payload=report.model_dump(),
                group_id=lobby_uuid, photon_room_id=report.photon_room_id,
                reporter_id=id_by_steam.get(report.reported_by_steam_id),
                player_ids=list(id_by_steam.values()))
        raise HTTPException(409, "Lobby is not active")
    # Roster validation (review finds 1/3): member_ids is the lock-time roster
    # ORDERED BY SLOT (queue rows get pruned; this array doesn't). The report
    # must cover the roster EXACTLY — a subset would let a hostile reporter
    # drop whoever beat them and still bank rating/XP. Leavers stay in the
    # report with left_early=true, so a shrinking lobby is not a valid excuse.
    if not member_set:
        raise HTTPException(409, "Lobby has no recorded roster")
    if reported_ids != member_set:
        raise HTTPException(403, "Report must cover exactly the lobby roster")
    if len(report.players) != int(lobby["player_count"] or len(members)):
        raise HTTPException(403, "Report player count does not match the lobby")
    slot_by_pid = {pid: i for i, pid in enumerate(members)}
    for p in report.players:
        pid = id_by_steam[p.steam_id]
        if slot_by_pid.get(pid) != p.slot:
            raise HTTPException(403, f"Slot mismatch for {p.steam_id}")
    # Engine invariants (review find 2): the FFA engine ends a game at exactly
    # the lobby's frozen score target, and nobody else can have reached it.
    # Score-SHAPE mismatches vs the row are QUARANTINED, not destroyed: the
    # honest cause is config skew (a client that missed the score-target room
    # prop plays to its default and reports a real game whose shape disagrees
    # with the row — the July-30 destroyed-reports class). This runs AFTER the
    # exact-roster + slot + HMAC binding, so it is not a capture-before-binding
    # write primitive; a crafted score from a real roster member lands in the
    # admin queue instead of silently vanishing either way.
    max_pts = _ffa_max_points(len(report.players), _score_target)
    _shape_error = None
    if max_rounds != _score_target:
        _shape_error = f"winner must hold exactly {_score_target} rounds"
    elif any(p.rounds_won > _score_target for p in report.players):
        _shape_error = "round tally above the game limit"
    elif any(p.points_total > max_pts for p in report.players):
        _shape_error = "point tally above the game limit"
    if _shape_error:
        print(f"[FFA] score-shape mismatch vs lobby {lobby_uuid} config "
              f"(target={_score_target}): {_shape_error} — quarantining")
        await _quarantine_report(
            db, mode="ffa", reason="score_shape_mismatch", status_code=409,
            payload=report.model_dump(), group_id=lobby_uuid,
            photon_room_id=report.photon_room_id,
            reporter_id=id_by_steam.get(report.reported_by_steam_id),
            player_ids=list(id_by_steam.values()))
        raise HTTPException(409, _shape_error)
    # Rate ceiling: a lobby's games are real matches taking minutes each. This
    # bounds a compromised client's fabrication rate even inside a live lobby
    # (a full server-issued per-game nonce is the next hardening step).
    if int(lobby["games_played"] or 0) >= FFA_MAX_GAMES_PER_LOBBY:
        await _quarantine_report(
            db, mode="ffa", reason="lobby_game_limit", status_code=409, payload=report.model_dump(),
            group_id=lobby_uuid, photon_room_id=report.photon_room_id,
            reporter_id=id_by_steam.get(report.reported_by_steam_id),
            player_ids=list(id_by_steam.values()))
        raise HTTPException(409, "Lobby game limit reached")

    # A v1 signature from a lobby whose ENTIRE roster advertised a v2-signing
    # build at lock is definitionally a downgrade attempt (Codex Aug-3 r2
    # find 2: binding this to the SUBMIT request's claimed version would
    # allow claim-switching between join and submit; the frozen flag closes
    # that). Runs AFTER the active/roster/slot/shape/limit binding above (r3
    # find 1: capture-before-binding was a quarantine-quota spam primitive);
    # the endpoint-top replay echo already returned for any recorded room, so
    # only unrecorded games reach this capture. RESIDUAL (accepted): a
    # concurrent report committing the same room between that check and this
    # capture leaves a stale quarantine row for an admin to reject — the
    # capture itself runs in its own transaction after a rollback, so no lock
    # is held across it. Quarantined, not dropped, so the vanishing-rare
    # honest case (mid-sitting DLL downgrade) stays admin-recoverable.
    if canonical_form == "v1" and _lobby_kills_capable:
        await _quarantine_report(
            db, mode="ffa", reason="v1_canonical_downgrade", status_code=403,
            payload=report.model_dump(), group_id=lobby_uuid,
            photon_room_id=report.photon_room_id,
            reporter_id=id_by_steam.get(report.reported_by_steam_id),
            player_ids=list(id_by_steam.values()))
        raise HTTPException(403, "This lobby requires the current report signature")

    # Players pass: sorted FOR NO KEY UPDATE (#202/#203 — never FOR UPDATE,
    # and this pass is the real gate; glicko rows may not exist yet).
    for pid in sorted(reported_ids, key=str):
        await db.execute(text(
            "SELECT 1 FROM players WHERE id = :pid FOR NO KEY UPDATE"
        ), {"pid": pid})

    # Server-side placements: (rounds desc, points desc, kills desc); ties
    # share the same placement, COMPETITION style (1,2,2,4 — not dense; Codex
    # design find 15). `kills` breaks ties ONLY when kills_break_ties: the
    # report verified under the v2 canonical (kills signed — Sid approved
    # 2026-08-03) AND the whole roster is on a kills-signing build (the
    # capability gate above). On a v1 legacy report kills is unsigned, so it
    # keeps the pre-v1.36 exclusion: a modified reporter could otherwise
    # reorder placements — and therefore ratings and gold — by inventing kill
    # counts an old server would never have covered. The trailing
    # _ffa_sort_key only stabilises entry ORDER, never separates a shared
    # place.
    def _place_key(p) -> tuple:
        return (p.rounds_won, p.points_total, p.kills if kills_break_ties else 0)
    entries = sorted(report.players,
                     key=lambda p: tuple(-v for v in _place_key(p))
                     + (_ffa_sort_key(p.steam_id),))
    placements: dict[str, int] = {}
    prev_key = None
    prev_place = 0
    for i, p in enumerate(entries):
        k = _place_key(p)
        place = prev_place if k == prev_key else i + 1
        placements[p.steam_id] = place
        prev_key, prev_place = k, place
    # GHOSTS: a member who left in an EARLIER game of the sitting still rides
    # every rematch report so the frozen-roster check holds (Codex review
    # 2026-07-28 find 3 — clearing them made game 2+ reports 403), but with
    # left_early and all-zero tallies. They keep their roster row + last
    # placement, and are excluded from rating, XP/gold, and everyone else's
    # beaten counts — one leave must not keep costing them (or feeding
    # everyone else) across games they never played.
    # Keyed on the explicit `absent` flag (a mid-game leaver at zero score is
    # absent=False and still rated — leaving early must not dodge the loss).
    # FFA exists only on the current build, so no legacy-client heuristic.
    # REFUTATION GUARD: `absent` is client-supplied and OUTSIDE the HMAC
    # canonical, but rounds_won/points_total are signed — a player whose
    # signed tally is non-zero was demonstrably present this game, so an
    # `absent` claim against them is ignored (a modified reporter could
    # otherwise void the real winner's entire result for ~1% cost). Logged so
    # a refuted claim is visible evidence, not a silent correction. Kills
    # count as presence proof only when signed (v2) — an unsigned kills field
    # must never override an honest absent flag.
    ghosts = set()
    for p in report.players:
        if not (p.left_early and bool(getattr(p, "absent", False))):
            continue
        if p.rounds_won > 0 or p.points_total > 0 or (kills_in_canonical and p.kills > 0):
            print(f"[FFA] absent claim REFUTED for {p.steam_id}: signed tally "
                  f"{p.rounds_won}r/{p.points_total}p/{p.kills}k is non-zero "
                  f"(reporter {report.reported_by_steam_id}, room {report.photon_room_id})")
            continue
        ghosts.add(p.steam_id)
    # Strictly-beaten counts drive XP (a tied pair didn't beat each other).
    beaten_count = {
        p.steam_id: sum(1 for q in report.players
                        if q.steam_id not in ghosts
                        and placements[q.steam_id] > placements[p.steam_id])
        for p in report.players
    }

    # ── Economy meter inputs (v1.36.0, §5 of the config-lobby spec). ──
    # battles = Σ points_total (signed — inside the HMAC canonical).
    # elapsed is measured from SERVER receipt times only: the previous game's
    # ended_at (or lobby activation for game 1), never the client-supplied
    # started_at/duration. GREATEST + floor guards the admin-replay case where
    # a re-inserted historical row leaves MAX(ended_at) in the future
    # (monotonic guard — elapsed can never go negative or absurdly small).
    _n_live_meter = len(report.players) - len(ghosts)
    battles_total = sum(max(0, int(p.points_total)) for p in report.players)
    _max_prior_end = (await db.execute(text(
        "SELECT MAX(ended_at) FROM ffa_matches WHERE lobby_id = :lid"
    ), {"lid": lobby_uuid})).scalar()
    _anchor_candidates = [t for t in (lobby["created_at"], _max_prior_end) if t is not None]
    # ONE post-lock DB clock for BOTH the elapsed computation and the stored
    # ended_at (Codex find 4): the first draft measured elapsed with a
    # post-wait wall clock but stored NOW() — PostgreSQL's TRANSACTION-START
    # time, frozen before this request waited on the lobby lock. Queued
    # reports would each re-count their predecessors' lock/processing time as
    # payable elapsed, defeating the pace ceiling. clock_timestamp() here runs
    # after the FOR UPDATE above, and the identical value is bound into the
    # INSERT, so the next report's anchor is exactly this report's meter end.
    _now_dt = (await db.execute(text("SELECT clock_timestamp()"))).scalar()
    _anchor = max(_anchor_candidates) if _anchor_candidates else _now_dt
    elapsed_seconds = max(30.0, (_now_dt - _anchor).total_seconds())
    _sec_per_battle = _ffa_sec_per_battle(max(2, _n_live_meter))
    paid_battles = min(float(battles_total),
                       elapsed_seconds * FFA_PACE_HEADROOM / _sec_per_battle)

    match_id = uuid.uuid4()
    n = len(report.players)
    try:
        await db.execute(text("""
            INSERT INTO ffa_matches (id, lobby_id, photon_room_id, player_count, winner_id,
                duration_seconds, game_version, region, hmac_signature, reported_by,
                is_ranked, started_at, ended_at, timeline,
                battles_total, paid_battles, elapsed_seconds)
            VALUES (:id, :lid, :room, :n, :win, :dur, :gv, :reg, :hmac, :rep, :ranked, :started, :endts, :tl,
                :bt, :pb, :es)
        """), {"id": match_id, "lid": lobby_uuid, "room": (report.photon_room_id or "")[:64],
               "n": n, "win": id_by_steam[report.winner_steam_id],
               "dur": report.match_duration, "gv": (report.game_version or "")[:32] or None,
               "reg": (report.region or "")[:8] or None,
               "hmac": (report.hmac_signature or "")[:160] or None,
               "rep": id_by_steam.get(report.reported_by_steam_id),
               "ranked": rated, "started": report.started_at,
               "tl": (report.timeline or "")[:2000] or None,
               "bt": battles_total, "pb": round(paid_battles, 2),
               "es": int(elapsed_seconds), "endts": _now_dt})
    except IntegrityError as ie:
        await db.rollback()
        # Only the room-id unique means "replay" — any OTHER integrity error
        # (FK violation etc.) is a real failure, not a duplicate (Codex design
        # find 11: a catch-all here would misreport broken inserts as success).
        if "uq_ffa_match_room" not in str(getattr(ie, "orig", ie)):
            raise HTTPException(500, "FFA match insert failed")
        # Replay that raced past the early check: same idempotent echo.
        _echo = await _ffa_replay_echo(db, report, lobby_uuid, id_by_steam, n)
        if _echo is None:
            raise HTTPException(409, "Duplicate room id")
        return _echo

    # ── Pairwise Glicko (pre-match snapshots for everyone). ──
    rating_changes: dict[str, float] = {}
    pre: dict[str, tuple[float, float, float]] = {}
    if rated:
        # Glicko rows sorted FOR UPDATE (after the players pass).
        for pid in sorted(reported_ids, key=str):
            await db.execute(text(
                "SELECT 1 FROM glicko_ratings_ffa WHERE player_id = :pid FOR UPDATE"
            ), {"pid": pid})
        grows = (await db.execute(text(
            "SELECT player_id, rating, rating_deviation, volatility FROM glicko_ratings_ffa"
            " WHERE player_id = ANY(:pids)"
        ), {"pids": list(reported_ids)})).mappings().all()
        by_pid = {r["player_id"]: r for r in grows}
        for sid_, pid in id_by_steam.items():
            r = by_pid.get(pid)
            pre[sid_] = ((float(r["rating"]), float(r["rating_deviation"]), float(r["volatility"]))
                         if r else (1500.0, 350.0, 0.06))
        # Rating comparisons are BOUNDED to the placement-adjacent opponents
        # (up to FFA_MAX_RATED_OPPONENTS, nearest placements first): raw full
        # pairwise would make a 10-player game move ratings ~4.5x as much as a
        # 3-player game and crush RD after a handful of lobbies (Codex design
        # find 14). Adjacent placements are also the most informative
        # comparisons. Deterministic: sorted by |placement gap| then the
        # canonical steam ordering.
        for p in report.players:
            if p.steam_id in ghosts:
                continue   # not in this game — no rating period for them
            my_place = placements[p.steam_id]
            ranked_opps = sorted(
                (q for q in report.players
                 if q.steam_id != p.steam_id and q.steam_id not in ghosts),
                key=lambda q: (abs(placements[q.steam_id] - my_place),
                               _ffa_sort_key(q.steam_id)))
            opponents = []
            for q in ranked_opps[:FFA_MAX_RATED_OPPONENTS]:
                score = (1.0 if my_place < placements[q.steam_id]
                         else 0.0 if my_place > placements[q.steam_id] else 0.5)
                opponents.append((pre[q.steam_id][0], pre[q.steam_id][1], score))
            old_r, old_rd, old_vol = pre[p.steam_id]
            # w(N) = min(1, (N-1)/4): a game to a shorter score target carries
            # less information, so it counts as a fraction of a game (§5e —
            # scales variance AND update). N=5 (today's default) gives w=1.0,
            # byte-identical to the unweighted path; clamped at 1.0 above N=5
            # so grinding long lobbies is never the rating-efficient path.
            _wN = min(1.0, (_score_target - 1) / 4.0)
            new_r, new_rd, new_vol = calculate_new_rating(
                old_r, old_rd, old_vol, opponents,
                weights=([_wN] * len(opponents)) if _wN < 1.0 else None)
            rating_changes[p.steam_id] = round(new_r - old_r, 1)
            pid = id_by_steam[p.steam_id]
            await db.execute(text("""
                INSERT INTO glicko_ratings_ffa (player_id, rating, rating_deviation, volatility,
                    peak_rating, games_played, wins, top3, placement_sum, last_calculated, updated_at)
                VALUES (:pid, :r, :rd, :vol, :peak, 1, :w, :t3, :pl, NOW(), NOW())
                ON CONFLICT (player_id) DO UPDATE SET
                    rating = :r, rating_deviation = :rd, volatility = :vol,
                    peak_rating = GREATEST(glicko_ratings_ffa.peak_rating, :peak),
                    games_played = glicko_ratings_ffa.games_played + 1,
                    wins = glicko_ratings_ffa.wins + :w,
                    top3 = glicko_ratings_ffa.top3 + :t3,
                    placement_sum = glicko_ratings_ffa.placement_sum + :pl,
                    last_calculated = NOW(), updated_at = NOW()
            """), {"pid": pid, "r": new_r, "rd": new_rd, "vol": new_vol, "peak": new_r,
                   "w": 1 if my_place == 1 else 0, "t3": 1 if my_place <= 3 else 0,
                   "pl": my_place})

    # ── XP + gold: battles × players meter (v1.36.0). The per-player pool is
    # rate(P) × paid_battles × placement-shape × tier-factor, split 45% XP /
    # 55% flat gold; atomic UPDATE..RETURNING (#148), canonical str(pid)
    # award order (#197). ──
    award_info: dict[str, tuple[int, int]] = {}
    by_steam = {p.steam_id: p for p in report.players}
    for pid in sorted(reported_ids, key=str):
        sid_ = next(s for s, i2 in id_by_steam.items() if i2 == pid)
        if sid_ in ghosts:
            continue   # no XP/gold for games they never played
        place = placements[sid_]
        beaten = beaten_count.get(sid_, 0)
        # Round-2 review find 10 + §5c correction 5: scale by players actually
        # IN this game — roster ghosts must not inflate the rate OR reach the
        # pace ceiling by roster padding.
        n_live = len(report.players) - len(ghosts)
        # Opponent-tier factor, NORMALISED to the x1.5 calibration field:
        # FFA_G_PER_PLAYER_MIN is calibrated "at tier x1.5" (the default-1500
        # field — learning #258), so the typical ranked lobby takes factor 1.0
        # and a Grand-Master field roughly doubles the rate. `pre` is only
        # populated for ranked games, so an unranked FFA takes tier 1.0 →
        # factor ≈0.67, preserving "casual pays less than ranked".
        opp_ratings = [pre[s][0] for s in pre
                       if s != sid_ and s not in ghosts]
        tier_mult = (_tier_mult_for(sum(opp_ratings) / len(opp_ratings))[0]
                     if opp_ratings else 1.0)
        pool = (_ffa_battle_rate(n_live) * paid_battles
                * _ffa_pool_shape(place, beaten, n_live)
                * (tier_mult / 1.5))
        xp = max(FFA_MIN_XP, int(round(pool * FFA_XP_SHARE * 100)))
        row = (await db.execute(text(
            "UPDATE players SET total_xp = COALESCE(total_xp,0) + :xp,"
            "       ffa_xp_earned = COALESCE(ffa_xp_earned,0) + :xp"
            " WHERE id = :pid"
            " RETURNING total_xp AS new_xp, (COALESCE(total_xp,0) - :xp) AS old_xp"
        ), {"xp": xp, "pid": pid})).mappings().first()
        new_xp = row["new_xp"] if row else xp
        old_xp = row["old_xp"] if row else 0
        gold_delta = max(0, (new_xp // 100) - (old_xp // 100))
        # Flat 55% half, FLOORED AT 1g (§5c correction 3): the ffa_placement
        # ledger row is the back-pay idempotency marker, so a live player must
        # ALWAYS produce one — a zero-rounded payout would suppress the row
        # and a later 164 rerun would back-pay this game at the legacy rate.
        place_gold = max(1, int(round(pool * (1.0 - FFA_XP_SHARE))))
        # Level-reward gold (bug #117 audit item: `_maybe_grant_level_rewards`
        # is called from submit_match and inlined in the 2v2 path, but FFA had
        # NO level rewards at all — an FFA-only player banked nothing for
        # dinging. Inlined here because we hold `pid`, not an ORM object.)
        old_lvl, _, _ = level_from_xp(old_xp)
        new_lvl, _, _ = level_from_xp(new_xp)
        level_gold = (sum(level_reward_for(lv) for lv in range(old_lvl + 1, new_lvl + 1))
                      if new_lvl > old_lvl else 0)
        # ONE players UPDATE per player: the canonical tuple-lock order
        # (#197/#202) must not gain a second write site inside the loop.
        total_gold = gold_delta + place_gold + level_gold
        if total_gold > 0:
            await db.execute(text(
                "UPDATE players SET gold_earned = COALESCE(gold_earned,0) + :g,"
                "       ffa_gold_earned = COALESCE(ffa_gold_earned,0) + :g WHERE id = :pid"
            ), {"g": total_gold, "pid": pid})
        # Separate audit rows per reason (same shape as 1v1's "xp" +
        # "level_reward" sharing one reference_id). `ffa_placement` is the
        # idempotency key the back-pay migration keys off — do not rename.
        if gold_delta > 0:
            db.add(GoldTransaction(player_id=pid, amount=gold_delta, reason="ffa_xp",
                                   reference_id=str(match_id)))
        if place_gold > 0:
            db.add(GoldTransaction(player_id=pid, amount=place_gold, reason="ffa_placement",
                                   reference_id=str(match_id)))
        if level_gold > 0:
            db.add(GoldTransaction(player_id=pid, amount=level_gold, reason="level_reward",
                                   reference_id=str(match_id)))
        award_info[sid_] = (xp, total_gold)

    # ── Per-player rows + cards. ──
    for p in report.players:
        pid = id_by_steam[p.steam_id]
        tel = p.telemetry
        xp_g, gold_g = award_info.get(p.steam_id, (0, 0))
        old_r = pre.get(p.steam_id, (None, None, None))[0]
        chg = rating_changes.get(p.steam_id)
        await db.execute(text("""
            INSERT INTO ffa_match_players (match_id, player_id, slot, rounds_won, points_total,
                kills, placement, left_early, rating_before, rating_after, rating_change,
                xp_gained, gold_gained, fps_avg, ping_avg, bullets_fired, bullets_hit,
                blocks_activated, blocks_successful, keys_pressed, active_seconds,
                fps_timeline, ping_timeline, hit_timeline, block_timeline,
                damage_dealt, damage_dealt_timeline, kill_timeline, absent)
            VALUES (:m, :p, :slot, :rw, :pt, :k, :pl, :le, :rb, :ra, :rc, :xp, :g, :fps, :ping,
                    :bf, :bh, :ba, :bs, :kp, :asec, :ft, :pt2, :ht, :bt,
                    :dmg, :dmgtl, :killtl, :absent)
        """), {"m": match_id, "p": pid, "slot": p.slot, "rw": p.rounds_won, "pt": p.points_total,
               "k": int(getattr(p, "kills", 0) or 0),
               # Bugs #127/#130. Pass None straight through — do NOT collapse it
               # with `or None`, which would turn a genuine 0 (this player dealt
               # no damage) into "not reported" and quietly drop real zeros out of
               # the average. The schema default is already None for old clients.
               "dmg": getattr(p, "damage_dealt", None),
               # Roster ghost: held the slot but did not play THIS game.
               # Persist the EFFECTIVE decision (the refutation-filtered
               # ghosts set), not the raw client claim — a refuted absent
               # flag stored as true would exclude a real winner's played
               # row from every profile aggregate while their glicko
               # games_played still counted the game (Codex v1.36 find 7).
               "absent": p.steam_id in ghosts,
               "dmgtl": (getattr(p, "damage_dealt_timeline", None) or None),
               "killtl": (getattr(p, "kill_timeline", None) or None),
               "pl": placements[p.steam_id], "le": bool(p.left_early),
               "rb": old_r, "ra": (old_r + chg) if (old_r is not None and chg is not None) else None,
               "rc": chg, "xp": xp_g, "g": gold_g,
               "fps": p.fps, "ping": tel.ping_avg if tel else None,
               "bf": tel.bullets_fired if tel else None, "bh": tel.bullets_hit if tel else None,
               "ba": tel.blocks_activated if tel else None,
               "bs": tel.blocks_successful if tel else None,
               "kp": tel.keys_pressed if tel else None,
               "asec": tel.active_seconds if tel else None,
               "ft": tel.fps_timeline if tel else None, "pt2": tel.ping_timeline if tel else None,
               "ht": tel.hit_timeline if tel else None, "bt": tel.block_timeline if tel else None})
        # Cap + sanitize (Codex Jul-29 adjacent finds): the cards list is
        # client-supplied and outside the HMAC canonical — bound the row count
        # (a real game never exceeds a few dozen picks) and strip control
        # characters, which otherwise reach TMP as literal line breaks and
        # wreck row-height estimates and tooltips.
        # 128, not 64 (Codex find 9): a 10-player first-to-10 legitimately
        # produces up to ~90 picks for a busy non-winner — 64 truncated valid
        # target-10 games. Sized above the structural max with slack.
        for i, c in enumerate((p.cards or [])[:128]):
            nm = getattr(c, "card_name", None)
            if not nm:
                continue
            # Strip C0 AND C1 controls AND the Unicode line/paragraph
            # separators — U+0085/U+2028/U+2029 are line breaks to TMP and
            # survive a bare `< ' '` test (Codex round-2 find 5).
            nm_clean = "".join(
                " " if (ord(ch) < 0x20 or 0x7F <= ord(ch) <= 0x9F
                        or ord(ch) in (0x2028, 0x2029)) else ch
                for ch in str(nm))
            await db.execute(text(
                "INSERT INTO ffa_match_cards (match_id, player_id, card_name, card_rarity,"
                " pick_order, round_number, rolled) VALUES (:m, :p, :c, :r, :o, :rn, :rl)"
            ), {"m": match_id, "p": pid, "c": nm_clean[:64],
                "r": (getattr(c, "card_rarity", None) or "")[:16] or None,
                "rl": bool(getattr(c, "rolled", False)),
                "o": getattr(c, "pick_order", i) or i,
                "rn": getattr(c, "round_number", None)})
        # Offered candidates (§10 baseline; migration 178). Same trust posture
        # as the picks list: outside the canonical, so row-capped and
        # control-stripped. 512 covers the structural max (~90 draws × 5
        # candidates = 450 in a 10-player first-to-10 — Codex find 9).
        for off in (getattr(p, "card_offers", None) or [])[:512]:
            onm = getattr(off, "card_name", None)
            if not onm:
                continue
            onm_clean = "".join(
                " " if (ord(ch) < 0x20 or 0x7F <= ord(ch) <= 0x9F
                        or ord(ch) in (0x2028, 0x2029)) else ch
                for ch in str(onm))
            await db.execute(text(
                "INSERT INTO ffa_card_offers (match_id, player_id, round_number,"
                " card_name, was_picked) VALUES (:m, :p, :rn, :c, :w)"
            ), {"m": match_id, "p": pid, "rn": int(getattr(off, "round_number", 1) or 1),
                "c": onm_clean[:64], "w": bool(getattr(off, "was_picked", False))})

    # Settle FFA bets. Codex round-2 review finds 3+4: keyed by the game's
    # REAL identity (the _rN suffix inside the HMAC-covered room id), never
    # by arrival order — an outbox-delayed game-1 report must not let game
    # 2's winner pay game-1 wagers. The catch-up pass then re-resolves any
    # OLDER unsettled bets (out-of-order arrival, or a prior settle savepoint
    # rolled back on a deadlock) against their own recorded matches, so a
    # failed settle self-heals on the next report instead of stranding.
    # SAVEPOINT so a betting problem can never take the report down (#187).
    # Bug #114 item 3: game_no used to be computed OUTSIDE this try — the
    # bare-`re` NameError in _ffa_room_game_no therefore 500'd the whole
    # report instead of being swallowed here. Every statement of the bet
    # block lives inside the guard now.
    try:
        game_no = _ffa_room_game_no(report.photon_room_id) or (int(lobby["games_played"] or 0) + 1)
        async with db.begin_nested():
            winner_pid = id_by_steam[report.winner_steam_id]
            await _settle_ffa_bets_for_game(db, lobby_uuid, game_no, winner_pid)
            stragglers = (await db.execute(text(
                "SELECT DISTINCT game_number FROM ffa_bets"
                " WHERE lobby_id = :lid AND settled_at IS NULL AND game_number < :g"
            ), {"lid": lobby_uuid, "g": game_no})).scalars().all()
            for sg in stragglers:
                past_winner = (await db.execute(text(
                    "SELECT winner_id FROM ffa_matches"
                    " WHERE lobby_id = :lid AND photon_room_id LIKE :sfx ESCAPE '\\'"
                    "   AND invalidated_at IS NULL ORDER BY ended_at LIMIT 1"
                ), {"lid": lobby_uuid, "sfx": f"%\\_r{int(sg)}"})).scalar()
                if past_winner is not None:
                    await _settle_ffa_bets_for_game(db, lobby_uuid, int(sg), past_winner)
    except Exception as bet_ex:
        print(f"[FFA-BETS] settle failed (report unaffected, catch-up next report): {bet_ex}")

    await db.execute(text(
        "UPDATE ffa_lobbies SET games_played = games_played + 1 WHERE id = :lid"
    ), {"lid": lobby_uuid})
    await db.commit()

    rep_place = placements.get(report.reported_by_steam_id, 0)
    rep_xp, rep_gold = award_info.get(report.reported_by_steam_id, (0, 0))
    print(f"[FFA-REPORT] match {match_id} lobby {lobby_uuid} n={n} "
          f"winner={report.winner_steam_id} reporter_place={rep_place}")
    return FfaMatchResponse(
        match_id=match_id, lobby_id=lobby_uuid, placement=rep_place, player_count=n,
        rating_changes=rating_changes, xp_gained=rep_xp, gold_gained=rep_gold)


_FFA_LB_SORTS = {
    "rating": "g.rating DESC",
    "wins": "g.wins DESC, g.rating DESC",
    "games": "g.games_played DESC, g.rating DESC",
    "win_rate": "(g.wins::float / NULLIF(g.games_played,0)) DESC NULLS LAST, g.rating DESC",
    "top3": "g.top3 DESC, g.rating DESC",
    "avg_placement": "(g.placement_sum::float / NULLIF(g.games_played,0)) ASC NULLS LAST, g.rating DESC",
}


@app.get("/api/v1/ffa/leaderboard", response_model=FfaLeaderboardResponse, tags=["FFA Matches"])
async def ffa_leaderboard(limit: int = 200, min_games: int = 1, sort_by: str = "rating",
                          db: AsyncSession = Depends(get_db)):
    """FFA leaderboard — RANKED. sort_by resolves through a dict allowlist
    (never interpolate the raw param — learning #188)."""
    order_sql = _FFA_LB_SORTS.get(sort_by, _FFA_LB_SORTS["rating"])
    rows = (await db.execute(text(f"""
        SELECT p.id AS player_id, p.steam_id, p.display_name, p.total_xp, p.hide_gold,
               p.ffa_gold_earned, p.ffa_xp_earned,
               g.rating, g.rating_deviation, g.games_played, g.wins, g.top3, g.placement_sum,
               si.name AS title_name, si.preview_color AS title_color, si.sku AS title_sku,
               gr.rating AS rating_1v1
          FROM glicko_ratings_ffa g
          JOIN players p ON p.id = g.player_id
          LEFT JOIN shop_items si ON si.id = p.active_title_id
          LEFT JOIN glicko_ratings gr ON gr.player_id = p.id
         WHERE g.games_played >= :ming AND p.deleted_at IS NULL
         ORDER BY {order_sql}
         LIMIT :lim
    """), {"ming": max(1, min_games), "lim": max(1, min(limit, 500))})).mappings().all()
    _colors = await _rank_colors(db)
    _pmap = await _podium_map(db) if any(
        r["title_sku"] == TITLE_PODIUM_SKU for r in rows) else {}
    entries = []
    for i, r in enumerate(rows):
        games = int(r["games_played"] or 0)
        wins = int(r["wins"] or 0)
        lvl, _, _ = level_from_xp(r["total_xp"] or 0)
        t_name, t_color = _display_title_sync(
            _colors, r["title_sku"], r["title_name"], r["title_color"],
            r["rating_1v1"], podium_pos=_pmap.get(str(r["player_id"])))
        entries.append(FfaLeaderboardEntry(
            rank=i + 1, steam_id=r["steam_id"], display_name=r["display_name"] or "Player",
            rating=int(round(r["rating"] or 1500)), rd=int(round(r["rating_deviation"] or 350)),
            games_played=games, wins=wins, top3=int(r["top3"] or 0),
            avg_placement=round((r["placement_sum"] or 0) / games, 2) if games else 0.0,
            win_rate=round(wins / games, 3) if games else 0.0,
            level=lvl, title=t_name, title_color=t_color,
            ffa_gold_earned=(-1 if r["hide_gold"] else int(r["ffa_gold_earned"] or 0)),
            ffa_xp_earned=int(r["ffa_xp_earned"] or 0),
        ))
    return FfaLeaderboardResponse(
        entries=entries, total_players=len(entries),
        last_updated=datetime.now(timezone.utc), is_ranked=True)


@app.get("/api/v1/ffa/recent", tags=["FFA Matches"])
async def ffa_recent(page: int = Query(0, ge=0), page_size: int = Query(5, ge=1, le=10),
                     ranked: bool = Query(True),
                     db: AsyncSession = Depends(get_db)):
    """Recent FFA matches, newest first, with the full per-player stat
    surface (placements, rounds, rating deltas, cards, telemetry) — the
    'Recent Ranked FFAs' panel feed, and with ranked=false the new 'Recent
    Casual FFAs' panel (Sid, Aug 3). Browsable by anyone, like
    /team/all-series-paged."""
    # §6: ranked and casual games never mix in one panel. `bool` is genuinely
    # type-validated by FastAPI (unlike Query enum= — learning #188) and bound
    # as a parameter in BOTH queries (a filter drift between COUNT and page
    # desyncs total_pages from the page contents).
    total = (await db.execute(text(
        "SELECT COUNT(*) FROM ffa_matches WHERE invalidated_at IS NULL AND is_ranked = :rk"
    ), {"rk": ranked})).scalar() or 0
    matches = (await db.execute(text("""
        SELECT m.id, m.photon_room_id, m.player_count, m.duration_seconds,
               m.ended_at, m.is_ranked, m.timeline, pw.steam_id AS winner_steam,
               -- Sid, Aug 3: show the lobby's settings beside each game. The
               -- config is immutable once a lobby leaves 'open' (settings are
               -- host-only AND status-gated), so this row still describes
               -- exactly what these games were played under. LEFT JOIN so a
               -- pre-config-era match simply reports nulls.
               l.score_target, l.card_cap, l.initial_picks,
               l.card_candidates, l.same_card_rule, l.settings_known
          FROM ffa_matches m
          LEFT JOIN players pw ON pw.id = m.winner_id
          LEFT JOIN ffa_lobbies l ON l.id = m.lobby_id
         WHERE m.invalidated_at IS NULL AND m.is_ranked = :rk
         ORDER BY m.ended_at DESC
         LIMIT :lim OFFSET :off
    """), {"lim": page_size, "off": page * page_size, "rk": ranked})).mappings().all()
    match_ids = [r["id"] for r in matches]
    players_by_match: dict = {mid: [] for mid in match_ids}
    cards_by_match_player: dict = {}
    if match_ids:
        # Title join mirrors the leaderboard's (live rank-title resolution via
        # _display_title_sync needs the 1v1 rating for title_rank skus).
        prow = (await db.execute(text("""
            SELECT fmp.*, p.steam_id, p.display_name,
                   si.name AS title_name, si.preview_color AS title_pcolor,
                   si.sku AS title_sku, gr.rating AS rating_1v1
              FROM ffa_match_players fmp
              JOIN players p ON p.id = fmp.player_id
              LEFT JOIN shop_items si ON si.id = p.active_title_id
              LEFT JOIN glicko_ratings gr ON gr.player_id = p.id
             WHERE fmp.match_id = ANY(:mids)
             ORDER BY fmp.placement ASC, fmp.rounds_won DESC
        """), {"mids": match_ids})).mappings().all()
        crow = (await db.execute(text("""
            SELECT fc.match_id, p.steam_id, fc.card_name, fc.pick_order, fc.rolled
              FROM ffa_match_cards fc
              JOIN players p ON p.id = fc.player_id
             WHERE fc.match_id = ANY(:mids)
             ORDER BY fc.pick_order ASC
        """), {"mids": match_ids})).mappings().all()
        for c in crow:
            cards_by_match_player.setdefault((c["match_id"], c["steam_id"]), []).append(
                {"n": c["card_name"], "r": bool(c["rolled"])})
        _colors = await _rank_colors(db)
        _pmap = await _podium_map(db) if any(
            r["title_sku"] == TITLE_PODIUM_SKU for r in prow) else {}
        for r in prow:
            t_name, t_color = _display_title_sync(
                _colors, r["title_sku"], r["title_name"], r["title_pcolor"],
                r["rating_1v1"], podium_pos=_pmap.get(str(r["player_id"])))
            players_by_match[r["match_id"]].append({
                "steam_id": r["steam_id"],
                "display_name": r["display_name"] or "Player",
                "title": t_name or "",
                "title_color": t_color or "",
                "slot": int(r["slot"]) if r["slot"] is not None else -1,
                "placement": int(r["placement"]),
                "rounds_won": int(r["rounds_won"] or 0),
                "points_total": int(r["points_total"] or 0),
                "kills": int(r["kills"] or 0),
                "left_early": bool(r["left_early"]),
                "rating_change": float(r["rating_change"]) if r["rating_change"] is not None else None,
                "xp_gained": int(r["xp_gained"] or 0),
                "gold_gained": int(r["gold_gained"] or 0),
                "fps_avg": int(r["fps_avg"]) if r["fps_avg"] is not None else 0,
                "ping_avg": int(r["ping_avg"]) if r["ping_avg"] is not None else None,
                "bullets_fired": r["bullets_fired"], "bullets_hit": r["bullets_hit"],
                "blocks_activated": r["blocks_activated"],
                "blocks_successful": r["blocks_successful"],
                "keys_pressed": r["keys_pressed"], "active_seconds": r["active_seconds"],
                "fps_timeline": r["fps_timeline"], "ping_timeline": r["ping_timeline"],
                "hit_timeline": r["hit_timeline"], "block_timeline": r["block_timeline"],
                "cards": cards_by_match_player.get((r["match_id"], r["steam_id"]), []),
            })
    return {
        "matches": [
            {"match_id": str(m["id"]), "photon_room_id": m["photon_room_id"],
             "player_count": int(m["player_count"] or 0),
             "duration_seconds": m["duration_seconds"],
             "ended_at": m["ended_at"].isoformat() if m["ended_at"] else None,
             "is_ranked": bool(m["is_ranked"]),
             "winner_steam_id": m["winner_steam"],
             "timeline": m["timeline"] or "",
             # Lobby settings this game was played under (null for
             # pre-config-era matches, which the client renders as blank
             # rather than as defaults it cannot vouch for).
             # settings_known is FALSE for lobbies that predate the
             # configurable-lobby feature: migration 176 gave them DEFAULT
             # values they were never played under (early games were
             # first-to-3), so report unknown rather than a plausible lie.
             "settings": (None if (m["score_target"] is None
                                   or not m["settings_known"]) else {
                 "score_target": int(m["score_target"]),
                 "card_cap": int(m["card_cap"]),
                 "initial_picks": int(m["initial_picks"]),
                 "card_candidates": int(m["card_candidates"]),
                 "same_card_rule": bool(m["same_card_rule"]),
             }),
             "players": players_by_match.get(m["id"], [])}
            for m in matches
        ],
        "page": page, "page_size": page_size, "total": int(total),
        "total_pages": (int(total) + page_size - 1) // page_size if total else 0,
    }


# ── FFA betting (Sid round-2 item 6) ────────────────────────────────────────
# Mirrors place_bet/place_team_bet: HMAC-signed, session-checked, debit-now /
# credit-on-settle, odds snapshotted on the bet row. FFA odds are FIELD odds:
#   E_i = mean pairwise Glicko expectancy of i vs each opponent
#   p_i = E_i / sum_j E_j          (normalized win probability)
#   mult = clamp(1 / (2 * p_i), 1.10, cap)
# so an average player in an n-player lobby pays ~n/2 (x1.5 at 3 ... x5.0 at
# 10 — Sid's ceiling). The cap shrinks with rating uncertainty like the 1v1
# ramp, but keyed to FFA RD (fresh FFA ratings start at 350): full cap at
# RD<=150 down to 1.0 at RD>=350 — the 1.10x floor then rejects the bet
# outright, same anti-smurf posture as 1v1.

def _ffa_race_probs(shares: list[float], target: int) -> list[float]:
    """P(player i banks `target` points first) when each point's winner is
    iid categorical with the given shares. EXACT via the Poisson-race
    embedding: superpose points as a unit-rate Poisson process thinned by the
    shares — the thinned processes are INDEPENDENT and the discrete winner
    sequence is identical in law, so
        P_i = ∫ Gamma(target, q_i).pdf(t) · Π_{j≠i} P(N_j(t) < target) dt.
    This is the §8b fix: single-encounter expectancy compresses toward 1/n,
    but the true probability of winning a first-to-N RACE does not — a
    1.5x-per-point favourite in a 6-player lobby wins first-to-5 at ~0.66
    while the flat share prices it at 0.23 (a repeatable +33-40% EV leak for
    anyone backing favourites, growing with N)."""
    n = len(shares)
    tot = sum(shares) or 1e-9
    q = [max(1e-9, s / tot) for s in shares]
    tgt = max(1, int(target))
    # Grid over the merged process time. The race ALWAYS ends within
    # n·(tgt−1)+1 point arrivals (pigeonhole), and merged arrivals run at unit
    # rate, so t beyond ~2·n·tgt is unreachable — bound t_max structurally,
    # NEVER from min(q): a near-zero share would stretch the grid by orders of
    # magnitude and the real contenders' mass would fall between grid points.
    t_max = 2.0 * n * tgt + 20.0
    steps = 600
    dt = t_max / steps
    lam = [[qi * (k + 0.5) * dt for k in range(steps)] for qi in q]   # q_i * t
    # Poisson survival S_j(t) = P(N_j(t) <= target-1), per player per grid pt.
    surv = []
    for j in range(n):
        col = []
        for k in range(steps):
            x = lam[j][k]
            term = math.exp(-x)
            acc = term
            for m in range(1, tgt):
                term *= x / m
                acc += term
            col.append(acc)
        surv.append(col)
    fact = math.factorial(tgt - 1)
    probs = []
    for i in range(n):
        acc = 0.0
        for k in range(steps):
            x = lam[i][k]
            # Gamma(target, rate q_i) pdf at t = q_i * x^(tgt-1) e^-x / (tgt-1)!
            pdf = q[i] * (x ** (tgt - 1)) * math.exp(-x) / fact
            prod = 1.0
            for j in range(n):
                if j != i:
                    prod *= surv[j][k]
            acc += pdf * prod * dt
        probs.append(acc)
    s = sum(probs) or 1e-9
    return [p / s for p in probs]


# Odds cache (Codex v1.36 review find 10): the race integral costs ~9ms for a
# worst-case 10-player/target-10 field and /ffa/bettable is unauthenticated on
# the 150/10s bucket — twenty uncached fields could eat the single worker.
# Keyed on the exact inputs; single-process state is safe here (#125's
# single-worker invariant is enforced by the compose command override).
_FFA_ODDS_CACHE: dict = {}
_FFA_ODDS_CACHE_AT: dict = {}
_FFA_ODDS_CACHE_TTL = 5.0


def _ffa_field_odds(field: list[tuple[str, float, float]],
                    score_target: int = 5) -> dict[str, float]:
    """field = [(steam_id, rating, rd)] for the full roster. Returns
    steam_id -> payout multiplier (uncapped by lobby size here; caller caps).
    score_target is the lobby's first-to-N — the race length changes true win
    probabilities materially (§8b), so it is part of the price."""
    n = len(field)
    if n < 2:
        return {s: 1.01 for s, _, _ in field}
    _ck = (int(score_target or 5),
           tuple(sorted((s, round(r, 1), round(rd, 1)) for s, r, rd in field)))
    _now_mono = time.monotonic()
    if _ck in _FFA_ODDS_CACHE and _now_mono - _FFA_ODDS_CACHE_AT.get(_ck, 0.0) < _FFA_ODDS_CACHE_TTL:
        return dict(_FFA_ODDS_CACHE[_ck])
    # Per-point win shares are BRADLEY-TERRY strengths derived from rating
    # directly: s_i = 10^(r_i/400), so pairwise p_ij = s_i/(s_i+s_j) — the
    # Luce/categorical model the Poisson race actually assumes. The first
    # draft fed it MEAN PAIRWISE EXPECTANCIES, which are Borda-like scores,
    # not shares — that compressed a true 66% favourite to p≈0.41 and left a
    # reproducible +33% EV on backing favourites (Codex find 3, with the
    # exact-DP verification). RD does not enter the strength — uncertainty is
    # priced by the cap ramp below, exactly as before.
    r_ref = min(r for _, r, _ in field)
    strengths_l: list[float] = [pow(10.0, (r - r_ref) / 400.0) for _, r, _ in field]
    race = _ffa_race_probs(strengths_l, max(1, int(score_target or 5)))
    race_by_sid = {sid: race[i] for i, (sid, _, _) in enumerate(field)}
    mults: dict[str, float] = {}
    full_cap = min(FFA_ODDS_MAX, n / 2.0)
    # Sid's ask: "minimum odds 2x for 5+ people games". A floor RAISES what the
    # house pays on favourites (the 5-player screenshot had the top seed at
    # x1.39), so it narrows the margin rather than widening it — but only from
    # enormous to large: picking 1 winner from 5 is a true p of ~0.2, i.e. fair
    # odds of 5.0, so paying 2.0 still keeps roughly half. Verified in the
    # house-edge check below the function.
    floor = FFA_ODDS_MIN_LARGE if n >= 5 else FFA_ODDS_MIN_SMALL
    for sid_i, r_i, rd_i in field:
        p = race_by_sid[sid_i]
        raw = 1.0 / max(1e-6, 2.0 * p)
        # EV-SAFE floor (Codex find 3, second half): a hard 2.0 floor on a
        # player whose TRUE race probability exceeds 0.5 pays out more than
        # fair — a structural money printer no share model can fix. The floor
        # therefore yields to 0.95/p (a guaranteed >=5% house margin) for
        # probable winners; longshots — the floor's actual purpose — keep the
        # full 2.0 because 0.95/p is enormous there. Sid's "minimum 2x at 5+"
        # was set when favourites were mispriced at ~0.24; a 2x payout on a
        # 66% favourite is +33% EV per bet, forever, to anyone who notices.
        eff_floor = min(floor, 0.95 / max(1e-6, p))
        other_rds = [rd for s, _, rd in field if s != sid_i]
        field_rd = (sum(other_rds) / len(other_rds)) if other_rds else rd_i
        # OWN RD dominates the cap (was: max(own, field mean), which let a
        # single unrated player in the lobby collapse EVERYONE's cap). Sid's
        # "max x5 for low elo low rd players" is precisely this: low RD means a
        # CONVERGED, trusted rating (#68 uses RD <= 110 as the trust
        # threshold), so a confidently-weak player is a genuine longshot and
        # earns the ceiling. Keeping a 30% weight on the field's uncertainty is
        # the anti-smurf term: a fresh account carries RD 350, so its own cap
        # collapses and it can never be the x5 longshot that mints gold.
        rd_eff = 0.70 * rd_i + 0.30 * field_rd
        if rd_eff <= 150.0:
            cap = full_cap
        elif rd_eff >= 350.0:
            cap = 1.0
        else:
            cap = 1.0 + (full_cap - 1.0) * (350.0 - rd_eff) / 200.0
        # The floor must never be squeezed out by a low cap in an uncertain
        # field, or "minimum 2x at 5+" would silently not hold (for the
        # longshots it exists for — the EV-safe eff_floor governs favourites).
        cap = max(cap, eff_floor)
        mults[sid_i] = max(eff_floor, min(raw, cap))
    _FFA_ODDS_CACHE[_ck] = dict(mults)
    _FFA_ODDS_CACHE_AT[_ck] = _now_mono
    # Bound the cache (rotating lobbies would grow it forever).
    if len(_FFA_ODDS_CACHE) > 200:
        _FFA_ODDS_CACHE.clear()
        _FFA_ODDS_CACHE_AT.clear()
    return mults


def _ffa_lobby_is_live(lobby) -> bool:
    """Is a NEXT game plausibly coming in this lobby?

    The only predicate used to be `status = 'active'`, and nothing advances that
    status when a sitting simply ends — so a finished lobby stayed listed as
    bettable indefinitely (Sid: "the Live FFA betting is glitched and still
    showing the last session of people"). A lobby qualifies while it is either
    still assembling its first game, or its most recent game ended recently
    enough that another is expected.

    `lobby` needs id / games_played / created_at / last_game_at.
    """
    try:
        now = datetime.now(timezone.utc)
        games = int(lobby["games_played"] or 0)
        last = lobby["last_game_at"]
        if games <= 0 or last is None:
            created = lobby["created_at"]
            if created is None:
                return False
            return (now - created).total_seconds() <= FFA_BET_LIVE_ASSEMBLY_MINUTES * 60
        return (now - last).total_seconds() <= FFA_BET_LIVE_AFTER_GAME_MINUTES * 60
    except Exception:
        return False


def _ffa_bet_window_open(lobby) -> bool:
    """INTERIM exploit gate — see FFA_BET_OPEN_SECONDS.

    Sid's rule is "let people bet until someone has 2 points", but the server
    has no live FFA score: nothing reports progress between the lock and the
    game's final report, so the only enforceable gate today is elapsed time.
    Without it, betting stays open until the last kill, and with the odds floor
    raised to 2.0 (5.0 at ten players) that is a guaranteed multiple on a
    decided game for anyone spectating.

    So: game 1 is bettable for FFA_BET_OPEN_SECONDS after the lock, game N+1
    for the same window after game N ended. This is deliberately COARSER than
    the real rule — it can close while a slow lobby is still picking cards —
    and it is replaced by the exact 2-point lock as soon as the client can push
    live scores. Being slightly too strict costs a missed bet; being too loose
    mints gold.
    """
    try:
        now = datetime.now(timezone.utc)
        anchor = lobby["last_game_at"] if int(lobby["games_played"] or 0) > 0 else lobby["created_at"]
        if anchor is None:
            return False
        return (now - anchor).total_seconds() <= FFA_BET_OPEN_SECONDS
    except Exception:
        return False


async def _ffa_lobby_field(db: AsyncSession, member_ids: list) -> list[dict]:
    """Roster with names + FFA rating/RD (1v1 rating as display fallback for
    players without FFA games — RD stays 350 so odds treat them as unknown)."""
    if not member_ids:
        return []
    rows = (await db.execute(text("""
        SELECT p.id, p.steam_id, p.display_name,
               g.rating AS ffa_rating, g.rating_deviation AS ffa_rd, g.games_played AS ffa_games,
               gr.rating AS rating_1v1
          FROM players p
          LEFT JOIN glicko_ratings_ffa g ON g.player_id = p.id
          LEFT JOIN glicko_ratings gr ON gr.player_id = p.id
         WHERE p.id = ANY(:ids)
    """), {"ids": list(member_ids)})).mappings().all()
    out = []
    for r in rows:
        has_ffa = (r["ffa_games"] or 0) > 0
        out.append({
            "player_id": r["id"], "steam_id": r["steam_id"],
            "display_name": r["display_name"] or "Player",
            "rating": float(r["ffa_rating"]) if has_ffa else float(r["rating_1v1"] or 1500),
            "rd": float(r["ffa_rd"]) if has_ffa else 350.0,
        })
    return out


def _ffa_room_game_no(room_id: str | None) -> int | None:
    """Game number from the per-game report room id ('..._rN', HMAC-covered).

    July 28 bug #114 item 3: this said bare `re.` while the module imports
    `re as _re` — a NameError that 500'd EVERY FFA match report whose lobby
    had bets (the only caller is the bet-settle branch), which then left
    games_played at 0 so the 10-minute dead-lock heuristic cancelled the live
    lobby mid-game and the whole session went unrecorded (learning #135's
    untested-branch import trap, again)."""
    m = _re.search(r"_r(\d+)$", room_id or "")
    return int(m.group(1)) if m else None


async def _settle_ffa_bets_for_game(db: AsyncSession, lobby_id, game_no: int, winner_pid):
    """Pay/lose every unsettled bet on one specific game. Gold credit is a
    single atomic UPDATE (#148). Each bet is CLAIMED first (settled_at set in
    the same statement that is gated on settled_at IS NULL) so two concurrent
    settle passes — e.g. two reports' catch-up loops, or a report racing the
    stranded-bet janitor — can never both pay the same bet."""
    open_bets = (await db.execute(text(
        "SELECT id, player_id, bet_on_player_id, amount, odds_multiplier"
        "  FROM ffa_bets WHERE lobby_id = :lid AND game_number = :g AND settled_at IS NULL"
        " ORDER BY player_id::text, id LIMIT 200"
    ), {"lid": lobby_id, "g": game_no})).mappings().all()
    n = 0
    for b in open_bets:
        # FLOOR, never round (Codex round-3 find 11): the odds already carry
        # the continuous 0.95/p EV cap, but round(1 × 1.58) = 2 re-opens a
        # +20% EV edge on 1g favourite bets. Floor keeps the discrete payout
        # under the continuous bound at every stake; the sub-1g remainder is
        # the house's.
        # Arithmetic stays DECIMAL end-to-end (round-4 find 4): the NUMERIC
        # column arrives as decimal.Decimal, and converting to binary float
        # first turns 25 × 1.16 into 28.999999999999996 — a 1g underpay.
        # int() on a positive Decimal truncates, which IS the floor here.
        won = b["bet_on_player_id"] == winner_pid
        pay = int(b["amount"] * b["odds_multiplier"]) if won else 0
        claimed = (await db.execute(text(
            "UPDATE ffa_bets SET payout = :p, settled_at = NOW(), settlement_kind = :k"
            " WHERE id = :bid AND settled_at IS NULL RETURNING id"
        ), {"p": pay, "k": "won" if won else "lost", "bid": b["id"]})).scalar()
        if claimed is None:
            continue   # another pass got here first — it also moved the gold
        n += 1
        if pay > 0:
            await db.execute(text(
                "UPDATE players SET gold_earned = COALESCE(gold_earned,0) + :g WHERE id = :pid"
            ), {"g": pay, "pid": b["player_id"]})
            db.add(GoldTransaction(player_id=b["player_id"], amount=pay,
                                   reason="ffa_bet_win", reference_id=str(lobby_id)))
    if n:
        print(f"[FFA-BETS] settled {n} bet(s) on lobby {lobby_id} game {game_no}")


async def _refund_ffa_lobby_bets(db: AsyncSession, lobby_id, reason: str, game_number: int | None = None):
    """Refund unsettled bets on a lobby (cancel/sweep paths), optionally only
    one game's. Payout == stake marks a refund (#107 display rule). Claim-first
    like the settle (no double-refund across concurrent passes). Runs inside
    its OWN savepoint and never raises (Codex round-2 review find 5: a refund
    deadlock used to leave the CALLER's transaction aborted, killing the whole
    leave/cancel)."""
    try:
        async with db.begin_nested():
            game_filter = " AND game_number = :g" if game_number is not None else ""
            params = {"lid": lobby_id}
            if game_number is not None:
                params["g"] = int(game_number)
            rows = (await db.execute(text(
                "SELECT id, player_id, amount FROM ffa_bets"
                " WHERE lobby_id = :lid AND settled_at IS NULL"
                + game_filter +
                " ORDER BY player_id::text, id LIMIT 200"
            ), params)).mappings().all()
            n = 0
            for b in rows:
                claimed = (await db.execute(text(
                    "UPDATE ffa_bets SET payout = amount, settled_at = NOW(),"
                    " settlement_kind = 'refunded'"
                    " WHERE id = :bid AND settled_at IS NULL RETURNING id"
                ), {"bid": b["id"]})).scalar()
                if claimed is None:
                    continue
                n += 1
                await db.execute(text(
                    "UPDATE players SET gold_spent = GREATEST(0, COALESCE(gold_spent,0) - :amt) WHERE id = :pid"
                ), {"amt": b["amount"], "pid": b["player_id"]})
                db.add(GoldTransaction(player_id=b["player_id"], amount=b["amount"],
                                       reason="ffa_bet_refund", reference_id=str(lobby_id)))
            # Flush INSIDE the savepoint — an unflushed ORM add would survive
            # the rollback and write a ledger row without its gold move (#187).
            await db.flush()
            if n:
                print(f"[FFA-BETS] refunded {n} bet(s) on lobby {lobby_id} ({reason})")
    except Exception as ex:
        print(f"[FFA-BETS] refund pass failed for {lobby_id} ({reason}) — retried at next closure event: {ex}")


async def _reconcile_ffa_lobby_bets(db: AsyncSession, lobby_id, reason: str):
    """Terminal bet resolution for a lobby that is closing (or already closed):
    settle every unsettled bet whose game has a RECORDED result, refund only
    the wagers on games that never happened (#241 — a blanket refund mis-pays
    both sides of a played game whose settle savepoint rolled back). Safe on
    zero-game lobbies (degrades to pure refund), idempotent (settled_at gate),
    savepoint-contained, never raises."""
    unresolved_games: list = []
    try:
        async with db.begin_nested():
            games = (await db.execute(text(
                "SELECT DISTINCT game_number FROM ffa_bets"
                " WHERE lobby_id = :lid AND settled_at IS NULL ORDER BY game_number"
            ), {"lid": lobby_id})).scalars().all()
            for g in games:
                winner = (await db.execute(text(
                    "SELECT winner_id FROM ffa_matches"
                    " WHERE lobby_id = :lid AND photon_room_id LIKE :sfx ESCAPE '\\'"
                    "   AND invalidated_at IS NULL ORDER BY ended_at LIMIT 1"
                ), {"lid": lobby_id, "sfx": f"%\\_r{int(g)}"})).scalar()
                if winner is not None:
                    await _settle_ffa_bets_for_game(db, lobby_id, int(g), winner)
                else:
                    unresolved_games.append(int(g))
            # Flush the settle's ORM ledger adds inside the savepoint (#187).
            await db.flush()
    except Exception as ex:
        # Do NOT fall through to the refund: with the settle pass rolled back,
        # a refund would return stakes on games that DO have a recorded result
        # (#241's exact mis-pay). The stranded-bet janitor sweep retries the
        # whole reconcile on its next tick instead.
        print(f"[FFA-BETS] closure reconcile failed for {lobby_id} ({reason}) — janitor retries: {ex}")
        return
    # Refund ONLY games with no recorded result — never a blanket pass over
    # the leftovers (Codex round-2 find 7: with 200+ bets on one recorded
    # game, the settle's per-pass cap leaves overflow unsettled, and a
    # blanket refund would mis-pay it; scoped this way the overflow simply
    # waits for the sweep's next tick to settle correctly).
    for g in unresolved_games:
        await _refund_ffa_lobby_bets(db, lobby_id, reason, game_number=g)


@app.get("/api/v1/ffa/bettable", tags=["Betting"])
async def ffa_bettable(steam_id: str = Query(""), db: AsyncSession = Depends(get_db)):
    """Active FFA lobbies with per-player odds for the bet UI. Lobbies the
    requester is a member of are flagged (client hides the buttons)."""
    lobbies = (await db.execute(text("""
        SELECT l.id, l.member_ids, l.departed_ids, l.player_count, l.games_played,
               l.created_at, l.score_target,
               (SELECT MAX(m.ended_at) FROM ffa_matches m
                 WHERE m.lobby_id = l.id AND m.invalidated_at IS NULL) AS last_game_at
          FROM ffa_lobbies l
         WHERE l.status = 'active'
           AND l.is_ranked          -- §6: no betting on casual lobbies (odds
                                    -- are rating-derived; a casual sitting has
                                    -- no rating stakes to price)
         ORDER BY l.created_at DESC LIMIT 20
    """))).mappings().all()
    me = None
    if steam_id:
        me = (await db.execute(text(
            "SELECT id FROM players WHERE steam_id = :sid"
        ), {"sid": steam_id})).scalar()
    out = []
    for l in lobbies:
        if not _ffa_lobby_is_live(l):
            continue
        # Codex wave-5 finding 6: listing a lobby whose per-game window has
        # closed made the shipped client render live Bet buttons that the POST
        # then rejected with a 409. The listing and the enforcement must use the
        # SAME predicate; `bets_open` lets the panel dim rather than lie.
        window_open = _ffa_bet_window_open(l)
        # Departed members are out of the field: no odds, no bet target
        # (round-2 review find 6).
        departed = set(l["departed_ids"] or [])
        live_ids = [m for m in (l["member_ids"] or []) if m not in departed]
        if len(live_ids) < 2:
            continue
        field_rows = await _ffa_lobby_field(db, live_ids)
        field = [(f["steam_id"], f["rating"], f["rd"]) for f in field_rows]
        mults = _ffa_field_odds(field, _ffa_lobby_config(l)["score_target"])
        next_game = int(l["games_played"] or 0) + 1
        already = False
        if me is not None:
            already = bool((await db.execute(text(
                "SELECT 1 FROM ffa_bets WHERE lobby_id = :lid AND game_number = :g AND player_id = :pid"
            ), {"lid": l["id"], "g": next_game, "pid": me})).scalar())
        out.append({
            "lobby_id": str(l["id"]),
            "player_count": int(l["player_count"] or len(field)),
            "game_number": next_game,
            "is_member": bool(me is not None and any(f["player_id"] == me for f in field_rows)),
            "already_bet": already,
            "bets_open": window_open,
            "players": [
                {"steam_id": f["steam_id"], "display_name": f["display_name"],
                 "rating": int(round(f["rating"])),
                 "odds_multiplier": round(mults.get(f["steam_id"], 1.01), 2),
                 "bettable": window_open and mults.get(f["steam_id"], 1.01) >= 1.10}
                for f in field_rows
            ],
        })
    return {"lobbies": out}


@app.post("/api/v1/ffa/bets", tags=["Betting"])
async def place_ffa_bet(
    request: Request,
    steam_id: str = Query(...),
    lobby_id: str = Query(...),
    bet_on_steam_id: str = Query(...),
    amount: int = Query(..., ge=1, le=2000),   # same 2000g ceiling as 1v1/2v2
    game_number: int = Query(..., ge=1),
    sig: str = Query(...),
    db: AsyncSession = Depends(get_db),
):
    """Bet on the NEXT unreported game of an active FFA lobby. HMAC over
    `ffa-bet:{steam_id}:{lobby_id}:{bet_on_steam_id}:{amount}:{game_number}`.
    game_number is signed and validated against the lobby (Codex round-2
    review find 2: an unbound signed URL was replayable once per LATER game —
    a lost-response retry after game 1 settled would silently place a game-2
    bet). The window is enforced HERE, not just hidden in the UI — a client-side
    hide is a rendering suggestion, not a gate (#159)."""
    await _check_steam_session(request, steam_id, db)
    if not MATCH_HMAC_SECRET:
        raise HTTPException(status_code=503, detail="HMAC not configured")
    expected = hmac.new(
        MATCH_HMAC_SECRET.encode(),
        f"ffa-bet:{steam_id}:{lobby_id}:{bet_on_steam_id}:{amount}:{game_number}".encode(),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(sig, expected):
        raise HTTPException(status_code=403, detail="Invalid signature")
    await _check_ban_or_raise(db, steam_id)

    bettor = (await db.execute(select(Player).where(Player.steam_id == steam_id))).scalar_one_or_none()
    if bettor is None:
        raise HTTPException(status_code=404, detail="Player not found")
    try:
        lid = UUID(lobby_id)
    except Exception:
        raise HTTPException(status_code=400, detail="Invalid lobby_id")
    # FOR NO KEY UPDATE, not FOR UPDATE: ffa_bets.lobby_id and
    # ffa_queue.series_id both FK to ffa_lobbies, so every ffa_bets INSERT takes
    # FOR KEY SHARE on this row — and FOR KEY SHARE conflicts with exactly one
    # mode, FOR UPDATE (#202). Taking the strongest lock here enrolled every
    # concurrent bet insert in our wait graph for no benefit; we never change a
    # key column.
    lobby = (await db.execute(text(
        "SELECT id, status, member_ids, departed_ids, games_played, created_at,"
        "       score_target, is_ranked,"
        "       (SELECT MAX(m.ended_at) FROM ffa_matches m"
        "         WHERE m.lobby_id = ffa_lobbies.id AND m.invalidated_at IS NULL) AS last_game_at"
        "  FROM ffa_lobbies WHERE id = :lid FOR NO KEY UPDATE"
    ), {"lid": lid})).mappings().first()
    if lobby is None:
        raise HTTPException(status_code=404, detail="Lobby not found")
    if lobby["status"] != "active":
        raise HTTPException(status_code=409, detail="Lobby is not active")
    if not bool(lobby["is_ranked"] if lobby["is_ranked"] is not None else True):
        # §6: the listing filters casual lobbies, and the POST must agree with
        # the listing rather than trust it (same-predicate rule, wave-5 find 6).
        raise HTTPException(status_code=409, detail="Casual lobbies are not bettable")
    if not _ffa_lobby_is_live(lobby):
        raise HTTPException(status_code=409, detail="Betting closed - this sitting has ended")
    if not _ffa_bet_window_open(lobby):
        raise HTTPException(status_code=409,
                            detail="Betting for this game has closed - wait for the next one")
    member_ids = list(lobby["member_ids"] or [])
    if bettor.id in member_ids:
        raise HTTPException(status_code=409, detail="Cannot bet on your own lobby")

    # Build the field from LIVE members only. /ffa/bettable already excludes
    # departed players, but this endpoint used the raw member_ids — so a signed
    # request could bet on someone who had already left, and settlement would
    # then score them as a loser (critic M3).
    departed = set(lobby["departed_ids"] or [])
    field_rows = await _ffa_lobby_field(db, [m for m in member_ids if m not in departed])
    target = next((f for f in field_rows if f["steam_id"] == bet_on_steam_id), None)
    if target is None:
        raise HTTPException(status_code=400, detail="bet_on_steam_id is not in this lobby")

    expected_game = int(lobby["games_played"] or 0) + 1
    if game_number != expected_game:
        # Signed for a game that already settled (retry replay) or hasn't
        # opened yet — never silently retarget the stake.
        raise HTTPException(status_code=409,
            detail=f"Bet window for game {game_number} is closed (current: {expected_game})")
    existing = (await db.execute(text(
        "SELECT 1 FROM ffa_bets WHERE lobby_id = :lid AND game_number = :g AND player_id = :pid"
    ), {"lid": lid, "g": game_number, "pid": bettor.id})).scalar()
    if existing:
        raise HTTPException(status_code=409, detail="Already bet on this game")

    field = [(f["steam_id"], f["rating"], f["rd"]) for f in field_rows]
    mult = _ffa_field_odds(field, _ffa_lobby_config(lobby)["score_target"]).get(bet_on_steam_id, 1.01)
    if mult < 1.10:
        raise HTTPException(status_code=409,
            detail="Bets restricted — odds offer no meaningful profit (ratings still uncertain)")

    # Codex round-2 review find 1 (CRITICAL): balance check + debit must be
    # ONE atomic statement — the read-check-ORM-write shape loses updates
    # across two concurrent bets on DIFFERENT lobbies (#148: two readers see
    # the same gold_spent, both pass, last absolute write wins = free stake).
    debited = (await db.execute(text(
        "UPDATE players SET gold_spent = COALESCE(gold_spent,0) + :amt"
        " WHERE id = :pid"
        "   AND (COALESCE(gold_earned,0) - COALESCE(gold_spent,0)) >= :amt"
        " RETURNING id"
    ), {"amt": amount, "pid": bettor.id})).scalar()
    if debited is None:
        raise HTTPException(status_code=402, detail="Insufficient gold")
    db.add(GoldTransaction(player_id=bettor.id, amount=-amount,
                           reason="ffa_bet_stake", reference_id=lobby_id))
    await db.execute(text("""
        INSERT INTO ffa_bets (lobby_id, game_number, player_id, bet_on_player_id, amount, odds_multiplier)
        VALUES (:lid, :g, :pid, :target, :amt, :mult)
    """), {"lid": lid, "g": game_number, "pid": bettor.id,
           "target": target["player_id"], "amt": amount, "mult": round(mult, 2)})
    await db.commit()
    # The quote must be EXACTLY what settlement will pay (round-4 find 3):
    # settlement floors the STORED 2-decimal odds in decimal arithmetic, so
    # the quote does the same — never round(), never the raw float mult.
    _stored_mult = _decimal.Decimal(str(round(mult, 2)))
    return {"status": "placed", "game_number": game_number, "amount": amount,
            "odds_multiplier": round(mult, 2),
            "potential_payout": int(_decimal.Decimal(amount) * _stored_mult)}


# ── Per-player mode histories (Sid round-2 item 8) ──────────────────────────

@app.get("/api/v1/players/{steam_id}/ffa-history", tags=["FFA Matches"])
async def player_ffa_history(steam_id: str, limit: int = Query(15, ge=1, le=50),
                             db: AsyncSession = Depends(get_db)):
    """This player's recent FFA games: player count, placement, rating delta,
    date, and the other participants (name list, placement order)."""
    rows = (await db.execute(text("""
        SELECT m.id AS match_id, m.player_count, m.ended_at, fmp.placement,
               fmp.rating_change, fmp.kills, fmp.rounds_won, fmp.points_total
          FROM ffa_match_players fmp
          JOIN ffa_matches m ON m.id = fmp.match_id
          JOIN players p ON p.id = fmp.player_id
         WHERE p.steam_id = :sid AND m.invalidated_at IS NULL
         ORDER BY m.ended_at DESC
         LIMIT :lim
    """), {"sid": steam_id, "lim": limit})).mappings().all()
    mids = [r["match_id"] for r in rows]
    parts: dict = {}
    if mids:
        prow = (await db.execute(text("""
            SELECT fmp.match_id, p2.display_name, fmp.placement
              FROM ffa_match_players fmp
              JOIN players p2 ON p2.id = fmp.player_id
             WHERE fmp.match_id = ANY(:mids)
               AND p2.steam_id != :sid   -- "the other participants"
             ORDER BY fmp.placement ASC
        """), {"mids": mids, "sid": steam_id})).mappings().all()
        for r in prow:
            parts.setdefault(r["match_id"], []).append(r["display_name"] or "Player")
    return {"games": [
        {"match_id": str(r["match_id"]), "player_count": int(r["player_count"] or 0),
         "placement": int(r["placement"]), "rating_change": float(r["rating_change"]) if r["rating_change"] is not None else None,
         "kills": int(r["kills"] or 0), "rounds_won": int(r["rounds_won"] or 0),
         "points_total": int(r["points_total"] or 0),
         "ended_at": r["ended_at"].isoformat() if r["ended_at"] else None,
         "participants": parts.get(r["match_id"], [])}
        for r in rows
    ]}


@app.get("/api/v1/players/{steam_id}/team-history", tags=["2v2"])
async def player_team_history(steam_id: str, limit: int = Query(10, ge=1, le=30),
                              db: AsyncSession = Depends(get_db)):
    """This player's recent completed 2v2 series: mate, opponents, result,
    series score, own rating delta, date."""
    rows = (await db.execute(text("""
        SELECT ts.id, ts.completed_at, ts.winner_team,
               ts.t1_series_wins, ts.t2_series_wins,
               ts.t1a_id, ts.t1b_id, ts.t2a_id, ts.t2b_id,
               ts.t1a_rating_change, ts.t1b_rating_change, ts.t2a_rating_change, ts.t2b_rating_change,
               pa.display_name AS n1a, pb.display_name AS n1b,
               pc.display_name AS n2a, pd.display_name AS n2b,
               me.id AS my_id
          FROM team_series ts
          JOIN players me ON me.steam_id = :sid
          LEFT JOIN players pa ON pa.id = ts.t1a_id
          LEFT JOIN players pb ON pb.id = ts.t1b_id
          LEFT JOIN players pc ON pc.id = ts.t2a_id
          LEFT JOIN players pd ON pd.id = ts.t2b_id
         WHERE ts.status = 'completed' AND ts.invalidated_at IS NULL
           AND me.id IN (ts.t1a_id, ts.t1b_id, ts.t2a_id, ts.t2b_id)
         ORDER BY ts.completed_at DESC
         LIMIT :lim
    """), {"sid": steam_id, "lim": limit})).mappings().all()
    games = []
    for r in rows:
        my = r["my_id"]
        on_t1 = my in (r["t1a_id"], r["t1b_id"])
        mate = (r["n1b"] if my == r["t1a_id"] else r["n1a"]) if on_t1 \
            else (r["n2b"] if my == r["t2a_id"] else r["n2a"])
        opps = [r["n2a"], r["n2b"]] if on_t1 else [r["n1a"], r["n1b"]]
        won = (r["winner_team"] == 1) == on_t1
        my_rc = {r["t1a_id"]: r["t1a_rating_change"], r["t1b_id"]: r["t1b_rating_change"],
                 r["t2a_id"]: r["t2a_rating_change"], r["t2b_id"]: r["t2b_rating_change"]}.get(my)
        score = f"{r['t1_series_wins']}-{r['t2_series_wins']}" if on_t1 \
            else f"{r['t2_series_wins']}-{r['t1_series_wins']}"
        games.append({
            "series_id": str(r["id"]), "won": won, "score": score,
            "mate": mate or "?", "opponents": [o or "?" for o in opps],
            "rating_change": float(my_rc) if my_rc is not None else None,
            "completed_at": r["completed_at"].isoformat() if r["completed_at"] else None,
        })
    return {"series": games}


@app.get("/api/v1/players/{steam_id}/ovt-history", tags=["1v2"])
async def player_ovt_history(steam_id: str, limit: int = Query(10, ge=1, le=30),
                             db: AsyncSession = Depends(get_db)):
    """This player's recent 1v2 games: role, result, score, the other players,
    date. 1v2 is unranked, so no rating delta."""
    rows = (await db.execute(text("""
        SELECT m.id, m.ended_at, m.winner_side,
               m.solo_rounds_won AS solo_rounds, m.duo_rounds_won AS duo_rounds,
               m.solo_id, m.duo_a_id, m.duo_b_id,
               ps.display_name AS solo_name, pa.display_name AS duo_a_name,
               pb.display_name AS duo_b_name, me.id AS my_id,
               -- Bug #129: the per-game reward, so My Stats' 1v2 history can show
               -- it like the 1v1 and FFA rows already do. Read from the ledger
               -- rather than a new column: ovt_matches has no per-player reward
               -- columns and the series accumulators are series-cumulative.
               (SELECT COALESCE(SUM(gt.amount), 0) FROM gold_transactions gt
                 WHERE gt.player_id = me.id
                   AND gt.reason IN ('ovt_xp', 'level_reward')
                   AND gt.reference_id = m.id::text) AS gold_gained,
               (SELECT COALESCE(SUM(gt.amount), 0) FROM gold_transactions gt
                 WHERE gt.player_id = me.id
                   AND gt.reason IN ('ovt_series_win', 'ovt_series_loss')
                   AND gt.reference_id = m.series_id::text) AS series_gold_gained
          FROM ovt_matches m
          JOIN players me ON me.steam_id = :sid
          LEFT JOIN players ps ON ps.id = m.solo_id
          LEFT JOIN players pa ON pa.id = m.duo_a_id
          LEFT JOIN players pb ON pb.id = m.duo_b_id
         WHERE m.invalidated_at IS NULL
           AND me.id IN (m.solo_id, m.duo_a_id, m.duo_b_id)
         ORDER BY m.ended_at DESC
         LIMIT :lim
    """), {"sid": steam_id, "lim": limit})).mappings().all()
    games = []
    for r in rows:
        is_solo = r["my_id"] == r["solo_id"]
        won = (r["winner_side"] == 1) == is_solo
        games.append({
            "match_id": str(r["id"]), "role": "solo" if is_solo else "duo", "won": won,
            "score": f"{r['solo_rounds']}-{r['duo_rounds']}" if is_solo else f"{r['duo_rounds']}-{r['solo_rounds']}",
            "solo": r["solo_name"] or "?",
            "duo": [r["duo_a_name"] or "?", r["duo_b_name"] or "?"],
            "ended_at": r["ended_at"].isoformat() if r["ended_at"] else None,
            "gold_gained": int(r["gold_gained"] or 0),
            "series_gold_gained": int(r["series_gold_gained"] or 0),
        })
    return {"games": games}


@app.post("/api/v1/team/matches", response_model=TeamMatchResponse, tags=["Team Matches"])
async def submit_team_match(report: TeamMatchReport, request: Request, db: AsyncSession = Depends(get_db)):
    """Submitted by the lowest-Steam-ID participant after a 2v2 game ends.
    HMAC verifies the canonical 11-field message. On series completion, applies
    Glicko-2 update to all 4 players (each player has 2 opponents = the other team)."""
    await _check_steam_session(request, report.reported_by_steam_id, db)
    if not _verify_team_hmac(report):
        raise HTTPException(403, "Invalid team match signature")
    try:
        series_uuid = UUID(report.series_id)
    except (ValueError, TypeError):
        raise HTTPException(400, "Invalid series_id format")
    # Sanity validations.
    steams = {report.t1a.steam_id, report.t1b.steam_id, report.t2a.steam_id, report.t2b.steam_id}
    if len(steams) != 4:
        raise HTTPException(400, "All four players must be distinct")
    if report.t1_rounds_won == report.t2_rounds_won:
        raise HTTPException(400, "Match must have a winner")
    if report.t1_rounds_won > 5 or report.t2_rounds_won > 5:
        raise HTTPException(400, "Invalid round count")
    expected_winner = 1 if report.t1_rounds_won > report.t2_rounds_won else 2
    if expected_winner != report.winner_team:
        raise HTTPException(400, "winner_team disagrees with rounds")
    if report.photon_room_id and "offline" in report.photon_room_id.lower():
        raise HTTPException(400, "Offline matches are not recorded")
    # Round-20 find 4 companion (mirrors the ovt sink): an empty/NULL room
    # bypasses uq_team_match's dedup (Postgres NULLS DISTINCT, #147). The
    # client always sends a per-game-suffixed room; enforce it.
    if not (report.photon_room_id or "").strip():
        raise HTTPException(400, "photon_room_id is required")

    # Series must exist and be active. Lock to prevent advance races.
    # Lock order (learning #197 / Codex batch finding 5): this FOR UPDATE must
    # run BEFORE any Player row is resolved or dirtied. get_or_create_player
    # mutates display_name/last_seen on existing rows and the next statement's
    # autoflush takes those players tuple locks — resolving players first made
    # this path lock players→series, while every DC/grace-expiry/admin
    # completion locks series→players via _complete_team_series_with_ratings,
    # so a final-game submit racing a concurrent completion of the SAME series
    # could deadlock. Locking the series row first serializes those callers.
    s_q = await db.execute(
        text("""SELECT * FROM team_series WHERE id = :sid FOR UPDATE"""),
        {"sid": series_uuid},
    )
    series = s_q.mappings().first()
    if not series:
        # No row exists, so the report cannot be BOUND to a real roster —
        # capturing it would let anyone with the DLL secret spam arbitrary
        # payloads into the admin queue (Codex batch find 7). The July 30
        # incident class (a live series cancelled mid-game) always leaves the
        # row behind, so nothing recoverable is lost by rejecting outright.
        raise HTTPException(404, "team_series not found")
    if series["status"] != "active":
        # July 30 lifecycle audit item 1: this rejection fires BEFORE the
        # team_matches insert, so without capture the whole GAME is destroyed —
        # strictly worse than the FFA shape (which at least keeps the series).
        # Five paths can move a series off 'active' mid-game (janitor stale
        # sweep, DC grace expiry, completion helper, admin resolve, member
        # account deletion); quarantine the report like the FFA path does.
        #
        # Trust boundary (Codex batch find 7): capture ONLY a report whose
        # four players are exactly the series' recorded members and whose
        # reporter is one of them — the same binding the active path enforces
        # later. HMAC + score sanity have already passed, and player rows
        # resolve AFTER this gate, so the transaction has no writes to lose.
        _q_rows = (await db.execute(
            text("SELECT id, steam_id FROM players WHERE steam_id = ANY(:sids)"),
            {"sids": list(steams)},
        )).all()
        _q_by_steam = {r.steam_id: r.id for r in _q_rows}
        _series_members = {series["t1a_id"], series["t1b_id"],
                          series["t2a_id"], series["t2b_id"]}
        _bound = (len(_q_by_steam) == 4
                  and set(_q_by_steam.values()) == _series_members
                  and report.reported_by_steam_id in _q_by_steam)
        if _bound:
            await _quarantine_report(
                db, mode="team", reason=f"series_{series['status']}",
                status_code=400, payload=report.model_dump(),
                group_id=series_uuid, photon_room_id=report.photon_room_id,
                reporter_id=_q_by_steam.get(report.reported_by_steam_id),
                player_ids=list(_q_by_steam.values()))
        raise HTTPException(400, f"team_series is {series['status']}")

    # Cross-series edge: two live series CAN share players (dc_incomplete husk
    # resolved while the same four play a fresh series), and different series
    # rows don't serialize. The players row is the one reliable cross-series
    # gate: every series member has one from queue join, whereas a
    # glicko_ratings_2v2 row doesn't exist until the player's first series
    # COMPLETION — a "lock glicko first" pass matches zero rows for
    # first-series players and locks nothing. So: lock the players rows,
    # ascending str(pid), one indexed statement per row (same rule as
    # _lock_queue_rows_ordered); the completion helper takes the same pass
    # before its glicko access, so any two transactions sharing a member
    # serialize here before either touches glicko rows (which also closes the
    # first-completion duplicate-PK INSERT race on glicko_ratings_2v2).
    # FOR NO KEY UPDATE, deliberately NOT FOR UPDATE (adversarial review
    # find): every later players write in this handler (autoflush of the
    # dirtied Player objects, XP loop, W/L counters, achievement gold) is a
    # non-key UPDATE, which takes exactly this lock — and unlike FOR UPDATE
    # it does not conflict with the FOR KEY SHARE RI locks held by concurrent
    # FK inserts naming these players (report-dc INSERTs its synthetic
    # forfeit team_matches row before calling the helper; FOR UPDATE here
    # formed a fresh deadlock edge with that). Discovery read is deliberately
    # unlocked: legitimate members always exist by queue join, and a steam_id
    # with no row yet has nothing to lock (its INSERT below cannot form a
    # lock edge on an existing tuple).
    _known_pids = (await db.execute(
        text("SELECT id FROM players WHERE steam_id = ANY(:sids)"),
        {"sids": list(steams)},
    )).scalars().all()
    for _pid in sorted(_known_pids, key=str):
        await db.execute(
            text("SELECT 1 FROM players WHERE id = :pid FOR NO KEY UPDATE"),
            {"pid": _pid},
        )

    # Resolve players — now safely under the series + canonical row locks.
    p_t1a = await get_or_create_player(db, report.t1a.steam_id, report.t1a.display_name)
    p_t1b = await get_or_create_player(db, report.t1b.steam_id, report.t1b.display_name)
    p_t2a = await get_or_create_player(db, report.t2a.steam_id, report.t2a.display_name)
    p_t2b = await get_or_create_player(db, report.t2b.steam_id, report.t2b.display_name)

    # Reporter
    by_steam = {report.t1a.steam_id: p_t1a, report.t1b.steam_id: p_t1b,
                report.t2a.steam_id: p_t2a, report.t2b.steam_id: p_t2b}
    reporter = by_steam.get(report.reported_by_steam_id)
    if not reporter:
        raise HTTPException(400, "Reporter must be one of the four participants")
    # Roster binding (Codex round-3 out-of-scope find, pre-existing): the
    # first-match slot realign below rewrites the stored t*_id slots to the
    # CLIENT's grouping — without this set-equality check, one participant
    # with a valid session could substitute three arbitrary registered
    # players and mint a fabricated series result. Same rule the FFA report
    # path has enforced since its review: the report may REORDER the locked
    # roster, never change it.
    #
    # ACCEPTED residual (rounds 4+5, #242 cut): a member deleting their
    # account mid-series desyncs the roster (their steam id resolves to a
    # fresh tombstone UUID), so the sitting's remaining reports 403 here.
    # Two successive "tolerate the tombstone pair" fixes each broke a
    # DIFFERENT downstream consumer (the slot realign, then the completion
    # block's delta_by_pid/slot_to_pid keying — which ALREADY KeyError'd on
    # this scenario before the binding existed). The trigger is a player
    # destroying their account mid-active-series; losing that sitting's
    # remaining games is an acceptable consequence, and a strict gate is the
    # only shape two review rounds could not break.
    _series_member_set = {series["t1a_id"], series["t1b_id"],
                          series["t2a_id"], series["t2b_id"]}
    if {p_t1a.id, p_t1b.id, p_t2a.id, p_t2b.id} != _series_member_set:
        raise HTTPException(403, "Report players must be exactly the series roster")
    # Round-20 find 4: bind the report to the sitting's issued room. The
    # client's report room is "<room>_<token>_r<total>" (BuildReportRoomId)
    # while the series stores the raw issued room, so the relation is
    # PREFIX, not equality. The series room is read from the CURRENT row —
    # a legacy dc_paused resume re-issues the room AND rewrites the stored
    # value, so live sittings always match. NULL stored room (pre-issuance
    # legacy rows) falls through.
    _series_room = (series["photon_room_id"] or "").strip()
    # Full suffix grammar, not a bare prefix (round-21 find 2): startswith
    # would alias raw room "R_x" against stored room "R". BuildReportRoomId
    # emits exactly "<raw-room>_<6-digit token>_r<total>" (token = shared
    # game token, or HHmmss fallback — both always 6 digits; verified
    # against 100% of organic prod rows in both team_ and ovt_ tables).
    if _series_room and not _re.fullmatch(
            _re.escape(_series_room) + r"_\d{6}_r\d+",
            (report.photon_room_id or "")):
        raise HTTPException(400, "Report room does not match the series room")
    # 2v2 reporter clearly has the mod installed.
    await _mark_mod_seen(db, reporter)

    # First-match-of-series team_series slot alignment. The server's balancer
    # assigned team1/team2 at lock time, but the client's t1a/t1b/t2a/t2b
    # labels in the match report come from ROUNDS' in-game teamID — those
    # don't have to align. Re-stamp team_series.t1a_id/t1b_id/t2a_id/t2b_id
    # to mirror the report's grouping ONLY on the first match (so winner_team
    # increments + per-slot rating_change persistence stay consistent across
    # all 3 BO3 matches). Once any match is recorded, the slot mapping is
    # frozen and subsequent matches just have to use the same grouping.
    is_first_match = (series["t1_series_wins"] or 0) == 0 and (series["t2_series_wins"] or 0) == 0
    if is_first_match:
        client_t1_set = frozenset([p_t1a.id, p_t1b.id])
        server_t1_set = frozenset([series["t1a_id"], series["t1b_id"]])
        if client_t1_set != server_t1_set:
            # PARTITION-preserving only (round-19 find 4): ROUNDS' in-game
            # teamID legitimately swaps SIDES and within-team a/b order, so
            # the client's t1 pair may equal the server's t2 pair — but a
            # report whose pairs match NEITHER stored pair is a different
            # PARTITION (A+C vs B+D), and realigning to it would rewrite the
            # continuation gate's own ground truth. Reject it instead.
            server_t2_set = frozenset([series["t2a_id"], series["t2b_id"]])
            if client_t1_set != server_t2_set:
                raise HTTPException(400, "Report team split does not match the series partition")
            await db.execute(
                text("""UPDATE team_series
                       SET t1a_id=:t1a, t1b_id=:t1b, t2a_id=:t2a, t2b_id=:t2b
                       WHERE id = :sid"""),
                {"sid": series_uuid,
                 "t1a": p_t1a.id, "t1b": p_t1b.id,
                 "t2a": p_t2a.id, "t2b": p_t2b.id},
            )
            # Re-read for downstream slot lookups.
            s_q2 = await db.execute(
                text("SELECT * FROM team_series WHERE id = :sid"), {"sid": series_uuid},
            )
            series = s_q2.mappings().first()
            print(f"[TEAM-MATCH] series {series_uuid} slots realigned to client grouping")
    else:
        # Round-20 find 3: the partition gate must hold for EVERY match, not
        # just the 0-0 realign — a mid-series report could otherwise carry
        # an A+C-vs-B+D split past the set-only roster check and drive the
        # positional wins/economy paths with a partition the series never
        # had. Compare against the CURRENT stored slots, NOT match 1's
        # grouping: the between-matches auto-balance (weakest-winner swap)
        # legitimately rewrites the slots mid-series, so "frozen since match
        # 1" would 400 every post-rebalance report. Side order may swap
        # (in-game teamID), so client t1 matching EITHER stored pair is a
        # valid same-partition report.
        client_t1_set = frozenset([p_t1a.id, p_t1b.id])
        server_t1_set = frozenset([series["t1a_id"], series["t1b_id"]])
        server_t2_set = frozenset([series["t2a_id"], series["t2b_id"]])
        if client_t1_set != server_t1_set and client_t1_set != server_t2_set:
            raise HTTPException(400, "Report team split does not match the series partition")

    # Insert team_matches row. is_ranked is server-authoritative for 2v2 since
    # the team_series row was created by /queue/poll's lock — by definition
    # all 4 players queued through ranked matchmaking. The client's matchIsRanked
    # heuristic is computed from the FIRST resolved peer's flags, which can
    # legitimately drop to false in 4-player rooms (only one peer is the "primary
    # opponent" the resolver picks). Forcing true here keeps the leaderboard +
    # series Glicko-update path aligned with the queue-was-ranked invariant.
    new_match = TeamMatch(
        series_id=series_uuid,
        t1a_id=p_t1a.id, t1b_id=p_t1b.id, t2a_id=p_t2a.id, t2b_id=p_t2b.id,
        t1_rounds_won=report.t1_rounds_won,
        t2_rounds_won=report.t2_rounds_won,
        t1_points_total=report.t1_points_total,
        t2_points_total=report.t2_points_total,
        winner_team=report.winner_team,
        t1a_fps_avg=(report.t1a_fps if (report.t1a_fps or 0) > 0 else None),
        t1b_fps_avg=(report.t1b_fps if (report.t1b_fps or 0) > 0 else None),
        t2a_fps_avg=(report.t2a_fps if (report.t2a_fps or 0) > 0 else None),
        t2b_fps_avg=(report.t2b_fps if (report.t2b_fps or 0) > 0 else None),
        duration_seconds=report.match_duration,
        photon_room_id=report.photon_room_id,
        game_version=report.game_version,
        region=report.region,
        hmac_signature=report.hmac_signature,
        reported_by=reporter.id,
        is_ranked=True,
        started_at=report.started_at,
    )
    db.add(new_match)
    await db.flush()

    # Card picks (4 lists)
    for player_obj, side in (
        (p_t1a, report.t1a), (p_t1b, report.t1b),
        (p_t2a, report.t2a), (p_t2b, report.t2b),
    ):
        for card in side.cards:
            db.add(TeamMatchCard(
                match_id=new_match.id,
                player_id=player_obj.id,
                card_name=card.card_name,
                card_rarity=card.card_rarity,
                pick_order=card.pick_order,
                round_number=card.round_number,
            ))

    # July 22 (migration 142): per-player telemetry rows. Slots whose data
    # never reached the reporter (old-client peers) arrive as None — no row.
    for player_obj, tele in (
        (p_t1a, report.t1a_telemetry), (p_t1b, report.t1b_telemetry),
        (p_t2a, report.t2a_telemetry), (p_t2b, report.t2b_telemetry),
    ):
        if tele is None:
            continue
        db.add(TeamMatchTelemetry(
            match_id=new_match.id,
            player_id=player_obj.id,
            fps_timeline=(tele.fps_timeline or None),
            ping_timeline=(tele.ping_timeline or None),
            ping_avg=tele.ping_avg,
            hit_timeline=(tele.hit_timeline or None),
            block_timeline=(tele.block_timeline or None),
            bullets_fired=tele.bullets_fired,
            bullets_hit=tele.bullets_hit,
            blocks_activated=tele.blocks_activated,
            blocks_successful=tele.blocks_successful,
            keys_pressed=tele.keys_pressed,
            active_seconds=tele.active_seconds,
        ))

    # Per-match XP awards. Higher base than 1v1 so wins land in user's
    # ~800-900 band and losses near ~600. 100xp=1g auto-conversion still
    # applies (mirrors the 1v1 path) so a clean win also drops a few gold.
    # Per-series accumulator (tax slot positions in team_series so the F5 UI
    # can render +Ng/+Nxp beside each player's name in their own series).
    series_xp_by_pid: dict = {}
    series_gold_by_pid: dict = {}
    # July 20 item 6: opposing-TEAM tier multiplier (avg of the two opposing
    # players' 2v2 ratings, pre-update — 2v2 Glicko only applies at series
    # completion, later than this block). Missing rating rows default 1500.
    _t2v2_ratings: dict = {}
    try:
        _t2v2_rows = (await db.execute(text(
            "SELECT player_id, rating FROM glicko_ratings_2v2 WHERE player_id IN (:a, :b, :c, :d)"
        ), {"a": str(p_t1a.id), "b": str(p_t1b.id), "c": str(p_t2a.id), "d": str(p_t2b.id)})).all()
        _t2v2_ratings = {str(r[0]): float(r[1]) for r in _t2v2_rows}
    except Exception as _rex:
        print(f"[TEAM-ECON] 2v2 tier-mult rating fetch failed (defaulting x1.0): {_rex}")
    _t1_avg_rating = (_t2v2_ratings.get(str(p_t1a.id), 1500.0) + _t2v2_ratings.get(str(p_t1b.id), 1500.0)) / 2.0
    _t2_avg_rating = (_t2v2_ratings.get(str(p_t2a.id), 1500.0) + _t2v2_ratings.get(str(p_t2b.id), 1500.0)) / 2.0
    try:
        team_match_winner = report.winner_team
        for p in (p_t1a, p_t1b, p_t2a, p_t2b):
            p_team = 1 if p.id in (p_t1a.id, p_t1b.id) else 2
            won_match = (p_team == team_match_winner)
            _opp_mult, _ = _tier_mult_for(_t2_avg_rating if p_team == 1 else _t1_avg_rating)
            xp = int(TEAM_MATCH_XP_BASE * _opp_mult)
            if won_match:
                xp = int(xp * TEAM_MATCH_WIN_MULT)
            old_xp_q = await db.execute(text("SELECT total_xp FROM players WHERE id = :pid"), {"pid": p.id})
            old_xp = old_xp_q.scalar() or 0
            new_xp = old_xp + xp
            await db.execute(
                text("UPDATE players SET total_xp = :new, "
                     "team_xp_earned = COALESCE(team_xp_earned,0) + :delta WHERE id = :pid"),
                {"new": new_xp, "delta": xp, "pid": p.id},
            )
            series_xp_by_pid[p.id] = series_xp_by_pid.get(p.id, 0) + xp
            # Level rewards (v1.26.8): granted when crossing 5x level
            # boundaries. 100g per band through 50, 500g per band 55-100.
            old_lvl, _, _ = level_from_xp(old_xp)
            new_lvl, _, _ = level_from_xp(new_xp)
            if new_lvl > old_lvl:
                lvl_reward = sum(level_reward_for(lv) for lv in range(old_lvl + 1, new_lvl + 1))
                if lvl_reward > 0:
                    await db.execute(
                        text("UPDATE players SET gold_earned = COALESCE(gold_earned,0) + :g WHERE id = :pid"),
                        {"g": lvl_reward, "pid": p.id},
                    )
                    db.add(GoldTransaction(
                        player_id=p.id, amount=lvl_reward,
                        reason="level_reward", reference_id=str(new_match.id),
                    ))
            # 100 XP = 1 gold conversion (mirrors submit_match logic).
            gold_delta = (new_xp // 100) - (old_xp // 100)
            if gold_delta > 0:
                await db.execute(
                    text("UPDATE players SET gold_earned = COALESCE(gold_earned,0) + :g, "
                         "team_gold_earned = COALESCE(team_gold_earned,0) + :g WHERE id = :pid"),
                    {"g": gold_delta, "pid": p.id},
                )
                db.add(GoldTransaction(
                    player_id=p.id, amount=gold_delta,
                    reason="team_xp", reference_id=str(new_match.id),
                ))
                series_gold_by_pid[p.id] = series_gold_by_pid.get(p.id, 0) + gold_delta
    except Exception as xpex:
        print(f"[TEAM-ECON] per-match XP failed for match {new_match.id}: {xpex}")

    # Roll the per-match awards into the team_series row's per-slot accumulators.
    try:
        slot_pid = {
            "t1a": series["t1a_id"], "t1b": series["t1b_id"],
            "t2a": series["t2a_id"], "t2b": series["t2b_id"],
        }
        await db.execute(text(
            "UPDATE team_series SET "
            "t1a_xp_earned = COALESCE(t1a_xp_earned,0) + :t1a_xp, "
            "t1b_xp_earned = COALESCE(t1b_xp_earned,0) + :t1b_xp, "
            "t2a_xp_earned = COALESCE(t2a_xp_earned,0) + :t2a_xp, "
            "t2b_xp_earned = COALESCE(t2b_xp_earned,0) + :t2b_xp, "
            "t1a_gold_earned = COALESCE(t1a_gold_earned,0) + :t1a_g, "
            "t1b_gold_earned = COALESCE(t1b_gold_earned,0) + :t1b_g, "
            "t2a_gold_earned = COALESCE(t2a_gold_earned,0) + :t2a_g, "
            "t2b_gold_earned = COALESCE(t2b_gold_earned,0) + :t2b_g "
            "WHERE id = :sid"
        ), {
            "sid": series_uuid,
            "t1a_xp": series_xp_by_pid.get(slot_pid["t1a"], 0),
            "t1b_xp": series_xp_by_pid.get(slot_pid["t1b"], 0),
            "t2a_xp": series_xp_by_pid.get(slot_pid["t2a"], 0),
            "t2b_xp": series_xp_by_pid.get(slot_pid["t2b"], 0),
            "t1a_g":  series_gold_by_pid.get(slot_pid["t1a"], 0),
            "t1b_g":  series_gold_by_pid.get(slot_pid["t1b"], 0),
            "t2a_g":  series_gold_by_pid.get(slot_pid["t2a"], 0),
            "t2b_g":  series_gold_by_pid.get(slot_pid["t2b"], 0),
        })
    except Exception as agex:
        print(f"[TEAM-ECON] per-series accumulator update failed: {agex}")

    # Tag Team Sweep: 5-0 (round shutout) win in this individual 2v2 game.
    # Fires per-match — matches the canonical "sweep = 5-0 game" definition
    # used by the 1v1 sweep stat counter. Previously this was checked at
    # series-completion against a 2-0 series score which is a different
    # criterion entirely; corrected in v1.26.8 to align with player intent.
    game_sweep = (report.t1_rounds_won == 5 and report.t2_rounds_won == 0) \
              or (report.t2_rounds_won == 5 and report.t1_rounds_won == 0)
    if game_sweep:
        sweep_winners = (p_t1a, p_t1b) if report.winner_team == 1 else (p_t2a, p_t2b)
        for wp in sweep_winners:
            await _grant_achievement_inline(db, wp.id, "team_sweep")

    # Advance series counters.
    if report.winner_team == 1:
        new_t1w = (series["t1_series_wins"] or 0) + 1
        new_t2w = series["t2_series_wins"] or 0
    else:
        new_t1w = series["t1_series_wins"] or 0
        new_t2w = (series["t2_series_wins"] or 0) + 1

    series_completed = new_t1w >= 2 or new_t2w >= 2
    series_status = "completed" if series_completed else "active"
    winner_team = (1 if new_t1w > new_t2w else 2) if series_completed else None

    rebalance_assignments: dict[str, int] | None = None
    new_ratings: dict[str, float] = {}

    if series_completed:
        await db.execute(
            text("""UPDATE team_series
                   SET t1_series_wins = :t1, t2_series_wins = :t2,
                       status = 'completed', winner_team = :w, completed_at = NOW()
                   WHERE id = :sid"""),
            {"t1": new_t1w, "t2": new_t2w, "w": winner_team, "sid": report.series_id},
        )
        # Settle 2v2 bets. Winning bets pay amount × odds; losing bets close
        # with payout=0. Mirrors the 1v1 bet settlement that runs on
        # ranked_series completion (in submit_match elsewhere).
        # SAVEPOINT (learning #187): without begin_nested a failed statement
        # here aborts the whole transaction and the match write dies with it —
        # the old comment's promise was not actually true. flush() runs the
        # ORM adds inside the savepoint.
        try:
            async with db.begin_nested():
                unsettled = (await db.execute(text("""
                    SELECT b.id, b.player_id, b.amount, b.odds_multiplier, b.bet_on_team
                      FROM team_bets b
                     WHERE b.team_series_id = :sid AND b.settled_at IS NULL
                     ORDER BY b.player_id::text, b.id
                """), {"sid": series_uuid})).mappings().all()
                for b in unsettled:
                    won = (b["bet_on_team"] == winner_team)
                    payout = int(round(b["amount"] * b["odds_multiplier"])) if won else 0
                    # Claim-gated (Codex Jul-29 find 1): a janitor reconcile
                    # can terminal-ize this bet between the snapshot SELECT
                    # and here; an unconditional UPDATE would overwrite it and
                    # double-pay.
                    claimed = (await db.execute(text("""
                        UPDATE team_bets
                           SET settled_at = NOW(), payout = :p, settlement_kind = :k
                         WHERE id = :id AND settled_at IS NULL
                        RETURNING id
                    """), {"p": payout, "k": "won" if won else "lost",
                           "id": b["id"]})).scalar()
                    if claimed is None:
                        continue
                    if payout > 0:
                        # Credit the bettor's gold.
                        await db.execute(text("""
                            UPDATE players
                               SET gold_earned = COALESCE(gold_earned, 0) + :p
                             WHERE id = :pid
                        """), {"p": payout, "pid": b["player_id"]})
                        db.add(GoldTransaction(
                            player_id=b["player_id"], amount=payout,
                            reason="team_bet_payout", reference_id=str(series_uuid),
                        ))
                await db.flush()
        except Exception as bex:
            # Don't let bet settlement failures block the team-match write.
            print(f"[TEAM-BET-SETTLE] error settling for series {series_uuid}: {bex}")
        # Apply Glicko-2 updates. Each player's "rating period" = this series.
        # Their two opponents are the two players on the other team.
        team1_ps = [p_t1a, p_t1b]
        team2_ps = [p_t2a, p_t2b]
        team1_won = (winner_team == 1)
        # Snapshot current ratings before any update.
        gids = [p_t1a.id, p_t1b.id, p_t2a.id, p_t2b.id]
        # Canonical-order lock pass (learning #197 / review find): mirrors the
        # DC-helper — two completions can share players across different
        # series, and ANY(...) FOR UPDATE locks in planner order (ABBA edge).
        for _pid in sorted(gids, key=str):
            await db.execute(
                text("SELECT 1 FROM glicko_ratings_2v2 WHERE player_id = :pid FOR UPDATE"),
                {"pid": _pid},
            )
        gres = await db.execute(
            text("SELECT player_id, rating, rating_deviation, volatility, peak_rating, completed_series "
                 "FROM glicko_ratings_2v2 WHERE player_id = ANY(:ids)"),
            {"ids": gids},
        )
        existing = {r["player_id"]: dict(r) for r in gres.mappings().all()}
        # Default rows for first-timers.
        for pid in gids:
            if pid not in existing:
                existing[pid] = {
                    "player_id": pid,
                    "rating": GLICKO2_DEFAULT_RATING,
                    "rating_deviation": GLICKO2_DEFAULT_RD,
                    "volatility": GLICKO2_DEFAULT_VOLATILITY,
                    "peak_rating": GLICKO2_DEFAULT_RATING,
                    "completed_series": 0,
                    "_new": True,
                }
        # Compute new ratings using PRE-update opponent values.
        def update_player(p, opps_pre, won: bool):
            opps = [(o["rating"], o["rating_deviation"], 1.0 if won else 0.0) for o in opps_pre]
            return calculate_new_rating(
                p["rating"], p["rating_deviation"], p["volatility"], opps, GLICKO2_TAU,
            )
        # Snapshot inputs first so each player's update sees the pre-update opp values.
        inputs = {pid: existing[pid] for pid in gids}
        results: dict[str, tuple[float, float, float]] = {}
        for p in team1_ps:
            results[p.id] = update_player(
                inputs[p.id],
                [inputs[p_t2a.id], inputs[p_t2b.id]],
                team1_won,
            )
        for p in team2_ps:
            results[p.id] = update_player(
                inputs[p.id],
                [inputs[p_t1a.id], inputs[p_t1b.id]],
                not team1_won,
            )
        # Persist.
        for pid, (new_r, new_rd, new_vol) in results.items():
            existing_pre = inputs[pid]
            new_peak = max(existing_pre.get("peak_rating") or new_r, new_r)
            if existing_pre.get("_new"):
                db.add(GlickoRating2v2(
                    player_id=pid,
                    rating=new_r,
                    rating_deviation=new_rd,
                    volatility=new_vol,
                    peak_rating=new_peak,
                    games_in_period=0,
                    completed_series=1,
                    last_calculated=datetime.now(timezone.utc),
                ))
            else:
                await db.execute(
                    text("""UPDATE glicko_ratings_2v2
                           SET rating=:r, rating_deviation=:rd, volatility=:v,
                               peak_rating=GREATEST(COALESCE(peak_rating,:r), :r),
                               completed_series = completed_series + 1,
                               last_calculated=NOW(), updated_at=NOW()
                           WHERE player_id=:pid"""),
                    {"r": new_r, "rd": new_rd, "v": new_vol, "pid": pid},
                )
            new_ratings[str(pid)] = round(new_r, 1)
            # Rating achievements: crossed threshold in 2v2.
            await _grant_rating_achievements(db, pid, new_r)
        # Persist the per-player series Elo deltas in the team_series slot that
        # holds each player's player_id — NOT in the slot whose label happens to
        # match the report's t1a/t1b/t2a/t2b naming. The two can disagree
        # because the balancer assigns server-team1/team2 at lock time but
        # ROUNDS' in-game teamID (which the client uses to label t1a/t1b/t2a/t2b
        # in the report) is independent of that. Joining by player_id keeps the
        # team-matches history endpoint reading the correct rating_change for
        # each player no matter how the labels happen to align this game.
        delta_by_pid = {pid: round(results[pid][0] - inputs[pid]["rating"], 1) for pid in gids}
        slot_to_pid = {
            "t1a": series["t1a_id"], "t1b": series["t1b_id"],
            "t2a": series["t2a_id"], "t2b": series["t2b_id"],
        }
        await db.execute(
            text("""UPDATE team_series SET
                       t1a_rating_change = :t1a_d, t1b_rating_change = :t1b_d,
                       t2a_rating_change = :t2a_d, t2b_rating_change = :t2b_d
                   WHERE id = :sid"""),
            {
                "sid": series_uuid,
                "t1a_d": delta_by_pid[slot_to_pid["t1a"]],
                "t1b_d": delta_by_pid[slot_to_pid["t1b"]],
                "t2a_d": delta_by_pid[slot_to_pid["t2a"]],
                "t2b_d": delta_by_pid[slot_to_pid["t2b"]],
            },
        )

        # Series-completion gold: +50g winner, +25g loser, scaled by the
        # opposing team's tier (July 20 item 6 — the 50-vs-25 split already
        # encodes the "winning doubles" rule; uses the PRE-update team-average
        # ratings fetched for the per-game multiplier). Also folded into
        # the team_series per-slot gold accumulator so the F5 panel can
        # render "+Ng / +Nxp" beside each player.
        bonus_by_pid = {}
        # SAVEPOINT (learning #187): contains a mid-loop failure to this block —
        # without it, a failed statement aborts the whole transaction and the
        # match write above is lost too. flush() runs the ORM adds inside the
        # savepoint so a rollback actually discards them.
        try:
            async with db.begin_nested():
                # sorted(key=str(id)): canonical players-row lock order —
                # slot order differs per series (review find, ABBA edge).
                for p in sorted((p_t1a, p_t1b, p_t2a, p_t2b), key=lambda x: str(x.id)):
                    player_team = 1 if p.id in (p_t1a.id, p_t1b.id) else 2
                    won_series = (player_team == winner_team)
                    _s_mult, _ = _tier_mult_for(_t2_avg_rating if player_team == 1 else _t1_avg_rating)
                    bonus = int((TEAM_SERIES_WIN_GOLD if won_series else TEAM_SERIES_LOSS_GOLD) * _s_mult)
                    await db.execute(
                        text("UPDATE players SET gold_earned = COALESCE(gold_earned,0) + :g, "
                             "team_gold_earned = COALESCE(team_gold_earned,0) + :g WHERE id = :pid"),
                        {"g": bonus, "pid": p.id},
                    )
                    db.add(GoldTransaction(
                        player_id=p.id, amount=bonus,
                        reason=("team_series_win" if won_series else "team_series_loss"),
                        reference_id=str(series_uuid),
                    ))
                    bonus_by_pid[p.id] = bonus
                slot_pid = {
                    "t1a": series["t1a_id"], "t1b": series["t1b_id"],
                    "t2a": series["t2a_id"], "t2b": series["t2b_id"],
                }
                await db.execute(text(
                    "UPDATE team_series SET "
                    "t1a_gold_earned = COALESCE(t1a_gold_earned,0) + :t1a_g, "
                    "t1b_gold_earned = COALESCE(t1b_gold_earned,0) + :t1b_g, "
                    "t2a_gold_earned = COALESCE(t2a_gold_earned,0) + :t2a_g, "
                    "t2b_gold_earned = COALESCE(t2b_gold_earned,0) + :t2b_g "
                    "WHERE id = :sid"
                ), {
                    "sid": series_uuid,
                    "t1a_g": bonus_by_pid.get(slot_pid["t1a"], 0),
                    "t1b_g": bonus_by_pid.get(slot_pid["t1b"], 0),
                    "t2a_g": bonus_by_pid.get(slot_pid["t2a"], 0),
                    "t2b_g": bonus_by_pid.get(slot_pid["t2b"], 0),
                })
                await db.flush()
        except Exception as gex:
            print(f"[TEAM-ECON] series-bonus gold failed for {series_uuid}: {gex}")

        # Free the queue rows so all 4 can re-queue.
        await _lock_queue_rows_ordered(
            db, "team_queue",
            [p_t1a.id, p_t1b.id, p_t2a.id, p_t2b.id],
        )
        await db.execute(
            text("DELETE FROM team_queue WHERE series_id = :sid"),
            {"sid": series_uuid},
        )
    else:
        # Mid-series advance.
        await db.execute(
            text("""UPDATE team_series SET t1_series_wins = :t1, t2_series_wins = :t2 WHERE id = :sid"""),
            {"t1": new_t1w, "t2": new_t2w, "sid": report.series_id},
        )

        # ── Auto-balance between matches in an auto-balanced series ──
        # When the previous match was lopsided (point margin >= AUTO_BALANCE_SWAP_MARGIN)
        # AND the series was originally auto-balanced (not a manual pick lobby),
        # swap the weakest winner with the strongest loser so the next match
        # plays with reshuffled teams. The rebalance only applies to the NEXT
        # match — the client gets a `rebalance_assignments` payload on the
        # response and updates each player's TeamID before round 1 starts.
        # SAVEPOINT (learning #187): this block writes team_series AND
        # team_queue — a failure between the two used to be swallowed with the
        # slot rewrite already applied (queue rows never updated, clients never
        # told), and worse, the failed statement aborted the whole transaction
        # so the match write died too. begin_nested makes the block atomic:
        # both writes land or neither does, and rebalance_assignments only
        # survives when they landed.
        try:
            async with db.begin_nested():
                was_auto = bool(series["was_auto_balanced"]) if "was_auto_balanced" in series else True
                margin = abs(int(report.t1_points_total or 0) - int(report.t2_points_total or 0))
                if was_auto and margin >= AUTO_BALANCE_SWAP_MARGIN:
                    # Pull each player's current effective rating (2v2 if trusted, else 1v1 fallback).
                    pids = [p_t1a.id, p_t1b.id, p_t2a.id, p_t2b.id]
                    rate_q = await db.execute(
                        text("""
                            SELECT p.id AS pid,
                                   COALESCE(g2.rating, 1500.0) AS r2,
                                   COALESCE(g2.rating_deviation, 350.0) AS rd2,
                                   COALESCE(g2.completed_series, 0) AS cs,
                                   COALESCE(g1.rating, 1500.0) AS r1
                              FROM players p
                              LEFT JOIN glicko_ratings_2v2 g2 ON g2.player_id = p.id
                              LEFT JOIN glicko_ratings    g1 ON g1.player_id = p.id
                             WHERE p.id = ANY(:ids)
                        """),
                        {"ids": pids},
                    )
                    rate_by_pid = {r["pid"]: _team_balance_rating(
                        float(r["r2"]), int(r["cs"]), float(r["r1"]), float(r["rd2"])
                    ) for r in rate_q.mappings().all()}

                    winner_team_match = report.winner_team
                    if winner_team_match == 1:
                        winners = [(p_t1a.id, rate_by_pid.get(p_t1a.id, 1500.0)),
                                   (p_t1b.id, rate_by_pid.get(p_t1b.id, 1500.0))]
                        losers  = [(p_t2a.id, rate_by_pid.get(p_t2a.id, 1500.0)),
                                   (p_t2b.id, rate_by_pid.get(p_t2b.id, 1500.0))]
                    else:
                        winners = [(p_t2a.id, rate_by_pid.get(p_t2a.id, 1500.0)),
                                   (p_t2b.id, rate_by_pid.get(p_t2b.id, 1500.0))]
                        losers  = [(p_t1a.id, rate_by_pid.get(p_t1a.id, 1500.0)),
                                   (p_t1b.id, rate_by_pid.get(p_t1b.id, 1500.0))]
                    # Weakest winner + strongest loser swap.
                    weakest_winner = min(winners, key=lambda t: t[1])[0]
                    strongest_loser = max(losers, key=lambda t: t[1])[0]

                    # Build the new (post-swap) team rosters.
                    t1_ids = [p_t1a.id, p_t1b.id]
                    t2_ids = [p_t2a.id, p_t2b.id]
                    new_t1 = [pid for pid in t1_ids if pid != weakest_winner and pid != strongest_loser]
                    new_t2 = [pid for pid in t2_ids if pid != weakest_winner and pid != strongest_loser]
                    if winner_team_match == 1:
                        # weakest_winner was on t1, strongest_loser was on t2 → swap them.
                        new_t1.append(strongest_loser); new_t2.append(weakest_winner)
                    else:
                        new_t2.append(strongest_loser); new_t1.append(weakest_winner)

                    # Canonicalize within-team order by steam_id (matches lock-time sort).
                    pid_to_steam = {
                        p_t1a.id: p_t1a.steam_id, p_t1b.id: p_t1b.steam_id,
                        p_t2a.id: p_t2a.steam_id, p_t2b.id: p_t2b.steam_id,
                    }
                    new_t1.sort(key=lambda pid: pid_to_steam[pid])
                    new_t2.sort(key=lambda pid: pid_to_steam[pid])

                    # Persist new slot order on team_series.
                    await db.execute(
                        text("""UPDATE team_series
                                  SET t1a_id = :t1a, t1b_id = :t1b,
                                      t2a_id = :t2a, t2b_id = :t2b,
                                      rebalance_count = COALESCE(rebalance_count, 0) + 1
                                WHERE id = :sid"""),
                        {"t1a": new_t1[0], "t1b": new_t1[1],
                         "t2a": new_t2[0], "t2b": new_t2[1],
                         "sid": series_uuid},
                    )
                    # Update queue rows so /poll reflects the new team_assigned.
                    await _lock_queue_rows_ordered(
                        db, "team_queue",
                        [p_t1a.id, p_t1b.id, p_t2a.id, p_t2b.id],
                    )
                    await db.execute(
                        text("""UPDATE team_queue
                                  SET team_assigned = CASE
                                                        WHEN player_id = ANY(:t1) THEN 1
                                                        ELSE 2
                                                      END
                                WHERE series_id = :sid"""),
                        {"t1": new_t1, "sid": series_uuid},
                    )

                    # Build rebalance_assignments keyed by Steam ID (the client
                    # uses the Steam ID it knows for each peer to look up the new
                    # team and update its local Player.TeamID + spawn / body color).
                    steam_to_pid = {v: k for k, v in pid_to_steam.items()}
                    rebalance_assignments = {}
                    for pid in new_t1:
                        rebalance_assignments[pid_to_steam[pid]] = 1
                    for pid in new_t2:
                        rebalance_assignments[pid_to_steam[pid]] = 2
                    print(f"[TEAM-REBALANCE] series={series_uuid} margin={margin} swapped: "
                          f"weakest_winner={pid_to_steam[weakest_winner]} ↔ strongest_loser={pid_to_steam[strongest_loser]}")
        except Exception as rex:
            rebalance_assignments = None
            print(f"[TEAM-REBALANCE] error: {rex}")

    await db.commit()

    # Build response: series_score from the reporter's team perspective.
    reporter_team = 1 if reporter.id in (p_t1a.id, p_t1b.id) else 2
    if reporter_team == 1:
        score_str = f"{new_t1w}-{new_t2w}"
    else:
        score_str = f"{new_t2w}-{new_t1w}"

    return TeamMatchResponse(
        match_id=new_match.id,
        series_id=series_uuid,
        series_status=series_status,
        series_score=score_str,
        winner_team=(winner_team or report.winner_team),
        rebalance_assignments=rebalance_assignments,
        new_t1a_rating=new_ratings.get(str(p_t1a.id)),
        new_t1b_rating=new_ratings.get(str(p_t1b.id)),
        new_t2a_rating=new_ratings.get(str(p_t2a.id)),
        new_t2b_rating=new_ratings.get(str(p_t2b.id)),
    )


@app.get("/api/v1/team/players/{steam_id}/team-stats", response_model=TeamStatsResponse, tags=["Team Matches"])
async def get_player_team_stats(steam_id: str, db: AsyncSession = Depends(get_db)):
    """Per-player 2v2 stats — drives the My Stats tab 2v2 row + 2v2 leaderboard
    detail panel. Includes current series-level streak (positive=W streak,
    negative=L streak) by walking completed series in time order."""
    result = await db.execute(select(Player).where(Player.steam_id == steam_id))
    player = result.scalar_one_or_none()
    if not player:
        raise HTTPException(404, "Player not found")
    g_q = await db.execute(select(GlickoRating2v2).where(GlickoRating2v2.player_id == player.id))
    g = g_q.scalar_one_or_none()
    rating = g.rating if g else GLICKO2_DEFAULT_RATING
    rd = g.rating_deviation if g else GLICKO2_DEFAULT_RD
    peak = g.peak_rating if (g and g.peak_rating) else rating
    completed_series = g.completed_series if g else 0

    # Series wins/losses — UNION across all 4 slots.
    sw_q = await db.execute(
        text("""
            SELECT
                SUM(CASE WHEN s.winner_team = 1 AND :pid IN (s.t1a_id, s.t1b_id) THEN 1
                         WHEN s.winner_team = 2 AND :pid IN (s.t2a_id, s.t2b_id) THEN 1
                         ELSE 0 END) AS wins,
                SUM(CASE WHEN s.winner_team = 1 AND :pid IN (s.t2a_id, s.t2b_id) THEN 1
                         WHEN s.winner_team = 2 AND :pid IN (s.t1a_id, s.t1b_id) THEN 1
                         ELSE 0 END) AS losses
            FROM team_series s
            WHERE s.status = 'completed'
              AND :pid IN (s.t1a_id, s.t1b_id, s.t2a_id, s.t2b_id)
        """),
        {"pid": player.id},
    )
    sw_row = sw_q.mappings().first()
    series_wins = int(sw_row["wins"] or 0)
    series_losses = int(sw_row["losses"] or 0)

    # Match wins/losses inside team_matches.
    mw_q = await db.execute(
        text("""
            SELECT
                SUM(CASE WHEN m.winner_team = 1 AND :pid IN (m.t1a_id, m.t1b_id) THEN 1
                         WHEN m.winner_team = 2 AND :pid IN (m.t2a_id, m.t2b_id) THEN 1
                         ELSE 0 END) AS wins,
                SUM(CASE WHEN m.winner_team = 1 AND :pid IN (m.t2a_id, m.t2b_id) THEN 1
                         WHEN m.winner_team = 2 AND :pid IN (m.t1a_id, m.t1b_id) THEN 1
                         ELSE 0 END) AS losses
            FROM team_matches m
            WHERE m.invalidated_at IS NULL
              AND :pid IN (m.t1a_id, m.t1b_id, m.t2a_id, m.t2b_id)
        """),
        {"pid": player.id},
    )
    mw_row = mw_q.mappings().first()
    match_wins = int(mw_row["wins"] or 0)
    match_losses = int(mw_row["losses"] or 0)

    # Series streak — walk completed series newest first, count consecutive same-result.
    # No LIMIT: the loop breaks at the first opposite result, so it only walks the actual
    # streak. A prior LIMIT 50 silently capped the 2v2 streak at 50 (same class as #17).
    streak_q = await db.execute(
        text("""
            SELECT s.winner_team,
                   CASE WHEN :pid IN (s.t1a_id, s.t1b_id) THEN 1 ELSE 2 END AS my_team
            FROM team_series s
            WHERE s.status = 'completed'
              AND :pid IN (s.t1a_id, s.t1b_id, s.t2a_id, s.t2b_id)
            ORDER BY s.completed_at DESC
        """),
        {"pid": player.id},
    )
    rows = streak_q.mappings().all()
    streak = 0
    last_was_win = None
    for r in rows:
        won = (r["winner_team"] == r["my_team"])
        if last_was_win is None:
            last_was_win = won
            streak = 1 if won else -1
        elif won == last_was_win:
            streak = streak + 1 if won else streak - 1
        else:
            break

    total_series = series_wins + series_losses
    return TeamStatsResponse(
        steam_id=steam_id,
        display_name=player.display_name,
        rating=round(rating, 1),
        rating_deviation=round(rd, 1),
        peak_rating=round(peak, 1),
        completed_series=completed_series,
        series_wins=series_wins,
        series_losses=series_losses,
        series_win_rate=round(series_wins / total_series, 4) if total_series > 0 else 0.0,
        match_wins=match_wins,
        match_losses=match_losses,
        current_streak=streak,
    )


@app.get("/api/v1/team/players/{steam_id}/team-matches", response_model=list[TeamMatchHistoryEntry], tags=["Team Matches"])
async def get_player_team_matches(
    steam_id: str,
    limit: int = Query(50, ge=1, le=500),
    db: AsyncSession = Depends(get_db),
):
    """Recent 2v2 matches played by a given player. Used by the F5 2v2 tab
    history list. Renders the 4 names + win/loss + series score + per-player
    cards + FPS averages."""
    result = await db.execute(select(Player).where(Player.steam_id == steam_id))
    player = result.scalar_one_or_none()
    if not player:
        raise HTTPException(404, "Player not found")

    q = text("""
        SELECT
            tm.id AS match_id, tm.ended_at, tm.winner_team, tm.series_id,
            tm.t1_rounds_won, tm.t2_rounds_won,
            tm.t1_points_total, tm.t2_points_total,
            tm.t1a_id, tm.t1b_id, tm.t2a_id, tm.t2b_id,
            tm.t1a_fps_avg, tm.t1b_fps_avg, tm.t2a_fps_avg, tm.t2b_fps_avg,
            p1a.steam_id AS t1a_sid, p1a.display_name AS t1a_name,
            p1b.steam_id AS t1b_sid, p1b.display_name AS t1b_name,
            p2a.steam_id AS t2a_sid, p2a.display_name AS t2a_name,
            p2b.steam_id AS t2b_sid, p2b.display_name AS t2b_name,
            ts.t1_series_wins, ts.t2_series_wins, ts.winner_team AS series_winner_team,
            ts.t1a_id AS s_t1a, ts.t1b_id AS s_t1b,
            CASE
                WHEN :pid IN (ts.t1a_id, ts.t1b_id) THEN
                    CASE WHEN ts.t1a_id = :pid THEN ts.t1a_rating_change ELSE ts.t1b_rating_change END
                ELSE
                    CASE WHEN ts.t2a_id = :pid THEN ts.t2a_rating_change ELSE ts.t2b_rating_change END
            END AS rating_change
        FROM team_matches tm
        JOIN players p1a ON p1a.id = tm.t1a_id
        JOIN players p1b ON p1b.id = tm.t1b_id
        JOIN players p2a ON p2a.id = tm.t2a_id
        JOIN players p2b ON p2b.id = tm.t2b_id
        LEFT JOIN team_series ts ON ts.id = tm.series_id
        WHERE :pid IN (tm.t1a_id, tm.t1b_id, tm.t2a_id, tm.t2b_id)
          AND tm.invalidated_at IS NULL
        ORDER BY tm.ended_at DESC
        LIMIT :lim
    """)
    rows = (await db.execute(q, {"pid": player.id, "lim": limit})).mappings().all()

    entries: list[TeamMatchHistoryEntry] = []
    for r in rows:
        my_team = 1 if player.id in (r["t1a_id"], r["t1b_id"]) else 2
        won = (r["winner_team"] == my_team)
        # Card picks per (match_id, player_id)
        cards_q = await db.execute(
            text("""SELECT player_id, card_name, card_rarity, pick_order, round_number
                   FROM team_match_cards
                   WHERE match_id = :mid
                   ORDER BY player_id, round_number, pick_order"""),
            {"mid": r["match_id"]},
        )
        cards_by_player: dict[str, list] = {}
        for c in cards_q.mappings().all():
            pid_str = str(c["player_id"])
            cards_by_player.setdefault(pid_str, []).append({
                "card_name": c["card_name"], "card_rarity": c["card_rarity"],
                "pick_order": c["pick_order"], "round_number": c["round_number"],
            })
        # Re-key by Steam ID for the response (client doesn't know UUIDs).
        pid_to_sid = {
            str(r["t1a_id"]): r["t1a_sid"], str(r["t1b_id"]): r["t1b_sid"],
            str(r["t2a_id"]): r["t2a_sid"], str(r["t2b_id"]): r["t2b_sid"],
        }
        cards_by_steam: dict[str, list] = {}
        for pid_str, lst in cards_by_player.items():
            sid_for = pid_to_sid.get(pid_str)
            if sid_for:
                cards_by_steam[sid_for] = lst

        fps_by_steam: dict[str, int] = {}
        if r["t1a_fps_avg"]: fps_by_steam[r["t1a_sid"]] = int(r["t1a_fps_avg"])
        if r["t1b_fps_avg"]: fps_by_steam[r["t1b_sid"]] = int(r["t1b_fps_avg"])
        if r["t2a_fps_avg"]: fps_by_steam[r["t2a_sid"]] = int(r["t2a_fps_avg"])
        if r["t2b_fps_avg"]: fps_by_steam[r["t2b_sid"]] = int(r["t2b_fps_avg"])

        # Series score from caller's team perspective.
        series_score = None
        if r["series_id"] is not None and r["t1_series_wins"] is not None:
            t1w, t2w = r["t1_series_wins"] or 0, r["t2_series_wins"] or 0
            # Determine which team the caller was on FOR THIS SERIES (the series
            # uses balancer-time assignments; team_assigned in the match row may
            # have been rebalanced — we don't rebalance yet so they're identical
            # but keeping the logic explicit so future Phase 3 changes don't break it).
            in_series_team1 = player.id in (r["s_t1a"], r["s_t1b"])
            if in_series_team1:
                series_score = f"{t1w}-{t2w}"
            else:
                series_score = f"{t2w}-{t1w}"

        rating_change = None
        if r["rating_change"] is not None:
            rating_change = float(r["rating_change"])

        entries.append(TeamMatchHistoryEntry(
            match_id=r["match_id"],
            series_id=str(r["series_id"]) if r["series_id"] else "",
            ended_at=r["ended_at"],
            won=won,
            my_team=my_team,
            t1a_steam_id=r["t1a_sid"], t1a_name=r["t1a_name"],
            t1b_steam_id=r["t1b_sid"], t1b_name=r["t1b_name"],
            t2a_steam_id=r["t2a_sid"], t2a_name=r["t2a_name"],
            t2b_steam_id=r["t2b_sid"], t2b_name=r["t2b_name"],
            t1_rounds_won=r["t1_rounds_won"],
            t2_rounds_won=r["t2_rounds_won"],
            t1_points_total=r["t1_points_total"] or 0,
            t2_points_total=r["t2_points_total"] or 0,
            cards_by_player=cards_by_steam,
            series_score=series_score,
            series_rating_change=rating_change,
            fps_by_player=fps_by_steam,
        ))
    return entries


@app.get("/api/v1/team/series/recent", tags=["Team Matches"])
async def team_series_recent(minutes: int = Query(5, ge=1, le=60), db: AsyncSession = Depends(get_db)):
    """Series completed in the last N minutes — drives the Discord 2v2 announcement.
    Returns names + ratings + Elo changes per player so the bot can render the embed
    without further fetches."""
    q = text("""
        SELECT
            s.id AS series_id,
            s.completed_at,
            s.t1_series_wins, s.t2_series_wins, s.winner_team,
            s.t1a_rating_change, s.t1b_rating_change, s.t2a_rating_change, s.t2b_rating_change,
            p1a.steam_id AS t1a_sid, p1a.display_name AS t1a_name, p1a.discord_id AS t1a_did,
            p1b.steam_id AS t1b_sid, p1b.display_name AS t1b_name, p1b.discord_id AS t1b_did,
            p2a.steam_id AS t2a_sid, p2a.display_name AS t2a_name, p2a.discord_id AS t2a_did,
            p2b.steam_id AS t2b_sid, p2b.display_name AS t2b_name, p2b.discord_id AS t2b_did,
            g1a.rating AS t1a_rating, g1b.rating AS t1b_rating,
            g2a.rating AS t2a_rating, g2b.rating AS t2b_rating
        FROM team_series s
        JOIN players p1a ON p1a.id = s.t1a_id
        JOIN players p1b ON p1b.id = s.t1b_id
        JOIN players p2a ON p2a.id = s.t2a_id
        JOIN players p2b ON p2b.id = s.t2b_id
        LEFT JOIN glicko_ratings_2v2 g1a ON g1a.player_id = s.t1a_id
        LEFT JOIN glicko_ratings_2v2 g1b ON g1b.player_id = s.t1b_id
        LEFT JOIN glicko_ratings_2v2 g2a ON g2a.player_id = s.t2a_id
        LEFT JOIN glicko_ratings_2v2 g2b ON g2b.player_id = s.t2b_id
        WHERE s.status = 'completed'
          AND s.completed_at > NOW() - INTERVAL '1 minute' * :mins
        ORDER BY s.completed_at DESC
    """)
    rows = (await db.execute(q, {"mins": minutes})).mappings().all()
    return {"series": [
        {
            "series_id": str(r["series_id"]),
            "completed_at": r["completed_at"].isoformat() if r["completed_at"] else None,
            "winner_team": r["winner_team"],
            "t1_series_wins": r["t1_series_wins"], "t2_series_wins": r["t2_series_wins"],
            "t1a": {"steam_id": r["t1a_sid"], "name": r["t1a_name"], "discord_id": r["t1a_did"],
                    "rating": float(r["t1a_rating"]) if r["t1a_rating"] is not None else 1500.0,
                    "rating_change": float(r["t1a_rating_change"] or 0)},
            "t1b": {"steam_id": r["t1b_sid"], "name": r["t1b_name"], "discord_id": r["t1b_did"],
                    "rating": float(r["t1b_rating"]) if r["t1b_rating"] is not None else 1500.0,
                    "rating_change": float(r["t1b_rating_change"] or 0)},
            "t2a": {"steam_id": r["t2a_sid"], "name": r["t2a_name"], "discord_id": r["t2a_did"],
                    "rating": float(r["t2a_rating"]) if r["t2a_rating"] is not None else 1500.0,
                    "rating_change": float(r["t2a_rating_change"] or 0)},
            "t2b": {"steam_id": r["t2b_sid"], "name": r["t2b_name"], "discord_id": r["t2b_did"],
                    "rating": float(r["t2b_rating"]) if r["t2b_rating"] is not None else 1500.0,
                    "rating_change": float(r["t2b_rating_change"] or 0)},
        }
        for r in rows
    ]}


@app.get("/api/v1/team/all-series-paged", tags=["Team Matches"])
async def team_all_series_paged(
    page: int = Query(0, ge=0),
    page_size: int = Query(3, ge=1, le=20),
    db: AsyncSession = Depends(get_db),
):
    """Paginated feed of every completed 2v2 series. Drives the F5 'Recent 2v2
    Series' panel. Each series includes per-slot ratings + rating deltas +
    titles + per-slot gold/XP earned in this series, plus the matches array
    with per-player card picks. Replaces the per-player /team-matches feed
    so non-participants can also browse the global series history."""
    total_q = await db.execute(text("SELECT COUNT(*) FROM team_series WHERE status='completed'"))
    total = total_q.scalar() or 0

    series_q = text("""
        SELECT s.id AS series_id, s.completed_at, s.created_at,
               s.t1_series_wins, s.t2_series_wins, s.winner_team,
               s.t1a_id, s.t1b_id, s.t2a_id, s.t2b_id,
               s.t1a_rating_change, s.t1b_rating_change, s.t2a_rating_change, s.t2b_rating_change,
               s.t1a_gold_earned, s.t1b_gold_earned, s.t2a_gold_earned, s.t2b_gold_earned,
               s.t1a_xp_earned,   s.t1b_xp_earned,   s.t2a_xp_earned,   s.t2b_xp_earned,
               p1a.steam_id AS t1a_sid, p1a.display_name AS t1a_name, ti1a.name AS t1a_title, ti1a.preview_color AS t1a_title_color,
               p1b.steam_id AS t1b_sid, p1b.display_name AS t1b_name, ti1b.name AS t1b_title, ti1b.preview_color AS t1b_title_color,
               p2a.steam_id AS t2a_sid, p2a.display_name AS t2a_name, ti2a.name AS t2a_title, ti2a.preview_color AS t2a_title_color,
               p2b.steam_id AS t2b_sid, p2b.display_name AS t2b_name, ti2b.name AS t2b_title, ti2b.preview_color AS t2b_title_color,
               ti1a.sku AS t1a_title_sku, ti1b.sku AS t1b_title_sku,
               ti2a.sku AS t2a_title_sku, ti2b.sku AS t2b_title_sku,
               g1a.rating AS t1a_rating, g1b.rating AS t1b_rating,
               g2a.rating AS t2a_rating, g2b.rating AS t2b_rating,
               -- 1v1 ratings feed the dynamic 'Current Rank' title (#48) —
               -- rank tiers are defined on the 1v1 ladder, not the 2v2 one.
               v1a.rating AS t1a_rating_1v1, v1b.rating AS t1b_rating_1v1,
               v2a.rating AS t2a_rating_1v1, v2b.rating AS t2b_rating_1v1
          FROM team_series s
          JOIN players p1a ON p1a.id = s.t1a_id
          JOIN players p1b ON p1b.id = s.t1b_id
          JOIN players p2a ON p2a.id = s.t2a_id
          JOIN players p2b ON p2b.id = s.t2b_id
          LEFT JOIN shop_items ti1a ON ti1a.id = p1a.active_title_id
          LEFT JOIN shop_items ti1b ON ti1b.id = p1b.active_title_id
          LEFT JOIN shop_items ti2a ON ti2a.id = p2a.active_title_id
          LEFT JOIN shop_items ti2b ON ti2b.id = p2b.active_title_id
          LEFT JOIN glicko_ratings_2v2 g1a ON g1a.player_id = s.t1a_id
          LEFT JOIN glicko_ratings_2v2 g1b ON g1b.player_id = s.t1b_id
          LEFT JOIN glicko_ratings_2v2 g2a ON g2a.player_id = s.t2a_id
          LEFT JOIN glicko_ratings_2v2 g2b ON g2b.player_id = s.t2b_id
          LEFT JOIN glicko_ratings v1a ON v1a.player_id = s.t1a_id
          LEFT JOIN glicko_ratings v1b ON v1b.player_id = s.t1b_id
          LEFT JOIN glicko_ratings v2a ON v2a.player_id = s.t2a_id
          LEFT JOIN glicko_ratings v2b ON v2b.player_id = s.t2b_id
         WHERE s.status = 'completed'
         ORDER BY s.completed_at DESC
         LIMIT :lim OFFSET :off
    """)
    rows = (await db.execute(series_q, {"lim": page_size, "off": page * page_size})).mappings().all()

    _colors = await _rank_colors(db)
    # Podium map only when some slot wears the dynamic podium title.
    _pmap = await _podium_map(db) if any(
        r[f"{pfx}_title_sku"] == TITLE_PODIUM_SKU
        for r in rows for pfx in ("t1a", "t1b", "t2a", "t2b")) else {}
    out_series = []
    for r in rows:
        # Per-series matches.
        m_q = text("""
            SELECT id AS match_id, ended_at, t1_rounds_won, t2_rounds_won,
                   t1_points_total, t2_points_total, duration_seconds,
                   t1a_fps_avg, t1b_fps_avg, t2a_fps_avg, t2b_fps_avg,
                   t1a_id, t1b_id, t2a_id, t2b_id
              FROM team_matches
             WHERE series_id = :sid AND invalidated_at IS NULL
             ORDER BY ended_at ASC
        """)
        m_rows = (await db.execute(m_q, {"sid": r["series_id"]})).mappings().all()
        matches = []
        # Per-(match, player) cards + telemetry lookups.
        match_ids = [m["match_id"] for m in m_rows]
        pid_to_sid = {
            str(r["t1a_id"]): r["t1a_sid"], str(r["t1b_id"]): r["t1b_sid"],
            str(r["t2a_id"]): r["t2a_sid"], str(r["t2b_id"]): r["t2b_sid"],
        }
        cards_by_match: dict = {}
        tele_by_match: dict = {}
        if match_ids:
            c_q = text("""
                SELECT match_id, player_id, card_name, pick_order, round_number
                  FROM team_match_cards
                 WHERE match_id = ANY(:mids)
                 ORDER BY match_id, player_id, round_number, pick_order
            """)
            c_rows = (await db.execute(c_q, {"mids": match_ids})).mappings().all()
            for c in c_rows:
                mid_key = str(c["match_id"])
                sid_for = pid_to_sid.get(str(c["player_id"]))
                if not sid_for: continue
                cards_by_match.setdefault(mid_key, {}).setdefault(sid_for, []).append(c["card_name"])
            # July 22 (migration 142): per-player telemetry for the game-row
            # stats line + hover graphs on the 2v2 tab.
            t_rows = (await db.execute(text("""
                SELECT match_id, player_id, fps_timeline, ping_timeline, ping_avg,
                       hit_timeline, block_timeline, bullets_fired, bullets_hit,
                       blocks_activated, blocks_successful
                  FROM team_match_telemetry
                 WHERE match_id = ANY(:mids)
            """), {"mids": match_ids})).mappings().all()
            for t in t_rows:
                sid_for = pid_to_sid.get(str(t["player_id"]))
                if not sid_for: continue
                tele_by_match.setdefault(str(t["match_id"]), {})[sid_for] = {
                    "fps_timeline": t["fps_timeline"],
                    "ping_timeline": t["ping_timeline"],
                    "ping_avg": t["ping_avg"] or 0,
                    "hit_timeline": t["hit_timeline"],
                    "block_timeline": t["block_timeline"],
                    "bullets_fired": t["bullets_fired"] or 0,
                    "bullets_hit": t["bullets_hit"] or 0,
                    "blocks_activated": t["blocks_activated"] or 0,
                    "blocks_successful": t["blocks_successful"] or 0,
                }
        for m in m_rows:
            # Review [5]: key FPS by the MATCH row's own slot ids (mid-series
            # auto-balance and slot realigns make series-row slots diverge from
            # match-row slots — series-keyed FPS cross-attributes swapped
            # players). pid_to_sid covers the same 4-player set.
            fps_by_player = {}
            for pfx in ("t1a", "t1b", "t2a", "t2b"):
                if m[f"{pfx}_fps_avg"]:
                    sid_for = pid_to_sid.get(str(m[f"{pfx}_id"]))
                    if sid_for:
                        fps_by_player[sid_for] = int(m[f"{pfx}_fps_avg"])
            matches.append({
                "match_id": str(m["match_id"]),
                "ended_at": m["ended_at"].isoformat() if m["ended_at"] else None,
                "t1_rounds_won": m["t1_rounds_won"], "t2_rounds_won": m["t2_rounds_won"],
                "t1_points_total": m["t1_points_total"] or 0, "t2_points_total": m["t2_points_total"] or 0,
                "duration_seconds": m["duration_seconds"] or 0,
                "fps_by_player": fps_by_player,
                "cards_by_player": cards_by_match.get(str(m["match_id"]), {}),
                "telemetry_by_player": tele_by_match.get(str(m["match_id"]), {}),
            })

        def slot(prefix):
            # Dynamic 'Current Rank' title resolves against the 1v1 rating (#48).
            _t, _tc = _display_title_sync(
                _colors, r[f"{prefix}_title_sku"], r[f"{prefix}_title"], r[f"{prefix}_title_color"],
                float(r[f"{prefix}_rating_1v1"]) if r[f"{prefix}_rating_1v1"] is not None else None,
                podium_pos=_pmap.get(str(r[f"{prefix}_id"])))
            return {
                "steam_id": r[f"{prefix}_sid"], "name": r[f"{prefix}_name"],
                "title": _t, "title_color": _tc,
                "rating": float(r[f"{prefix}_rating"]) if r[f"{prefix}_rating"] is not None else 1500.0,
                "rating_change": float(r[f"{prefix}_rating_change"] or 0),
                "gold_earned": int(r[f"{prefix}_gold_earned"] or 0),
                "xp_earned":   int(r[f"{prefix}_xp_earned"] or 0),
            }
        out_series.append({
            "series_id": str(r["series_id"]),
            "completed_at": r["completed_at"].isoformat() if r["completed_at"] else None,
            "winner_team": r["winner_team"],
            "t1_series_wins": r["t1_series_wins"], "t2_series_wins": r["t2_series_wins"],
            "t1a": slot("t1a"), "t1b": slot("t1b"),
            "t2a": slot("t2a"), "t2b": slot("t2b"),
            "matches": matches,
        })

    return {
        "series": out_series,
        "page": page, "page_size": page_size, "total": total,
        "total_pages": (total + page_size - 1) // page_size if total else 0,
    }


@app.get("/api/v1/team/leaderboard", response_model=Team2v2LeaderboardResponse, tags=["Team Matches"])
async def team_leaderboard(
    limit: int = Query(200, ge=1, le=500),
    min_series: int = Query(1, ge=0),
    sort_by: str = Query("rating"),
    db: AsyncSession = Depends(get_db),
):
    """Top players by 2v2 Glicko rating. Includes title, avg teammate elo,
    total 2v2 gold + XP earned. sort_by accepts: rating, wins, win_rate,
    avg_teammate_elo, team_gold_earned, team_xp_earned."""
    sort_map = {
        "rating": "g2.rating DESC",
        "wins": "wins DESC",
        "win_rate": "win_rate DESC",
        "avg_teammate_elo": "avg_teammate_elo DESC",
        "team_gold_earned": "team_gold_earned DESC",
        "team_xp_earned": "team_xp_earned DESC",
    }
    order_clause = sort_map.get(sort_by, "g2.rating DESC")

    # avg_teammate_elo: pull the OTHER member's 2v2 rating across all completed
    # series this player was in (or 1v1 fallback if their teammate is provisional),
    # then average. Self-reference filtered so own rating doesn't pollute.
    q = text(f"""
        WITH series_stats AS (
            SELECT player_id, SUM(won) AS wins, SUM(lost) AS losses, COUNT(*) AS total
            FROM (
                SELECT t1a_id AS player_id,
                       CASE WHEN winner_team = 1 THEN 1 ELSE 0 END AS won,
                       CASE WHEN winner_team = 2 THEN 1 ELSE 0 END AS lost
                FROM team_series WHERE status='completed'
                UNION ALL
                SELECT t1b_id, CASE WHEN winner_team = 1 THEN 1 ELSE 0 END,
                       CASE WHEN winner_team = 2 THEN 1 ELSE 0 END
                FROM team_series WHERE status='completed'
                UNION ALL
                SELECT t2a_id, CASE WHEN winner_team = 2 THEN 1 ELSE 0 END,
                       CASE WHEN winner_team = 1 THEN 1 ELSE 0 END
                FROM team_series WHERE status='completed'
                UNION ALL
                SELECT t2b_id, CASE WHEN winner_team = 2 THEN 1 ELSE 0 END,
                       CASE WHEN winner_team = 1 THEN 1 ELSE 0 END
                FROM team_series WHERE status='completed'
            ) sub
            GROUP BY player_id
        ),
        teammate_pairs AS (
            SELECT t1a_id AS player_id, t1b_id AS teammate_id
              FROM team_series WHERE status='completed'
            UNION ALL
            SELECT t1b_id, t1a_id FROM team_series WHERE status='completed'
            UNION ALL
            SELECT t2a_id, t2b_id FROM team_series WHERE status='completed'
            UNION ALL
            SELECT t2b_id, t2a_id FROM team_series WHERE status='completed'
        ),
        teammate_elo AS (
            SELECT tp.player_id, ROUND(AVG(COALESCE(g2t.rating, gt1.rating, 1500))::numeric, 0) AS avg_teammate_elo
              FROM teammate_pairs tp
              LEFT JOIN glicko_ratings_2v2 g2t ON g2t.player_id = tp.teammate_id AND g2t.completed_series >= 5
              LEFT JOIN glicko_ratings    gt1 ON gt1.player_id = tp.teammate_id
             GROUP BY tp.player_id
        )
        SELECT
            p.id::text AS player_id,
            p.steam_id,
            p.display_name,
            ROUND(g2.rating::numeric, 0) AS rating,
            ROUND(g2.rating_deviation::numeric, 0) AS rd,
            g2.completed_series,
            COALESCE(ss.wins, 0) AS wins,
            COALESCE(ss.losses, 0) AS losses,
            CASE WHEN COALESCE(ss.total, 0) > 0
                 THEN ROUND(COALESCE(ss.wins, 0)::numeric / ss.total, 4)
                 ELSE 0 END AS win_rate,
            COALESCE(p.total_xp, 0) AS total_xp,
            COALESCE(p.team_gold_earned, 0) AS team_gold_earned,
            COALESCE(p.team_xp_earned,   0) AS team_xp_earned,
            COALESCE(te.avg_teammate_elo, 0) AS avg_teammate_elo,
            si.name AS title,
            si.preview_color AS title_color,
            si.sku AS title_sku,
            g1.rating AS rating_1v1
        FROM glicko_ratings_2v2 g2
        JOIN players p ON p.id = g2.player_id
        LEFT JOIN series_stats ss ON ss.player_id = p.id
        LEFT JOIN teammate_elo te  ON te.player_id = p.id
        LEFT JOIN shop_items si    ON si.id = p.active_title_id
        LEFT JOIN glicko_ratings g1 ON g1.player_id = p.id
        WHERE g2.completed_series >= :min_series
          AND p.deleted_at IS NULL
        ORDER BY {order_clause}
        LIMIT :limit
    """)
    rows = (await db.execute(q, {"min_series": min_series, "limit": limit})).mappings().all()
    _colors = await _rank_colors(db)
    # Podium map only when some row wears the dynamic podium title.
    _pmap = await _podium_map(db) if any(
        r["title_sku"] == TITLE_PODIUM_SKU for r in rows) else {}
    entries = []
    for idx, r in enumerate(rows, start=1):
        # Dynamic 'Current Rank' title (#48) — resolves against the 1v1 ladder.
        _t, _tc = _display_title_sync(
            _colors, r["title_sku"], r["title"], r["title_color"],
            float(r["rating_1v1"]) if r["rating_1v1"] is not None else None,
            podium_pos=_pmap.get(r["player_id"]))
        entries.append(Team2v2LeaderboardEntry(
            rank=idx,
            steam_id=r["steam_id"],
            display_name=r["display_name"],
            rating=int(r["rating"]),
            rd=int(r["rd"]),
            completed_series=r["completed_series"],
            series_wins=r["wins"],
            series_losses=r["losses"],
            win_rate=float(r["win_rate"]),
            level=level_from_xp(r["total_xp"])[0],
            title=_t,
            title_color=_tc,
            avg_teammate_elo=int(r["avg_teammate_elo"] or 0),
            team_gold_earned=int(r["team_gold_earned"] or 0),
            team_xp_earned=int(r["team_xp_earned"] or 0),
        ))
    cnt = (await db.execute(
        text("SELECT COUNT(*) FROM glicko_ratings_2v2 WHERE completed_series >= :m"),
        {"m": min_series},
    )).scalar() or 0
    return Team2v2LeaderboardResponse(entries=entries, total_players=cnt, last_updated=datetime.now(timezone.utc))


class _AdminQuarantineReq(BaseModel):
    admin_steam_id: str
    hmac_signature: str | None = None
    note: str | None = None


async def _quarantine_later_rated_count(db, mode: str, player_ids, since) -> int:
    """How many results have been RATED for these participants since the
    quarantined report was captured — in the rating system the report itself
    would touch (Codex batch find 11: the check was FFA-only, so a 2v2
    quarantine row could read 'safe to accept' while later 2v2 results made an
    in-order apply impossible). FFA and 2v2 glicko are separate ladders, so
    each mode checks only its own tables."""
    pids = list(player_ids or [])
    if not pids:
        return 0
    if mode == "team":
        return (await db.execute(text("""
            SELECT COUNT(*) FROM team_matches tm
             WHERE tm.created_at > :since
               AND (tm.t1a_id = ANY(:pids) OR tm.t1b_id = ANY(:pids)
                    OR tm.t2a_id = ANY(:pids) OR tm.t2b_id = ANY(:pids))
        """), {"pids": pids, "since": since})).scalar() or 0
    return (await db.execute(text("""
        SELECT COUNT(*) FROM ffa_match_players f
          JOIN ffa_matches m ON m.id = f.match_id
         WHERE f.player_id = ANY(:pids) AND m.ended_at > :since
    """), {"pids": pids, "since": since})).scalar() or 0


# ── Routes: match-report quarantine (July 30 lifecycle sweep) ──────────────
# Sid: "if it fails again, send it to the admin tab instead of having it
# straight deleted." Capture happens at the lifecycle rejection sites via
# _quarantine_report; these three routes are the admin surface over it.

@app.get("/api/v1/admin/quarantine", tags=["Admin"])
async def admin_list_quarantine(
    admin_steam_id: str = Query(...),
    hmac_signature: str = Query(None),
    db: AsyncSession = Depends(get_db),
):
    """Pending rejected reports, newest first.

    `can_accept` is computed SERVER-side and is authoritative — the client only
    renders it. Accepting a report re-applies Glicko, and Glicko is order
    dependent: if any participant has been rated since this report was rejected,
    applying it now would write a rating that never existed in that order. The
    July 30 recovery needed a full chronological ladder replay for exactly this
    reason, so Accept is offered only when nothing has moved since.
    """
    await _require_admin(db, admin_steam_id, "quarantine", "list", hmac_signature)
    rows = (await db.execute(text("""
        SELECT q.id, q.mode, q.reason, q.http_status, q.group_id, q.photon_room_id,
               q.player_ids, q.payload, q.status, q.created_at,
               (SELECT COALESCE(ARRAY_AGG(p.display_name ORDER BY p.display_name), '{}'::text[])
                  FROM players p WHERE p.id = ANY(q.player_ids)) AS names
          FROM match_report_quarantine q
         WHERE q.status = 'pending'
         ORDER BY q.created_at DESC
         LIMIT 50
    """))).mappings().all()
    out = []
    for r in rows:
        # Has anything rated these players since? Any later FFA result for a
        # participant means an accept would land out of order.
        blocked = None
        try:
            async with db.begin_nested():
                later = await _quarantine_later_rated_count(
                    db, r["mode"], r["player_ids"], r["created_at"])
            if later:
                blocked = (f"{later} later rated game(s) for these players — accepting now "
                           "would apply rating out of order; needs an ordered replay")
        except Exception as ex:
            blocked = f"eligibility check failed: {ex}"
        # Compose the human-readable result from the stored payload. Without
        # this the admin panel renders "score unavailable" on every row - and the
        # score is the single fact an admin needs to judge what they are about to
        # re-apply to the participants' ratings. The payload is the verbatim
        # report, so this is derived, never trusted as authority.
        score = ""
        try:
            pl = r["payload"] if isinstance(r["payload"], dict) else _json.loads(r["payload"])
            if r["mode"] == "team":
                def _tn(k):
                    return str((pl.get(k) or {}).get("display_name") or "?")[:12]
                score = (f"{_tn('t1a')} + {_tn('t1b')} {int(pl.get('t1_rounds_won') or 0)}"
                         f" | {_tn('t2a')} + {_tn('t2b')} {int(pl.get('t2_rounds_won') or 0)}")
            else:
                entries = sorted(
                    [(str(x.get("display_name") or "?")[:14], int(x.get("rounds_won") or 0))
                     for x in (pl.get("players") or [])],
                    key=lambda t: -t[1])
                score = " | ".join(f"{n} {v}" for n, v in entries[:10])
        except Exception:
            score = ""
        out.append({
            "id": str(r["id"]), "mode": r["mode"], "reason": r["reason"],
            "score": score,
            "http_status": int(r["http_status"]), "created_at": r["created_at"].isoformat(),
            "player_names": list(r["names"] or []),
            "room": r["photon_room_id"], "status": r["status"],
            "can_accept": blocked is None,
            "accept_blocked_reason": blocked or "",
        })
    return {"reports": out}


@app.post("/api/v1/admin/quarantine/{qid}/discard", tags=["Admin"])
async def admin_discard_quarantine(qid: str, req: _AdminQuarantineReq,
                                   db: AsyncSession = Depends(get_db)):
    await _require_admin(db, req.admin_steam_id, "quarantine_action", qid, req.hmac_signature)
    res = await db.execute(text("""
        UPDATE match_report_quarantine
           SET status='discarded', reviewed_at=NOW(), review_note=:note,
               reviewed_by=(SELECT id FROM players WHERE steam_id=:sid)
         WHERE id=CAST(:qid AS UUID) AND status='pending'
    """), {"qid": qid, "sid": req.admin_steam_id, "note": (req.note or "")[:500]})
    await db.commit()
    if not res.rowcount:
        raise HTTPException(409, "Already reviewed")
    return {"status": "discarded"}


@app.post("/api/v1/admin/quarantine/{qid}/accept", tags=["Admin"])
async def admin_accept_quarantine(qid: str, req: _AdminQuarantineReq,
                                  db: AsyncSession = Depends(get_db)):
    """Marks a quarantined report approved for recovery.

    Deliberately does NOT re-run the submit path. Re-applying an old report
    inline would rate it at today's ratings rather than at its own point in
    history, which is precisely the corruption the July 30 recovery had to undo
    with a chronological replay. This route records the admin's decision and
    locks the row; the actual application is an ordered replay, run deliberately.
    """
    await _require_admin(db, req.admin_steam_id, "quarantine_action", qid, req.hmac_signature)
    row = (await db.execute(text(
        "SELECT player_ids, created_at, status, mode FROM match_report_quarantine"
        " WHERE id = CAST(:qid AS UUID) FOR UPDATE"), {"qid": qid})).mappings().first()
    if row is None:
        raise HTTPException(404, "Not found")
    if row["status"] != "pending":
        raise HTTPException(409, "Already reviewed")
    later = await _quarantine_later_rated_count(
        db, row["mode"], row["player_ids"], row["created_at"])
    if later:
        # Re-checked under the row lock, not just at list time (#178/#208): the
        # admin may have been looking at a stale screen.
        raise HTTPException(409, f"{later} later rated game(s) — needs an ordered replay")
    await db.execute(text("""
        UPDATE match_report_quarantine
           SET status='accepted', reviewed_at=NOW(),
               reviewed_by=(SELECT id FROM players WHERE steam_id=:sid)
         WHERE id=CAST(:qid AS UUID) AND status='pending'
    """), {"qid": qid, "sid": req.admin_steam_id})
    await db.commit()
    print(f"[QUARANTINE] {qid} accepted by {req.admin_steam_id}")
    return {"status": "accepted"}
